def _db():
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    return con


def _kullanici_id():
    u = session.get('kullanici')
    return u.get('Id') if u else None


def _kullanici_ad():
    u = session.get('kullanici')
    return u.get('KullaniciAdi', 'sistem') if u else 'sistem'


def _taban_kalemler(kalemler):
    """Ana formül görünümü: BOYA satırları hariç (RF/renk panelinde yönetilir)."""
    return [k for k in kalemler if (k.get('kategori') or '').upper() != 'BOYA']


def _boya_kalemler_filtre(kalemler):
    return [k for k in kalemler if (k.get('kategori') or '').upper() == 'BOYA']


_RF_UI_IDENTITY_PREFIX = "IMPORT_RF_ID|"


def _rf_ui_identity_parcala(aciklama: str | None) -> dict:
    """TABAN import RF kimliği — aciklama alanından cari/parent/rv/renk."""
    out = {"cari_kod": "", "parent_kod": "", "rv": "", "renk_kodu": ""}
    if not aciklama or _RF_UI_IDENTITY_PREFIX not in aciklama:
        return out
    try:
        part = aciklama.split(_RF_UI_IDENTITY_PREFIX, 1)[1].split("|")
        if len(part) >= 4:
            out["cari_kod"] = (part[0] or "").strip()
            out["parent_kod"] = (part[1] or "").strip()
            out["rv"] = (part[2] or "").strip()
            out["renk_kodu"] = (part[3] or "").strip()
    except Exception:
        pass
    return out


def _rf_ui_pigment_fp(con, rf_renk_id: int) -> str:
    rows = con.execute("""
        SELECT sk.kod, rk.miktar_kg
        FROM nexgen_rf_kalem rk
        JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.rf_renk_id=? AND rk.aktif=1
        ORDER BY sk.kod
    """, (rf_renk_id,)).fetchall()
    return "|".join(f"{r['kod']}:{float(r['miktar_kg']):.6f}" for r in rows)


def _rf_ui_rev_bilgi(con, rf_renk_id: int, aktif_rev_no: int) -> dict:
    rev = {"rev_no": aktif_rev_no or 0, "durum": None, "var_mi": False}
    if not con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_rf_revizyon'"
    ).fetchone():
        return rev
    row = con.execute("""
        SELECT rev_no, durum FROM nexgen_rf_revizyon
        WHERE rf_renk_id=? AND aktif=1
        ORDER BY rev_no DESC LIMIT 1
    """, (rf_renk_id,)).fetchone()
    if row:
        rev = {"rev_no": row["rev_no"], "durum": row["durum"], "var_mi": True}
    return rev


def _kg_to_gr_etiket(kg):
    """Test kalem kg → tablet boya özeti (gram)."""
    try:
        g = float(kg) * 1000
    except (TypeError, ValueError):
        return '—'
    if g >= 10:
        s = f'{g:.1f}'.rstrip('0').rstrip('.')
    else:
        s = f'{g:.2f}'.rstrip('0').rstrip('.')
    return f'{s} gr'


def _miktar_kg_to_gr(kg) -> float:
    """Tek dönüşüm: miktar_gr = miktar_kg × 1000 (max 6 ondalık)."""
    try:
        return round(float(kg) * 1000, 6)
    except (TypeError, ValueError):
        return 0.0


def _rf_pigment_payload_olustur(ham_kalemler: list[dict]) -> dict:
    """RF pigment kalemlerini tek normalize payload'a dönüştürür.

    Her kalem: stok_kodu, pigment_adi, miktar_kg_raw, miktar_gr, oran_yuzde, aktif
    Özet: kalem_sayisi, toplam_gr, toplam_kg
    """
    aktif = [
        k for k in (ham_kalemler or [])
        if k.get('aktif', 1) not in (0, False, '0')
    ]
    if not aktif and ham_kalemler:
        aktif = list(ham_kalemler)

    toplam_kg = sum(
        float(k.get('miktar_kg') or k.get('miktar') or k.get('miktar_kg_raw') or 0)
        for k in aktif
    )
    toplam_gr = _miktar_kg_to_gr(toplam_kg)

    pigmentler = []
    for k in aktif:
        mkg = float(k.get('miktar_kg') or k.get('miktar') or k.get('miktar_kg_raw') or 0)
        mgr = _miktar_kg_to_gr(mkg)
        stok_kodu = (
            k.get('stok_kodu') or k.get('stok_kod') or k.get('kod') or '—'
        )
        pigment_adi = (
            k.get('pigment_adi') or k.get('stok_adi') or k.get('stok_ad')
            or k.get('pigment_ad') or k.get('ad') or '—'
        )
        pigmentler.append({
            'sira':         k.get('sira'),
            'stok_kodu':    stok_kodu,
            'stok_adi':     pigment_adi,
            'pigment_adi':  pigment_adi,
            'kategori':     k.get('kategori') or '—',
            'miktar_kg_raw': round(mkg, 6),
            'miktar_kg':    round(mkg, 6),
            'miktar_gr':    mgr,
            'oran_yuzde':   round((mgr / toplam_gr * 100), 6) if toplam_gr else 0.0,
            'aktif':        k.get('aktif', 1),
        })

    return {
        'pigmentler': pigmentler,
        'ozet': {
            'kalem_sayisi': len(pigmentler),
            'toplam_kg':    round(toplam_kg, 6),
            'toplam_gr':    toplam_gr,
        },
    }


def _stok_boya_dropdown_etiket(kod, ad):
    """Tablet boya select: KOD — AD."""
    k = (kod or '').strip()
    a = (ad or '').strip()
    if k and a:
        return f'{k} — {a}'
    return a or k or 'Boya'


def _stok_boya_ozet_ad(kod, ad):
    """Sol panel boya özeti — operatör adı (N550, P.Red 48:3)."""
    return (ad or kod or 'Boya').strip()


def _arge_test_boya_ozet(con, test_id, limit=3):
    """Tablet sol panel: BOYA kalem özeti satırları."""
    rows = con.execute("""
        SELECT sk.ad, sk.kod, tk.test_miktar_kg
        FROM nexgen_arge_test_kalem tk
        JOIN nexgen_stok_kart sk ON sk.id = tk.stok_kart_id
        WHERE tk.test_id = ? AND UPPER(COALESCE(sk.kategori, '')) = 'BOYA'
        ORDER BY tk.sira, tk.id
    """, (test_id,)).fetchall()
    satirlar = []
    for r in rows[:limit]:
        ad = _stok_boya_ozet_ad(r['kod'], r['ad'])
        satirlar.append({'ad': ad, 'gram': _kg_to_gr_etiket(r['test_miktar_kg'])})
    return satirlar, max(0, len(rows) - limit)


# ─────────────────────────────────────────────────────────────
# Stok miktarı hesapla (hareket toplamı)
# ─────────────────────────────────────────────────────────────
def _mevcut_stok(con, kart_id):
    row = con.execute(
        "SELECT COALESCE(SUM(miktar_kg), 0) AS toplam "
        "FROM nexgen_stok_hareket WHERE stok_kart_id=?",
        (kart_id,)
    ).fetchone()
    return round(row["toplam"], 3) if row else 0.0


def _stok_hareket_yaz(con, stok_kart_id, hareket_tipi, miktar_kg,
                      aciklama=None, referans_tip=None, referans_id=None,
                      olusturan_id=None, olusturma_tarihi=None):
    """Tek stok hareketi INSERT — yalnızca ledger yazımı (iş kuralı yok).

    miktar_kg: imzalı değer (giriş pozitif, çıkış negatif); çağıran belirler.
    Dönüş: hareket_id, onceki_stok, sonraki_stok
    """
    onceki = _mevcut_stok(con, stok_kart_id)
    miktar_kayit = round(float(miktar_kg), 3)
    sonraki = round(onceki + miktar_kayit, 3)
    uid = olusturan_id if olusturan_id is not None else _kullanici_id()

    if olusturma_tarihi:
        con.execute("""
            INSERT INTO nexgen_stok_hareket
              (stok_kart_id, hareket_tipi, miktar_kg,
               onceki_stok, sonraki_stok,
               aciklama, referans_tip, referans_id,
               olusturan_id, olusturma_tarihi)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """, (
            stok_kart_id, hareket_tipi, miktar_kayit,
            onceki, sonraki,
            aciklama, referans_tip, referans_id,
            uid, olusturma_tarihi,
        ))
    else:
        con.execute("""
            INSERT INTO nexgen_stok_hareket
              (stok_kart_id, hareket_tipi, miktar_kg,
               onceki_stok, sonraki_stok,
               aciklama, referans_tip, referans_id,
               olusturan_id, olusturma_tarihi)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
        """, (
            stok_kart_id, hareket_tipi, miktar_kayit,
            onceki, sonraki,
            aciklama, referans_tip, referans_id,
            uid,
        ))

    hareket_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]
    return {
        'hareket_id': hareket_id,
        'onceki_stok': onceki,
        'sonraki_stok': sonraki,
    }


