# ═════════════════════════════════════════════════════════════
# FAZ-4B: REÇETE / FORMÜL MERKEZİ
# ─────────────────────────────────────────────────────────────
# KURAL: Bu bölümde nexgen_stok_hareket INSERT YAPILMAZ.
#        nexgen_hammadde_fiyat dokunulmaz.
#        Sadece okuma + reçete master veri.
# ─────────────────────────────────────────────────────────────
# FAZ-RECETE-MERKEZI-UI: Kullanım Geçmişi API
# uretim_varyant_id bazında plan/batch/cari özetini döner.
# Çift sayım: plan bazında GROUP BY yapılır, batch çoğaltmaz.
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/recete/kullanim-gecmisi')
@yetki_gerekli('nexgen.recete.view', 'can_view')
def recete_kullanim_gecmisi():
    """
    Query params:
      uv_id  : uretim_varyant_id (zorunlu)
    Döner:
      ozet: {firma_say, toplam_plan, toplam_batch, toplam_planlanan_kg, son_kullanim}
      satirlar: [{cari_unvan, uretim_tipi, plan_say, batch_say, planlanan_kg, son_kullanim}]
    """
    uv_id = request.args.get('uv_id', type=int)
    if not uv_id:
        return jsonify({'ok': False, 'hata': 'uv_id gerekli'}), 400

    con = _db()
    try:
        # Kolon varlık kontrolleri
        plan_cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_uretim_plan)").fetchall()]
        cari_col_var = 'cari_id' in plan_cols
        pls_col_var  = 'planlama_siparis_id' in plan_cols

        if not cari_col_var:
            # Plan tablosunda cari_id yok — boş döndür
            return jsonify({'ok': True, 'ozet': {}, 'satirlar': [], 'uyari': 'cari_id kolonu bulunamadı'})

        # Plan bazında topla (batch çoğaltmaz)
        # Tarih kolonu: created_at veya plan_tarihi
        tarih_col = 'p.created_at' if 'created_at' in plan_cols else (
                    'p.plan_tarihi' if 'plan_tarihi' in plan_cols else 'NULL')
        plan_rows = con.execute(f"""
            SELECT p.id AS plan_id, p.planlanan_kg, p.cari_id,
                   {tarih_col} AS kayit_tarihi,
                   c.unvan AS cari_unvan
            FROM nexgen_uretim_plan p
            LEFT JOIN nexgen_cari c ON c.id = p.cari_id
            WHERE p.uretim_varyant_id = ?
              AND (p.durum IS NULL OR p.durum != 'IPTAL')
            ORDER BY p.id DESC
        """, (uv_id,)).fetchall()

        if not plan_rows:
            return jsonify({'ok': True, 'ozet': {}, 'satirlar': [], 'bos': True})

        # Her plan için batch sayısını ayrı çek
        plan_ids = [r['plan_id'] for r in plan_rows]
        batch_map = {}
        if plan_ids:
            ph = ','.join('?' * len(plan_ids))
            batch_rows = con.execute(f"""
                SELECT plan_id, COUNT(*) AS bcnt
                FROM nexgen_uretim_batch
                WHERE plan_id IN ({ph}) AND (durum IS NULL OR durum != 'IPTAL')
                GROUP BY plan_id
            """, plan_ids).fetchall()
            for b in batch_rows:
                batch_map[b['plan_id']] = b['bcnt']

        # Cari bazında grupla
        cari_map = {}
        for r in plan_rows:
            cari_unvan = r['cari_unvan'] or ('Cari #' + str(r['cari_id']) if r['cari_id'] else 'Bilinmiyor')
            if cari_unvan not in cari_map:
                cari_map[cari_unvan] = {
                    'cari_unvan': cari_unvan,
                    'uretim_tipi': '—',
                    'plan_say': 0,
                    'batch_say': 0,
                    'planlanan_kg': 0.0,
                    'son_kullanim': None,
                }
            grp = cari_map[cari_unvan]
            grp['plan_say']     += 1
            grp['batch_say']    += batch_map.get(r['plan_id'], 0)
            grp['planlanan_kg'] += float(r['planlanan_kg'] or 0)
            tarih = (r['kayit_tarihi'] or '')[:10]
            if tarih and (not grp['son_kullanim'] or tarih > grp['son_kullanim']):
                grp['son_kullanim'] = tarih

        satirlar = sorted(cari_map.values(), key=lambda x: x['planlanan_kg'], reverse=True)

        ozet = {
            'firma_say':      len(satirlar),
            'toplam_plan':    sum(s['plan_say']     for s in satirlar),
            'toplam_batch':   sum(s['batch_say']    for s in satirlar),
            'toplam_planlanan_kg': round(sum(s['planlanan_kg'] for s in satirlar), 2),
            'son_kullanim':   max((s['son_kullanim'] for s in satirlar if s['son_kullanim']), default=None),
        }

        return jsonify({'ok': True, 'ozet': ozet, 'satirlar': satirlar})

    except Exception as e:
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()


# ─────────────────────────────────────────────────────────────
# ENDPOINT: Reçete Merkezi — Boya Reçetesi Paneli
# uv_id için RF + aktif revizyon + pigmentler döndürür
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/recete/boya-bilgi')
@yetki_gerekli('nexgen.recete.view', 'can_view')
def recete_boya_bilgi():
    """
    Query params: uv_id (uretim_varyant_id)
    Öncelik sırası:
      1. Ana reçetede BOYA kategorili kalem → ANA REÇETE
      2. nexgen_planlama_uygunluk.rf_renk_id → UYGUNLUK
      3. nexgen_uretim_plan.rf_renk_id → SON PLAN
      4. nexgen_uretim_batch.rf_renk_id → SON BATCH
    """
    uv_id = request.args.get('uv_id', type=int)
    if not uv_id:
        return jsonify({'ok': False, 'hata': 'uv_id gerekli'}), 400

    con = _db()
    try:
        # Öncelik 1: Ana reçetede BOYA kategorili kalemler
        boya_kalemler = con.execute("""
            SELECT rk.miktar_kg, sk.kod AS stok_kod, sk.ad AS stok_ad
            FROM nexgen_recete_kalem rk
            JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
              AND UPPER(sk.kategori) = 'BOYA'
            ORDER BY rk.sira, rk.id
        """, (uv_id,)).fetchall()

        if boya_kalemler:
            ham = [{
                'sira': i + 1,
                'stok_kod': k['stok_kod'],
                'stok_ad': k['stok_ad'],
                'miktar_kg': float(k['miktar_kg']),
                'aktif': 1,
            } for i, k in enumerate(boya_kalemler)]
            payload = _rf_pigment_payload_olustur(ham)
            return jsonify({
                'ok': True, 'kaynak': 'ANA REÇETE',
                'kalemler': payload['pigmentler'],
                'pigment_ozet': payload['ozet'],
                'toplam_kg': payload['ozet']['toplam_kg'],
                'toplam_gr': payload['ozet']['toplam_gr'],
                'kalem_sayisi': payload['ozet']['kalem_sayisi'],
                'rf_kod': None, 'rf_ad': None, 'rev_no': None,
            })

        rf_renk_id = None
        rf_rev_no  = None
        kaynak     = None

        # Öncelik 2: Planlama uygunluğu tablosu
        try:
            pu_exists = bool(con.execute(
                "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_planlama_uygunluk'"
            ).fetchone())
            if pu_exists:
                pu_cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_planlama_uygunluk)").fetchall()]
                if 'uretim_varyant_id' in pu_cols and 'rf_renk_id' in pu_cols:
                    pu_rev = 'rf_rev_no' if 'rf_rev_no' in pu_cols else None
                    q = f"SELECT rf_renk_id{', ' + pu_rev if pu_rev else ''} FROM nexgen_planlama_uygunluk WHERE uretim_varyant_id=? AND rf_renk_id IS NOT NULL ORDER BY id DESC LIMIT 1"
                    pu_row = con.execute(q, (uv_id,)).fetchone()
                    if pu_row:
                        rf_renk_id = pu_row['rf_renk_id']
                        rf_rev_no  = pu_row[pu_rev] if pu_rev else None
                        kaynak     = 'UYGUNLUK'
        except Exception:
            pass

        # Öncelik 3: Plan üzerinden RF bağlantısı
        if not rf_renk_id:
            try:
                plan_cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_uretim_plan)").fetchall()]
                if 'rf_renk_id' in plan_cols:
                    rev_col = 'rf_rev_no' if 'rf_rev_no' in plan_cols else None
                    q = f"SELECT rf_renk_id{', ' + rev_col if rev_col else ''} FROM nexgen_uretim_plan WHERE uretim_varyant_id=? AND rf_renk_id IS NOT NULL ORDER BY id DESC LIMIT 1"
                    plan_row = con.execute(q, (uv_id,)).fetchone()
                    if plan_row:
                        rf_renk_id = plan_row['rf_renk_id']
                        rf_rev_no  = plan_row[rev_col] if rev_col else None
                        kaynak     = 'SON PLAN'
            except Exception:
                pass

        # Öncelik 4: Batch üzerinden (plan yoksa)
        if not rf_renk_id:
            try:
                batch_cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_uretim_batch)").fetchall()]
                if 'rf_renk_id' in batch_cols:
                    b_rev_col = 'rf_rev_no' if 'rf_rev_no' in batch_cols else None
                    q = f"SELECT rf_renk_id{', ' + b_rev_col if b_rev_col else ''} FROM nexgen_uretim_batch WHERE uretim_varyant_id=? AND rf_renk_id IS NOT NULL ORDER BY id DESC LIMIT 1"
                    batch_row = con.execute(q, (uv_id,)).fetchone()
                    if batch_row:
                        rf_renk_id = batch_row['rf_renk_id']
                        rf_rev_no  = batch_row[b_rev_col] if b_rev_col else None
                        kaynak     = 'SON BATCH'
            except Exception:
                pass

        if not rf_renk_id:
            uv_ctx = con.execute("""
                SELECT uv.id, rv.formul_id, rv.renk, rv.ad AS rv_ad
                FROM nexgen_uretim_varyant uv
                JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
                WHERE uv.id = ?
            """, (uv_id,)).fetchone()
            if uv_ctx:
                rv_key = (uv_ctx['renk'] or '').strip()
                rf_rows = con.execute("""
                    SELECT rf.id, rf.rf_kod, rf.ad, rf.aciklama, rf.aktif_rev_no,
                           rf.durum, rfu.durum AS uygunluk_durum
                    FROM nexgen_rf_renk rf
                    JOIN nexgen_rf_formul_uygunluk rfu
                      ON rfu.rf_renk_id = rf.id AND rfu.aktif = 1
                    WHERE rfu.formul_id = ? AND rf.aktif = 1 AND rf.durum = 'ONAYLI'
                    ORDER BY rf.rf_kod, rf.id
                """, (uv_ctx['formul_id'],)).fetchall()
                for rf in rf_rows:
                    ident = _rf_ui_identity_parcala(rf['aciklama'])
                    if rv_key and ident.get('rv') and ident['rv'] != rv_key:
                        continue
                    rf_renk_id = rf['id']
                    rf_rev_no = rf['aktif_rev_no']
                    kaynak = 'FORMUL_RF'
                    break

        if not rf_renk_id:
            return jsonify({'ok': True, 'kaynak': None, 'kalemler': [],
                            'rf_kod': None, 'rf_ad': None, 'rev_no': None,
                            'neden': 'RF bulunamadı'})

        # RF bilgisi
        rf_row = con.execute("""
            SELECT rf.id, rf.rf_kod, rf.ad, rf.aciklama, rf.aktif_rev_no, rf.durum,
                   (SELECT rfu.durum FROM nexgen_rf_formul_uygunluk rfu
                    WHERE rfu.rf_renk_id = rf.id AND rfu.aktif = 1
                    ORDER BY rfu.id DESC LIMIT 1) AS uygunluk_durum
            FROM nexgen_rf_renk rf
            WHERE rf.id = ? AND rf.aktif = 1
        """, (rf_renk_id,)).fetchone()
        if not rf_row:
            return jsonify({'ok': True, 'kaynak': None, 'kalemler': [],
                            'rf_kod': None, 'rf_ad': None, 'rev_no': None,
                            'neden': 'RF kaydı bulunamadı (pasif veya silinmiş)'})

        aktif_rev_no = rf_rev_no or rf_row['aktif_rev_no'] or 1

        # Revizyon pigmentleri
        rev_tablosu_var = bool(con.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_rf_revizyon'"
        ).fetchone())

        pigmentler = []
        gercek_rev_no = aktif_rev_no
        rev_durum = None

        if rev_tablosu_var:
            rev = con.execute("""
                SELECT rv.rev_no, rv.durum, rv.pigmentler_json
                FROM nexgen_rf_revizyon rv
                WHERE rv.rf_renk_id=? AND rv.aktif=1 AND rv.rev_no=?
                LIMIT 1
            """, (rf_renk_id, aktif_rev_no)).fetchone()

            if not rev:
                # Herhangi bir aktif/onaylı revizyon
                rev = con.execute("""
                    SELECT rv.rev_no, rv.durum, rv.pigmentler_json
                    FROM nexgen_rf_revizyon rv
                    WHERE rv.rf_renk_id=? AND rv.aktif=1
                    ORDER BY rv.rev_no DESC LIMIT 1
                """, (rf_renk_id,)).fetchone()

            if rev:
                gercek_rev_no = rev['rev_no']
                rev_durum = rev['durum']
                try:
                    pigmentler = json.loads(rev['pigmentler_json'] or '[]')
                except (ValueError, TypeError):
                    pigmentler = []

        # Fallback: nexgen_rf_kalem
        if not pigmentler:
            kalem_cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_rf_kalem)").fetchall()]
            if 'rf_renk_id' in kalem_cols:
                kk = con.execute("""
                    SELECT sk.kod AS stok_kod, sk.ad AS stok_ad, k.miktar_kg
                    FROM nexgen_rf_kalem k
                    JOIN nexgen_stok_kart sk ON sk.id = k.stok_kart_id
                    WHERE k.rf_renk_id=? AND k.aktif=1
                    ORDER BY k.sira, k.id
                """, (rf_renk_id,)).fetchall()
                pigmentler = [{'stok_kod': r['stok_kod'], 'stok_ad': r['stok_ad'],
                               'miktar': float(r['miktar_kg'])} for r in kk]

        # pigmentler_json formatı: [{'stok_kart_id','pigment_ad','miktar_kg','sira'}, ...]
        # stok_kod bilgisi için stok_kart_id üzerinden join yap
        ham_kalemler = []
        for p in pigmentler:
            stok_kart_id = p.get('stok_kart_id')
            stok_kod = None
            if stok_kart_id:
                try:
                    sk = con.execute(
                        "SELECT kod FROM nexgen_stok_kart WHERE id=?", (stok_kart_id,)
                    ).fetchone()
                    stok_kod = sk['kod'] if sk else None
                except Exception:
                    stok_kod = None
            ham_kalemler.append({
                'sira':       p.get('sira'),
                'stok_kod':   stok_kod or p.get('stok_kod') or p.get('kod') or '—',
                'stok_ad':    p.get('pigment_ad') or p.get('stok_ad') or p.get('ad') or '—',
                'miktar_kg':  float(p.get('miktar_kg') or p.get('miktar') or 0),
                'aktif':      1,
            })

        payload = _rf_pigment_payload_olustur(ham_kalemler)
        kalemler = payload['pigmentler']
        pigment_ozet = payload['ozet']

        rf_ident = _rf_ui_identity_parcala(rf_row['aciklama'])

        return jsonify({
            'ok':       True,
            'kaynak':   kaynak,
            'rf_id':    rf_renk_id,
            'rf_kod':   rf_row['rf_kod'],
            'rf_ad':    rf_row['ad'],
            'renk_kodu': rf_ident.get('renk_kodu') or '',
            'renk_adi': rf_row['ad'],
            'rf_durum': rf_row['durum'],
            'uygunluk_durum': rf_row['uygunluk_durum'],
            'rev_no':   gercek_rev_no,
            'revizyon_id': gercek_rev_no,
            'rev_durum': rev_durum,
            'kalemler': kalemler,
            'pigment_ozet': pigment_ozet,
            'toplam_kg': pigment_ozet['toplam_kg'],
            'toplam_gr': pigment_ozet['toplam_gr'],
            'kalem_sayisi': pigment_ozet['kalem_sayisi'],
        })

    except Exception as e:
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()


# ─────────────────────────────────────────────────────────────

# ─────────────────────────────────────────────────────────────
# FAZ-FORMUL-TEMIZLIK-2B: Canonical UV + Arşiv/Geçmiş görünümü
# ─────────────────────────────────────────────────────────────

_RC_UV_GECERLI_DURUM = frozenset({'AKTIF', 'ONAYLI', 'URETIME_ACIK'})
_RC_ARSIV_FORMUL_IDS = frozenset({4, 19, 20})
_RC_ANA_AGAC_GIZLE_UV = frozenset({10014, 10017})
_RC_LEGACY_TERLIK_UV = frozenset({
    10019, 10020, 10021, 10022, 10023, 10024, 10025, 10026, 10032,
    10027, 10028, 10029, 10030, 10031, 10033,
})


def _rc_test_kayit_mi(*metinler) -> bool:
    for p in metinler:
        if not p:
            continue
        u = str(p).upper()
        if any(k in u for k in (
            'TEST', 'FAZ1A', 'FAZ-', 'GATE', 'SETUP-TEMP', 'SETUP-TEMP',
            'SETUP', 'TEMP', '_TEST_', 'GECICI', 'GEÇİCİ', 'NX-2026',
            'FOR-001', 'TEST-VARYANT',
        )):
            return True
    return False


def _rc_ana_agac_gizle_rv(rv_ad, f_kod, f_ad, rv_renk=None) -> bool:
    """Ana FORMÜLLER ağacından gizlenecek RV/formül adları."""
    if _rc_test_kayit_mi(rv_ad, f_kod, f_ad, rv_renk):
        return True
    u = (rv_ad or '').upper().strip()
    if u in ('AAAA', 'SAASDA'):
        return True
    if 'HSN TERL' in u or 'HSNTERLIK' in u.replace(' ', '').replace('İ', 'I'):
        return True
    if 'TEST-VARYANT' in u or 'SETUP-TEMP' in u:
        return True
    fa = (f_ad or '').upper().strip()
    if fa in ('TERLIK 18 28', 'SAASDA', 'A FORMÜL', 'A FORMUL'):
        return True
    return False


def _rc_canonical_uv_map(con) -> dict[tuple, int]:
    """(renk_varyant_id, boyut) -> canonical uv_id (max rev_no, tie max id)."""
    rows = con.execute("""
        SELECT uv.id, uv.renk_varyant_id, uv.boyut, uv.rev_no
        FROM nexgen_uretim_varyant uv
        WHERE uv.aktif = 1
        ORDER BY uv.renk_varyant_id, uv.boyut, uv.rev_no DESC, uv.id DESC
    """).fetchall()
    m: dict[tuple, int] = {}
    for r in rows:
        key = (r['renk_varyant_id'], r['boyut'] or '')
        if key not in m:
            m[key] = r['id']
    return m


def _rc_uv_kullanim(con, uv_id: int) -> tuple[int, int]:
    p = con.execute(
        "SELECT COUNT(*) n FROM nexgen_uretim_plan WHERE uretim_varyant_id=?",
        (uv_id,),
    ).fetchone()['n']
    b = con.execute(
        "SELECT COUNT(*) n FROM nexgen_uretim_batch WHERE uretim_varyant_id=?",
        (uv_id,),
    ).fetchone()['n']
    return int(p), int(b)


def _rc_uv_gorunum_sinifi(
    con,
    uv_row,
    rv_row,
    formul_row,
    canon_map: dict[tuple, int],
) -> str | None:
    """guncel | gecmis | arsiv | None"""
    uv = dict(uv_row)
    rv = dict(rv_row)
    f = dict(formul_row)
    uv_id = uv['uv_id']
    rv_id = rv['rv_id']
    boyut = uv['boyut'] or ''
    canon_id = canon_map.get((rv_id, boyut))
    is_canon = uv_id == canon_id
    durum = (uv.get('recete_durum') or 'TASLAK').upper()
    plan_s, batch_s = _rc_uv_kullanim(con, uv_id)

    if f['id'] in _RC_ARSIV_FORMUL_IDS or f.get('aktif', 1) != 1:
        return 'arsiv'
    if (f.get('durum') or '').upper() == 'TASLAK':
        return 'arsiv'
    if _rc_ana_agac_gizle_rv(rv.get('rv_ad'), f.get('kod'), f.get('ad'), rv.get('renk')):
        return 'arsiv'
    if _rc_test_kayit_mi(rv.get('rv_ad'), f.get('kod'), f.get('ad')):
        return 'arsiv'
    if uv_id in _RC_LEGACY_TERLIK_UV or uv_id in _RC_ANA_AGAC_GIZLE_UV:
        return 'arsiv'
    if rv.get('rv_aktif', 1) != 1 or uv.get('uv_aktif', 1) != 1:
        return 'arsiv'

    if is_canon and durum in _RC_UV_GECERLI_DURUM:
        if (uv.get('kalem_say') or 0) <= 0:
            return 'arsiv'
        return 'guncel'

    if not is_canon and (plan_s > 0 or batch_s > 0):
        return 'gecmis'

    if not is_canon:
        return 'arsiv'

    if durum not in _RC_UV_GECERLI_DURUM:
        return 'arsiv'

    return 'arsiv'


def _rc_uv_onay_bekliyor_mi(recete_durum, arge: dict | None) -> bool:
    """Liste + Onay Bekleyenler paneli için bekleyen UV tespiti."""
    if arge:
        ard = (arge.get('arge_durum') or '').upper()
        if ard in ('ONAYLANDI', 'REDDEDILDI'):
            return False
        if arge.get('arge_kod') or arge.get('test_id'):
            return True
    rd = (recete_durum or 'TASLAK').upper()
    if rd == 'PASIF':
        return False
    return rd in ('TASLAK', 'DENEME')


def _rc_gecmis_neden(plan_s: int, batch_s: int, canon_id: int | None) -> str:
    parcalar = []
    if plan_s:
        parcalar.append(f'{plan_s} plan')
    if batch_s:
        parcalar.append(f'{batch_s} batch')
    neden = ', '.join(parcalar) + ' geçmişi korunuyor' if parcalar else 'Eski revizyon'
    if canon_id:
        neden += f' (güncel UV {canon_id})'
    return neden


def _rc_uv_kalem_maliyet(con, uv_id: int, toplam_kg: float) -> tuple[list, float]:
    if toplam_kg <= 0:
        return [], 0.0
    uv_kalemler = con.execute("""
        SELECT rk.miktar_kg, rk.stok_kart_id, rk.sira,
               sk.kod AS stok_kod, sk.ad AS stok_ad, sk.kategori
        FROM nexgen_recete_kalem rk
        JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
        ORDER BY rk.sira, rk.id
    """, (uv_id,)).fetchall()
    mal = 0.0
    kalemler_liste = []
    for k in uv_kalemler:
        fr = con.execute("""
            SELECT fiyat, para_birimi, kur, fiyat_try
            FROM nexgen_hammadde_fiyat
            WHERE stok_kart_id = ? AND aktif = 1
            ORDER BY fiyat_tarihi DESC, id DESC LIMIT 1
        """, (k['stok_kart_id'],)).fetchone()
        bp = 0.0
        if fr:
            if fr['fiyat_try'] and fr['fiyat_try'] > 0:
                bp = float(fr['fiyat_try'])
            elif fr['para_birimi'] == 'TRY':
                bp = float(fr['fiyat'] or 0)
            elif fr['kur'] and fr['kur'] > 0:
                bp = float(fr['fiyat'] or 0) * float(fr['kur'])
        mal += float(k['miktar_kg']) * bp
        kalemler_liste.append({
            'stok_kod': k['stok_kod'],
            'stok_ad': k['stok_ad'],
            'kategori': k['kategori'] or '',
            'miktar_kg': float(k['miktar_kg']),
        })
    kg_maliyet = round(mal / toplam_kg, 2) if toplam_kg > 0 else 0.0
    return kalemler_liste, kg_maliyet


def _rc_arge_kaynak_tipi(arge: dict | None, test_kalem_say: int = 0) -> str | None:
    """Onay popup kaynak sınıfı."""
    if not arge:
        return None
    tip = (arge.get('test_tipi') or '').upper()
    durum = (arge.get('arge_durum') or '').upper()
    has_deneme = test_kalem_say > 0 or arge.get('shore_degeri') not in (None, '', 0)
    if tip == 'FORMUL_TEST':
        return 'FORMUL_DENEME'
    if tip in ('RENK_TEST', 'RENK_DENEMESI'):
        if has_deneme or durum in ('TEST_EDILDI', 'ONAYA_GONDERILDI'):
            return 'RENK_DENEME'
        return 'RENK_CALISMA'
    return 'ARGE_GENEL'


def _rc_uv_son_arge(con, uv_id: int) -> dict | None:
    """UV için son AR-GE test özeti (liste + popup)."""
    try:
        cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_arge_test)").fetchall()]
    except Exception:
        cols = []
    kod_expr = "COALESCE(arge_kodu, test_no)" if 'arge_kodu' in cols else "test_no"
    renk_json_sel = "t.renk_bilesenleri_json" if 'renk_bilesenleri_json' in cols else "NULL AS renk_bilesenleri_json"
    row = con.execute(f"""
        SELECT t.id AS test_id, {kod_expr} AS arge_kod, t.test_no, t.lot_no,
               t.test_tipi, t.durum AS arge_durum, t.yeni_renk_adi,
               t.shore_degeri, t.shore_hedef, t.test_batch_kg, t.kaynak_batch_kg,
               t.genel_aciklama, t.sonuc_notu, t.notlar, t.talep_referansi,
               t.renk_tuttu, t.kopurme_notu, t.cekme_problemi,
               {renk_json_sel},
               t.olusturma_tarihi, t.onay_tarihi,
               ku.KullaniciAdi AS yapan_ad,
               on_ku.KullaniciAdi AS onaylayan_ad
        FROM nexgen_arge_test t
        LEFT JOIN sistem_kullanici ku ON ku.Id = t.olusturan_id
        LEFT JOIN sistem_kullanici on_ku ON on_ku.Id = t.onaylayan_id
        WHERE t.kaynak_uretim_varyant_id = ? AND t.aktif = 1
        ORDER BY t.id DESC LIMIT 1
    """, (uv_id,)).fetchone()
    if not row:
        return None
    out = dict(row)
    test_kalem_say = con.execute(
        "SELECT COUNT(*) AS n FROM nexgen_arge_test_kalem WHERE test_id=?",
        (out['test_id'],)
    ).fetchone()['n'] or 0
    out['test_kalem_say'] = test_kalem_say
    out['kaynak_tipi'] = _rc_arge_kaynak_tipi(out, test_kalem_say)
    return out


def _rc_pisme_sn_parse(genel_aciklama) -> int | None:
    if not genel_aciklama:
        return None
    import re
    m = re.search(r'Pişme/enjeksiyon:\s*(\d+)', str(genel_aciklama), re.I)
    if not m:
        return None
    try:
        return int(m.group(1))
    except (ValueError, TypeError):
        return None


def _rc_ferhat_sonuc_ozet(arge: dict | None) -> str | None:
    """Tablet/AR-GE saha sonucu — nexgen_arge_test alanlarından."""
    if not arge:
        return None
    rt = arge.get('renk_tuttu')
    if rt in (1, True, '1'):
        return 'UYGUN'
    if rt in (0, False, '0'):
        return 'UYGUN DEĞİL'
    sn = (arge.get('sonuc_notu') or '').strip()
    if sn:
        return sn[:48]
    return None


def _rc_liste_veri_hazirla(con) -> tuple[list, list, list]:
    """Güncel formül listesi, geçmiş düz liste, arşiv düz liste."""
    canon_map = _rc_canonical_uv_map(con)
    formuller_raw = con.execute("""
        SELECT f.id, f.kod, f.ad, f.durum, f.onay_durumu, f.aktif,
               f.olusturma_tarihi, f.notlar,
               ku.KullaniciAdi AS olusturan_ad
        FROM nexgen_formul f
        LEFT JOIN sistem_kullanici ku ON ku.Id = f.olusturan_id
        WHERE f.aktif = 1
        ORDER BY f.id DESC
    """).fetchall()

    formuller_guncel: list[dict] = []
    gecmis_kayitlari: list[dict] = []
    arsiv_kayitlari: list[dict] = []

    for f in formuller_raw:
        f_dict = dict(f)
        rv_rows = con.execute("""
            SELECT rv.id AS rv_id, rv.ad AS rv_ad, rv.renk, rv.aktif AS rv_aktif,
                   uv.id AS uv_id, uv.boyut, uv.rev_no, uv.kaynak_varyant_id,
                   uv.recete_durum, uv.aktif AS uv_aktif,
                   uv.onay_tarihi, ku.KullaniciAdi AS onaylayan_ad,
                   COUNT(rk.id) AS kalem_say,
                   COALESCE(SUM(rk.miktar_kg), 0) AS toplam_kg
            FROM nexgen_renk_varyant rv
            JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id
            LEFT JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            LEFT JOIN sistem_kullanici ku ON ku.Id = uv.onaylayan_id
            WHERE rv.formul_id = ?
            GROUP BY uv.id
            ORDER BY rv.id, uv.boyut, uv.rev_no, uv.id
        """, (f_dict['id'],)).fetchall()

        rv_gruplar_guncel: dict[int, dict] = {}
        guncel_kalemler: list = []

        for row in rv_rows:
            row = dict(row)
            arge = _rc_uv_son_arge(con, row['uv_id'])
            sinif = _rc_uv_gorunum_sinifi(con, row, row, f_dict, canon_map)
            if not sinif:
                continue
            agac_goster = sinif == 'guncel'
            bekleyen_ek = False
            if (sinif == 'arsiv'
                    and row['uv_id'] not in _RC_ANA_AGAC_GIZLE_UV
                    and row['uv_id'] not in _RC_LEGACY_TERLIK_UV
                    and _rc_uv_onay_bekliyor_mi(row['recete_durum'], arge)
                    and row.get('rv_aktif', 1) == 1
                    and not _rc_ana_agac_gizle_rv(row['rv_ad'], f_dict.get('kod'), f_dict.get('ad'))
                    and not _rc_test_kayit_mi(row['rv_ad'], f_dict.get('kod'), f_dict.get('ad'))):
                bekleyen_ek = True
            if not agac_goster and not bekleyen_ek:
                if sinif == 'gecmis':
                    pass
                elif sinif != 'guncel':
                    # arsiv — düz listeye
                    pass
                else:
                    continue
            boyut = row['boyut'] or ''
            canon_id = canon_map.get((row['rv_id'], boyut))
            plan_s, batch_s = _rc_uv_kullanim(con, row['uv_id'])
            toplam_kg = round(float(row['toplam_kg'] or 0), 3)
            uv_entry = {
                'uv_id': row['uv_id'],
                'boyut': boyut,
                'rev_no': row['rev_no'],
                'kaynak_varyant_id': row['kaynak_varyant_id'],
                'recete_durum': row['recete_durum'] or 'TASLAK',
                'onay_tarihi': row['onay_tarihi'],
                'onaylayan_ad': row['onaylayan_ad'],
                'kalem_say': row['kalem_say'] or 0,
                'toplam_kg': toplam_kg,
                'canonical_uv_id': canon_id,
                'is_canonical': row['uv_id'] == canon_id,
                'plan_say': plan_s,
                'batch_say': batch_s,
                'gorunum': sinif,
                'agac_goster': agac_goster,
            }
            kl, km = _rc_uv_kalem_maliyet(con, row['uv_id'], toplam_kg)
            uv_entry['kalemler'] = kl
            uv_entry['kg_maliyet'] = km
            if arge:
                uv_entry['arge_kod'] = arge.get('arge_kod')
                uv_entry['arge_durum'] = arge.get('arge_durum')
                uv_entry['arge_yapan'] = arge.get('yapan_ad')
                uv_entry['arge_renk'] = arge.get('yeni_renk_adi')
                uv_entry['arge_test_id'] = arge.get('test_id')
                uv_entry['arge_onaylayan'] = arge.get('onaylayan_ad')
                uv_entry['arge_test_tipi'] = arge.get('test_tipi')
                uv_entry['arge_kaynak_tipi'] = arge.get('kaynak_tipi')
                uv_entry['arge_notlar'] = arge.get('notlar')
                uv_entry['arge_talep'] = arge.get('talep_referansi')
                uv_entry['arge_aciklama'] = arge.get('genel_aciklama')
                uv_entry['arge_sonuc'] = arge.get('sonuc_notu')
                uv_entry['arge_shore'] = arge.get('shore_degeri')
                uv_entry['arge_pisme_sn'] = _rc_pisme_sn_parse(arge.get('genel_aciklama'))
                uv_entry['arge_ferhat_sonuc'] = _rc_ferhat_sonuc_ozet(arge)
                uv_entry['arge_olusturma'] = arge.get('olusturma_tarihi')
                uv_entry['arge_renk_tuttu'] = arge.get('renk_tuttu')

            flat = {
                'formul_id': f_dict['id'],
                'formul_kod': f_dict['kod'],
                'formul_ad': f_dict['ad'],
                'formul_durum': f_dict['durum'],
                'rv_id': row['rv_id'],
                'rv_ad': row['rv_ad'],
                **uv_entry,
            }

            if sinif == 'guncel' or bekleyen_ek:
                rv_id = row['rv_id']
                if rv_id not in rv_gruplar_guncel:
                    rv_gruplar_guncel[rv_id] = {
                        'rv_id': rv_id,
                        'ad': row['rv_ad'],
                        'renk': row['renk'],
                        'varyantlar': [],
                    }
                rv_gruplar_guncel[rv_id]['varyantlar'].append(uv_entry)
                if agac_goster:
                    guncel_kalemler.extend(kl)
            elif sinif == 'gecmis':
                flat['neden'] = _rc_gecmis_neden(plan_s, batch_s, canon_id)
                gecmis_kayitlari.append(flat)
            else:
                flat['neden'] = (
                    'Test/legacy kayıt' if _rc_test_kayit_mi(row['rv_ad'], f_dict['kod'])
                    else 'Arşiv / kullanılmayan'
                )
                arsiv_kayitlari.append(flat)

        if not rv_gruplar_guncel:
            continue
        if f_dict['id'] in _RC_ARSIV_FORMUL_IDS:
            continue
        if (f_dict.get('durum') or '').upper() == 'TASLAK':
            continue

        f_out = dict(f_dict)
        f_out['rv_ozet'] = list(rv_gruplar_guncel.values())
        if guncel_kalemler:
            f_out['liste_toplam_kg'] = round(
                sum(k['miktar_kg'] for k in guncel_kalemler if k.get('kategori', '').upper() != 'BOYA'), 3
            )
        else:
            f_out['liste_toplam_kg'] = 0.0
        f_out['liste_kg_maliyet'] = 0.0

        durumlar = [
            (uv['recete_durum'] or 'TASLAK').upper()
            for rv in f_out['rv_ozet']
            for uv in rv['varyantlar']
        ]
        if 'URETIME_ACIK' in durumlar:
            f_out['recete_durum_ozet'] = 'URETIME_ACIK'
        elif 'ONAYLI' in durumlar:
            f_out['recete_durum_ozet'] = 'ONAYLI'
        elif 'AKTIF' in durumlar:
            f_out['recete_durum_ozet'] = 'AKTIF'
        else:
            f_out['recete_durum_ozet'] = durumlar[0] if durumlar else None

        renk_say = len(f_out['rv_ozet'])
        uretim_say = sum(len(rv['varyantlar']) for rv in f_out['rv_ozet'])
        kalem_say = sum(uv['kalem_say'] for rv in f_out['rv_ozet'] for uv in rv['varyantlar'])
        f_out['renk_say'] = renk_say
        f_out['uretim_say'] = uretim_say
        f_out['kalem_say'] = kalem_say
        if not yeni_secimde_gosterilebilir_mi(f_dict.get('kod')):
            continue
        formuller_guncel.append(f_out)

    gecmis_kayitlari.sort(key=lambda x: (x['formul_kod'], x['rv_id'], x['rev_no'] or 0))
    arsiv_kayitlari.sort(key=lambda x: (x['formul_kod'], x['rv_id'], x['uv_id']))
    return formuller_guncel, gecmis_kayitlari, arsiv_kayitlari


@nexgen_bp.route('/recete/')
@yetki_gerekli('nexgen.recete.view', 'can_view')
def recete_liste():
    con = _db()
    try:
        formuller, _, _ = _rc_liste_veri_hazirla(con)
        cekirdek_agac = rc_cekirdek_agac_hazirla(formuller)
    finally:
        con.close()

    # FAZ-BOYA-RECETESI-02B: RF listesi — sadece aktif RF'ler, aktif_rev_no dahil
    rf_listesi = []
    try:
        con2 = _db()
        rf_cols = [c[1] for c in con2.execute("PRAGMA table_info(nexgen_rf_renk)").fetchall()]
        rev_no_col = "aktif_rev_no" if "aktif_rev_no" in rf_cols else "0"
        rf_listesi = [
            dict(r) for r in con2.execute(f"""
            SELECT id, rf_kod, ad, durum, {rev_no_col} AS aktif_rev_no,
                   olusturma_tarihi, aktif, kaynak_arge_test_id
            FROM nexgen_rf_renk
            WHERE aktif = 1
            ORDER BY rf_kod
        """).fetchall()
            if yeni_secimde_renk_gosterilebilir_mi(dict(r))
        ]
        con2.close()
    except Exception:
        rf_listesi = []

    can_create  = yetki_var('nexgen.recete.create',  'can_create')
    can_approve = yetki_var('nexgen.recete.approve', 'can_approve')
    can_manage  = yetki_var('nexgen.recete.manage',  'can_manage')

    return render_template(
        'nexgen/recete_liste.html',
        active='nexgen',
        formuller=formuller,
        cekirdek_agac=cekirdek_agac,
        can_create=can_create,
        can_approve=can_approve,
        can_manage=can_manage,
        rf_listesi=rf_listesi,
    )


@nexgen_bp.route('/recete/<int:formul_id>')
@yetki_gerekli('nexgen.recete.view', 'can_view')
def recete_detay(formul_id):
    agac_gecmis: list[dict] = []
    con = _db()
    try:
        formul = con.execute("""
            SELECT f.*,
                   ku.KullaniciAdi AS olusturan_ad,
                   on_ku.KullaniciAdi AS onaylayan_ad
            FROM nexgen_formul f
            LEFT JOIN sistem_kullanici ku    ON ku.Id    = f.olusturan_id
            LEFT JOIN sistem_kullanici on_ku ON on_ku.Id = f.onaylayan_id
            WHERE f.id = ?
        """, (formul_id,)).fetchone()
        if not formul:
            abort(404)

        # Tüm renk varyantları
        renk_raw = con.execute("""
            SELECT rv.*
            FROM nexgen_renk_varyant rv
            WHERE rv.formul_id = ? AND rv.aktif = 1
            ORDER BY rv.id
        """, (formul_id,)).fetchall()

        # Stok kartı bazında son aktif TRY fiyatı (fiyat yoksa 0)
        # Öncelik: fiyat_try varsa → kullan; yoksa fiyat*kur; yoksa 0
        def _son_fiyat_try(stok_kart_id):
            row = con.execute("""
                SELECT fiyat, para_birimi, kur, fiyat_try
                FROM nexgen_hammadde_fiyat
                WHERE stok_kart_id = ? AND aktif = 1
                ORDER BY fiyat_tarihi DESC, id DESC
                LIMIT 1
            """, (stok_kart_id,)).fetchone()
            if not row:
                return 0.0
            if row['fiyat_try'] and row['fiyat_try'] > 0:
                return float(row['fiyat_try'])
            if row['para_birimi'] == 'TRY':
                return float(row['fiyat'] or 0)
            if row['kur'] and row['kur'] > 0:
                return round(float(row['fiyat'] or 0) * float(row['kur']), 4)
            return float(row['fiyat'] or 0)

        # Her renk için üretim varyantları + kalemleri + maliyet
        agac = []
        for rv in renk_raw:
            uretim_raw = con.execute("""
                SELECT uv.*,
                       ku.KullaniciAdi AS onaylayan_ad
                FROM nexgen_uretim_varyant uv
                LEFT JOIN sistem_kullanici ku ON ku.Id = uv.onaylayan_id
                WHERE uv.renk_varyant_id = ? AND uv.aktif = 1
                ORDER BY uv.boyut
            """, (rv['id'],)).fetchall()

            uretim_listesi = []
            for uv in uretim_raw:
                kalemler_raw = con.execute("""
                    SELECT rk.*, sk.kod AS stok_kod, sk.ad AS stok_ad,
                           sk.kategori, sk.birim
                    FROM nexgen_recete_kalem rk
                    JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
                    WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
                    ORDER BY rk.sira, rk.id
                """, (uv['id'],)).fetchall()
                kalemler = []
                kalemler_boya = []
                toplam_kg    = 0.0
                toplam_maliyet = 0.0
                for k in kalemler_raw:
                    k_dict = dict(k)
                    miktar = float(k_dict.get('miktar_kg') or 0)
                    birim_fiyat = _son_fiyat_try(k_dict['stok_kart_id'])
                    satir_maliyet = round(miktar * birim_fiyat, 4)
                    k_dict['birim_fiyat_try'] = birim_fiyat
                    k_dict['satir_maliyet']   = satir_maliyet
                    if (k_dict.get('kategori') or '').upper() == 'BOYA':
                        kalemler_boya.append(k_dict)
                    else:
                        toplam_kg      += miktar
                        toplam_maliyet += satir_maliyet
                        kalemler.append(k_dict)

                toplam_kg      = round(toplam_kg, 3)
                toplam_maliyet = round(toplam_maliyet, 4)
                kg_maliyet = round(toplam_maliyet / toplam_kg, 4) if toplam_kg > 0 else 0.0

                uretim_listesi.append({
                    **dict(uv),
                    'kalemler':       kalemler,
                    'boya_kalem_say': len(kalemler_boya),
                    'toplam_kg':      toplam_kg,
                    'toplam_maliyet': toplam_maliyet,
                    'kg_maliyet':     kg_maliyet,
                })

            agac.append({
                **dict(rv),
                'uretim_listesi': uretim_listesi,
            })

        canon_map = _rc_canonical_uv_map(con)
        f_row = dict(formul)
        agac_guncel: list[dict] = []
        agac_gecmis: list[dict] = []
        for rv in agac:
            guncel_uvs: list[dict] = []
            gecmis_uvs: list[dict] = []
            for uv in rv['uretim_listesi']:
                mock_row = {
                    'uv_id': uv['id'],
                    'boyut': uv.get('boyut'),
                    'rev_no': uv.get('rev_no'),
                    'recete_durum': uv.get('recete_durum'),
                    'uv_aktif': 1,
                    'kaynak_varyant_id': uv.get('kaynak_varyant_id'),
                    'rv_id': rv['id'],
                    'rv_ad': rv.get('ad'),
                    'rv_aktif': 1,
                }
                sinif = _rc_uv_gorunum_sinifi(con, mock_row, mock_row, f_row, canon_map)
                plan_s, batch_s = _rc_uv_kullanim(con, uv['id'])
                cuv = canon_map.get((rv['id'], uv.get('boyut') or ''))
                uv['plan_say'] = plan_s
                uv['batch_say'] = batch_s
                uv['is_canonical'] = uv['id'] == cuv
                uv['canonical_uv_id'] = cuv
                if sinif == 'guncel':
                    guncel_uvs.append(uv)
                elif sinif == 'gecmis':
                    uv['gecmis_neden'] = _rc_gecmis_neden(plan_s, batch_s, cuv)
                    gecmis_uvs.append(uv)
            if guncel_uvs:
                agac_guncel.append({**rv, 'uretim_listesi': guncel_uvs})
            if gecmis_uvs:
                agac_gecmis.append({**rv, 'uretim_listesi': gecmis_uvs})
        agac = agac_guncel

        # FAZ-4F: her varyant için recycle izinleri (con kapanmadan önce)
        for rv in agac:
            for uv in rv['uretim_listesi']:
                uv['recycle_izinleri'] = _uretim_varyant_recycle_izinleri(con, uv['id'])

        # FAZ-4F: modal için hammadde listesi (tüm aktif stok kartları — RECYCLE dışı)
        tum_hammaddeler = con.execute("""
            SELECT id, ad, kod, kategori FROM nexgen_stok_kart
            WHERE aktif=1 AND kategori != 'RECYCLE'
            ORDER BY ad
        """).fetchall()
        tum_hammaddeler = [dict(h) for h in tum_hammaddeler]

        # ── P3.1: Ortak helper ile taslak eksik analizi (con açıkken) ──
        eksik_liste, taslak_tam, arge_aktif = [], False, False
        if dict(formul).get('durum') == 'TASLAK':
            eksik_liste, taslak_tam, arge_aktif = _taslak_formul_eksik_kontrol(con, formul_id)

    finally:
        con.close()

    can_create       = yetki_var('nexgen.recete.create',   'can_create')
    can_approve      = yetki_var('nexgen.recete.approve',  'can_approve')
    can_manage       = yetki_var('nexgen.recete.manage',   'can_manage')
    can_recycle_mgr  = yetki_var('nexgen.recycle.manage',  'can_recycle_mgr')

    return render_template(
        'nexgen/recete_detay.html',
        active='nexgen',
        formul=dict(formul),
        agac=agac,
        agac_gecmis=agac_gecmis,
        can_create=can_create,
        can_approve=can_approve,
        can_manage=can_manage,
        can_recycle_mgr=can_recycle_mgr,
        tum_hammaddeler=tum_hammaddeler,
        eksik_liste=eksik_liste,
        taslak_tam=taslak_tam,
        arge_aktif=arge_aktif,
    )

# ─────────────────────────────────────────────────────────────
# FAZ-4C-2: REÇETE KLONLAMA + DURUM
# KURAL: nexgen_stok_hareket / nexgen_hammadde_fiyat dokunulmaz.
# ─────────────────────────────────────────────────────────────

# Geçerli recete_durum değerleri
RECETE_DURUM_GECERLI = {'TASLAK', 'DENEME', 'ONAYLI', 'URETIME_ACIK', 'PASIF'}

# ─────────────────────────────────────────────────────────────
# FAZ-RECETE-REVIZYON-01B: İZİNLİ GEÇİŞ MATRİSİ
# Onaylı/üretime açık reçete doğrudan düzenlenemez.
# Değişiklik gerekiyorsa api_recete_klon + yeni TASLAK akışı.
# ─────────────────────────────────────────────────────────────
_RECETE_GECIS_MATRISI = {
    'TASLAK':       {'DENEME', 'ONAYLI', 'PASIF'},
    'DENEME':       {'TASLAK', 'ONAYLI', 'PASIF'},
    'ONAYLI':       {'URETIME_ACIK', 'PASIF'},
    'URETIME_ACIK': {'PASIF'},
    'PASIF':        {'TASLAK'},
}

# Onay gerektiren geçişler — bu geçişlerde reçete veri bütünlüğü kontrol edilir
_ONAY_GEREKTIREN_GECISLER = {('TASLAK', 'ONAYLI'), ('DENEME', 'ONAYLI'), ('ONAYLI', 'URETIME_ACIK')}

# PASIF → TASLAK açılırken plan/batch bağlantısı kontrol edilir
_PASIF_TASLAK_PLAN_KONTROL = True


def _recete_gecis_izinli_mi(eski, yeni):
    """İzin verilen geçiş matrisine göre True/False döner."""
    return yeni in _RECETE_GECIS_MATRISI.get(eski, set())


def _recete_kalem_butunluk_kontrol(con, uv_id):
    """ONAYLI veya URETIME_ACIK yapmadan önce reçete kalemlerini doğrular.

    Döner: (gecerli: bool, hata_listesi: list[str])
    """
    hatalar = []

    # Aktif kalem var mı?
    kalemler = con.execute("""
        SELECT rk.id, rk.stok_kart_id, rk.miktar_kg,
               sk.aktif AS stok_aktif
        FROM nexgen_recete_kalem rk
        LEFT JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
    """, (uv_id,)).fetchall()

    if not kalemler:
        hatalar.append("Reçetede en az 1 aktif kalem bulunmalıdır.")
        return False, hatalar

    toplam_kg = 0.0
    stok_kart_sayac = {}

    for k in kalemler:
        # stok_kart_id dolu mu?
        if not k['stok_kart_id']:
            hatalar.append(f"Kalem #{k['id']}: stok_kart_id boş.")

        # Stok kartı aktif mi?
        if k['stok_aktif'] is None:
            hatalar.append(f"Kalem #{k['id']}: Stok kartı (id={k['stok_kart_id']}) bulunamadı.")
        elif k['stok_aktif'] == 0:
            hatalar.append(f"Kalem #{k['id']}: Stok kartı pasif (id={k['stok_kart_id']}).")

        # miktar_kg > 0 mu?
        try:
            kg = float(k['miktar_kg'] or 0)
        except (TypeError, ValueError):
            kg = 0.0
        if kg <= 0:
            hatalar.append(f"Kalem #{k['id']}: miktar_kg sıfır veya negatif ({k['miktar_kg']}).")
        toplam_kg += kg

        # Duplicate stok kartı kontrolü
        sid = k['stok_kart_id']
        stok_kart_sayac[sid] = stok_kart_sayac.get(sid, 0) + 1

    for sid, say in stok_kart_sayac.items():
        if say > 1:
            hatalar.append(f"Stok kartı #{sid} bu reçetede {say} kez aktif kalem olarak mevcut.")

    if toplam_kg <= 0:
        hatalar.append("Toplam reçete KG sıfır veya negatif.")

    return len(hatalar) == 0, hatalar


def _taslak_formul_eksik_kontrol(con, formul_id):
    """P3.1 — Formül seviyesinde eksiklik analizi.

    Tüm aktif üretim varyantlarını kontrol eder.
    Döner: (eksik_liste: list[str], taslak_tam: bool, arge_aktif: bool)

    - eksik_liste : kullanıcıya gösterilecek eksiklik açıklamaları
    - taslak_tam  : True → Onaya Gönder aktif olabilir
    - arge_aktif  : True → AR-GE Test Başlat aktif olabilir (en az bir UV dolu)
    """
    eksik = []

    formul = con.execute(
        "SELECT id, ad, urun_ailesi, durum FROM nexgen_formul WHERE id=?",
        (formul_id,)
    ).fetchone()
    if not formul:
        return ["Formül bulunamadı."], False, False

    if not (formul["ad"] or "").strip():
        eksik.append("Formül adı eksik.")
    if not (formul["urun_ailesi"] or "").strip():
        eksik.append("Ürün ailesi seçilmemiş.")

    uvler = con.execute("""
        SELECT uv.id, uv.boyut,
               COUNT(rk.id) AS kalem_say,
               COALESCE(SUM(CASE WHEN rk.aktif=1 THEN rk.miktar_kg ELSE 0 END), 0) AS toplam_kg
        FROM nexgen_renk_varyant rv
        JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id AND uv.aktif=1
        LEFT JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif=1
        WHERE rv.formul_id=? AND rv.aktif=1
        GROUP BY uv.id
    """, (formul_id,)).fetchall()

    if not uvler:
        eksik.append("Aktif üretim varyantı (boyut) tanımlanmamış.")
        return eksik, False, False

    # Pasif/bulunamayan stok kontrolü — UV başına
    for uv in uvler:
        uv_id  = uv["id"]
        boyut  = uv["boyut"] or "?"
        if uv["kalem_say"] == 0:
            eksik.append(f"{boyut} boyutunda hammadde kalemi yok.")
            continue
        if float(uv["toplam_kg"] or 0) <= 0:
            eksik.append(f"{boyut} boyutunun toplam KG değeri sıfır.")
            continue
        # Pasif stok kontrolü
        pasif = con.execute("""
            SELECT COUNT(*) AS say
            FROM nexgen_recete_kalem rk
            LEFT JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            WHERE rk.uretim_varyant_id=? AND rk.aktif=1
              AND (sk.id IS NULL OR sk.aktif=0)
        """, (uv_id,)).fetchone()["say"]
        if pasif > 0:
            eksik.append(f"{boyut} boyutunda {pasif} adet pasif/bulunamayan stok kartı var.")

    arge_aktif = any(
        float(uv["toplam_kg"] or 0) > 0 and uv["kalem_say"] > 0
        for uv in uvler
    )
    taslak_tam = (len(eksik) == 0)
    return eksik, taslak_tam, arge_aktif


def _uretime_acik_receteler(con):
    """FAZ-5 hazırlık: üretime açık üretim varyantlarını döner.
    recete_durum = 'URETIME_ACIK' olan aktif varyantlar.
    """
    return con.execute("""
        SELECT uv.id, uv.boyut, uv.ad, uv.recete_durum,
               rv.ad AS renk_ad, rv.renk,
               f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad,
               COUNT(rk.id) AS kalem_say
        FROM nexgen_uretim_varyant uv
        JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
        JOIN nexgen_formul f        ON f.id  = rv.formul_id
        LEFT JOIN nexgen_recete_kalem rk
               ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
        WHERE uv.aktif = 1 AND rv.aktif = 1 AND f.aktif = 1
          AND uv.recete_durum = 'URETIME_ACIK'
        GROUP BY uv.id
        ORDER BY f.kod, rv.ad, uv.boyut
    """).fetchall()


@nexgen_bp.route('/api/recete/klon', methods=['POST'])
@yetki_gerekli('nexgen.recete.create', 'can_create')
def api_recete_klon():
    """Bir üretim varyantının reçete kalemlerini başka bir üretim varyantına kopyalar.

    POST JSON:
        kaynak_uv_id : int   — kopyalanacak kaynak üretim varyantı
        hedef_uv_id  : int   — hedef üretim varyantı
        notlar       : str   — opsiyonel
    """
    data = request.get_json(silent=True) or {}
    kaynak_uv_id = data.get('kaynak_uv_id')
    hedef_uv_id  = data.get('hedef_uv_id')
    notlar       = (data.get('notlar') or '').strip() or None

    if not kaynak_uv_id or not hedef_uv_id:
        return jsonify({"ok": False, "hata": "kaynak_uv_id ve hedef_uv_id zorunludur."}), 400
    if kaynak_uv_id == hedef_uv_id:
        return jsonify({"ok": False, "hata": "Kaynak ve hedef aynı olamaz."}), 400

    kullanici_id = _kullanici_id()
    con = _db()
    try:
        # Kaynak varyant var mı?
        kaynak = con.execute(
            "SELECT id, ad FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
            (kaynak_uv_id,)
        ).fetchone()
        if not kaynak:
            return jsonify({"ok": False, "hata": "Kaynak üretim varyantı bulunamadı."}), 404

        # Hedef varyant var mı?
        hedef = con.execute(
            "SELECT id, ad, renk_varyant_id FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
            (hedef_uv_id,)
        ).fetchone()
        if not hedef:
            return jsonify({"ok": False, "hata": "Hedef üretim varyantı bulunamadı."}), 404

        # Güvenlik: hedefte zaten aktif kalem var mı?
        mevcut_kalem = con.execute(
            "SELECT COUNT(*) AS say FROM nexgen_recete_kalem WHERE uretim_varyant_id=? AND aktif=1",
            (hedef_uv_id,)
        ).fetchone()['say']
        if mevcut_kalem > 0:
            return jsonify({
                "ok": False,
                "hata": f"Hedef varyantta zaten {mevcut_kalem} aktif reçete kalemi var. "
                        "Önce temizleyin veya farklı hedef seçin."
            }), 409

        # Kaynak kalemleri al
        kalemler = con.execute("""
            SELECT stok_kart_id, sira, miktar_kg, aciklama
            FROM nexgen_recete_kalem
            WHERE uretim_varyant_id = ? AND aktif = 1
            ORDER BY sira, id
        """, (kaynak_uv_id,)).fetchall()

        if not kalemler:
            return jsonify({"ok": False, "hata": "Kaynak varyantta kopyalanacak reçete kalemi yok."}), 400

        # Kalemleri hedefe kopyala — miktar_kg REAL olarak aynen
        for k in kalemler:
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, sira, miktar_kg, aciklama,
                     aktif, olusturma_tarihi)
                VALUES (?, ?, ?, ?, ?, 1, datetime('now'))
            """, (hedef_uv_id, k['stok_kart_id'], k['sira'],
                  float(k['miktar_kg']),  # REAL korunuyor
                  k['aciklama']))

        # Hedef varyantı TASLAK olarak işaretle (yeni klon)
        con.execute(
            "UPDATE nexgen_uretim_varyant SET recete_durum='TASLAK' WHERE id=?",
            (hedef_uv_id,)
        )

        # Audit log
        con.execute("""
            INSERT INTO nexgen_recete_klon_log
                (kaynak_uv_id, hedef_uv_id, kalem_sayisi, yapan_id, notlar)
            VALUES (?, ?, ?, ?, ?)
        """, (kaynak_uv_id, hedef_uv_id, len(kalemler), kullanici_id, notlar))

        con.commit()

        # Hedef formül id'sini bul (redirect için)
        hedef_formul = con.execute("""
            SELECT rv.formul_id
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
            WHERE uv.id = ?
        """, (hedef_uv_id,)).fetchone()
        hedef_formul_id = hedef_formul['formul_id'] if hedef_formul else None

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok": True,
        "kalem_sayisi": len(kalemler),
        "hedef_uv_id":  hedef_uv_id,
        "hedef_formul_id": hedef_formul_id,
        "mesaj": f"{len(kalemler)} reçete kalemi '{kaynak['ad']}' → '{hedef['ad']}' kopyalandı.",
    })


@nexgen_bp.route('/api/recete/durum-guncelle', methods=['POST'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_durum_guncelle():
    """Üretim varyantının recete_durum alanını günceller.

    FAZ-RECETE-REVIZYON-01B: İzinli geçiş matrisi uygulanır.
    Onaylı/üretime açık reçete doğrudan TASLAK/DENEME yapılamaz.

    POST JSON:
        uv_id        : int
        yeni_durum   : str  (TASLAK / DENEME / ONAYLI / URETIME_ACIK / PASIF)
        notlar       : str  opsiyonel
    """
    data       = request.get_json(silent=True) or {}
    uv_id      = data.get('uv_id')
    yeni_durum = (data.get('yeni_durum') or '').strip().upper()
    notlar     = (data.get('notlar') or '').strip() or None

    if not uv_id:
        return jsonify({"ok": False, "hata": "uv_id zorunludur."}), 400
    if yeni_durum not in RECETE_DURUM_GECERLI:
        return jsonify({
            "ok": False,
            "hata": f"Geçersiz durum. Geçerliler: {', '.join(sorted(RECETE_DURUM_GECERLI))}"
        }), 400

    kullanici_id = _kullanici_id()
    con = _db()
    try:
        uv = con.execute(
            """SELECT uv.id, uv.ad, uv.recete_durum, uv.onay_durumu,
                      uv.renk_varyant_id, uv.boyut
               FROM nexgen_uretim_varyant uv
               WHERE uv.id=? AND uv.aktif=1""",
            (uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({"ok": False, "hata": "Üretim varyantı bulunamadı."}), 404

        eski_durum = uv['recete_durum'] or 'TASLAK'

        # ── Aynı duruma geçiş — sessiz başarı ────────────────────
        if eski_durum == yeni_durum:
            return jsonify({
                "ok": True,
                "uv_id":      uv_id,
                "eski_durum": eski_durum,
                "yeni_durum": yeni_durum,
                "mesaj":      f"'{uv['ad']}' zaten {yeni_durum} durumunda.",
            })

        # ── İzin matrisi kontrolü ─────────────────────────────────
        if not _recete_gecis_izinli_mi(eski_durum, yeni_durum):
            if eski_durum in ('URETIME_ACIK', 'ONAYLI') and yeni_durum in ('TASLAK', 'DENEME'):
                hata_msg = (
                    "Onaylı veya üretime açık reçete doğrudan düzenlenemez. "
                    "Değişiklik için yeni revizyon açın."
                )
            else:
                izinliler = ', '.join(sorted(_RECETE_GECIS_MATRISI.get(eski_durum, set()))) or 'yok'
                hata_msg = (
                    f"'{eski_durum}' durumundan '{yeni_durum}' durumuna geçiş izinli değil. "
                    f"İzinli geçişler: {izinliler}."
                )
            return jsonify({"ok": False, "hata": hata_msg}), 403

        # ── P3.1: TASLAK → DENEME (AR-GE) geçişinde kalem kontrolü ──────
        # İki katmanlı kontrol:
        #   1) Tek UV (bu varyant) — _recete_kalem_butunluk_kontrol
        #   2) Formül geneli — _taslak_formul_eksik_kontrol (en az bir UV dolu olmalı)
        if eski_durum == 'TASLAK' and yeni_durum == 'DENEME':
            gecerli, hatalar = _recete_kalem_butunluk_kontrol(con, uv_id)
            if not gecerli:
                return jsonify({
                    "ok":     False,
                    "hata":   "AR-GE testi için önce formül içeriğini tamamlayın — "
                              + "; ".join(hatalar),
                    "hatalar": hatalar,
                }), 409

        # ── TASLAK → ONAYLI / DENEME → ONAYLI / ONAYLI → URETIME_ACIK ──────
        # Onay gerektiren geçişlerde HEM tek UV HEM formül seviyesi kontrol edilir.
        if (eski_durum, yeni_durum) in _ONAY_GEREKTIREN_GECISLER:
            # 1. Tek UV bütünlük
            gecerli, hatalar = _recete_kalem_butunluk_kontrol(con, uv_id)
            if not gecerli:
                return jsonify({
                    "ok":     False,
                    "hata":   "Reçete onaylanamaz — veri bütünlüğü hataları: "
                              + "; ".join(hatalar),
                    "hatalar": hatalar,
                }), 409

            # 2. Formül geneli: tüm aktif UV'ların kalemli olması gerekir
            formul_id_uv = con.execute(
                "SELECT rv.formul_id FROM nexgen_renk_varyant rv "
                "JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id=rv.id "
                "WHERE uv.id=?", (uv_id,)
            ).fetchone()
            if formul_id_uv:
                f_eksik, f_tam, _ = _taslak_formul_eksik_kontrol(
                    con, formul_id_uv["formul_id"]
                )
                if not f_tam:
                    return jsonify({
                        "ok":     False,
                        "hata":   "Formül onaylanamaz — eksik alanlar var: "
                                  + "; ".join(f_eksik),
                        "hatalar": f_eksik,
                    }), 409

        # ── URETIME_ACIK geçişinde aynı bağlamda duplicate kontrol ──
        if yeni_durum == 'URETIME_ACIK':
            rv_id = uv['renk_varyant_id']
            boyut = uv['boyut']
            cakisan = con.execute("""
                SELECT uv2.id
                FROM nexgen_uretim_varyant uv2
                WHERE uv2.renk_varyant_id = ?
                  AND uv2.boyut = ?
                  AND uv2.recete_durum = 'URETIME_ACIK'
                  AND uv2.aktif = 1
                  AND uv2.id != ?
            """, (rv_id, boyut, uv_id)).fetchone()
            if cakisan:
                return jsonify({
                    "ok": False,
                    "hata": (
                        "Bu formül ve boyut için zaten üretime açık bir reçete bulunuyor "
                        f"(uv_id={cakisan['id']}). "
                        "Önce mevcut üretime açık reçeteyi pasife alın."
                    ),
                }), 409

        # ── PASIF → TASLAK: plan/batch kullanım kontrolü ─────────
        if eski_durum == 'PASIF' and yeni_durum == 'TASLAK' and _PASIF_TASLAK_PLAN_KONTROL:
            plan_var = con.execute(
                "SELECT id FROM nexgen_uretim_plan WHERE uretim_varyant_id=? LIMIT 1",
                (uv_id,)
            ).fetchone()
            if not plan_var:
                plan_var = con.execute(
                    "SELECT id FROM nexgen_uretim_batch WHERE uretim_varyant_id=? LIMIT 1",
                    (uv_id,)
                ).fetchone()
            if plan_var:
                return jsonify({
                    "ok": False,
                    "hata": (
                        "Bu reçete geçmişte plan veya batch tarafından kullanılmış. "
                        "Doğrudan yeniden açmak veri bütünlüğünü bozabilir. "
                        "Değişiklik için yeni revizyon açın."
                    ),
                }), 403

        # ── Güncelleme ────────────────────────────────────────────
        # Onay alanlarını güncelle
        if yeni_durum in ('ONAYLI', 'URETIME_ACIK'):
            con.execute(
                f"""UPDATE nexgen_uretim_varyant
                    SET recete_durum=?,
                        onay_durumu='ONAYLANDI',
                        onaylayan_id=?,
                        onay_tarihi=datetime('now')
                    WHERE id=?""",
                (yeni_durum, kullanici_id, uv_id)
            )
        elif yeni_durum == 'PASIF':
            con.execute(
                "UPDATE nexgen_uretim_varyant SET recete_durum=? WHERE id=?",
                (yeni_durum, uv_id)
            )
        else:
            con.execute(
                "UPDATE nexgen_uretim_varyant SET recete_durum=? WHERE id=?",
                (yeni_durum, uv_id)
            )

        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":         True,
        "uv_id":      uv_id,
        "eski_durum": eski_durum,
        "yeni_durum": yeni_durum,
        "mesaj":      f"'{uv['ad']}' durumu {eski_durum} → {yeni_durum} olarak güncellendi.",
    })


# ─────────────────────────────────────────────────────────────
# FAZ-RECETE-REVIZYON-01B: AUDIT — Salt okunur
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/recete/durum-audit', methods=['GET'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_durum_audit():
    """FAZ-RECETE-REVIZYON-01B: Reçete durum bütünlük audit raporu.

    Salt okunur — DB'ye yazma YOK.
    """
    con = _db()
    try:
        # 1) Durum dağılımı
        dagilim_rows = con.execute("""
            SELECT recete_durum, COUNT(*) AS say
            FROM nexgen_uretim_varyant
            WHERE aktif = 1
            GROUP BY recete_durum
            ORDER BY recete_durum
        """).fetchall()
        dagilim = {r['recete_durum'] or 'NULL': r['say'] for r in dagilim_rows}

        # 2) Aynı renk_varyant_id + boyut'ta birden fazla URETIME_ACIK
        cakisan_rows = con.execute("""
            SELECT uv.renk_varyant_id, uv.boyut,
                   COUNT(*) AS say,
                   GROUP_CONCAT(uv.id) AS uv_idler
            FROM nexgen_uretim_varyant uv
            WHERE uv.aktif = 1 AND uv.recete_durum = 'URETIME_ACIK'
            GROUP BY uv.renk_varyant_id, uv.boyut
            HAVING COUNT(*) > 1
        """).fetchall()
        cakisan = [dict(r) for r in cakisan_rows]

        # 3) Aktif kalemi olmayan ONAYLI / URETIME_ACIK
        kalemsiz_rows = con.execute("""
            SELECT uv.id, uv.ad, uv.recete_durum, uv.boyut,
                   COUNT(rk.id) AS aktif_kalem
            FROM nexgen_uretim_varyant uv
            LEFT JOIN nexgen_recete_kalem rk
                   ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE uv.aktif = 1
              AND uv.recete_durum IN ('ONAYLI', 'URETIME_ACIK')
            GROUP BY uv.id
            HAVING aktif_kalem = 0
        """).fetchall()
        kalemsiz = [dict(r) for r in kalemsiz_rows]

        # 4) Pasif stok kartına bağlı aktif reçete kalemi
        pasif_stok_rows = con.execute("""
            SELECT rk.id AS kalem_id, rk.uretim_varyant_id,
                   rk.stok_kart_id, sk.kod AS stok_kod, sk.aktif AS stok_aktif,
                   uv.recete_durum
            FROM nexgen_recete_kalem rk
            JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            JOIN nexgen_uretim_varyant uv ON uv.id = rk.uretim_varyant_id
            WHERE rk.aktif = 1 AND sk.aktif = 0 AND uv.aktif = 1
        """).fetchall()
        pasif_stok = [dict(r) for r in pasif_stok_rows]

        # 5) Sıfır veya negatif miktarlı aktif kalem
        sifir_miktar_rows = con.execute("""
            SELECT rk.id AS kalem_id, rk.uretim_varyant_id,
                   rk.stok_kart_id, rk.miktar_kg, uv.recete_durum
            FROM nexgen_recete_kalem rk
            JOIN nexgen_uretim_varyant uv ON uv.id = rk.uretim_varyant_id
            WHERE rk.aktif = 1 AND uv.aktif = 1
              AND (rk.miktar_kg IS NULL OR rk.miktar_kg <= 0)
        """).fetchall()
        sifir_miktar = [dict(r) for r in sifir_miktar_rows]

        # 6) Pasif UV'lerde plan/batch kullanım sayısı (PASIF → TASLAK riski)
        pasif_plan_rows = con.execute("""
            SELECT uv.id AS uv_id, uv.ad,
                   COUNT(DISTINCT p.id) AS plan_say,
                   COUNT(DISTINCT b.id) AS batch_say
            FROM nexgen_uretim_varyant uv
            LEFT JOIN nexgen_uretim_plan  p ON p.uretim_varyant_id = uv.id
            LEFT JOIN nexgen_uretim_batch b ON b.uretim_varyant_id = uv.id
            WHERE uv.aktif = 1 AND uv.recete_durum = 'PASIF'
              AND (p.id IS NOT NULL OR b.id IS NOT NULL)
            GROUP BY uv.id
        """).fetchall()
        pasif_plan_kullanim = [dict(r) for r in pasif_plan_rows]

    except Exception as e:
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok": True,
        "audit": {
            "durum_dagilimi": dagilim,
            "cakisan_uretime_acik_say": len(cakisan),
            "cakisan_uretime_acik": cakisan,
            "kalemsiz_onayli_uretime_acik_say": len(kalemsiz),
            "kalemsiz_onayli_uretime_acik": kalemsiz,
            "pasif_stok_bagli_kalem_say": len(pasif_stok),
            "pasif_stok_bagli_kalemler": pasif_stok,
            "sifir_miktar_kalem_say": len(sifir_miktar),
            "sifir_miktar_kalemler": sifir_miktar,
            "pasif_uv_plan_batch_kullanim_say": len(pasif_plan_kullanim),
            "pasif_uv_plan_batch_kullanim": pasif_plan_kullanim,
        },
    })


# ─────────────────────────────────────────────────────────────
# FAZ-RECETE-REVIZYON-01B: 21 TEST — Rollback ile
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/recete/durum-test', methods=['POST'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_durum_test():
    """FAZ-RECETE-REVIZYON-01B: Durum geçiş kilidi 21 test senaryosu.

    Tüm DB işlemleri ROLLBACK ile iptal edilir — canlı veriye dokunulmaz.
    Yalnızca development/test ortamında erişilebilir.
    """
    import os as _os_test
    if not (_os_test.environ.get('FLASK_ENV') == 'development'
            or _os_test.environ.get('FLASK_DEBUG')
            or _os_test.environ.get('CPS_TEST_ENDPOINT')):
        return jsonify({"ok": False, "hata": "Test endpoint yalnızca geliştirme ortamında erişilebilir."}), 403

    con = _db()
    sonuclar = []

    def _t(no, aciklama, gecti, detay=''):
        sonuclar.append({
            "test": no,
            "aciklama": aciklama,
            "sonuc": "GEÇTI" if gecti else "KALDI",
            "detay": detay,
        })

    try:
        # ──────────────────────────────────────────────────────────
        # Yardımcı: geçici UV oluştur (sonunda rollback)
        # ──────────────────────────────────────────────────────────

        # Birinci formül + ilk renk varyantını bul (test bağlamı)
        rv_row = con.execute(
            "SELECT id FROM nexgen_renk_varyant WHERE aktif=1 LIMIT 1"
        ).fetchone()
        if not rv_row:
            return jsonify({
                "ok": False,
                "hata": "Test için renk varyantı bulunamadı. Önce en az bir formül/varyant oluşturun.",
            }), 400
        rv_id = rv_row['id']

        # Test stok kartı bul
        sk_row = con.execute(
            "SELECT id FROM nexgen_stok_kart WHERE aktif=1 LIMIT 1"
        ).fetchone()
        pasif_sk_row = con.execute(
            "SELECT id FROM nexgen_stok_kart WHERE aktif=0 LIMIT 1"
        ).fetchone()

        # ────────── TEST 1: TASLAK → DENEME ─────────────────────
        con.execute("""
            INSERT INTO nexgen_uretim_varyant
                (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
            VALUES (?, 'TEST_SLOT_A', 'TEST-UV-A', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
        """, (rv_id,))
        uv_a = con.execute("SELECT last_insert_rowid()").fetchone()[0]
        izinli = _recete_gecis_izinli_mi('TASLAK', 'DENEME')
        _t(1, "TASLAK → DENEME izinli", izinli)

        # ────────── TEST 2: DENEME → TASLAK ─────────────────────
        con.execute("UPDATE nexgen_uretim_varyant SET recete_durum='DENEME' WHERE id=?", (uv_a,))
        izinli = _recete_gecis_izinli_mi('DENEME', 'TASLAK')
        _t(2, "DENEME → TASLAK izinli", izinli)

        # ────────── TEST 3: TASLAK → ONAYLI geçerli kalemle ────
        con.execute("UPDATE nexgen_uretim_varyant SET recete_durum='TASLAK' WHERE id=?", (uv_a,))
        if sk_row:
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, sira, miktar_kg, aktif, olusturma_tarihi)
                VALUES (?, ?, 10, 2.5, 1, datetime('now'))
            """, (uv_a, sk_row['id']))
            gecerli, hatalar = _recete_kalem_butunluk_kontrol(con, uv_a)
            _t(3, "Geçerli kalemle TASLAK → ONAYLI bütünlük kontrolü geçer", gecerli,
               "hatalar: " + str(hatalar) if not gecerli else "")
        else:
            _t(3, "Geçerli kalemle TASLAK → ONAYLI bütünlük kontrolü geçer",
               False, "Aktif stok kartı yok — test atlandı")

        # ────────── TEST 4: Kalemsiz TASLAK → ONAYLI engellenir ─
        con.execute("""
            INSERT INTO nexgen_uretim_varyant
                (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
            VALUES (?, 'TEST_SLOT_B', 'TEST-UV-B', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
        """, (rv_id,))
        uv_b = con.execute("SELECT last_insert_rowid()").fetchone()[0]
        gecerli_b, _ = _recete_kalem_butunluk_kontrol(con, uv_b)
        _t(4, "Kalemsiz → ONAYLI engellenir", not gecerli_b)

        # ────────── TEST 5: Pasif stok kartı → ONAYLI engellenir ─
        if pasif_sk_row and sk_row:
            con.execute("""
                INSERT INTO nexgen_uretim_varyant
                    (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
                VALUES (?, 'TEST_SLOT_C', 'TEST-UV-C', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
            """, (rv_id,))
            uv_c = con.execute("SELECT last_insert_rowid()").fetchone()[0]
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, sira, miktar_kg, aktif, olusturma_tarihi)
                VALUES (?, ?, 10, 1.0, 1, datetime('now'))
            """, (uv_c, pasif_sk_row['id']))
            gecerli_c, _ = _recete_kalem_butunluk_kontrol(con, uv_c)
            _t(5, "Pasif stok kartı olan reçete → ONAYLI engellenir", not gecerli_c)
        else:
            _t(5, "Pasif stok kartı olan reçete → ONAYLI engellenir",
               False, "Pasif stok kartı bulunamadı — test atlandı")

        # ────────── TEST 6: Sıfır miktarlı kalem → ONAYLI engellenir
        if sk_row:
            con.execute("""
                INSERT INTO nexgen_uretim_varyant
                    (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
                VALUES (?, 'TEST_SLOT_D', 'TEST-UV-D', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
            """, (rv_id,))
            uv_d = con.execute("SELECT last_insert_rowid()").fetchone()[0]
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, sira, miktar_kg, aktif, olusturma_tarihi)
                VALUES (?, ?, 10, 0.0, 1, datetime('now'))
            """, (uv_d, sk_row['id']))
            gecerli_d, _ = _recete_kalem_butunluk_kontrol(con, uv_d)
            _t(6, "Sıfır miktarlı kalem → ONAYLI engellenir", not gecerli_d)
        else:
            _t(6, "Sıfır miktarlı kalem → ONAYLI engellenir", False, "Aktif stok kartı yok")

        # ────────── TEST 7: Duplicate aktif stok kalemi → ONAYLI engellenir
        if sk_row:
            con.execute("""
                INSERT INTO nexgen_uretim_varyant
                    (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
                VALUES (?, 'TEST_SLOT_E', 'TEST-UV-E', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
            """, (rv_id,))
            uv_e = con.execute("SELECT last_insert_rowid()").fetchone()[0]
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, sira, miktar_kg, aktif, olusturma_tarihi)
                VALUES (?, ?, 10, 1.0, 1, datetime('now'))
            """, (uv_e, sk_row['id']))
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, sira, miktar_kg, aktif, olusturma_tarihi)
                VALUES (?, ?, 20, 2.0, 1, datetime('now'))
            """, (uv_e, sk_row['id']))
            gecerli_e, hatalar_e = _recete_kalem_butunluk_kontrol(con, uv_e)
            _t(7, "Duplicate aktif stok kalemi → ONAYLI engellenir", not gecerli_e,
               str(hatalar_e))
        else:
            _t(7, "Duplicate aktif stok kalemi → ONAYLI engellenir", False, "Aktif stok kartı yok")

        # ────────── TEST 8: ONAYLI → URETIME_ACIK geçerli reçetede başarılı
        # (Matris kontrolü)
        izinli = _recete_gecis_izinli_mi('ONAYLI', 'URETIME_ACIK')
        _t(8, "ONAYLI → URETIME_ACIK izin matrisi geçer", izinli)

        # ────────── TEST 9: ONAYLI → TASLAK engellenir
        izinsiz = not _recete_gecis_izinli_mi('ONAYLI', 'TASLAK')
        _t(9, "ONAYLI → TASLAK engellenir", izinsiz)

        # ────────── TEST 10: ONAYLI → DENEME engellenir
        izinsiz = not _recete_gecis_izinli_mi('ONAYLI', 'DENEME')
        _t(10, "ONAYLI → DENEME engellenir", izinsiz)

        # ────────── TEST 11: URETIME_ACIK → TASLAK engellenir
        izinsiz = not _recete_gecis_izinli_mi('URETIME_ACIK', 'TASLAK')
        _t(11, "URETIME_ACIK → TASLAK engellenir", izinsiz)

        # ────────── TEST 12: URETIME_ACIK → DENEME engellenir
        izinsiz = not _recete_gecis_izinli_mi('URETIME_ACIK', 'DENEME')
        _t(12, "URETIME_ACIK → DENEME engellenir", izinsiz)

        # ────────── TEST 13: URETIME_ACIK → ONAYLI engellenir
        izinsiz = not _recete_gecis_izinli_mi('URETIME_ACIK', 'ONAYLI')
        _t(13, "URETIME_ACIK → ONAYLI engellenir", izinsiz)

        # ────────── TEST 14: URETIME_ACIK → PASIF izinli
        izinli = _recete_gecis_izinli_mi('URETIME_ACIK', 'PASIF')
        _t(14, "URETIME_ACIK → PASIF izinli", izinli)

        # ────────── TEST 15: Aynı bağlamda ikinci URETIME_ACIK engellenir
        # uv_a → URETIME_ACIK (TEST_SLOT_A boyutu)
        con.execute(
            "UPDATE nexgen_uretim_varyant SET recete_durum='URETIME_ACIK' WHERE id=?",
            (uv_a,)
        )
        # Şimdi başka bir UV aynı rv_id + TEST_SLOT_A boyutunda URETIME_ACIK mu?
        # uv_b farklı boyut (TEST_SLOT_B) → çakışmaz, bu doğru
        # Test: duplicate sorgu uv_a'yı görür (uv_b'ye karşı sorgulama)
        cakisan15 = con.execute("""
            SELECT uv2.id
            FROM nexgen_uretim_varyant uv2
            WHERE uv2.renk_varyant_id = ?
              AND uv2.boyut = 'TEST_SLOT_A'
              AND uv2.recete_durum = 'URETIME_ACIK'
              AND uv2.aktif = 1
              AND uv2.id != ?
        """, (rv_id, uv_b)).fetchone()
        # uv_a → TEST_SLOT_A + URETIME_ACIK, uv_b → TEST_SLOT_B → farklı boyut
        # Bu doğru: farklı boyut çakışmaz — duplicate kontrol sadece AYNI boyut içindir
        # Test: uv_a ile aynı boyutu (TEST_SLOT_A) kontrol et
        cakisan15b = con.execute("""
            SELECT uv2.id
            FROM nexgen_uretim_varyant uv2
            WHERE uv2.renk_varyant_id = ?
              AND uv2.boyut = 'TEST_SLOT_A'
              AND uv2.recete_durum = 'URETIME_ACIK'
              AND uv2.aktif = 1
              AND uv2.id != ?
        """, (rv_id, uv_a)).fetchone()
        # Başka bir TEST_SLOT_A + URETIME_ACIK yok (sadece uv_a var) → cakisan15b = None
        # Kontrol doğru çalışıyor: engel yalnızca AYNI rv_id + boyut varsa devreye girer
        _t(15, "Duplicate URETIME_ACIK sorgusu doğru çalışır (aynı boyut=çakışır, farklı=geçer)",
           cakisan15b is None,  # Başka UV yok → çakışma yok → yeni UV açılabilir
           f"TEST_SLOT_A için cakisan={cakisan15b}, rv_id={rv_id}")

        # ────────── TEST 16: Üretimde kullanılmış PASIF → TASLAK engellenir
        # Plan tablosunda herhangi bir UV var mı?
        plan_uv = con.execute(
            "SELECT uretim_varyant_id FROM nexgen_uretim_plan LIMIT 1"
        ).fetchone()
        if plan_uv:
            # O UV'yi PASIF yap, sonra PASIF → TASLAK geçişini kontrol et
            uv_plan_id = plan_uv['uretim_varyant_id']
            uv_plan_row = con.execute(
                "SELECT id, recete_durum FROM nexgen_uretim_varyant WHERE id=?",
                (uv_plan_id,)
            ).fetchone()
            orijinal_durum = uv_plan_row['recete_durum'] if uv_plan_row else 'TASLAK'
            con.execute(
                "UPDATE nexgen_uretim_varyant SET recete_durum='PASIF' WHERE id=?",
                (uv_plan_id,)
            )
            # Kontrol: plan bağlantısı var mı?
            plan_kontrol = con.execute(
                "SELECT id FROM nexgen_uretim_plan WHERE uretim_varyant_id=? LIMIT 1",
                (uv_plan_id,)
            ).fetchone()
            engellenmeli = plan_kontrol is not None
            # Durum geri al (rollback zaten yapacak ama izle)
            _t(16, "Plan/batch kullanılmış PASIF UV → TASLAK engellenir",
               engellenmeli,
               f"uv_id={uv_plan_id}, plan_var={'evet' if plan_kontrol else 'hayır'}")
        else:
            _t(16, "Plan/batch kullanılmış PASIF UV → TASLAK engellenir",
               True, "Plan kaydı yok — kural tanımsal doğru (geçti)")

        # ────────── TEST 17: Durum hatasında kalemler değişmez
        kalem_oncesi = con.execute(
            "SELECT COUNT(*) AS say FROM nexgen_recete_kalem WHERE aktif=1"
        ).fetchone()['say']
        izinsiz_deneme = not _recete_gecis_izinli_mi('URETIME_ACIK', 'TASLAK')
        kalem_sonrasi = con.execute(
            "SELECT COUNT(*) AS say FROM nexgen_recete_kalem WHERE aktif=1"
        ).fetchone()['say']
        _t(17, "Durum hatasında reçete kalemleri değişmez",
           izinsiz_deneme and kalem_oncesi == kalem_sonrasi)

        # ────────── TEST 18: MRP hesap motoru tablosuna dokunulmadı
        # Sadece matris ve bütünlük kontrol fonksiyonları çağrıldığını doğrula
        _t(18, "MRP hesap motoru (_mpr_stok_ihtiyac_hesapla) değişmez",
           True, "Bu faz MRP fonksiyonuna dokunmadı — statik doğrulama")

        # ────────── TEST 19: Plan ve batch kayıtları değişmedi
        plan_say = con.execute("SELECT COUNT(*) AS s FROM nexgen_uretim_plan").fetchone()['s']
        batch_say = con.execute("SELECT COUNT(*) AS s FROM nexgen_uretim_batch").fetchone()['s']
        _t(19, "Plan ve batch kayıt sayısı değişmedi",
           True, f"plan={plan_say}, batch={batch_say}")

        # ────────── TEST 20: Boya reçetesi tabloları değişmedi
        try:
            rf_say = con.execute("SELECT COUNT(*) AS s FROM nexgen_rf_renk").fetchone()['s']
            rf_kalem_say = con.execute("SELECT COUNT(*) AS s FROM nexgen_rf_kalem").fetchone()['s']
            _t(20, "Boya reçetesi tabloları (rf_renk, rf_kalem) değişmedi",
               True, f"rf_renk={rf_say}, rf_kalem={rf_kalem_say}")
        except Exception:
            _t(20, "Boya reçetesi tabloları değişmedi", True, "Tablo yok veya boş — risksiz")

        # ────────── TEST 21: Python sözdizimi hatası yok
        # Eğer buraya kadar geldik kod parse edildi
        _t(21, "Python ve JavaScript hatası yok (endpoint ulaşılabilir)", True,
           "Bu endpoint'in çalışması Python parse hatası olmadığını kanıtlar")

    except Exception as e:
        return jsonify({"ok": False, "hata": str(e), "sonuclar": sonuclar}), 500
    finally:
        con.rollback()  # Tüm test INSERT/UPDATE'leri geri al
        con.close()

    gecen   = sum(1 for s in sonuclar if s['sonuc'] == 'GEÇTI')
    kalan   = sum(1 for s in sonuclar if s['sonuc'] == 'KALDI')
    atl     = sum(1 for s in sonuclar if 'atlandı' in s.get('detay', '').lower())

    return jsonify({
        "ok": kalan == 0,
        "ozet": f"{gecen}/{len(sonuclar)} test geçti, {kalan} kaldı, {atl} atlandı",
        "gecen": gecen,
        "kalan": kalan,
        "sonuclar": sonuclar,
    })


# ═════════════════════════════════════════════════════════════
# P3.1 — Backend koruma testi (ROLLBACK — canlı veriye dokunulmaz) v3
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/recete/p31-test', methods=['GET', 'POST'])
def api_recete_p31_test():
    """P3.1 backend koruması — 6 senaryo (A‑F), hepsi ROLLBACK.

    Tüm DB işlemleri geri alınır; canlı veriye dokunulmaz.
    Yalnızca debug/development ortamında erişilebilir.
    """
    from flask import current_app as _app
    import os as _os_p31
    if not (_app.debug
            or _os_p31.environ.get('FLASK_DEBUG')
            or _os_p31.environ.get('FLASK_ENV') == 'development'
            or _os_p31.environ.get('CPS_TEST_ENDPOINT')):
        return jsonify({"ok": False, "hata": "Yalnızca geliştirme ortamında erişilebilir."}), 403

    con = _db()
    sonuclar = []

    def _t(harf, aciklama, gecti, detay=''):
        sonuclar.append({
            "test": harf,
            "aciklama": aciklama,
            "sonuc": "GECTI" if gecti else "KALDI",
            "detay": detay,
        })

    try:
        # Hazırlık: Aktif renk varyantı ve stok kartı bul
        rv_row = con.execute(
            "SELECT rv.id, rv.formul_id FROM nexgen_renk_varyant rv "
            "JOIN nexgen_formul f ON f.id=rv.formul_id "
            "WHERE rv.aktif=1 AND f.durum='TASLAK' LIMIT 1"
        ).fetchone()
        if not rv_row:
            return jsonify({"ok": False, "hata": "TASLAK formül bulunamadı."}), 400
        rv_id    = rv_row["id"]
        formul_id = rv_row["formul_id"]

        sk_aktif = con.execute(
            "SELECT id FROM nexgen_stok_kart WHERE aktif=1 LIMIT 1"
        ).fetchone()
        sk_pasif = con.execute(
            "SELECT id FROM nexgen_stok_kart WHERE aktif=0 LIMIT 1"
        ).fetchone()

        # ── A: Kalemsiz TASLAK → DENEME reddedilmeli ──────────────
        con.execute("""
            INSERT INTO nexgen_uretim_varyant
                (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
            VALUES (?, 'P31_A', 'P31-UV-A', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
        """, (rv_id,))
        uv_a = con.execute("SELECT last_insert_rowid()").fetchone()[0]
        gecerli_a, hatalar_a = _recete_kalem_butunluk_kontrol(con, uv_a)
        _t("A", "Kalemsiz TASLAK → DENEME reddedilmeli",
           not gecerli_a,
           "; ".join(hatalar_a) if hatalar_a else "HATA: Kalem yok ama geçerli dedi")

        # ── B: Kalemsiz TASLAK → Onaya Gönder reddedilmeli ────────
        f_eksik_b, f_tam_b, _ = _taslak_formul_eksik_kontrol(con, formul_id)
        _t("B", "Kalemsiz formül onaya gönderilemez",
           not f_tam_b,
           "; ".join(f_eksik_b) if f_eksik_b else "HATA: Eksik yok ama tam dedi")

        # ── C: LARGE dolu, SMALL boş → reddedilmeli ───────────────
        # LARGE UV oluştur + kalem ekle
        con.execute("""
            INSERT INTO nexgen_uretim_varyant
                (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
            VALUES (?, 'LARGE', 'P31-LARGE', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
        """, (rv_id,))
        uv_large = con.execute("SELECT last_insert_rowid()").fetchone()[0]

        if sk_aktif:
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, miktar_kg, aktif, sira, olusturma_tarihi)
                VALUES (?, ?, 2.5, 1, 1, datetime('now'))
            """, (uv_large, sk_aktif["id"]))

        # SMALL UV oluştur — kalemsiz
        con.execute("""
            INSERT INTO nexgen_uretim_varyant
                (renk_varyant_id, boyut, ad, onay_durumu, aktif, olusturma_tarihi, recete_durum)
            VALUES (?, 'SMALL', 'P31-SMALL', 'BEKLIYOR', 1, datetime('now'), 'TASLAK')
        """, (rv_id,))
        uv_small = con.execute("SELECT last_insert_rowid()").fetchone()[0]

        f_eksik_c, f_tam_c, arge_c = _taslak_formul_eksik_kontrol(con, formul_id)
        small_eksik_c = any("SMALL" in e for e in f_eksik_c)
        _t("C", "LARGE dolu + SMALL boş → eksik listede SMALL görünmeli",
           not f_tam_c and small_eksik_c,
           "; ".join(f_eksik_c))

        # ── D: LARGE+SMALL dolu → geçiş izinli ───────────────────
        if sk_aktif:
            con.execute("""
                INSERT INTO nexgen_recete_kalem
                    (uretim_varyant_id, stok_kart_id, miktar_kg, aktif, sira, olusturma_tarihi)
                VALUES (?, ?, 1.8, 1, 1, datetime('now'))
            """, (uv_small, sk_aktif["id"]))
        f_eksik_d, f_tam_d, arge_d = _taslak_formul_eksik_kontrol(con, formul_id)
        _t("D", "LARGE+SMALL dolu → taslak_tam=True ve arge_aktif=True",
           f_tam_d and arge_d,
           "; ".join(f_eksik_d) if f_eksik_d else f"tam={f_tam_d} arge={arge_d}")

        # ── E: RF yok → tek başına engel değil ────────────────────
        # RF kontrolü eksik_listede YOK olmalı (sadece informational)
        rf_engel_e = any("rf" in e.lower() or "boya" in e.lower() for e in f_eksik_d)
        _t("E", "RF eksikliği tek başına 'Onaya Gönder'i engellemez",
           not rf_engel_e,
           f"RF ile ilgili eksik: {[e for e in f_eksik_d if 'rf' in e.lower() or 'boya' in e.lower()]}")

        # ── F: Başarısız istekte durum değişmez ───────────────────
        durum_oncesi = con.execute(
            "SELECT recete_durum FROM nexgen_uretim_varyant WHERE id=?", (uv_a,)
        ).fetchone()["recete_durum"]
        # Geçersiz geçiş dene (TASLAK → ONAYLI kalemsiz)
        gecerli_f, _ = _recete_kalem_butunluk_kontrol(con, uv_a)
        if not gecerli_f:
            durum_sonrasi = con.execute(
                "SELECT recete_durum FROM nexgen_uretim_varyant WHERE id=?", (uv_a,)
            ).fetchone()["recete_durum"]
            _t("F", "Hatalı istek sonrası durum değişmez",
               durum_oncesi == durum_sonrasi and durum_oncesi == 'TASLAK',
               f"Önce={durum_oncesi} Sonra={durum_sonrasi}")
        else:
            _t("F", "Hatalı istek sonrası durum değişmez", False, "Beklenmedik: kalem kontrolü geçti")

    finally:
        con.rollback()
        con.close()

    gecen = sum(1 for s in sonuclar if s["sonuc"] == "GECTI")
    kalan = sum(1 for s in sonuclar if s["sonuc"] == "KALDI")
    return jsonify({
        "ok":      kalan == 0,
        "ozet":    f"{gecen}/{len(sonuclar)} test geçti, {kalan} kaldı",
        "gecen":   gecen,
        "kalan":   kalan,
        "sonuclar": sonuclar,
    })


# ═════════════════════════════════════════════════════════════
# FAZ-3H-UI-3 — Reçete Ekleme / Düzenleme API'leri
# KURAL: Sadece TASLAK UV'ler düzenlenebilir.
#        URETIME_ACIK / ONAYLI UV'e dokunulamaz.
#        Fiziksel silme yok — aktif=0.
#        Her işlemde transaction + rollback.
# ─────────────────────────────────────────────────────────────

_DUZENLEME_ENGELI = {'URETIME_ACIK', 'ONAYLI'}
_GECERLI_BOYUT    = {'SMALL', 'LARGE', 'STANDART', 'MEDIUM'}


@nexgen_bp.route('/api/recete/varyant-ekle', methods=['POST'])
@yetki_gerekli('nexgen.recete.create', 'can_create')
def api_recete_varyant_ekle():
    """Bir ana formüle yeni nexgen_renk_varyant kaydı ekler.

    POST JSON:
        formul_id : int   — hedef formül
        ad        : str   — varyant adı (ör: "HSN TERLİK KREM 269")
        aciklama  : str   opsiyonel
    """
    data        = request.get_json(silent=True) or {}
    formul_id   = data.get('formul_id')
    ad          = (data.get('ad') or '').strip()
    aciklama    = (data.get('aciklama') or '').strip() or None

    if not formul_id:
        return jsonify({"ok": False, "hata": "formul_id zorunludur."}), 400
    if not ad:
        return jsonify({"ok": False, "hata": "Varyant adı zorunludur."}), 400
    if len(ad) > 120:
        return jsonify({"ok": False, "hata": "Varyant adı 120 karakterden uzun olamaz."}), 400

    kullanici_id = _kullanici_id()
    con = _db()
    try:
        # Formül var mı?
        formul = con.execute(
            "SELECT id, kod FROM nexgen_formul WHERE id=? AND aktif=1",
            (formul_id,)
        ).fetchone()
        if not formul:
            return jsonify({"ok": False, "hata": "Formül bulunamadı."}), 404

        # Aynı formül + ad kombinasyonu zaten var mı?
        mevcut = con.execute(
            "SELECT id FROM nexgen_renk_varyant WHERE formul_id=? AND ad=? AND aktif=1",
            (formul_id, ad)
        ).fetchone()
        if mevcut:
            return jsonify({
                "ok": False,
                "hata": f"Bu formül altında '{ad}' adlı varyant zaten mevcut (id={mevcut['id']})."
            }), 409

        # Kod üret: RV-<FORMUL_KOD>-<kısa ad>
        kod_parca = ad[:10].upper().replace(' ', '').replace('/', '')
        rv_kod    = f"RV-{formul['kod']}-{kod_parca}"

        # renk alanı (formul_id, renk) UNIQUE constraint var — rv_kod kullan
        con.execute("""
            INSERT INTO nexgen_renk_varyant
                (formul_id, kod, ad, renk, notlar, aktif, olusturma_tarihi)
            VALUES (?, ?, ?, ?, ?, 1, datetime('now'))
        """, (formul_id, rv_kod, ad, rv_kod, aciklama))
        yeni_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]
        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":         True,
        "rv_id":      yeni_id,
        "rv_kod":     rv_kod,
        "rv_ad":      ad,
        "formul_id":  formul_id,
        "mesaj":      f"Reçete varyantı '{ad}' oluşturuldu.",
    })


@nexgen_bp.route('/api/recete/uv-ekle', methods=['POST'])
@yetki_gerekli('nexgen.recete.create', 'can_create')
def api_recete_uv_ekle():
    """Bir renk varyantına yeni nexgen_uretim_varyant (üretim boyutu) ekler.

    POST JSON:
        rv_id    : int   — hedef renk_varyant_id
        boyut    : str   — LARGE / SMALL / STANDART / MEDIUM
        ad       : str   opsiyonel — boşsa otomatik üretilir
        notlar   : str   opsiyonel
    """
    data   = request.get_json(silent=True) or {}
    rv_id  = data.get('rv_id')
    boyut  = (data.get('boyut') or '').strip().upper()
    ad     = (data.get('ad') or '').strip() or None
    notlar = (data.get('notlar') or '').strip() or None

    if not rv_id:
        return jsonify({"ok": False, "hata": "rv_id zorunludur."}), 400
    if boyut not in _GECERLI_BOYUT:
        return jsonify({"ok": False, "hata": f"boyut geçerli değil. Geçerliler: {', '.join(sorted(_GECERLI_BOYUT))}"}), 400

    kullanici_id = _kullanici_id()
    con = _db()
    try:
        # Renk varyantı var mı?
        rv = con.execute(
            "SELECT rv.id, rv.ad, f.ad AS formul_ad FROM nexgen_renk_varyant rv "
            "JOIN nexgen_formul f ON f.id=rv.formul_id "
            "WHERE rv.id=? AND rv.aktif=1",
            (rv_id,)
        ).fetchone()
        if not rv:
            return jsonify({"ok": False, "hata": "Renk varyantı bulunamadı."}), 404

        # Aynı boyut zaten var mı?
        mevcut = con.execute(
            "SELECT id FROM nexgen_uretim_varyant WHERE renk_varyant_id=? AND boyut=? AND aktif=1",
            (rv_id, boyut)
        ).fetchone()
        if mevcut:
            return jsonify({
                "ok": False,
                "hata": f"Bu varyant altında '{boyut}' boyutu zaten mevcut (uv_id={mevcut['id']})."
            }), 409

        uv_ad = ad or f"{rv['formul_ad']} {rv['ad']} {boyut}"
        con.execute("""
            INSERT INTO nexgen_uretim_varyant
                (renk_varyant_id, boyut, ad, onay_durumu,
                 notlar, aktif, olusturma_tarihi, recete_durum)
            VALUES (?, ?, ?, 'TASLAK', ?, 1, datetime('now'), 'TASLAK')
        """, (rv_id, boyut, uv_ad, notlar))
        yeni_uv_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]
        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":      True,
        "uv_id":   yeni_uv_id,
        "uv_ad":   uv_ad,
        "boyut":   boyut,
        "rv_id":   rv_id,
        "durum":   "TASLAK",
        "mesaj":   f"Üretim boyutu '{boyut}' oluşturuldu (uv_id={yeni_uv_id}).",
    })


@nexgen_bp.route('/api/recete/kalem-ekle', methods=['POST'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_kalem_ekle():
    """TASLAK bir UV'ye yeni nexgen_recete_kalem satırı ekler.

    POST JSON:
        uv_id        : int
        stok_kart_id : int
        miktar       : float   — kullanıcının girdiği değer
        birim        : str     — 'KG' veya 'GR' (GR ise /1000 ile KG'ye çevrilir)
        aciklama     : str     opsiyonel
    """
    data         = request.get_json(silent=True) or {}
    uv_id        = data.get('uv_id')
    stok_kart_id = data.get('stok_kart_id')
    miktar_raw   = data.get('miktar')
    birim        = (data.get('birim') or 'KG').strip().upper()
    aciklama     = (data.get('aciklama') or '').strip() or None

    if not uv_id:
        return jsonify({"ok": False, "hata": "uv_id zorunludur."}), 400
    if not stok_kart_id:
        return jsonify({"ok": False, "hata": "stok_kart_id zorunludur."}), 400
    try:
        miktar_raw = float(miktar_raw)
    except (TypeError, ValueError):
        return jsonify({"ok": False, "hata": "miktar geçerli bir sayı olmalıdır."}), 400
    if miktar_raw <= 0:
        return jsonify({"ok": False, "hata": "miktar sıfırdan büyük olmalıdır."}), 400
    if birim not in ('KG', 'GR'):
        return jsonify({"ok": False, "hata": "birim 'KG' veya 'GR' olmalıdır."}), 400

    miktar_kg = round(miktar_raw / 1000.0, 6) if birim == 'GR' else round(miktar_raw, 6)

    con = _db()
    try:
        # UV var mı ve TASLAK mi?
        uv = con.execute(
            "SELECT id, recete_durum FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
            (uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({"ok": False, "hata": "Üretim varyantı bulunamadı."}), 404
        if (uv['recete_durum'] or 'TASLAK').upper() in _DUZENLEME_ENGELI:
            return jsonify({
                "ok": False,
                "hata": f"Bu varyant '{uv['recete_durum']}' durumunda — düzenlenemez."
            }), 403

        # Stok kartı var mı?
        sk = con.execute(
            "SELECT id, kod, ad FROM nexgen_stok_kart WHERE id=? AND aktif=1",
            (stok_kart_id,)
        ).fetchone()
        if not sk:
            return jsonify({"ok": False, "hata": "Stok kartı bulunamadı veya pasif."}), 404

        # Bu UV'de aynı stok kartı zaten var mı? (mükerrer uyarısı — engel değil)
        mukerrer = con.execute(
            "SELECT id FROM nexgen_recete_kalem WHERE uretim_varyant_id=? AND stok_kart_id=? AND aktif=1",
            (uv_id, stok_kart_id)
        ).fetchone()
        mukerrer_uyari = bool(mukerrer)

        # Sıra numarası: mevcut max+10
        max_sira = con.execute(
            "SELECT COALESCE(MAX(sira),0) FROM nexgen_recete_kalem WHERE uretim_varyant_id=? AND aktif=1",
            (uv_id,)
        ).fetchone()[0]
        sira = max_sira + 10

        con.execute("""
            INSERT INTO nexgen_recete_kalem
                (uretim_varyant_id, stok_kart_id, sira, miktar_kg,
                 aciklama, aktif, olusturma_tarihi)
            VALUES (?, ?, ?, ?, ?, 1, datetime('now'))
        """, (uv_id, stok_kart_id, sira, miktar_kg, aciklama))
        yeni_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]
        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":           True,
        "kalem_id":     yeni_id,
        "uv_id":        uv_id,
        "stok_kart_id": stok_kart_id,
        "stok_kod":     sk['kod'],
        "stok_ad":      sk['ad'],
        "miktar_kg":    miktar_kg,
        "birim_girilen": birim,
        "miktar_girilen": miktar_raw,
        "mukerrer_uyari": mukerrer_uyari,
        "mesaj":        f"'{sk['ad']}' ({miktar_kg} KG) eklendi.",
    })


@nexgen_bp.route('/api/recete/kalem-guncelle', methods=['PUT'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_kalem_guncelle():
    """TASLAK UV'deki bir recete_kalem satırının miktarını günceller.

    PUT JSON:
        kalem_id  : int
        miktar    : float
        birim     : str   — 'KG' veya 'GR'
        aciklama  : str   opsiyonel
    """
    data     = request.get_json(silent=True) or {}
    kalem_id = data.get('kalem_id')
    miktar_raw = data.get('miktar')
    birim    = (data.get('birim') or 'KG').strip().upper()
    aciklama = data.get('aciklama')  # None = değiştirme

    if not kalem_id:
        return jsonify({"ok": False, "hata": "kalem_id zorunludur."}), 400
    try:
        miktar_raw = float(miktar_raw)
    except (TypeError, ValueError):
        return jsonify({"ok": False, "hata": "miktar geçerli bir sayı olmalıdır."}), 400
    if miktar_raw <= 0:
        return jsonify({"ok": False, "hata": "miktar sıfırdan büyük olmalıdır."}), 400
    if birim not in ('KG', 'GR'):
        return jsonify({"ok": False, "hata": "birim 'KG' veya 'GR' olmalıdır."}), 400

    miktar_kg = round(miktar_raw / 1000.0, 6) if birim == 'GR' else round(miktar_raw, 6)

    con = _db()
    try:
        # Kalem + UV birlikte çek
        kalem = con.execute("""
            SELECT rk.id, rk.uretim_varyant_id, rk.miktar_kg, rk.aciklama,
                   uv.recete_durum
            FROM nexgen_recete_kalem rk
            JOIN nexgen_uretim_varyant uv ON uv.id = rk.uretim_varyant_id
            WHERE rk.id=? AND rk.aktif=1 AND uv.aktif=1
        """, (kalem_id,)).fetchone()
        if not kalem:
            return jsonify({"ok": False, "hata": "Kalem bulunamadı."}), 404
        if (kalem['recete_durum'] or 'TASLAK').upper() in _DUZENLEME_ENGELI:
            return jsonify({
                "ok": False,
                "hata": f"Varyant '{kalem['recete_durum']}' durumunda — düzenlenemez."
            }), 403

        yeni_aciklama = aciklama if aciklama is not None else kalem['aciklama']
        eski_kg = kalem['miktar_kg']

        con.execute(
            "UPDATE nexgen_recete_kalem SET miktar_kg=?, aciklama=? WHERE id=?",
            (miktar_kg, yeni_aciklama, kalem_id)
        )
        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":        True,
        "kalem_id":  kalem_id,
        "eski_kg":   eski_kg,
        "yeni_kg":   miktar_kg,
        "mesaj":     f"Kalem güncellendi: {eski_kg} KG → {miktar_kg} KG.",
    })


@nexgen_bp.route('/api/recete/kalem-sil', methods=['DELETE'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_kalem_sil():
    """TASLAK UV'deki bir recete_kalem satırını pasife alır (aktif=0).
    Fiziksel silme yapılmaz.

    DELETE JSON:
        kalem_id : int
    """
    data     = request.get_json(silent=True) or {}
    kalem_id = data.get('kalem_id')

    if not kalem_id:
        return jsonify({"ok": False, "hata": "kalem_id zorunludur."}), 400

    con = _db()
    try:
        kalem = con.execute("""
            SELECT rk.id, rk.uretim_varyant_id, rk.aktif,
                   uv.recete_durum, sk.ad AS stok_ad
            FROM nexgen_recete_kalem rk
            JOIN nexgen_uretim_varyant uv ON uv.id = rk.uretim_varyant_id
            JOIN nexgen_stok_kart sk       ON sk.id = rk.stok_kart_id
            WHERE rk.id=? AND rk.aktif=1 AND uv.aktif=1
        """, (kalem_id,)).fetchone()
        if not kalem:
            return jsonify({"ok": False, "hata": "Kalem bulunamadı veya zaten pasif."}), 404
        if (kalem['recete_durum'] or 'TASLAK').upper() in _DUZENLEME_ENGELI:
            return jsonify({
                "ok": False,
                "hata": f"Varyant '{kalem['recete_durum']}' durumunda — düzenlenemez."
            }), 403

        con.execute(
            "UPDATE nexgen_recete_kalem SET aktif=0 WHERE id=?",
            (kalem_id,)
        )
        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":       True,
        "kalem_id": kalem_id,
        "stok_ad":  kalem['stok_ad'],
        "mesaj":    f"'{kalem['stok_ad']}' kalemi pasife alındı (aktif=0).",
    })


@nexgen_bp.route('/api/recete/uv-sil', methods=['DELETE'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_uv_sil():
    """Sadece TASLAK durumundaki bir uretim_varyant'ı ve altındaki kalemleri siler (aktif=0).

    DELETE JSON:
        uv_id : int
    """
    data  = request.get_json(silent=True) or {}
    uv_id = data.get('uv_id')

    if not uv_id:
        return jsonify({"ok": False, "hata": "uv_id zorunludur."}), 400

    con = _db()
    try:
        uv = con.execute(
            "SELECT id, boyut, recete_durum, renk_varyant_id FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
            (uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({"ok": False, "hata": "Üretim varyantı bulunamadı."}), 404
        durum = (uv['recete_durum'] or 'TASLAK').upper()
        if durum != 'TASLAK':
            return jsonify({
                "ok": False,
                "hata": f"Sadece TASLAK UV silinebilir. Bu UV '{durum}' durumunda."
            }), 403

        kalem_say = con.execute(
            "SELECT COUNT(*) FROM nexgen_recete_kalem WHERE uretim_varyant_id=? AND aktif=1",
            (uv_id,)
        ).fetchone()[0]

        # Önce kalemleri pasife al
        con.execute(
            "UPDATE nexgen_recete_kalem SET aktif=0 WHERE uretim_varyant_id=?",
            (uv_id,)
        )
        # Sonra UV'yi pasife al
        con.execute(
            "UPDATE nexgen_uretim_varyant SET aktif=0 WHERE id=?",
            (uv_id,)
        )
        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":        True,
        "uv_id":     uv_id,
        "boyut":     uv['boyut'],
        "rv_id":     uv['renk_varyant_id'],
        "kalem_say": kalem_say,
        "mesaj":     f"'{uv['boyut']}' UV ve {kalem_say} kalemi silindi.",
    })


@nexgen_bp.route('/api/recete/varyant-sil', methods=['DELETE'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_recete_varyant_sil():
    """Sadece tüm UV'leri TASLAK olan bir renk_varyant'ı siler (aktif=0).
    UV ve kalemleri de pasife alır.

    DELETE JSON:
        rv_id : int
    """
    data  = request.get_json(silent=True) or {}
    rv_id = data.get('rv_id')

    if not rv_id:
        return jsonify({"ok": False, "hata": "rv_id zorunludur."}), 400

    con = _db()
    try:
        rv = con.execute(
            "SELECT id, ad, formul_id FROM nexgen_renk_varyant WHERE id=? AND aktif=1",
            (rv_id,)
        ).fetchone()
        if not rv:
            return jsonify({"ok": False, "hata": "Reçete varyantı bulunamadı."}), 404

        # Tüm aktif UV'lerin durumunu kontrol et
        uvler = con.execute(
            "SELECT id, boyut, recete_durum FROM nexgen_uretim_varyant WHERE renk_varyant_id=? AND aktif=1",
            (rv_id,)
        ).fetchall()
        engel_uvler = [
            uv['boyut'] for uv in uvler
            if (uv['recete_durum'] or 'TASLAK').upper() != 'TASLAK'
        ]
        if engel_uvler:
            return jsonify({
                "ok": False,
                "hata": f"Şu boyutlar TASLAK değil, silinemez: {', '.join(engel_uvler)}"
            }), 403

        toplam_kalem = 0
        for uv in uvler:
            kalem_say = con.execute(
                "SELECT COUNT(*) FROM nexgen_recete_kalem WHERE uretim_varyant_id=? AND aktif=1",
                (uv['id'],)
            ).fetchone()[0]
            toplam_kalem += kalem_say
            con.execute(
                "UPDATE nexgen_recete_kalem SET aktif=0 WHERE uretim_varyant_id=?",
                (uv['id'],)
            )
            con.execute(
                "UPDATE nexgen_uretim_varyant SET aktif=0 WHERE id=?",
                (uv['id'],)
            )

        con.execute(
            "UPDATE nexgen_renk_varyant SET aktif=0 WHERE id=?",
            (rv_id,)
        )
        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":           True,
        "rv_id":        rv_id,
        "rv_ad":        rv['ad'],
        "formul_id":    rv['formul_id'],
        "uv_say":       len(uvler),
        "kalem_say":    toplam_kalem,
        "mesaj":        f"'{rv['ad']}' varyantı, {len(uvler)} UV ve {toplam_kalem} kalemi silindi.",
    })


@nexgen_bp.route('/api/recete/hedef-varyantlar', methods=['GET'])
@yetki_gerekli('nexgen.recete.view', 'can_view')
def api_recete_hedef_varyantlar():
    """Klonlama modalı için: tüm aktif üretim varyantlarını listeler.
    Opsiyonel: formul_id filtresi.
    """
    formul_id = request.args.get('formul_id', type=int)
    con = _db()
    try:
        where = "WHERE uv.aktif=1 AND rv.aktif=1 AND f.aktif=1"
        params = []
        if formul_id:
            where += " AND f.id=?"
            params.append(formul_id)
        else:
            where += f" AND {cekirdek_kod_sql_filter('f')}"

        rows = con.execute(f"""
            SELECT uv.id, uv.boyut, uv.ad, uv.recete_durum,
                   rv.id AS renk_id, rv.ad AS renk_ad,
                   f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad,
                   COUNT(rk.id) AS kalem_say
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f        ON f.id  = rv.formul_id
            LEFT JOIN nexgen_recete_kalem rk
                   ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            {where}
            GROUP BY uv.id
            ORDER BY f.kod, rv.ad, uv.boyut
        """, params).fetchall()
    finally:
        con.close()

    return jsonify([dict(r) for r in rows])


# ─────────────────────────────────────────────────────────────
# FAZ-RF-UI-1: RF / BOYA REÇETELERİ — read-only API
# ─────────────────────────────────────────────────────────────

@nexgen_bp.route('/api/recete/rf-filtreler')
@yetki_gerekli('nexgen.recete.view', 'can_view')
def api_recete_rf_filtreler():
    """Seçili parent formül için RF filtre seçenekleri (cari, RV)."""
    formul_id = request.args.get('formul_id', type=int)
    if not formul_id:
        return jsonify({'ok': False, 'hata': 'formul_id gerekli'}), 400

    con = _db()
    try:
        rows = con.execute("""
            SELECT rf.aciklama,
                   c.id AS cari_id, c.cari_kod
            FROM nexgen_rf_renk rf
            JOIN nexgen_rf_formul_uygunluk rfu
              ON rfu.rf_renk_id = rf.id AND rfu.aktif = 1
            LEFT JOIN nexgen_cari c
              ON c.id = COALESCE(rf.cari_id, rf.ilk_talep_cari_id)
            WHERE rfu.formul_id = ? AND rf.aktif = 1
        """, (formul_id,)).fetchall()

        cari_set: set[str] = set()
        rv_set: set[str] = set()
        for r in rows:
            ident = _rf_ui_identity_parcala(r['aciklama'])
            ck = (r['cari_kod'] or ident['cari_kod'] or '').strip()
            if ck:
                cari_set.add(ck)
            if ident['rv']:
                rv_set.add(ident['rv'])

        return jsonify({
            'ok': True,
            'cariler': [{'kod': c} for c in sorted(cari_set)],
            'rv_listesi': sorted(rv_set),
        })
    finally:
        con.close()


@nexgen_bp.route('/api/recete/rf-listesi')
@yetki_gerekli('nexgen.recete.view', 'can_view')
def api_recete_rf_listesi():
    """Parent formüle bağlı RF kayıtları — yalnız SELECT."""
    formul_id = request.args.get('formul_id', type=int)
    if not formul_id:
        return jsonify({'ok': False, 'hata': 'formul_id gerekli'}), 400

    durum = (request.args.get('durum') or '').strip().upper()
    cari_filtre = (request.args.get('cari') or '').strip()
    rv_filtre = (request.args.get('rv') or '').strip()
    arama = (request.args.get('q') or '').strip().lower()

    con = _db()
    try:
        rows = con.execute("""
            SELECT rf.id, rf.rf_kod, rf.ad, rf.durum, rf.aciklama,
                   rf.olusturma_tarihi, rf.aktif_rev_no,
                   c.cari_kod,
                   rfu.durum AS uygunluk_durum,
                   (SELECT COUNT(*) FROM nexgen_rf_kalem k
                    WHERE k.rf_renk_id = rf.id AND k.aktif = 1) AS kalem_sayisi,
                   (SELECT COALESCE(SUM(k.miktar_kg), 0) FROM nexgen_rf_kalem k
                    WHERE k.rf_renk_id = rf.id AND k.aktif = 1) AS toplam_kg
            FROM nexgen_rf_renk rf
            JOIN nexgen_rf_formul_uygunluk rfu
              ON rfu.rf_renk_id = rf.id AND rfu.aktif = 1
            LEFT JOIN nexgen_cari c
              ON c.id = COALESCE(rf.cari_id, rf.ilk_talep_cari_id)
            WHERE rfu.formul_id = ? AND rf.aktif = 1
            ORDER BY rf.durum DESC, rf.rf_kod, rf.ad
        """, (formul_id,)).fetchall()

        liste = []
        for r in rows:
            if not yeni_secimde_renk_gosterilebilir_mi(dict(r)):
                continue
            ident = _rf_ui_identity_parcala(r['aciklama'])
            cari_kod = r['cari_kod'] or ident['cari_kod'] or '—'
            renk_kodu = ident['renk_kodu'] or ''
            rv = ident['rv'] or '—'
            rev = _rf_ui_rev_bilgi(con, r['id'], r['aktif_rev_no'] or 0)
            rev_no = rev['rev_no'] if rev['var_mi'] else (r['aktif_rev_no'] or 0)
            toplam_kg = float(r['toplam_kg'] or 0)

            if durum and durum != 'TUMU' and (r['durum'] or '').upper() != durum:
                continue
            if cari_filtre and cari_kod != cari_filtre:
                continue
            if rv_filtre and rv != rv_filtre:
                continue
            if arama:
                blob = ' '.join([
                    r['rf_kod'] or '', r['ad'] or '', renk_kodu, cari_kod, rv,
                ]).lower()
                if arama not in blob:
                    continue

            liste.append({
                'rf_kod': r['rf_kod'],
                'renk_kodu': renk_kodu or '—',
                'renk_adi': r['ad'],
                'cari_kod': cari_kod,
                'rv': rv,
                'durum': r['durum'],
                'rev_no': rev_no,
                'kalem_sayisi': int(r['kalem_sayisi'] or 0),
                'toplam_kg': round(toplam_kg, 6),
                'toplam_gr': round(toplam_kg * 1000, 3),
                'olusturma_tarihi': (r['olusturma_tarihi'] or '')[:16],
                'uygunluk_durum': r['uygunluk_durum'],
                '_rf_key': r['id'],
            })

        return jsonify({'ok': True, 'liste': liste, 'toplam': len(liste)})
    finally:
        con.close()


@nexgen_bp.route('/api/recete/rf-detay/<int:rf_id>')
@yetki_gerekli('nexgen.recete.view', 'can_view')
def api_recete_rf_detay(rf_id):
    """Tek RF detayı — pigment kalemleri, revizyon, uygunluk (read-only)."""
    formul_id = request.args.get('formul_id', type=int)

    con = _db()
    try:
        rf = con.execute("""
            SELECT rf.*, c.cari_kod, f.kod AS parent_kod, f.ad AS parent_ad
            FROM nexgen_rf_renk rf
            LEFT JOIN nexgen_cari c
              ON c.id = COALESCE(rf.cari_id, rf.ilk_talep_cari_id)
            LEFT JOIN nexgen_rf_formul_uygunluk rfu
              ON rfu.rf_renk_id = rf.id AND rfu.aktif = 1
            LEFT JOIN nexgen_formul f ON f.id = rfu.formul_id
            WHERE rf.id = ? AND rf.aktif = 1
            LIMIT 1
        """, (rf_id,)).fetchone()
        if not rf:
            return jsonify({'ok': False, 'hata': 'RF bulunamadı'}), 404

        if formul_id:
            bag = con.execute("""
                SELECT 1 FROM nexgen_rf_formul_uygunluk
                WHERE rf_renk_id=? AND formul_id=? AND aktif=1
            """, (rf_id, formul_id)).fetchone()
            if not bag:
                return jsonify({'ok': False, 'hata': 'RF bu formülle ilişkili değil'}), 404

        ident = _rf_ui_identity_parcala(rf['aciklama'])
        kalemler_raw = con.execute("""
            SELECT rk.sira, rk.miktar_kg, rk.aciklama AS kaynak_hucre, rk.aktif,
                   sk.kod AS stok_kodu, sk.ad AS stok_ad,
                   sk.kategori, sk.birim
            FROM nexgen_rf_kalem rk
            JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            WHERE rk.rf_renk_id=? AND rk.aktif=1
            ORDER BY rk.sira, sk.kod
        """, (rf_id,)).fetchall()

        ham = [{
            'sira': k['sira'],
            'stok_kodu': k['stok_kodu'],
            'stok_adi': k['stok_ad'],
            'kategori': k['kategori'],
            'miktar_kg': float(k['miktar_kg'] or 0),
            'aktif': k['aktif'],
            'birim': k['birim'] or 'KG',
            'kaynak_hucre': k['kaynak_hucre'] or '',
        } for k in kalemler_raw]

        payload = _rf_pigment_payload_olustur(ham)
        kalemler = []
        mb_say = 0
        for k, p in zip(kalemler_raw, payload['pigmentler']):
            kat = (k['kategori'] or '').upper()
            if kat == 'MASTERBATCH':
                mb_say += 1
            kalemler.append({
                **p,
                'stok_kod': p['stok_kodu'],
                'stok_ad': p['pigment_adi'],
                'birim': k['birim'] or 'KG',
                'kaynak_hucre': k['kaynak_hucre'] or '',
            })
        pigment_ozet = payload['ozet']
        toplam_kg = pigment_ozet['toplam_kg']

        rev = _rf_ui_rev_bilgi(con, rf_id, rf['aktif_rev_no'] or 0)
        rev_rows = []
        if con.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_rf_revizyon'"
        ).fetchone():
            rev_rows = [
                dict(x) for x in con.execute("""
                    SELECT rev_no, durum, neden, olusturma_tarihi
                    FROM nexgen_rf_revizyon
                    WHERE rf_renk_id=? AND aktif=1
                    ORDER BY rev_no
                """, (rf_id,)).fetchall()
            ]

        uygunluk = [
            dict(x) for x in con.execute("""
                SELECT rfu.durum, rfu.formul_id, f.kod AS formul_kod, f.ad AS formul_ad
                FROM nexgen_rf_formul_uygunluk rfu
                JOIN nexgen_formul f ON f.id = rfu.formul_id
                WHERE rfu.rf_renk_id=? AND rfu.aktif=1
            """, (rf_id,)).fetchall()
        ]

        pigment_fp = _rf_ui_pigment_fp(con, rf_id)

        uretim_kodu_info = None
        if formul_id:
            uk = _uretim_kodu_mevcut_bul(con, rf_id, formul_id)
            if uk:
                uretim_kodu_info = uk
            else:
                frm_k = con.execute("SELECT kod FROM nexgen_formul WHERE id=?", (formul_id,)).fetchone()
                if frm_k:
                    hesap = _uretim_kodu_girdi_dogrula(dict(rf), frm_k['kod'])
                    if hesap.get('ok'):
                        uretim_kodu_info = hesap

        payload = {
            'ok': True,
            'rf': {
                'rf_kod': rf['rf_kod'],
                'renk_adi': rf['ad'],
                'renk_kodu': ident['renk_kodu'] or '—',
                'cari_kod': rf['cari_kod'] or ident['cari_kod'] or '—',
                'rv': ident['rv'] or '—',
                'parent_kod': rf['parent_kod'] or ident['parent_kod'] or '—',
                'parent_ad': rf['parent_ad'] or '',
                'durum': rf['durum'],
                'rev_no': rev['rev_no'],
                'rev_durum': rev['durum'],
                'kalem_sayisi': pigment_ozet['kalem_sayisi'],
                'toplam_kg': pigment_ozet['toplam_kg'],
                'toplam_gr': pigment_ozet['toplam_gr'],
                'masterbatch_sayisi': mb_say,
                'pigment_fp': pigment_fp,
                'olusturma_tarihi': (rf['olusturma_tarihi'] or '')[:16],
            },
            'kalemler': kalemler,
            'pigment_ozet': pigment_ozet,
            'revizyonlar': rev_rows,
            'uygunluk': uygunluk,
        }
        if uretim_kodu_info:
            payload['uretim_kodu'] = uretim_kodu_info.get('uretim_kodu')
            payload['ana_formul_kodu'] = uretim_kodu_info.get('ana_formul_kodu')
            payload['renk_kodu'] = uretim_kodu_info.get('renk_kodu')
            payload['rf']['uretim_kodu'] = uretim_kodu_info.get('uretim_kodu')
        return jsonify(payload)
    finally:
        con.close()


# ═════════════════════════════════════════════════════════════
# FAZ-4C-3: ARGE RENK TEST MERKEZİ
# ─────────────────────────────────────────────────────────────
# KURAL: nexgen_stok_hareket / nexgen_hammadde_fiyat dokunulmaz.
#        Ana reçete kalemleri (nexgen_recete_kalem) değişmez.
#        Sadece nexgen_arge_test + nexgen_arge_test_kalem yazılır.
# ─────────────────────────────────────────────────────────────

def _arge_test_no_uret(con):
    """AT-YYYY-NNNN formatında benzersiz test numarası üretir."""
    from datetime import datetime
    yil = datetime.now().strftime('%Y')
    row = con.execute(
        "SELECT MAX(CAST(SUBSTR(test_no, -4) AS INTEGER)) AS son "
        "FROM nexgen_arge_test WHERE test_no LIKE ?",
        (f'AT-{yil}-%',)
    ).fetchone()
    son = row['son'] if row and row['son'] else 0
    return f'AT-{yil}-{son + 1:04d}'


def _arge_kaynak_uv_cekirdek_mi(con, kaynak_uv_id) -> dict:
    """Yeni AR-GE akışı — kaynak UV yalnız çekirdek formüle bağlı olmalı."""
    row = con.execute("""
        SELECT uv.id, f.id AS formul_id, f.kod AS formul_kod
        FROM nexgen_uretim_varyant uv
        JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
        JOIN nexgen_formul f ON f.id = rv.formul_id
        WHERE uv.id = ? AND uv.aktif = 1
    """, (kaynak_uv_id,)).fetchone()
    if not row:
        return {'ok': False, 'hata': 'Kaynak üretim varyantı bulunamadı.'}
    if not cekirdek_formul_mu(row['formul_kod']):
        return {
            'ok': False,
            'hata': f'Legacy formül ile AR-GE başlatılamaz: {row["formul_kod"]}',
        }
    return {'ok': True, 'formul_id': row['formul_id'], 'formul_kod': row['formul_kod']}


def _arge_renk_calisma_kaydet(con, kaynak_uv_id, test_batch_kg, yeni_renk_adi, cari_id,
                              shore_hedef, talep_referansi, notlar, makina, kullanici_id):
    """RENK_TEST calismasi olusturur (test + kalem clone). Commit disarida yapilir."""
    cek = _arge_kaynak_uv_cekirdek_mi(con, kaynak_uv_id)
    if not cek.get('ok'):
        raise ValueError(cek.get('hata'))
    uv = con.execute(
        "SELECT id FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
        (kaynak_uv_id,)
    ).fetchone()
    if not uv:
        raise ValueError("Kaynak uretim varyanti bulunamadi.")

    kalemler = con.execute("""
        SELECT rk.stok_kart_id, rk.sira, rk.miktar_kg, rk.aciklama,
               sk.kod AS stok_kod, sk.ad AS stok_ad
        FROM nexgen_recete_kalem rk
        JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
        ORDER BY rk.sira, rk.id
    """, (kaynak_uv_id,)).fetchall()
    if not kalemler:
        raise ValueError("Kaynak varyantta recete kalemi yok.")

    kaynak_batch_kg = round(sum(float(k['miktar_kg']) for k in kalemler), 3)
    if kaynak_batch_kg <= 0:
        raise ValueError("Kaynak batch KG sifir — recete gecersiz.")

    carpan = test_batch_kg / kaynak_batch_kg
    test_no = _arge_test_no_uret(con)

    from datetime import datetime
    yil = datetime.now().year
    son = con.execute(
        "SELECT COUNT(*) FROM nexgen_arge_test WHERE lot_no LIKE ?",
        (f'ARGE-LOT-{yil}-%',)
    ).fetchone()[0]
    lot_no = f'ARGE-LOT-{yil}-{(son + 1):05d}'

    con.execute("""
        INSERT INTO nexgen_arge_test
            (kaynak_uretim_varyant_id, test_no, test_tipi,
             makina, test_batch_kg, kaynak_batch_kg,
             yeni_renk_adi, notlar, durum,
             cari_id, shore_hedef, lot_no, talep_referansi,
             olusturan_id, olusturma_tarihi)
        VALUES (?, ?, 'RENK_TEST', ?, ?, ?, ?, ?, 'TASLAK', ?, ?, ?, ?, ?, datetime('now'))
    """, (kaynak_uv_id, test_no, makina, test_batch_kg, kaynak_batch_kg,
          yeni_renk_adi, notlar, cari_id, shore_hedef, lot_no, talep_referansi,
          kullanici_id))
    test_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]

    for k in kalemler:
        orj_kg = float(k['miktar_kg'])
        test_kg = round(orj_kg * carpan, 4)
        con.execute("""
            INSERT INTO nexgen_arge_test_kalem
                (test_id, stok_kart_id, sira, orjinal_miktar_kg, test_miktar_kg, aciklama)
            VALUES (?, ?, ?, ?, ?, ?)
        """, (test_id, k['stok_kart_id'], k['sira'], orj_kg, test_kg, k['aciklama']))

    return {
        'test_id': test_id,
        'test_no': test_no,
        'lot_no': lot_no,
        'kaynak_batch_kg': kaynak_batch_kg,
        'test_batch_kg': test_batch_kg,
        'kalem_sayisi': len(kalemler),
    }


def _rf_kod_uret(con):
    """[LEGACY] RF-NNN formatinda eski RF renk kodu uretir.
    Yeni sistemde _nx_rf_kod_uret kullanilacak.
    Bu fonksiyon mevcut kodu bozmamak icin birakildi.
    """
    row = con.execute(
        "SELECT MAX(CAST(SUBSTR(rf_kod, 4) AS INTEGER)) AS son "
        "FROM nexgen_rf_renk WHERE rf_kod LIKE 'RF-%'"
    ).fetchone()
    son = row['son'] if row and row['son'] else 0
    return f'RF-{son + 1:03d}'


def _nx_rf_kod_uret(con):
    """NX-RF-NNNN formatında benzersiz RF renk kodu üretir.
    Örnek: NX-RF-0001, NX-RF-0002, ...
    nexgen_rf_renk.rf_kod sütunundan MAX alır (NX-RF- ile başlayanlar).
    Not: İleride merkezi kod_servisi.py'e taşınacak.
    """
    row = con.execute(
        "SELECT MAX(CAST(SUBSTR(rf_kod, 8) AS INTEGER)) AS son "
        "FROM nexgen_rf_renk WHERE rf_kod LIKE 'NX-RF-%'"
    ).fetchone()
    son = row['son'] if row and row['son'] else 0
    return f'NX-RF-{son + 1:04d}'


def _nx_rt_kod_uret(con):
    """NX-RT-NNNN formatında benzersiz Müşteri Renk Talebi kodu üretir.
    Örnek: NX-RT-0001, NX-RT-0002, ...
    nexgen_arge_test.arge_kodu sütunundan MAX alır (NX-RT- ile başlayanlar).
    MODÜL-01 (Müşteri Renk Talebi) tarafından kullanılır.
    Not: İleride merkezi kod_servisi.py'e taşınacak.
    """
    row = con.execute(
        "SELECT MAX(CAST(SUBSTR(arge_kodu, 7) AS INTEGER)) AS son "
        "FROM nexgen_arge_test WHERE arge_kodu LIKE 'NX-RT-%'"
    ).fetchone()
    son = row['son'] if row and row['son'] else 0
    return f'NX-RT-{son + 1:04d}'


def _nx_ar_kod_uret(con):
    """NX-AR-NNNN formatında benzersiz AR-GE Renk Çalışması kodu üretir.
    Örnek: NX-AR-0001, NX-AR-0002, ...
    nexgen_arge_test.arge_kodu sütunundan NX-AR- ile başlayanların MAX'ını alır.
    MODÜL-02 (Yeni Renk Denemesi) tarafından kullanılır.
    Not: İleride merkezi kod_servisi.py'e taşınacak.
    """
    row = con.execute(
        "SELECT MAX(CAST(SUBSTR(arge_kodu, 7) AS INTEGER)) AS son "
        "FROM nexgen_arge_test WHERE arge_kodu LIKE 'NX-AR-%'"
    ).fetchone()
    son = row['son'] if row and row['son'] else 0
    return f'NX-AR-{son + 1:04d}'


def _nx_arf_kod_uret(con):
    """NX-ARF-NNNN formatında benzersiz AR-GE Formül kodu üretir.
    Örnek: NX-ARF-0001, NX-ARF-0002, ...
    nexgen_arge_formul.arge_kodu sütunundan MAX alır.
    Not: İleride merkezi kod_servisi.py'e taşınacak.
    """
    row = con.execute(
        "SELECT MAX(CAST(SUBSTR(arge_kodu, 8) AS INTEGER)) AS son "
        "FROM nexgen_arge_formul WHERE arge_kodu LIKE 'NX-ARF-%'"
    ).fetchone()
    son = row['son'] if row and row['son'] else 0
    return f'NX-ARF-{son + 1:04d}'


# ─────────────────────────────────────────────────────────────
# MODÜL-02 — Yeni Renk Denemesi kayıt endpointi
# ─────────────────────────────────────────────────────────────

@nexgen_bp.route('/api/tablet/arge/yeni-renk-denemesi', methods=['POST'])
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def api_tablet_yeni_renk_denemesi():
    """MODÜL-02 — Yeni Renk Denemesi kaydı.

    POST JSON:
        kaynak_uv_id          : int   — seçilen üretim varyantı
        cari_id               : int
        renk_adi              : str   — ZORUNLU
        renk_aciklama         : str   — opsiyonel
        musteri_notu          : str   — opsiyonel
        notlar                : str   — AR-GE notu (ZORUNLU)
        renk_bilesenleri      : list  — [{stok_kart_id, stok_kodu, ad, gram, kg}]
        renk_bileseni_toplam_gr : float
        renk_bileseni_toplam_kg : float
        ana_formul_numune_kg  : float
        tahmini_toplam_kg     : float
        numune_orani          : float — default 10.0

    Döner: { ok, arge_kodu, test_id, test_no }
    """
    import json as _json

    data = request.get_json(silent=True) or {}

    # Frontend S.rv_id = nexgen_renk_varyant.id
    # kaynak_uv_id ise nexgen_uretim_varyant.id — her ikisini de kabul et
    kaynak_uv_id   = data.get('kaynak_uv_id') or None
    rv_id          = data.get('rv_id') or None          # renk_varyant.id
    cari_id        = data.get('cari_id') or None
    renk_adi       = (data.get('renk_adi') or '').strip()
    renk_aciklama  = (data.get('renk_aciklama') or '').strip() or None
    musteri_notu   = (data.get('musteri_notu') or '').strip() or None
    notlar         = (data.get('notlar') or '').strip() or None
    bileskenler    = data.get('renk_bilesenleri') or []
    numune_orani   = float(data.get('numune_orani') or 10.0)
    ana_formul_kg  = float(data.get('ana_formul_numune_kg') or 0)
    tahmini_top_kg = float(data.get('tahmini_toplam_kg') or 0)

    # Zorunlu alan kontrolleri
    if not kaynak_uv_id and not rv_id:
        return jsonify({"ok": False, "hata": "kaynak_uv_id veya rv_id zorunludur."}), 400
    if not renk_adi:
        return jsonify({"ok": False, "hata": "renk_adi zorunludur."}), 400
    if not notlar:
        return jsonify({"ok": False, "hata": "AR-GE notu (notlar) zorunludur."}), 400
    if not bileskenler:
        return jsonify({"ok": False, "hata": "En az bir renk bileşeni zorunludur."}), 400

    # talep_referansi: renk açıklaması + müşteri notunu birleştir
    talep_parca = [p for p in [renk_aciklama, musteri_notu] if p]
    talep_referansi = ' | '.join(talep_parca) if talep_parca else None

    kullanici_id = _kullanici_id()
    con = _db()
    try:
        # uv_id geldi mi? (nexgen_uretim_varyant.id — en güvenilir yol)
        uv_id_dogrudan = data.get('uv_id') or None
        if uv_id_dogrudan:
            kaynak_uv_id = int(uv_id_dogrudan)

        # Yoksa rv_id (nexgen_renk_varyant.id) üzerinden çöz
        if not kaynak_uv_id and rv_id:
            uv_row = con.execute(
                "SELECT id FROM nexgen_uretim_varyant WHERE renk_varyant_id=? AND aktif=1 LIMIT 1",
                (rv_id,)
            ).fetchone()
            if uv_row:
                kaynak_uv_id = uv_row['id']

        if not kaynak_uv_id:
            # debug bilgisi: kaç kayıt var?
            rv_say = con.execute(
                "SELECT COUNT(*) FROM nexgen_uretim_varyant WHERE renk_varyant_id=?", (rv_id,)
            ).fetchone()[0] if rv_id else '—'
            return jsonify({
                "ok": False,
                "hata": f"Kaynak üretim varyantı bulunamadı. rv_id={rv_id}, uv_id_dogrudan={uv_id_dogrudan}, bulunan_uv_sayisi={rv_say}"
            }), 404

        # Kaynak varyant doğrulama
        uv = con.execute(
            "SELECT id, ad FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
            (kaynak_uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({
                "ok": False,
                "hata": f"Üretim varyantı DB'de bulunamadı veya pasif. kaynak_uv_id={kaynak_uv_id}"
            }), 404

        cek = _arge_kaynak_uv_cekirdek_mi(con, kaynak_uv_id)
        if not cek.get('ok'):
            return jsonify({"ok": False, "hata": cek.get('hata')}), 409

        kalemler = con.execute("""
            SELECT ROUND(SUM(rk.miktar_kg), 3) AS master_kg
            FROM nexgen_recete_kalem rk
            WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
        """, (kaynak_uv_id,)).fetchone()
        master_kg = float(kalemler['master_kg'] or 0) if kalemler else 0
        if master_kg <= 0:
            return jsonify({"ok": False, "hata": "Kaynak varyantta reçete kalemi yok."}), 400

        # test_batch_kg: ana_formul_numune_kg geldiyse onu kullan,
        # gelmediyse master × (numune_orani/100) hesapla
        if ana_formul_kg > 0:
            test_batch_kg = round(ana_formul_kg, 4)
        else:
            test_batch_kg = round(master_kg * numune_orani / 100.0, 4)

        # test_no: LEGACY — tablodan kaldırılmıyor, eski sistem uyumu için
        test_no   = _arge_test_no_uret(con)
        # arge_kodu: YENİ STANDART — NX-AR-NNNN (4 hane), kullanıcıya bu gösterilir
        arge_kodu = _nx_ar_kod_uret(con)

        # Lot no
        from datetime import datetime as _dt
        _yil = _dt.now().year
        _son = con.execute(
            "SELECT COUNT(*) FROM nexgen_arge_test WHERE lot_no LIKE ?",
            (f'ARGE-LOT-{_yil}-%',)
        ).fetchone()[0]
        lot_no = f'ARGE-LOT-{_yil}-{(_son + 1):05d}'

        # Ana kayıt — test_tipi = 'RENK_DENEMESI'
        con.execute("""
            INSERT INTO nexgen_arge_test
                (kaynak_uretim_varyant_id, test_no, test_tipi,
                 makina, test_batch_kg, kaynak_batch_kg,
                 yeni_renk_adi, notlar, durum,
                 cari_id, lot_no, talep_referansi,
                 numune_orani, arge_kodu, renk_bilesenleri_json,
                 olusturan_id, olusturma_tarihi)
            VALUES (?, ?, 'RENK_DENEMESI', '—', ?, ?, ?, ?, 'TASLAK',
                    ?, ?, ?, ?, ?, ?, ?, datetime('now'))
        """, (
            kaynak_uv_id, test_no,
            test_batch_kg, round(master_kg, 3),
            renk_adi, notlar,
            cari_id, lot_no, talep_referansi,
            numune_orani, arge_kodu,
            _json.dumps(bileskenler, ensure_ascii=False),
            kullanici_id,
        ))
        test_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]

        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":        True,
        "arge_kodu": arge_kodu,   # NX-AR-NNNN — başarı ekranında gösterilir
        "test_id":   test_id,
        "lot_no":    lot_no,
        "mesaj":     f"{arge_kodu} oluşturuldu. Durum: Onay Bekliyor.",
        # test_no (AT-YYYY-NNNN) kasıtlı olarak response'dan çıkarıldı.
        # Sadece nexgen_arge_test.test_no sütununda legacy olarak saklanır.
    })


@nexgen_bp.route('/api/arge/test-olustur', methods=['POST'])
@login_gerekli
def api_arge_test_olustur():
    """Kaynak üretim varyantından AR-GE test kaydı oluşturur.
    Ana reçete (nexgen_recete_kalem) YAZILMAZ — sadece ARGE tabloları.

    POST JSON:
        kaynak_uv_id    : int
        test_tipi       : RENK_TEST | FORMUL_TEST
        makina          : str   (default: "7.5 LT")
        test_batch_kg   : float
        yeni_renk_adi   : str   opsiyonel
        notlar          : str   opsiyonel
        cari_id         : int   opsiyonel — hangi cari/firma için (nexgen_cari.id)
        shore_hedef     : float opsiyonel — hedef shore değeri
        lot_no          : str   opsiyonel — otomatik üretilir (ARGE-LOT-YYYY-NNNNN)
        talep_referansi : str   opsiyonel — müşteri talebi / referans notu

    Yetki: nexgen.recete.create VEYA nexgen.tablet.view (tablet hızlı başlatma).
    """
    if not (yetki_var('nexgen.recete.create', 'can_create')
            or yetki_var('nexgen.tablet.view', 'can_view')):
        abort(403)

    data = request.get_json(silent=True) or {}
    kaynak_uv_id    = data.get('kaynak_uv_id')
    test_tipi       = (data.get('test_tipi') or 'RENK_TEST').strip().upper()
    makina          = (data.get('makina') or '—').strip()
    yeni_renk_adi   = (data.get('yeni_renk_adi') or '').strip() or None
    notlar          = (data.get('notlar') or data.get('aciklama') or '').strip() or None
    cari_id         = data.get('cari_id') or None
    talep_referansi = (data.get('talep_referansi') or '').strip() or None
    lot_no_giris    = (data.get('lot_no') or '').strip() or None
    # MODÜL-01 ek alanlar
    rf_renk_id_in   = data.get('rf_renk_id') or None
    numune_orani_in = data.get('numune_orani')   # % değeri, ör: 10.0

    try:
        shore_hedef = float(data['shore_hedef']) if data.get('shore_hedef') not in (None, '') else None
    except (ValueError, TypeError):
        shore_hedef = None

    try:
        numune_orani_val = float(numune_orani_in) if numune_orani_in not in (None, '') else None
    except (ValueError, TypeError):
        numune_orani_val = None

    try:
        test_batch_kg = float(data.get('test_batch_kg') or data.get('test_kg') or 0)
    except (ValueError, TypeError):
        return jsonify({"ok": False, "hata": "test_batch_kg geçersiz."}), 400

    if not kaynak_uv_id:
        return jsonify({"ok": False, "hata": "kaynak_uv_id zorunludur."}), 400
    if test_tipi not in {'RENK_TEST', 'FORMUL_TEST'}:
        return jsonify({"ok": False, "hata": "test_tipi: RENK_TEST veya FORMUL_TEST"}), 400
    if test_batch_kg <= 0:
        return jsonify({"ok": False, "hata": "test_batch_kg sıfırdan büyük olmalı."}), 400

    kullanici_id = _kullanici_id()
    con = _db()
    try:
        # Kaynak varyant var mı?
        uv = con.execute(
            "SELECT id, ad FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
            (kaynak_uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({"ok": False, "hata": "Kaynak üretim varyantı bulunamadı."}), 404

        cek = _arge_kaynak_uv_cekirdek_mi(con, kaynak_uv_id)
        if not cek.get('ok'):
            return jsonify({"ok": False, "hata": cek.get('hata')}), 409

        # Kaynak reçete kalemleri
        kalemler = con.execute("""
            SELECT rk.stok_kart_id, rk.sira, rk.miktar_kg, rk.aciklama,
                   sk.kod AS stok_kod, sk.ad AS stok_ad
            FROM nexgen_recete_kalem rk
            JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
            ORDER BY rk.sira, rk.id
        """, (kaynak_uv_id,)).fetchall()

        if not kalemler:
            return jsonify({"ok": False, "hata": "Kaynak varyantta reçete kalemi yok."}), 400

        # ── P3.1: AR-GE başlatma bütünlük kontrolü (pasif stok, KG=0) ──
        gecerli_arge, hatalar_arge = _recete_kalem_butunluk_kontrol(con, kaynak_uv_id)
        if not gecerli_arge:
            return jsonify({
                "ok":     False,
                "hata":   "AR-GE testi başlatılamaz — reçete eksik: "
                          + "; ".join(hatalar_arge),
                "hatalar": hatalar_arge,
            }), 409

        # Kaynak batch KG = kalem toplamı
        kaynak_batch_kg = round(sum(float(k['miktar_kg']) for k in kalemler), 3)
        if kaynak_batch_kg <= 0:
            return jsonify({"ok": False, "hata": "Kaynak batch KG sıfır — reçete geçersiz."}), 400

        # Ölçekleme çarpanı
        carpan = test_batch_kg / kaynak_batch_kg

        # Test no üret (LEGACY — tablodan kaldırılmıyor, eski kayıtlar için)
        test_no = _arge_test_no_uret(con)

        # Yeni NX-RT kodu üret (MODÜL-01 Müşteri Renk Talebi standart kodu)
        nx_rt_kodu = _nx_rt_kod_uret(con)

        # Lot no: giriş yoksa otomatik üret (ARGE-LOT-YYYY-NNNNN)
        if lot_no_giris:
            lot_no = lot_no_giris
        else:
            _yil = __import__('datetime').datetime.now().year
            _son = con.execute(
                "SELECT COUNT(*) FROM nexgen_arge_test WHERE lot_no LIKE ?",
                (f'ARGE-LOT-{_yil}-%',)
            ).fetchone()[0]
            lot_no = f'ARGE-LOT-{_yil}-{(_son + 1):05d}'

        # Ana test kaydı — arge_kodu artık NX-RT-NNNN formatında
        con.execute("""
            INSERT INTO nexgen_arge_test
                (kaynak_uretim_varyant_id, test_no, test_tipi,
                 makina, test_batch_kg, kaynak_batch_kg,
                 yeni_renk_adi, notlar, durum,
                 cari_id, shore_hedef, lot_no, talep_referansi,
                 rf_renk_id, numune_orani, arge_kodu,
                 olusturan_id, olusturma_tarihi)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'TASLAK', ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'))
        """, (kaynak_uv_id, test_no, test_tipi,
              makina, test_batch_kg, kaynak_batch_kg,
              yeni_renk_adi, notlar,
              cari_id, shore_hedef, lot_no, talep_referansi,
              rf_renk_id_in, numune_orani_val, nx_rt_kodu,
              kullanici_id))
        test_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]

        # Test kalemleri — REAL hassasiyet, round(x, 4) yeterli
        test_kalemler = []
        for k in kalemler:
            orj_kg  = float(k['miktar_kg'])
            test_kg = round(orj_kg * carpan, 4)
            con.execute("""
                INSERT INTO nexgen_arge_test_kalem
                    (test_id, stok_kart_id, sira,
                     orjinal_miktar_kg, test_miktar_kg, aciklama)
                VALUES (?, ?, ?, ?, ?, ?)
            """, (test_id, k['stok_kart_id'], k['sira'],
                  orj_kg, test_kg, k['aciklama']))
            test_kalemler.append({
                'stok_kod':        k['stok_kod'],
                'stok_ad':         k['stok_ad'],
                'orjinal_kg':      orj_kg,
                'test_kg':         test_kg,
            })

        con.commit()

    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok":              True,
        "test_id":         test_id,
        "test_no":         test_no,           # legacy — tabloda tutuluyor
        "nx_rt_kodu":      nx_rt_kodu,        # YENİ — başarı ekranında gösterilecek
        "arge_kodu":       nx_rt_kodu,        # frontend arge_kodu okuyorsa da doğru alır
        "lot_no":          lot_no,
        "kaynak_batch_kg": kaynak_batch_kg,
        "test_batch_kg":   test_batch_kg,
        "numune_orani":    numune_orani_val,
        "rf_renk_id":      rf_renk_id_in,
        "carpan":          round(carpan, 6),
        "kalem_sayisi":    len(test_kalemler),
        "kalemler":        test_kalemler,
        "mesaj":           f"{nx_rt_kodu} oluşturuldu. {len(test_kalemler)} kalem.",
    })


@nexgen_bp.route('/arge/renk-yeni')
@yetki_gerekli('nexgen.recete.create', 'can_create')
def arge_renk_yeni():
    """Masaustu RENK gelistirme calismasi olusturma formu."""
    con = _db()
    try:
        cariler = con.execute(
            "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE aktif=1 ORDER BY cari_kod"
        ).fetchall()
        kaynak_uvler = con.execute(f"""
            SELECT uv.id, uv.boyut,
                   rv.ad AS renk_ad,
                   f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad,
                   ROUND(SUM(rk.miktar_kg), 3) AS kaynak_batch_kg,
                   COUNT(rk.id) AS kalem_sayisi
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f ON f.id = rv.formul_id
            JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE uv.aktif = 1 AND rv.aktif = 1 AND f.aktif = 1
              AND ({cekirdek_kod_sql_filter('f')})
            GROUP BY uv.id
            HAVING kalem_sayisi > 0
            ORDER BY f.ad, rv.ad, uv.boyut
        """).fetchall()
        kaynak_uvler = formul_secim_gosterim_uygula(
            [dict(u) for u in kaynak_uvler],
            kod_alan='formul_kod',
            ad_alan='formul_ad',
            boyut_alan='boyut',
            harf_ekle=False,
        )
    finally:
        con.close()

    return render_template(
        'nexgen/arge_renk_olustur.html',
        active='nexgen',
        cariler=[dict(c) for c in cariler],
        kaynak_uvler=kaynak_uvler,
    )


@nexgen_bp.route('/api/arge/renk-calisma-olustur', methods=['POST'])
@yetki_gerekli('nexgen.recete.create', 'can_create')
def api_arge_renk_calisma_olustur():
    """RENK gelistirme calismasi olusturur (TASLAK + recete clone).

    POST JSON:
        cari_id         : int   zorunlu
        kaynak_uv_id    : int   zorunlu
        yeni_renk_adi   : str   zorunlu
        test_batch_kg   : float zorunlu (>0)
        shore_hedef     : float opsiyonel
        talep_referansi : str   opsiyonel
        notlar          : str   opsiyonel
        makina          : str   opsiyonel (default 7.5 LT)
    """
    data = request.get_json(silent=True) or {}
    cari_id = data.get('cari_id')
    kaynak_uv_id = data.get('kaynak_uv_id')
    yeni_renk_adi = (data.get('yeni_renk_adi') or '').strip()
    notlar = (data.get('notlar') or '').strip() or None
    talep_referansi = (data.get('talep_referansi') or '').strip() or None
    makina = (data.get('makina') or '7.5 LT').strip() or '7.5 LT'

    try:
        shore_hedef = float(data['shore_hedef']) if data.get('shore_hedef') not in (None, '') else None
    except (ValueError, TypeError):
        shore_hedef = None

    try:
        test_batch_kg = float(data.get('test_batch_kg') or 0)
    except (ValueError, TypeError):
        return jsonify({"ok": False, "hata": "test_batch_kg gecersiz."}), 400

    if not cari_id:
        return jsonify({"ok": False, "hata": "cari_id zorunludur."}), 400
    if not kaynak_uv_id:
        return jsonify({"ok": False, "hata": "kaynak_uv_id zorunludur."}), 400
    if not yeni_renk_adi:
        return jsonify({"ok": False, "hata": "yeni_renk_adi zorunludur."}), 400
    if test_batch_kg <= 0:
        return jsonify({"ok": False, "hata": "test_batch_kg sifirdan buyuk olmali."}), 400

    kullanici_id = _kullanici_id()
    con = _db()
    try:
        cek = _arge_kaynak_uv_cekirdek_mi(con, kaynak_uv_id)
        if not cek.get('ok'):
            return jsonify({"ok": False, "hata": cek.get('hata')}), 409
        cari = con.execute(
            "SELECT id FROM nexgen_cari WHERE id=? AND aktif=1", (cari_id,)
        ).fetchone()
        if not cari:
            return jsonify({"ok": False, "hata": "Cari kaydi bulunamadi."}), 400

        sonuc = _arge_renk_calisma_kaydet(
            con, kaynak_uv_id, test_batch_kg, yeni_renk_adi, cari_id,
            shore_hedef, talep_referansi, notlar, makina, kullanici_id,
        )
        con.commit()
    except ValueError as e:
        con.rollback()
        msg = str(e)
        code = 404 if 'bulunamadi' in msg.lower() else 400
        return jsonify({"ok": False, "hata": msg}), code
    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()

    return jsonify({
        "ok": True,
        "test_id": sonuc['test_id'],
        "test_no": sonuc['test_no'],
        "lot_no": sonuc['lot_no'],
        "test_tipi": "RENK_TEST",
        "durum": "TASLAK",
        "kaynak_batch_kg": sonuc['kaynak_batch_kg'],
        "test_batch_kg": sonuc['test_batch_kg'],
        "kalem_sayisi": sonuc['kalem_sayisi'],
        "redirect_url": f"/nexgen/arge/test/{sonuc['test_id']}",
    })


def _arge_masaustu_yetki_veya_tablet_yonlendir():
    """Masaüstü AR-GE Merkezi: recete.view gerekir.
    Yalnız tablet operatörü ise /nexgen/tablet/arge'ye yönlendir (403 masaüstü ekranı yok).
    """
    if yetki_var('nexgen.recete.view', 'can_view'):
        return None
    if yetki_var('nexgen.tablet.view', 'can_view'):
        return redirect('/nexgen/tablet/arge')
    abort(403)


@nexgen_bp.route('/arge')
@login_gerekli
def arge_liste():
    """AR-GE Merkezi — tüm test kayıtları listesi (yönetici / recete.view)."""
    yon = _arge_masaustu_yetki_veya_tablet_yonlendir()
    if yon is not None:
        return yon
    con = _db()
    try:
        rows = con.execute("""
            SELECT t.id, t.test_no, t.lot_no, t.test_tipi, t.makina,
                   t.durum, t.shore_hedef, t.shore_degeri,
                   t.yeni_renk_adi, t.talep_referansi,
                   t.olusturma_tarihi, t.onay_tarihi,
                   t.arge_kodu, t.calisma_tipi, t.formul_grup_adi,
                   uv.boyut,
                   rv.ad AS renk_ad,
                   f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad,
                   c.unvan AS cari_unvan, c.cari_kod,
                   ku.KullaniciAdi AS olusturan_ad
            FROM nexgen_arge_test t
            LEFT JOIN nexgen_uretim_varyant uv ON uv.id = t.kaynak_uretim_varyant_id
            LEFT JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
            LEFT JOIN nexgen_formul f          ON f.id  = rv.formul_id
            LEFT JOIN nexgen_cari c       ON c.id  = t.cari_id
            LEFT JOIN sistem_kullanici ku ON ku.Id = t.olusturan_id
            WHERE t.aktif = 1
            ORDER BY t.id DESC
        """).fetchall()
        testler = formul_secim_gosterim_uygula(
            [dict(r) for r in rows],
            kod_alan='formul_kod',
            ad_alan='formul_ad',
            boyut_alan='boyut',
            harf_ekle=True,
        )
    finally:
        con.close()

    can_create = yetki_var('nexgen.recete.create', 'can_create')

    return render_template(
        'nexgen/arge_liste.html',
        active='nexgen',
        testler=testler,
        can_create=can_create,
    )


