# Satın Alma Ana Sayfa
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/satinalma')
@yetki_gerekli('nexgen.satinalma.view', 'can_view')
def satinalma_index():
    con = _db()
    try:
        durum_filtre = request.args.get('durum', '')
        tedarikci_filtre = request.args.get('tedarikci_id', '')
        mi_kaynak = (request.args.get('kaynak') or '').strip().lower() == 'mi'
        mi_stok_kod = (request.args.get('stok_kod') or '').strip()
        mi_net_eksik = (request.args.get('net_eksik_kg') or '').strip()
        mi_plan_ids = [
            int(x) for x in (request.args.get('plan_ids') or '').split(',')
            if str(x).strip().isdigit()
        ]
        mi_siparis_ids = [
            int(x) for x in (request.args.get('siparis_ids') or '').split(',')
            if str(x).strip().isdigit()
        ]
        mi_kopru = None

        sorgu = """
            SELECT s.id, s.siparis_no, s.siparis_tarihi, s.beklenen_teslim,
                   s.siparis_miktari_kg, s.para_birimi, s.durum, s.onay_durumu,
                   s.birim_fiyat, s.birim_fiyat_try, s.toplam_tutar_try,
                   s.vade_tarihi, s.aciklama,
                   t.ad AS tedarikci_ad, t.id AS tedarikci_id,
                   k.kod AS stok_kod, k.ad AS stok_ad,
                   COALESCE(
                       (SELECT SUM(mk.miktar_kg)
                        FROM nexgen_mal_kabul mk
                        WHERE mk.satin_siparis_id = s.id), 0
                   ) AS gelen_kg
            FROM nexgen_satin_siparis s
            JOIN nexgen_tedarikci t ON t.id = s.tedarikci_id
            JOIN nexgen_stok_kart k ON k.id = s.stok_kart_id
            WHERE 1=1
        """
        params = []
        if durum_filtre:
            sorgu += " AND s.durum = ?"
            params.append(durum_filtre)
        if tedarikci_filtre:
            sorgu += " AND s.tedarikci_id = ?"
            params.append(tedarikci_filtre)
        if mi_kaynak and mi_stok_kod:
            sorgu += " AND k.kod = ?"
            params.append(mi_stok_kod)
        sorgu += " ORDER BY s.id DESC"

        siparisler_raw = con.execute(sorgu, params).fetchall()
        tedarikciler   = con.execute(
            "SELECT id, ad FROM nexgen_tedarikci WHERE aktif=1 ORDER BY ad"
        ).fetchall()

        if mi_kaynak and (mi_stok_kod or mi_plan_ids or mi_siparis_ids):
            plan_etiketler = []
            if mi_plan_ids and _planlama_siparis_tablosu_var(con):
                ph = ','.join(['?'] * len(mi_plan_ids))
                for r in con.execute(
                    f"SELECT id, plan_kodu FROM nexgen_uretim_plan WHERE id IN ({ph})",
                    mi_plan_ids,
                ).fetchall():
                    plan_etiketler.append(dict(r))
            siparis_etiketler = []
            if mi_siparis_ids and _planlama_siparis_tablosu_var(con):
                ph = ','.join(['?'] * len(mi_siparis_ids))
                for r in con.execute(
                    f"SELECT id, siparis_no FROM nexgen_planlama_siparis WHERE id IN ({ph})",
                    mi_siparis_ids,
                ).fetchall():
                    siparis_etiketler.append(dict(r))
            stok_kart_id = None
            stok_ad = None
            if mi_stok_kod:
                sk = con.execute(
                    "SELECT id, kod, ad FROM nexgen_stok_kart WHERE kod=? AND aktif=1",
                    (mi_stok_kod,),
                ).fetchone()
                if sk:
                    stok_kart_id = sk['id']
                    stok_ad = sk['ad']
            mi_kopru = {
                'stok_kod': mi_stok_kod,
                'stok_ad': stok_ad,
                'stok_kart_id': stok_kart_id,
                'net_eksik_kg': mi_net_eksik,
                'plan_ids': mi_plan_ids,
                'siparis_ids': mi_siparis_ids,
                'planlar': plan_etiketler,
                'siparisler': siparis_etiketler,
            }
    finally:
        con.close()

    can_manage     = yetki_var('nexgen.satinalma.manage', 'can_create')
    can_approve    = yetki_var('nexgen.satinalma.approve', 'can_approve')
    can_fiyat      = yetki_var('nexgen.satinalma.fiyat', 'can_view')
    # Tedarikçi yönetimi: sadece Yönetim rolü — Satın Alma sadece görüntüler
    can_ted_manage = yetki_var('nexgen.tedarikci.manage', 'can_create')
    can_fiyat_view = yetki_var('nexgen.fiyat.view', 'can_view')

    siparisler = []
    for s in siparisler_raw:
        row = dict(s)
        siparis_kg = row.get('siparis_miktari_kg') or 0
        gelen_kg   = row.get('gelen_kg') or 0
        row['gelen_kg']  = round(gelen_kg, 3)
        row['kalan_kg']  = round(siparis_kg - gelen_kg, 3)
        # Teslim durumu DB'deki durum alanından okunur (depo mal kabul sonrası güncellendi)
        # Görsel etiket için ayrıca hesapla
        if gelen_kg <= 0:
            row['teslim_durum'] = 'BEKLIYOR'
        elif gelen_kg >= siparis_kg:
            row['teslim_durum'] = 'TAMAMLANDI'
        else:
            row['teslim_durum'] = 'KISMI_TESLIM'
        siparisler.append(row)

    return render_template(
        'nexgen/satinalma_index.html',
        active='nexgen',
        siparisler=siparisler,
        tedarikciler=[dict(t) for t in tedarikciler],
        durum_filtre=durum_filtre,
        tedarikci_filtre=tedarikci_filtre,
        mi_kopru=mi_kopru,
        can_manage=can_manage,
        can_approve=can_approve,
        can_fiyat=can_fiyat,
        can_ted_manage=can_ted_manage,
        can_fiyat_view=can_fiyat_view,
    )


# ─────────────────────────────────────────────────────────────
# Sipariş Detay
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/satinalma/siparis/<int:siparis_id>')
@yetki_gerekli('nexgen.satinalma.view', 'can_view')
def satinalma_siparis_detay(siparis_id):
    con = _db()
    try:
        siparis = con.execute("""
            SELECT s.*,
                   t.ad AS tedarikci_ad, t.kod AS tedarikci_kod,
                   t.ulke, t.iletisim_email,
                   k.kod AS stok_kod, k.ad AS stok_ad, k.kategori AS stok_kategori,
                   oc.KullaniciAdi AS olusturan_ad,
                   ap.KullaniciAdi AS onaylayan_ad
            FROM nexgen_satin_siparis s
            JOIN nexgen_tedarikci t ON t.id = s.tedarikci_id
            JOIN nexgen_stok_kart k ON k.id = s.stok_kart_id
            LEFT JOIN sistem_kullanici oc ON oc.Id = s.olusturan_id
            LEFT JOIN sistem_kullanici ap ON ap.Id = s.onaylayan_id
            WHERE s.id = ?
        """, (siparis_id,)).fetchone()
        if not siparis:
            abort(404)

        # Teslim özeti: nexgen_mal_kabul'dan hesapla
        teslim_row = con.execute("""
            SELECT
                COALESCE(SUM(mk.miktar_kg), 0)  AS gelen_kg,
                COUNT(mk.id)                     AS kabul_sayisi,
                MIN(mk.kabul_tarihi)             AS ilk_tarih,
                MAX(mk.kabul_tarihi)             AS son_tarih
            FROM nexgen_mal_kabul mk
            WHERE mk.satin_siparis_id = ?
        """, (siparis_id,)).fetchone()

        siparis_kg  = float(siparis['siparis_miktari_kg'] or 0)
        gelen_kg    = round(float(teslim_row['gelen_kg'] or 0), 3)
        kalan_kg    = round(siparis_kg - gelen_kg, 3)
        fazla_kg    = round(max(gelen_kg - siparis_kg, 0), 3)
        kabul_sayisi = int(teslim_row['kabul_sayisi'] or 0)

        if gelen_kg <= 0:
            teslim_durum = 'BEKLIYOR'
        elif gelen_kg > siparis_kg:
            teslim_durum = 'FAZLA_TESLIM'
        elif gelen_kg >= siparis_kg:
            teslim_durum = 'TAMAMLANDI'
        else:
            teslim_durum = 'KISMI_TESLIM'

        teslim_ozet = {
            'siparis_kg':   siparis_kg,
            'gelen_kg':     gelen_kg,
            'kalan_kg':     kalan_kg,
            'fazla_kg':     fazla_kg,
            'kabul_sayisi': kabul_sayisi,
            'ilk_tarih':    (teslim_row['ilk_tarih'] or '')[:10] or None,
            'son_tarih':    (teslim_row['son_tarih'] or '')[:10] or None,
            'teslim_durum': teslim_durum,
        }

        # Mal kabul geçmişi — LEFT JOIN ile eksik veriler kaybolmaz
        mal_kabul_rows = con.execute("""
            SELECT mk.id, mk.miktar_kg, mk.irsaliye_no, mk.lot_no,
                   mk.kabul_tarihi, mk.stok_hareket_id, mk.aciklama,
                   ku.KullaniciAdi AS kabul_eden_ad
            FROM nexgen_mal_kabul mk
            LEFT JOIN sistem_kullanici ku ON ku.Id = mk.kabul_eden_id
            WHERE mk.satin_siparis_id = ?
            ORDER BY mk.kabul_tarihi ASC, mk.id ASC
        """, (siparis_id,)).fetchall()

    finally:
        con.close()

    mal_kabul_gecmis = [dict(r) for r in mal_kabul_rows]
    # Mal kabul numarası: MK-{id:05d}
    for r in mal_kabul_gecmis:
        r['mal_kabul_no'] = f"MK-{r['id']:05d}"
        r['kabul_tarihi_fmt'] = (r['kabul_tarihi'] or '')[:16] or None

    can_approve = yetki_var('nexgen.satinalma.approve', 'can_approve')
    can_manage  = yetki_var('nexgen.satinalma.manage', 'can_update')
    can_fiyat   = yetki_var('nexgen.satinalma.fiyat', 'can_view')

    return render_template(
        'nexgen/satinalma_siparis_detay.html',
        active='nexgen',
        siparis=dict(siparis),
        teslim_ozet=teslim_ozet,
        mal_kabul_gecmis=mal_kabul_gecmis,
        can_approve=can_approve,
        can_manage=can_manage,
        can_fiyat=can_fiyat,
    )


