# ─────────────────────────────────────────────────────────────
# API — Stok Kartı için Uygun Tedarikçi Listesi
# GET /nexgen/api/satinalma/tedarikci-uygun?stok_kart_id=<id>
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/satinalma/tedarikci-uygun')
@yetki_gerekli('nexgen.satinalma.manage', 'can_create')
def api_satinalma_tedarikci_uygun():
    stok_kart_id = request.args.get('stok_kart_id', type=int)
    if not stok_kart_id:
        return jsonify({"ok": False, "hata": "stok_kart_id zorunludur."}), 400

    con = _db()
    try:
        # Aktif eşleşmesi olan tedarikçiler — tercih sırasıyla
        uygun = con.execute("""
            SELECT t.id, t.kod, t.ad, t.para_birimi, t.varsayilan_vade,
                   ts.tercih_sirasi
            FROM nexgen_tedarikci_stok ts
            JOIN nexgen_tedarikci t ON t.id = ts.tedarikci_id
            WHERE ts.stok_kart_id = ? AND ts.aktif = 1 AND t.aktif = 1
            ORDER BY ts.tercih_sirasi ASC, t.ad ASC
        """, (stok_kart_id,)).fetchall()

        uygun_ids = {r['id'] for r in uygun}

        # Eşleşmesi olmayan diğer aktif tedarikçiler (override için)
        digerleri = con.execute("""
            SELECT id, kod, ad, para_birimi, varsayilan_vade
            FROM nexgen_tedarikci
            WHERE aktif = 1
            ORDER BY ad
        """).fetchall()
        diger_list = [dict(r) for r in digerleri if r['id'] not in uygun_ids]

    finally:
        con.close()

    uygun_list = []
    for r in uygun:
        row = dict(r)
        tercih = row.get('tercih_sirasi') or 0
        row['rozet'] = 'Tercih 1' if tercih == 1 else (f'Tercih {tercih}' if tercih > 1 else 'Uygun Tedarikçi')
        uygun_list.append(row)

    return jsonify({
        "ok": True,
        "uygun": uygun_list,
        "diger": diger_list,
        "uygun_sayisi": len(uygun_list),
    })


# ═════════════════════════════════════════════════════════════
# FAZ-2.6 — HAFTALlK FİYAT YÖNETİMİ
# ═════════════════════════════════════════════════════════════
# KURAL: Bu bölümde nexgen_stok_hareket INSERT YAPILMAZ.
# Fiyat geçmişi ≠ stok hareketi.
# ─────────────────────────────────────────────────────────────


def _isoweek():
    """Geçerli ISO hafta kodu: '2026-W26'"""
    today = date.today()
    iso = today.isocalendar()
    return f"{iso[0]}-W{iso[1]:02d}"


def _son_fiyat(con, tedarikci_id, stok_kart_id):
    """
    Son aktif fiyat kaydını döndür.
    Kural: aktif=1 AND ORDER BY fiyat_tarihi DESC, id DESC LIMIT 1
    """
    return con.execute("""
        SELECT nhf.*, t.ad AS tedarikci_ad, sk.ad AS stok_ad,
               sk.kod AS stok_kod
        FROM nexgen_hammadde_fiyat nhf
        JOIN nexgen_tedarikci t ON t.id = nhf.tedarikci_id
        JOIN nexgen_stok_kart sk ON sk.id = nhf.stok_kart_id
        WHERE nhf.tedarikci_id = ?
          AND nhf.stok_kart_id = ?
          AND nhf.aktif = 1
        ORDER BY nhf.fiyat_tarihi DESC, nhf.id DESC
        LIMIT 1
    """, (tedarikci_id, stok_kart_id)).fetchone()


def _gecerli_fiyat(con, tedarikci_id, stok_kart_id, islem_tarihi=None):
    """FAZ-SATINALMA-FIYAT-01: İşlem tarihinde geçerli fiyatı döndür.

    Kesin geçerli fiyat kuralı:
      - aktif = 1
      - gecerlilik_bas IS NULL VEYA gecerlilik_bas <= islem_tarihi
      - gecerlilik_bitis IS NULL VEYA gecerlilik_bitis >= islem_tarihi

    Sonuçlar:
      {'ok': True, 'fiyat': row}              — tek geçerli fiyat bulundu
      {'ok': True, 'fiyat': None, 'uyari': '...'}  — geçerli fiyat yok
      {'ok': False, 'hata': '...', 'cakisan_sayisi': N}  — birden fazla aktif kayıt (veri hatası)

    Yönetim: gecerlilik_bas/bitis boşsa tarihe göre sıralı son kayıt döner
    (eski _son_fiyat davranışıyla geriye dönük uyumlu).
    """
    from datetime import date as _date
    if islem_tarihi is None:
        islem_tarihi = _date.today().strftime('%Y-%m-%d')

    rows = con.execute("""
        SELECT nhf.*, t.ad AS tedarikci_ad, sk.ad AS stok_ad, sk.kod AS stok_kod
        FROM nexgen_hammadde_fiyat nhf
        JOIN nexgen_tedarikci t  ON t.id  = nhf.tedarikci_id
        JOIN nexgen_stok_kart sk ON sk.id = nhf.stok_kart_id
        WHERE nhf.tedarikci_id = ?
          AND nhf.stok_kart_id = ?
          AND nhf.aktif = 1
          AND (nhf.gecerlilik_bas  IS NULL OR nhf.gecerlilik_bas  <= ?)
          AND (nhf.gecerlilik_bitis IS NULL OR nhf.gecerlilik_bitis >= ?)
        ORDER BY nhf.gecerlilik_bas DESC NULLS LAST, nhf.fiyat_tarihi DESC, nhf.id DESC
    """, (tedarikci_id, stok_kart_id, islem_tarihi, islem_tarihi)).fetchall()

    if not rows:
        return {
            'ok': True,
            'fiyat': None,
            'uyari': 'Bu tedarikçi ve hammadde için geçerli fiyat bulunamadı.',
        }
    if len(rows) > 1:
        return {
            'ok': False,
            'hata': (
                f'Bu tedarikçi ve hammadde için {islem_tarihi} tarihinde '
                f'{len(rows)} çakışan geçerli fiyat kaydı var. '
                'Fiyat listesinden çakışan kayıtları pasife alın.'
            ),
            'cakisan_sayisi': len(rows),
            'cakisan_idler': [r['id'] for r in rows],
        }
    return {'ok': True, 'fiyat': rows[0]}


def _fiyat_cakisma_kontrol(con, tedarikci_id, stok_kart_id,
                            gecerlilik_bas=None, gecerlilik_bitis=None,
                            haric_id=None):
    """FAZ-SATINALMA-FIYAT-01: Yeni/güncellenen fiyat için tarih çakışması kontrolü.

    Çakışma formülü (aralık kesişimi):
      A = [yeni_bas, yeni_bitis]   (NULL = sonsuz)
      B = [mevcut_bas, mevcut_bitis]
      Çakışır mı:
        NOT (A_bitis < B_bas OR B_bitis < A_bas)
        NULL uçlar sonsuz kabul edilir.

    Pasif kayıtlar (aktif=0) kontrole dahil edilmez.
    haric_id: güncelleme sırasında kaydın kendisini hariç tut.

    Dönüş:
      {'cakisiyor': False}
      {'cakisiyor': True, 'cakisan_kayitlar': [...]}
    """
    rows = con.execute("""
        SELECT id, fiyat, para_birimi, gecerlilik_bas, gecerlilik_bitis, fiyat_tarihi
        FROM nexgen_hammadde_fiyat
        WHERE tedarikci_id = ?
          AND stok_kart_id = ?
          AND aktif = 1
          AND id != COALESCE(?, -1)
    """, (tedarikci_id, stok_kart_id, haric_id)).fetchall()

    cakisanlar = []
    for r in rows:
        m_bas   = r['gecerlilik_bas']
        m_bitis = r['gecerlilik_bitis']

        # Çakışma koşulu: yeni_bas <= m_bitis AND m_bas <= yeni_bitis
        # NULL = sonsuz: NULL bitis her zaman büyük, NULL bas her zaman küçük
        yeni_bas_ok   = (gecerlilik_bitis is None) or (m_bas   is None) or (gecerlilik_bitis  >= m_bas)
        yeni_bitis_ok = (gecerlilik_bas   is None) or (m_bitis is None) or (gecerlilik_bas    <= m_bitis)

        if yeni_bas_ok and yeni_bitis_ok:
            cakisanlar.append({
                'id': r['id'],
                'fiyat': r['fiyat'],
                'para_birimi': r['para_birimi'],
                'gecerlilik_bas': r['gecerlilik_bas'],
                'gecerlilik_bitis': r['gecerlilik_bitis'],
                'fiyat_tarihi': r['fiyat_tarihi'],
            })

    if cakisanlar:
        return {'cakisiyor': True, 'cakisan_kayitlar': cakisanlar}
    return {'cakisiyor': False}


def _fiyat_farki(eski_fiyat, eski_pb, yeni_fiyat, yeni_pb):
    """Aynı para birimi varsa fark ve yüzde hesapla."""
    if eski_fiyat is None or yeni_fiyat is None:
        return None, None
    if eski_pb != yeni_pb:
        return None, None
    fark = yeni_fiyat - eski_fiyat
    yuzde = (fark / eski_fiyat * 100) if eski_fiyat != 0 else None
    return round(fark, 4), round(yuzde, 2) if yuzde is not None else None


# ─────────────────────────────────────────────────────────────
# Fiyat Listesi — GET /nexgen/satinalma/fiyat
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/satinalma/fiyat')
@yetki_gerekli('nexgen.fiyat.view', 'can_view')
def fiyat_listesi():
    con = _db()
    try:
        tedarikci_id = request.args.get('tedarikci_id', type=int)
        stok_kart_id = request.args.get('stok_kart_id', type=int)

        q = """
            SELECT nhf.id, nhf.fiyat, nhf.para_birimi, nhf.kur, nhf.fiyat_try,
                   nhf.vade_gun, nhf.fiyat_tarihi, nhf.kaynak, nhf.notlar,
                   nhf.aktif, nhf.batch_id,
                   t.kod AS tedarikci_kodu, t.ad AS tedarikci_ad,
                   sk.kod AS stok_kodu, sk.ad AS stok_ad
            FROM nexgen_hammadde_fiyat nhf
            JOIN nexgen_tedarikci t ON t.id = nhf.tedarikci_id
            JOIN nexgen_stok_kart sk ON sk.id = nhf.stok_kart_id
            WHERE 1=1
        """
        params = []
        if tedarikci_id:
            q += " AND nhf.tedarikci_id = ?"
            params.append(tedarikci_id)
        if stok_kart_id:
            q += " AND nhf.stok_kart_id = ?"
            params.append(stok_kart_id)
        q += " ORDER BY nhf.fiyat_tarihi DESC, nhf.id DESC LIMIT 200"

        fiyatlar = con.execute(q, params).fetchall()
        tedarikciler = con.execute(
            "SELECT id, kod, ad FROM nexgen_tedarikci WHERE aktif=1 ORDER BY ad"
        ).fetchall()
        stok_kartlari = con.execute(
            "SELECT id, kod, ad FROM nexgen_stok_kart WHERE aktif=1 ORDER BY kod"
        ).fetchall()
        son_batch = con.execute(
            "SELECT * FROM nexgen_fiyat_batch ORDER BY id DESC LIMIT 5"
        ).fetchall()

        can_manage = yetki_var('nexgen.fiyat.manage', 'can_create')
        can_admin  = yetki_var('nexgen.fiyat.admin', 'can_manage')
    finally:
        con.close()

    return render_template(
        'nexgen/fiyat_listesi.html',
        fiyatlar=fiyatlar,
        tedarikciler=tedarikciler,
        stok_kartlari=stok_kartlari,
        son_batch=son_batch,
        filtre_tedarikci=tedarikci_id,
        filtre_stok=stok_kart_id,
        can_manage=can_manage,
        can_admin=can_admin,
        active='nexgen'
    )


# ─────────────────────────────────────────────────────────────
# Excel Şablon İndir — GET /nexgen/satinalma/fiyat-sablonu-indir
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/satinalma/fiyat-sablonu-indir')
@yetki_gerekli('nexgen.fiyat.manage', 'can_create')
def fiyat_sablonu_indir():
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill, Alignment, Border, Side
    except ImportError:
        return jsonify({"ok": False, "hata": "openpyxl yüklü değil"}), 500

    con = _db()
    try:
        eslesmeler = con.execute("""
            SELECT ts.id, t.kod AS t_kod, t.ad AS t_ad, t.varsayilan_vade,
                   sk.kod AS s_kod, sk.ad AS s_ad,
                   t.id AS tedarikci_id, sk.id AS stok_kart_id
            FROM nexgen_tedarikci_stok ts
            JOIN nexgen_tedarikci t ON t.id = ts.tedarikci_id
            JOIN nexgen_stok_kart sk ON sk.id = ts.stok_kart_id
            WHERE ts.aktif = 1 AND t.aktif = 1 AND sk.aktif = 1
            ORDER BY t.kod, sk.kod
        """).fetchall()

        son_fiyatlar = {}
        for e in eslesmeler:
            sf = _son_fiyat(con, e['tedarikci_id'], e['stok_kart_id'])
            son_fiyatlar[(e['tedarikci_id'], e['stok_kart_id'])] = sf
    finally:
        con.close()

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "Fiyat Girişi"

    bugun = date.today().isoformat()
    hafta = _isoweek()

    baslik_font = Font(bold=True, color="FFFFFF")
    baslik_dolu = PatternFill("solid", fgColor="2C3E50")
    kilitli_dolu = PatternFill("solid", fgColor="ECF0F1")
    orta = Alignment(horizontal="center")

    basliklar = [
        "tedarikci_kodu", "tedarikci_adi", "stok_kodu", "stok_adi",
        "fiyat", "para_birimi", "kur", "vade_gun",
        "fiyat_tarihi", "gecerlilik_bas", "gecerlilik_bitis", "not",
        "son_fiyat_bilgi"
    ]
    ws.append(basliklar)
    for col, hdr in enumerate(basliklar, 1):
        cell = ws.cell(row=1, column=col)
        cell.font = baslik_font
        cell.fill = baslik_dolu
        cell.alignment = orta

    for e in eslesmeler:
        sf = son_fiyatlar.get((e['tedarikci_id'], e['stok_kart_id']))
        son_fiyat_bilgi = ""
        if sf:
            son_fiyat_bilgi = f"{sf['fiyat']} {sf['para_birimi']} ({sf['fiyat_tarihi']})"

        row = [
            e['t_kod'], e['t_ad'], e['s_kod'], e['s_ad'],
            None, "USD", None, e['varsayilan_vade'],
            bugun, bugun, None, None,
            son_fiyat_bilgi
        ]
        ws.append(row)

        r_idx = ws.max_row
        for col in [1, 2, 3, 4, 13]:
            ws.cell(row=r_idx, column=col).fill = kilitli_dolu

    for col_idx, width in zip(range(1, 14), [14, 22, 14, 28, 10, 12, 10, 10, 13, 13, 14, 20, 25]):
        ws.column_dimensions[openpyxl.utils.get_column_letter(col_idx)].width = width

    ws.freeze_panes = "E2"

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)

    dosya_adi = f"NexGen_Fiyat_Sablonu_{hafta}.xlsx"
    return Response(
        buf.getvalue(),
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename={dosya_adi}"}
    )


# ─────────────────────────────────────────────────────────────
# Excel Yükle + Preview — POST /nexgen/satinalma/fiyat-yukle
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/satinalma/fiyat-yukle', methods=['POST'])
@yetki_gerekli('nexgen.fiyat.manage', 'can_create')
def fiyat_yukle():
    try:
        import openpyxl
    except ImportError:
        return jsonify({"ok": False, "hata": "openpyxl yüklü değil"}), 500

    f = request.files.get('dosya')
    if not f or not f.filename.endswith('.xlsx'):
        return jsonify({"ok": False, "hata": "Geçerli bir .xlsx dosyası seçin"}), 400

    kullanici_id = _kullanici_id()
    hafta = _isoweek()

    con = _db()
    try:
        # FAZ-SATINALMA-FIYAT-01D: Dosya hash'ini hesapla (hard block için)
        import hashlib
        f.seek(0)
        dosya_baytlari = f.read()
        dosya_hash = hashlib.sha256(dosya_baytlari).hexdigest()
        f.seek(0)

        # Aynı hash daha önce onaylandı mı?
        ayni_hash_batch = con.execute("""
            SELECT id, hafta_kodu, dosya_adi, onay_tarihi
            FROM nexgen_fiyat_batch
            WHERE dosya_hash = ? AND durum = 'ONAYLANDI'
            ORDER BY onay_tarihi DESC
            LIMIT 1
        """, (dosya_hash,)).fetchone()

        # Aynı hafta onaylanmış farklı dosya var mı?
        ayni_hafta_batch = con.execute("""
            SELECT id, dosya_adi, dosya_hash, onay_tarihi
            FROM nexgen_fiyat_batch
            WHERE hafta_kodu = ? AND durum = 'ONAYLANDI' AND (dosya_hash != ? OR dosya_hash IS NULL)
            ORDER BY onay_tarihi DESC
            LIMIT 1
        """, (hafta, dosya_hash)).fetchone()

        onceki_batch_uyari = None
        if ayni_hash_batch:
            # Aynı içerik daha önce onaylanmış — bilgi ver, onayda hard block uygulanacak
            onceki_batch_uyari = (
                f"UYARI: Bu dosya daha önce onaylandı "
                f"(batch id={ayni_hash_batch['id']}, hafta={ayni_hash_batch['hafta_kodu']}). "
                "Onay aşamasında tekrar onaylamak engellenir."
            )
        elif ayni_hafta_batch:
            # Aynı hafta farklı dosya onaylanmış — güçlü uyarı
            onceki_batch_uyari = (
                f"UYARI: Bu hafta ({hafta}) için farklı bir dosya zaten onaylandı "
                f"(id={ayni_hafta_batch['id']}, dosya={ayni_hafta_batch['dosya_adi']}). "
                "Onay için açık gerekçe girmeniz gerekecektir."
            )

        # Batch kaydı oluştur
        con.execute("""
            INSERT INTO nexgen_fiyat_batch
              (hafta_kodu, dosya_adi, durum, yukleyen_id, dosya_hash)
            VALUES (?, ?, 'ONAY_BEKLIYOR', ?, ?)
        """, (hafta, f.filename, kullanici_id, dosya_hash))
        con.commit()
        batch_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]

        # Excel parse
        import io as _io
        wb = openpyxl.load_workbook(_io.BytesIO(dosya_baytlari), data_only=True)
        ws = wb.active

        tedarikci_map = {r[0]: r[1] for r in con.execute(
            "SELECT kod, id FROM nexgen_tedarikci"
        ).fetchall()}
        stok_map = {r[0]: r[1] for r in con.execute(
            "SELECT kod, id FROM nexgen_stok_kart"
        ).fetchall()}

        toplam = gecerli = hatali = 0
        for row in ws.iter_rows(min_row=2, values_only=True):
            if not any(row):
                continue
            t_kod = str(row[0]).strip() if row[0] else None
            s_kod = str(row[2]).strip() if row[2] else None
            fiyat_raw = row[4]
            pb = str(row[5]).strip().upper() if row[5] else 'USD'
            kur = row[6]
            vade = row[7]
            f_tarih = str(row[8]).strip() if row[8] else date.today().isoformat()
            g_bas = str(row[9]).strip() if row[9] else None
            g_bit = str(row[10]).strip() if row[10] else None
            notlar = str(row[11]).strip() if row[11] else None

            toplam += 1

            if fiyat_raw is None or str(fiyat_raw).strip() == '':
                continue

            hata = None
            t_id = s_id = None
            try:
                fiyat = float(fiyat_raw)
                if fiyat <= 0:
                    hata = "Fiyat sıfır veya negatif olamaz"
            except (ValueError, TypeError):
                hata = f"Geçersiz fiyat: {fiyat_raw}"
                fiyat = None

            if t_kod not in tedarikci_map:
                hata = f"Tedarikçi kodu bulunamadı: {t_kod}"
            else:
                t_id = tedarikci_map[t_kod]

            if s_kod not in stok_map:
                hata = (hata + " | " if hata else "") + f"Stok kodu bulunamadı: {s_kod}"
            else:
                s_id = stok_map[s_kod]

            onceki = None
            fark = yuzde = None
            if t_id and s_id:
                onceki = _son_fiyat(con, t_id, s_id)
            if onceki and fiyat and not hata:
                fark, yuzde = _fiyat_farki(
                    onceki['fiyat'], onceki['para_birimi'], fiyat, pb
                )

            fiyat_try = None
            if fiyat and kur:
                try:
                    fiyat_try = round(float(fiyat) * float(kur), 4)
                except Exception:
                    pass

            gecerli_mi = 0 if hata else 1
            if gecerli_mi:
                gecerli += 1
            else:
                hatali += 1

            con.execute("""
                INSERT INTO nexgen_fiyat_batch_detay
                  (batch_id, tedarikci_kodu, stok_kodu, tedarikci_id, stok_kart_id,
                   fiyat, para_birimi, kur, fiyat_try, vade_gun,
                   fiyat_tarihi, gecerlilik_bas, gecerlilik_bitis, notlar,
                   onceki_fiyat, onceki_pb, onceki_tarih, fark, yuzde_degisim,
                   gecerli_mi, hata_sebebi)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
            """, (
                batch_id, t_kod, s_kod, t_id, s_id,
                fiyat, pb, kur, fiyat_try, vade,
                f_tarih, g_bas, g_bit, notlar,
                onceki['fiyat'] if onceki else None,
                onceki['para_birimi'] if onceki else None,
                onceki['fiyat_tarihi'] if onceki else None,
                fark, yuzde,
                gecerli_mi, hata
            ))

        con.execute("""
            UPDATE nexgen_fiyat_batch
            SET toplam_satir=?, gecerli_satir=?, hatali_satir=?
            WHERE id=?
        """, (toplam, gecerli, hatali, batch_id))
        con.commit()
    finally:
        con.close()

    # FAZ-SATINALMA-FIYAT-01C: Aynı hafta için onaylı batch varsa uyarıyı flash ile taşı
    if onceki_batch_uyari:
        try:
            from flask import flash
            flash(onceki_batch_uyari, 'warning')
        except Exception:
            pass
    return redirect(url_for('nexgen.fiyat_preview', batch_id=batch_id))


