@nexgen_bp.route('/tablet/barkod/sonuc')
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def tablet_barkod_sonuc():
    """Barkod sorgu sonucu ekranı (GET ile, ?kod= parametresiyle)."""
    kod = (request.args.get('kod') or '').strip().upper()
    if not kod:
        return render_template('nexgen/tablet_barkod.html', active='nexgen', hata='Kod boş olamaz.')

    con = _db()
    try:
        # 1) NG-LOT-YYYY-NNNNN — üretim lot kodu
        if kod.startswith('NG-LOT-'):
            batch = con.execute("""
                SELECT nb.id, nb.batch_kodu, nb.lot_kodu, nb.planlanan_kg, nb.durum,
                       nb.olusturma_tarihi, nb.notlar,
                       uv.boyut,
                       rv.ad AS renk_ad,
                       f.ad AS formul_ad
                FROM nexgen_uretim_batch nb
                JOIN nexgen_uretim_varyant uv ON uv.id = nb.uretim_varyant_id
                JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
                JOIN nexgen_formul f          ON f.id  = rv.formul_id
                WHERE nb.lot_kodu = ?
            """, (kod,)).fetchone()
            if batch:
                return render_template(
                    'nexgen/tablet_barkod_sonuc.html', active='nexgen',
                    tip='URETIM_LOT', kayit=dict(batch), aranan_kod=kod,
                )

        # 2) NG-PRD-YYYY-NNNNN — üretim batch kodu
        if kod.startswith('NG-PRD-'):
            batch = con.execute("""
                SELECT nb.id, nb.batch_kodu, nb.lot_kodu, nb.planlanan_kg, nb.durum,
                       nb.olusturma_tarihi, nb.notlar,
                       uv.boyut,
                       rv.ad AS renk_ad,
                       f.ad AS formul_ad
                FROM nexgen_uretim_batch nb
                JOIN nexgen_uretim_varyant uv ON uv.id = nb.uretim_varyant_id
                JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
                JOIN nexgen_formul f          ON f.id  = rv.formul_id
                WHERE nb.batch_kodu = ?
            """, (kod,)).fetchone()
            if batch:
                return render_template(
                    'nexgen/tablet_barkod_sonuc.html', active='nexgen',
                    tip='URETIM_BATCH', kayit=dict(batch), aranan_kod=kod,
                )

        # 3) AT-YYYY-NNNNN — AR-GE test kodu
        if kod.startswith('AT-'):
            test = con.execute("""
                SELECT at.id, at.test_no, at.test_batch_kg, at.makina,
                       at.yeni_renk_adi, at.durum, at.olusturma_tarihi,
                       uv.boyut,
                       rv.ad AS renk_ad,
                       f.ad AS formul_ad
                FROM nexgen_arge_test at
                JOIN nexgen_uretim_varyant uv ON uv.id = at.kaynak_uretim_varyant_id
                JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
                JOIN nexgen_formul f          ON f.id  = rv.formul_id
                WHERE at.test_no = ?
            """, (kod,)).fetchone()
            if test:
                return render_template(
                    'nexgen/tablet_barkod_sonuc.html', active='nexgen',
                    tip='ARGE', kayit=dict(test), aranan_kod=kod,
                )

        # Hiçbiri bulunamadı
        return render_template(
            'nexgen/tablet_barkod.html', active='nexgen',
            hata=f'"{kod}" kodu bulunamadı. Kontrol edin.',
            son_kod=kod,
        )
    finally:
        con.close()


@nexgen_bp.route('/api/tablet/barkod-bul', methods=['POST'])
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def api_tablet_barkod_bul():
    """Barkod / LOT kodu arama API.

    POST JSON: { "kod": "NG-LOT-2026-00001" }
    Response:
        { ok: true, tip: "URETIM_LOT"|"URETIM_BATCH"|"ARGE",
          redirect_url: "...", ozet: {...} }
    """
    d = request.get_json(silent=True) or {}
    kod = (d.get('kod') or '').strip().upper()
    if not kod:
        return jsonify({'ok': False, 'hata': 'Kod boş olamaz'}), 400

    con = _db()
    try:
        # NG-LOT
        if kod.startswith('NG-LOT-'):
            row = con.execute(
                "SELECT nb.batch_kodu, nb.lot_kodu, nb.planlanan_kg, nb.durum, "
                "uv.boyut, rv.ad AS renk_ad, f.ad AS formul_ad "
                "FROM nexgen_uretim_batch nb "
                "JOIN nexgen_uretim_varyant uv ON uv.id=nb.uretim_varyant_id "
                "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
                "JOIN nexgen_formul f ON f.id=rv.formul_id "
                "WHERE nb.lot_kodu=?", (kod,)
            ).fetchone()
            if row:
                r = dict(row)
                return jsonify({
                    'ok': True, 'tip': 'URETIM_LOT',
                    'redirect_url': f'/nexgen/tablet/barkod/sonuc?kod={kod}',
                    'ozet': r,
                })

        # NG-PRD
        if kod.startswith('NG-PRD-'):
            row = con.execute(
                "SELECT nb.batch_kodu, nb.lot_kodu, nb.planlanan_kg, nb.durum, "
                "uv.boyut, rv.ad AS renk_ad, f.ad AS formul_ad "
                "FROM nexgen_uretim_batch nb "
                "JOIN nexgen_uretim_varyant uv ON uv.id=nb.uretim_varyant_id "
                "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
                "JOIN nexgen_formul f ON f.id=rv.formul_id "
                "WHERE nb.batch_kodu=?", (kod,)
            ).fetchone()
            if row:
                r = dict(row)
                return jsonify({
                    'ok': True, 'tip': 'URETIM_BATCH',
                    'redirect_url': f'/nexgen/tablet/barkod/sonuc?kod={kod}',
                    'ozet': r,
                })

        # AT-
        if kod.startswith('AT-'):
            row = con.execute(
                "SELECT at.test_no, at.test_batch_kg, at.makina, "
                "at.yeni_renk_adi, at.durum, "
                "rv.ad AS renk_ad, f.ad AS formul_ad "
                "FROM nexgen_arge_test at "
                "JOIN nexgen_uretim_varyant uv ON uv.id=at.kaynak_uretim_varyant_id "
                "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
                "JOIN nexgen_formul f ON f.id=rv.formul_id "
                "WHERE at.test_no=?", (kod,)
            ).fetchone()
            if row:
                r = dict(row)
                return jsonify({
                    'ok': True, 'tip': 'ARGE',
                    'redirect_url': f'/nexgen/tablet/barkod/sonuc?kod={kod}',
                    'ozet': r,
                })

        return jsonify({'ok': False, 'hata': f'"{kod}" kodu bulunamadı'}), 404
    finally:
        con.close()


@nexgen_bp.route('/tablet/uretim')
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def tablet_uretim():
    con = _db()
    try:
        varyantlar = _uretime_acik_receteler(con)
        liste = []
        for uv in varyantlar:
            uv_dict = dict(uv)
            kalemler = con.execute("""
                SELECT rk.miktar_kg, rk.stok_kart_id
                FROM nexgen_recete_kalem rk
                WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
            """, (uv_dict['id'],)).fetchall()
            toplam_kg = round(sum(k['miktar_kg'] for k in kalemler), 3) if kalemler else 0.0
            toplam_mal = 0.0
            for k in kalemler:
                fr = con.execute("""
                    SELECT fiyat, para_birimi, kur, fiyat_try
                    FROM nexgen_hammadde_fiyat
                    WHERE stok_kart_id=? AND aktif=1
                    ORDER BY fiyat_tarihi DESC, id DESC LIMIT 1
                """, (k['stok_kart_id'],)).fetchone()
                if fr:
                    if fr['fiyat_try'] and fr['fiyat_try'] > 0:
                        bp = float(fr['fiyat_try'])
                    elif fr['para_birimi'] == 'TRY':
                        bp = float(fr['fiyat'] or 0)
                    elif fr['kur'] and fr['kur'] > 0:
                        bp = float(fr['fiyat'] or 0) * float(fr['kur'])
                    else:
                        bp = 0.0
                    toplam_mal += float(k['miktar_kg']) * bp
            uv_dict['toplam_kg']   = toplam_kg
            uv_dict['kg_maliyet']  = round(toplam_mal / toplam_kg, 2) if toplam_kg > 0 else 0.0
            liste.append(uv_dict)

        # Açık TASLAK batch'lerden "bugünkü işler" — planlanan KG → kazan sayısı
        bugun = date.today().isoformat()
        acik_isler = con.execute("""
            SELECT nb.id, nb.batch_kodu, nb.planlanan_kg, nb.durum,
                   nb.olusturma_tarihi, nb.notlar,
                   uv.id AS uv_id, uv.boyut, uv.ad AS uv_ad,
                   rv.ad AS renk_ad,
                   f.ad AS formul_ad, f.kod AS formul_kod
            FROM nexgen_uretim_batch nb
            JOIN nexgen_uretim_varyant uv ON uv.id = nb.uretim_varyant_id
            JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f          ON f.id  = rv.formul_id
            WHERE nb.durum IN ('TASLAK','HAZIR')
              AND substr(nb.olusturma_tarihi,1,10) = ?
            ORDER BY nb.id ASC
        """, (bugun,)).fetchall()

        # Üretim planından PLANLANDI kayıtlarını da ekle (bugünkü + tarih uygun olanlar)
        plan_isler = con.execute("""
            SELECT np.id AS plan_id, np.plan_kodu, np.planlanan_kg,
                   np.durum AS plan_durum, np.plan_tarihi, np.notlar,
                   np.oncelik_sira, np.rf_renk_id,
                   uv.id AS uv_id, uv.boyut, uv.ad AS uv_ad,
                   rv.ad AS renk_ad,
                   f.ad AS formul_ad, f.kod AS formul_kod
            FROM nexgen_uretim_plan np
            JOIN nexgen_uretim_varyant uv ON uv.id = np.uretim_varyant_id
            JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f          ON f.id  = rv.formul_id
            WHERE np.durum = 'PLANLANDI'
              AND np.plan_tarihi <= ?
            ORDER BY np.oncelik_sira ASC, np.id ASC
        """, (bugun,)).fetchall()

        # Her iş için batch_kg (reçeteden) ve kazan sayısı hesapla
        acik_isler_liste = []
        for is_ in acik_isler:
            is_dict = dict(is_)
            is_dict['kaynak'] = 'BATCH'
            batch_meta = _batch_uretim_hesapla(
                con, is_dict['uv_id'], float(is_dict['planlanan_kg']),
                rf_renk_id=is_dict.get('rf_renk_id'),
            )
            is_dict['batch_kg'] = batch_meta.get('formul_batch_kg', 0.0)
            is_dict['kazan_sayisi'] = batch_meta.get('batch_sayisi', 0) if batch_meta.get('ok') else 0
            is_dict['uretilecek_kg'] = batch_meta.get('uretilecek_kg', 0.0) if batch_meta.get('ok') else 0.0
            is_dict['fazla_kg'] = batch_meta.get('fazla_kg', 0.0) if batch_meta.get('ok') else 0.0
            acik_isler_liste.append(is_dict)

        # Plan kayıtlarını da ekle (PLANLANDI + tarih uygun)
        for p_ in plan_isler:
            p_dict = dict(p_)
            p_dict['kaynak'] = 'PLAN'
            p_dict['batch_kodu'] = None
            p_dict['durum'] = p_dict.get('plan_durum', 'PLANLANDI')
            batch_meta = _batch_uretim_hesapla(
                con, p_dict['uv_id'], float(p_dict['planlanan_kg']),
                rf_renk_id=p_dict.get('rf_renk_id'),
            )
            p_dict['batch_kg'] = batch_meta.get('formul_batch_kg', 0.0)
            p_dict['kazan_sayisi'] = batch_meta.get('batch_sayisi', 0) if batch_meta.get('ok') else 0
            p_dict['uretilecek_kg'] = batch_meta.get('uretilecek_kg', 0.0) if batch_meta.get('ok') else 0.0
            p_dict['fazla_kg'] = batch_meta.get('fazla_kg', 0.0) if batch_meta.get('ok') else 0.0
            acik_isler_liste.append(p_dict)
    finally:
        con.close()

    return render_template(
        'nexgen/tablet_uretim.html',
        active='nexgen',
        varyantlar=liste,
        acik_isler=acik_isler_liste,
    )


@nexgen_bp.route('/tablet/arge')
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def tablet_arge():
    """AR-GE Tablet — yeni mimari (FAZ-3K).
    Akış: Cari → Formül → RF → Boyut → Miktar → Not → Kaydet → Barkod.
    """
    con = _db()
    try:
        # Formüller (reçetesi olan, aktif)
        formuller_raw = con.execute(f"""
            SELECT DISTINCT f.id, f.kod, f.ad
            FROM nexgen_formul f
            JOIN nexgen_renk_varyant rv ON rv.formul_id = f.id AND rv.aktif = 1
            JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id AND uv.aktif = 1
            JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE f.aktif = 1 AND uv.recete_durum != 'PASIF'
              AND ({cekirdek_kod_sql_filter('f')})
            ORDER BY f.kod, f.ad
        """).fetchall()
        formuller = [dict(r) for r in formuller_raw]

        # Üretim varyantları (formül+boyut bilgisiyle, taban reçetesi olan)
        # renk_varyant_id ve master_kg frontend için zorunlu
        varyantlar_raw = con.execute(f"""
            SELECT uv.id, uv.boyut, uv.ad AS uv_ad, uv.recete_durum,
                   rv.id AS renk_varyant_id,
                   rv.ad AS renk_ad,
                   f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad,
                   ROUND(SUM(rk.miktar_kg), 3) AS master_kg,
                   COUNT(rk.id) AS kalem_say
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id AND rv.aktif = 1
            JOIN nexgen_formul f        ON f.id  = rv.formul_id AND f.aktif = 1
            JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE uv.aktif = 1 AND uv.recete_durum != 'PASIF'
              AND ({cekirdek_kod_sql_filter('f')})
            GROUP BY uv.id
            HAVING kalem_say > 0
            ORDER BY f.kod, rv.ad, uv.boyut
        """).fetchall()
        varyantlar = formul_secim_gosterim_uygula(
            [dict(v) for v in varyantlar_raw],
            kod_alan='formul_kod',
            ad_alan='formul_ad',
            boyut_alan='boyut',
            harf_ekle=True,
        )
        uv_boyut_map = {
            int(v['formul_id']): v['boyut']
            for v in varyantlar
            if v.get('formul_id') and v.get('boyut')
        }
        formuller = formul_secim_gosterim_uygula(
            formuller, uv_boyut_map=uv_boyut_map, harf_ekle=True,
        )

        # RF renk listesi (onaylı) — kolon adı 'ad'
        rf_liste_raw = con.execute("""
            SELECT id, rf_kod, ad AS rf_ad, durum, aktif, kaynak_arge_test_id
            FROM nexgen_rf_renk
            WHERE aktif = 1 AND durum = 'ONAYLI'
            ORDER BY rf_kod
        """).fetchall()
        rf_liste = [
            dict(r) for r in rf_liste_raw
            if yeni_secimde_renk_gosterilebilir_mi(dict(r))
        ]

        # Boya stok (RF el girişi için)
        boya_stok_raw = con.execute("""
            SELECT id, kod, ad FROM nexgen_stok_kart
            WHERE aktif = 1 AND kategori = 'BOYA'
            ORDER BY kod, ad
        """).fetchall()
        boya_stok = [dict(r) for r in boya_stok_raw]

        # Cariler
        cariler_raw = con.execute(
            "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE aktif=1 ORDER BY unvan"
        ).fetchall()
        cariler = [dict(c) for c in cariler_raw]

        # Son numuneler (popup için — arama + son 3 + tam liste)
        son_numuneler_raw = con.execute("""
            SELECT t.id, t.test_no, t.arge_kodu, t.durum,
                   t.yeni_renk_adi, t.test_batch_kg,
                   t.olusturma_tarihi, t.aktif_rev_no,
                   t.calisma_tipi, t.formul_grup_adi, t.renk_kodu,
                   t.saha_testi_gerekli_mi, t.olusturan_id, t.sorumlu_kullanici_id,
                   f.kod AS formul_kod, f.ad AS formul_ad,
                   uv.boyut,
                   c.unvan AS cari_unvan,
                   ku.KullaniciAdi AS olusturan_ad,
                   (SELECT GROUP_CONCAT(ku2.boyut, ',')
                    FROM nexgen_arge_kaynak_uv ku2
                    WHERE ku2.arge_test_id = t.id AND ku2.aktif_mi = 1
                   ) AS boyutlar_csv
            FROM nexgen_arge_test t
            LEFT JOIN nexgen_uretim_varyant uv ON uv.id = t.kaynak_uretim_varyant_id
            LEFT JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
            LEFT JOIN nexgen_formul f          ON f.id  = rv.formul_id
            LEFT JOIN nexgen_cari c       ON c.id  = t.cari_id
            LEFT JOIN sistem_kullanici ku ON ku.Id  = t.olusturan_id
            WHERE t.aktif = 1
            ORDER BY t.id DESC LIMIT 40
        """).fetchall()
        son_numuneler = formul_secim_gosterim_uygula(
            [dict(r) for r in son_numuneler_raw],
            kod_alan='formul_kod',
            ad_alan='formul_ad',
            boyut_alan='boyut',
            harf_ekle=True,
        )
        _boyut_harf = {'LARGE': 'L', 'SMALL': 'S', 'MEDIUM': 'M'}
        _aksiyon_map = {
            'ARGE_HAZIR': 'Denemeyi başlat / etiket',
            'DENEMEDE': 'Denemeyi sürdür',
            'REVIZYON_GEREKLI': 'Revize et',
            'BEKLIYOR': 'İşlem bekliyor',
            'DEVAM': 'Devam et',
        }
        kid = _kullanici_id()
        aksiyon_numuneler = []
        for t in son_numuneler:
            durum = (t.get('durum') or '').upper()
            # Ferhat saha işleri Vedat aksiyon listesine düşmez
            if (t.get('saha_testi_gerekli_mi') or 0) and durum in (
                'ARGE_HAZIR', 'SAHA_BEKLIYOR', 'FERHAT_BEKLIYOR', 'SAHA_TESTTE'
            ):
                continue
            if durum not in ('ARGE_HAZIR', 'DENEMEDE', 'REVIZYON_GEREKLI', 'BEKLIYOR', 'DEVAM'):
                continue
            # NX-AR: kendisine atanmış / oluşturduğu; legacy: tümü
            is_nx = (t.get('arge_kodu') or '').startswith('NX-AR-')
            if is_nx and kid:
                atanmis = t.get('sorumlu_kullanici_id') or t.get('olusturan_id')
                if atanmis and int(atanmis) != int(kid):
                    continue
            csv = t.get('boyutlar_csv') or t.get('boyut') or ''
            harfler = []
            for part in str(csv).split(','):
                h = _boyut_harf.get(part.strip().upper(), '')
                if h and h not in harfler:
                    harfler.append(h)
            # L+S sırası
            order = {'L': 0, 'S': 1, 'M': 2}
            harfler.sort(key=lambda x: order.get(x, 9))
            t['boyut_etiket'] = '+'.join(harfler) if harfler else '—'
            t['formul_goster'] = t.get('formul_grup_adi') or t.get('formul_ad') or '—'
            t['renk_goster'] = t.get('yeni_renk_adi') or t.get('renk_kodu') or '—'
            t['aksiyon_metin'] = _aksiyon_map.get(durum, 'İşlem yap')
            aksiyon_numuneler.append(t)

        bugun_numune = con.execute(
            "SELECT COUNT(*) AS c FROM nexgen_arge_test "
            "WHERE aktif=1 AND date(olusturma_tarihi)=date('now')"
        ).fetchone()['c']

        # Ana ekran — bekleyen (tablet aksiyon + legacy)
        bekleyen_say = len(aksiyon_numuneler)

    finally:
        con.close()

    return render_template(
        'nexgen/tablet_arge.html',
        active='nexgen',
        formuller=formuller,
        varyantlar=varyantlar,
        rf_liste=rf_liste,
        boya_stok=boya_stok,
        cariler=cariler,
        son_numuneler=son_numuneler,
        aksiyon_numuneler=aksiyon_numuneler,
        bugun_numune=bugun_numune,
        bekleyen_say=bekleyen_say,
        kullanici_ad=_kullanici_ad(),
    )


@nexgen_bp.route('/tablet/arge/musteri-renk')
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def tablet_arge_musteri_renk():
    """MODÜL-01 — Müşteri Renk Talebi.
    Müşterinin karteladan seçtiği onaylı RF rengi ile numune hazırlama.
    Adımlar: Cari → Formül → RF → Boyut → Miktar → Reçete Önizleme → Kaydet & Barkod
    """
    con = _db()
    try:
        # Cariler
        cariler = [dict(r) for r in con.execute(
            "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE aktif=1 ORDER BY unvan"
        ).fetchall()]

        # Formüller — yalnız çekirdek, reçetesi olan
        formuller = [dict(r) for r in con.execute(f"""
            SELECT DISTINCT f.id, f.kod, f.ad, f.urun_ailesi
            FROM nexgen_formul f
            JOIN nexgen_renk_varyant rv ON rv.formul_id = f.id AND rv.aktif = 1
            JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id AND uv.aktif = 1
            JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE f.aktif = 1 AND uv.recete_durum != 'PASIF'
              AND ({cekirdek_kod_sql_filter('f')})
            ORDER BY f.kod, f.ad
        """).fetchall()]

        # Renk varyantları (alt formül / model — TERLİK 18-22, TABAN 18-28 vb.)
        renk_varyantlar = [dict(r) for r in con.execute(f"""
            SELECT rv.id, rv.ad AS rv_ad, rv.formul_id,
                   f.kod AS formul_kod,
                   GROUP_CONCAT(DISTINCT uv.boyut ORDER BY uv.boyut) AS boyutlar,
                   GROUP_CONCAT(DISTINCT uv.id    ORDER BY uv.boyut) AS uv_idler
            FROM nexgen_renk_varyant rv
            JOIN nexgen_formul f ON f.id = rv.formul_id AND f.aktif = 1
            JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id AND uv.aktif = 1
            JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE rv.aktif = 1 AND uv.recete_durum != 'PASIF'
              AND ({cekirdek_kod_sql_filter('f')})
            GROUP BY rv.id HAVING boyutlar IS NOT NULL
            ORDER BY rv.formul_id, rv.ad
        """).fetchall()]

        # Üretim varyantları (boyut → uv_id eşlemesi için, reçete önizlemede kullanılır)
        varyantlar = [dict(v) for v in con.execute(f"""
            SELECT uv.id, uv.boyut, uv.ad AS uv_ad, uv.recete_durum,
                   rv.id AS rv_id, rv.ad AS renk_ad,
                   f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad,
                   f.urun_ailesi,
                   ROUND(SUM(rk.miktar_kg), 3) AS master_kg,
                   COUNT(rk.id) AS kalem_say
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id AND rv.aktif = 1
            JOIN nexgen_formul f ON f.id = rv.formul_id AND f.aktif = 1
            JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE uv.aktif = 1 AND uv.recete_durum != 'PASIF'
              AND ({cekirdek_kod_sql_filter('f')})
            GROUP BY uv.id HAVING kalem_say > 0
            ORDER BY f.kod, rv.ad, uv.boyut
        """).fetchall()]
        formul_gruplar = formul_secim_gruplari_hazirla(varyantlar)
        uv_boyut_map = {
            int(v['formul_id']): v['boyut']
            for v in varyantlar
            if v.get('formul_id') and v.get('boyut')
        }
        formuller = formul_secim_gosterim_uygula(
            formuller, uv_boyut_map=uv_boyut_map, harf_ekle=True,
        )
        varyantlar = formul_secim_gosterim_uygula(
            varyantlar,
            kod_alan='formul_kod',
            ad_alan='formul_ad',
            boyut_alan='boyut',
            harf_ekle=True,
        )

        # Onaylı çekirdek RF renkleri
        rf_liste = [
            dict(r) for r in con.execute("""
                SELECT id, rf_kod, ad AS rf_ad, durum, aktif, kaynak_arge_test_id
                FROM nexgen_rf_renk
                WHERE aktif = 1 AND durum = 'ONAYLI'
                ORDER BY rf_kod
            """).fetchall()
            if yeni_secimde_renk_gosterilebilir_mi(dict(r))
        ]

    finally:
        con.close()

    return render_template(
        'nexgen/modul01_musteri_renk.html',
        active='nexgen',
        cariler=cariler,
        formuller=formuller,
        formul_gruplar=formul_gruplar,
        renk_varyantlar=renk_varyantlar,
        varyantlar=varyantlar,
        rf_liste=rf_liste,
        kullanici_ad=_kullanici_ad(),
    )


@nexgen_bp.route('/tablet/arge/yeni-rf')
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def tablet_arge_yeni_rf():
    """MODÜL-02 — Yeni RF Renk Geliştirme.
    Vedat stok pigmentlerinden seçip gramaj girerek yeni RF denemesi oluşturur.
    Backend API henüz bağlanmadı — frontend onayı bekleniyor.
    """
    con = _db()
    try:
        cariler = [dict(r) for r in con.execute(
            "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE aktif=1 ORDER BY unvan"
        ).fetchall()]

        # Yalnız çekirdek formüller (1BA/2BA/3BA) — legacy 575/627/675/810/FOR-001 yok
        formuller = [dict(r) for r in con.execute(f"""
            SELECT DISTINCT f.id, f.kod, f.ad
            FROM nexgen_formul f
            JOIN nexgen_renk_varyant rv ON rv.formul_id = f.id AND rv.aktif = 1
            WHERE f.aktif = 1
              AND ({cekirdek_kod_sql_filter('f')})
            ORDER BY f.kod, f.ad
        """).fetchall()]

        renk_varyantlar = [dict(r) for r in con.execute(f"""
            SELECT rv.id, rv.formul_id, rv.ad,
                   GROUP_CONCAT(DISTINCT uv.boyut) AS boyutlar
            FROM nexgen_renk_varyant rv
            JOIN nexgen_formul f ON f.id = rv.formul_id AND f.aktif = 1
            LEFT JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id AND uv.aktif = 1
            WHERE rv.aktif = 1
              AND ({cekirdek_kod_sql_filter('f')})
            GROUP BY rv.id
            ORDER BY rv.formul_id, rv.ad
        """).fetchall()]

        # renk_varyant_id ve master_kg frontend'de uv_id çözümü + hesap için zorunlu
        varyantlar = [dict(r) for r in con.execute(f"""
            SELECT uv.id, uv.renk_varyant_id, uv.boyut, uv.recete_durum,
                   rv.ad AS rv_ad, rv.formul_id,
                   ROUND(SUM(rk.miktar_kg), 3) AS master_kg
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id AND rv.aktif = 1
            JOIN nexgen_formul f ON f.id = rv.formul_id AND f.aktif = 1
            LEFT JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
            WHERE uv.aktif = 1
              AND ({cekirdek_kod_sql_filter('f')})
            GROUP BY uv.id
            ORDER BY rv.formul_id, rv.ad, uv.boyut
        """).fetchall()]
        uv_boyut_map = {
            int(v['formul_id']): v['boyut']
            for v in varyantlar
            if v.get('formul_id') and v.get('boyut')
        }
        formuller = formul_secim_gosterim_uygula(
            formuller, uv_boyut_map=uv_boyut_map, harf_ekle=True,
        )

        # Renk bileşenleri — renk_bileseni_mi=1 olan tüm kartlar
        # (BOYA kategorisi + ATR-312 gibi çift rollü katkılar dahil)
        # Liste: yeni_tanim - ad - kod formatında sıralanır
        stok_pigmentler = [dict(r) for r in con.execute("""
            SELECT id, kod, ad, kategori, yeni_tanim, tanim
            FROM nexgen_stok_kart
            WHERE aktif = 1 AND renk_bileseni_mi = 1
            ORDER BY yeni_tanim, ad
        """).fetchall()]

    finally:
        con.close()

    return render_template(
        'nexgen/modul02_yeni_rf.html',
        active='nexgen',
        cariler=cariler,
        formuller=formuller,
        renk_varyantlar=renk_varyantlar,
        varyantlar=varyantlar,
        stok_pigmentler=stok_pigmentler,
        kullanici_ad=_kullanici_ad(),
    )


@nexgen_bp.route('/tablet/arge/yeni-formul')
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def tablet_arge_yeni_formul():
    """MODÜL-03 — Yeni Formül Geliştir.  (FAZ-3F-10 / 2026-07-09)
    İki yol: (A) Mevcut formülden taslak al, (B) Sıfırdan yeni formül oluştur.
    Backend: POST /nexgen/api/tablet/arge/yeni-formul-kaydet → NX-ARF-NNNN
    """
    con = _db()
    try:
        # Cariler
        cariler = [dict(r) for r in con.execute(
            "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE aktif=1 ORDER BY unvan"
        ).fetchall()]

        # Referans formüller (taslak için) — yalnız çekirdek
        formuller = [dict(r) for r in con.execute(f"""
            SELECT DISTINCT f.id, f.kod, f.ad
            FROM nexgen_formul f
            JOIN nexgen_renk_varyant rv ON rv.formul_id = f.id AND rv.aktif = 1
            JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id AND uv.aktif = 1
            WHERE f.aktif = 1 AND ({cekirdek_kod_sql_filter('f')})
            ORDER BY f.kod, f.ad
        """).fetchall()]
        uv_boyut_rows = con.execute(f"""
            SELECT f.id AS formul_id, uv.boyut
            FROM nexgen_formul f
            JOIN nexgen_renk_varyant rv ON rv.formul_id = f.id AND rv.aktif = 1
            JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id AND uv.aktif = 1
            WHERE f.aktif = 1 AND ({cekirdek_kod_sql_filter('f')})
            ORDER BY f.id, uv.id
        """).fetchall()
        uv_boyut_map = {}
        for r in uv_boyut_rows:
            fid = int(r['formul_id'])
            if fid not in uv_boyut_map and r['boyut']:
                uv_boyut_map[fid] = r['boyut']
        formuller = formul_secim_gosterim_uygula(
            formuller, uv_boyut_map=uv_boyut_map, harf_ekle=True,
        )

        # Hammadde/Katkı/Recycle stok kartları (renk bileşeni olmayanlar)
        stok_hammaddeler = [dict(r) for r in con.execute("""
            SELECT id, kod, ad, kategori, yeni_tanim, tanim,
                   beklenen_kg, rezerve_kg, giris_kg
            FROM nexgen_stok_kart
            WHERE aktif = 1 AND COALESCE(renk_bileseni_mi, 0) = 0
            ORDER BY kategori, ad
        """).fetchall()]

        # Renk bileşenleri
        stok_renkler = [dict(r) for r in con.execute("""
            SELECT id, kod, ad, kategori, yeni_tanim, tanim,
                   beklenen_kg, rezerve_kg, giris_kg
            FROM nexgen_stok_kart
            WHERE aktif = 1 AND renk_bileseni_mi = 1
            ORDER BY yeni_tanim, ad
        """).fetchall()]

    except Exception as e:
        print(f"[nexgen] tablet_arge_yeni_formul hata: {e}")
        cariler = []
        formuller = []
        stok_hammaddeler = []
        stok_renkler = []
    finally:
        con.close()

    return render_template(
        'nexgen/modul03_yeni_formul.html',
        active='nexgen',
        cariler=cariler,
        formuller=formuller,
        stok_hammaddeler=stok_hammaddeler,
        stok_renkler=stok_renkler,
        kullanici_ad=_kullanici_ad(),
    )


# ─────────────────────────────────────────────────────────────
# MODÜL-03 — Yeni Formül Kaydet (FAZ-3F-9)
# POST /nexgen/api/tablet/arge/yeni-formul-kaydet
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/tablet/arge/yeni-formul-kaydet', methods=['POST'])
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def api_tablet_yeni_formul_kaydet():
    """MODÜL-03 — AR-GE Yeni Formül kaydı oluşturur.

    İki yol:
      yontem='SIFIRDAN'  → boş formül, hammaddeler payload'dan gelir
      yontem='TASLAK'    → kaynak_formul_id'nin reçete kalemleri kopyalanır,
                           üzerine payload'daki hammaddeler eklenir/güncellenir.

    Kaynak üretim formülü (nexgen_formul) ASLA değişmez.

    POST JSON:
    {
      "yontem"           : "SIFIRDAN" | "TASLAK",
      "cari_id"          : int | null,
      "formul_adi"       : str,         -- zorunlu
      "aciklama"         : str | null,
      "kaynak_formul_id" : int | null,  -- yontem=TASLAK ise zorunlu
      "hammaddeler"      : [            -- seçilen bileşenler
          {
            "stok_kart_id"    : int,
            "kg_str"          : str,    -- örn: "3.500"
            "yeni_tanim"      : str,
            "ad"              : str,
            "kategori"        : str,
            "renk_bileseni_mi": 0,
            "gram_str"        : str | null  -- renk bileşeni için
          }, ...
      ],
      "renk_bilesenleri" : [            -- renk bileşenleri (renk_secim='MEVCUT')
          {
            "stok_kart_id": int,
            "gram_str"    : str,
            "ad"          : str,
            "yeni_tanim"  : str
          }, ...
      ],
      "renk_secim"       : "YOK" | "MEVCUT" | "YENI",
      "arge_notu"        : str          -- zorunlu
    }

    Response (ok):
    {
      "ok"         : true,
      "arge_kodu"  : "NX-ARF-0001",
      "formul_id"  : int,
      "formul_adi" : str
    }
    """
    data = request.get_json(silent=True) or {}

    # ── Zorunlu alan kontrolü ──────────────────────────────────
    formul_adi  = (data.get('formul_adi') or '').strip()
    arge_notu   = (data.get('arge_notu')  or '').strip()
    yontem      = (data.get('yontem')     or 'SIFIRDAN').strip().upper()
    renk_secim  = (data.get('renk_secim') or 'YOK').strip().upper()

    if not formul_adi:
        return jsonify({"ok": False, "hata": "formul_adi zorunludur."}), 400
    if not arge_notu:
        return jsonify({"ok": False, "hata": "arge_notu zorunludur."}), 400
    if yontem not in {'SIFIRDAN', 'TASLAK'}:
        return jsonify({"ok": False, "hata": "yontem: SIFIRDAN veya TASLAK olmalı."}), 400

    cari_id           = data.get('cari_id')
    aciklama          = (data.get('aciklama') or '').strip() or None
    kaynak_formul_id  = data.get('kaynak_formul_id')
    hammaddeler       = data.get('hammaddeler') or []
    renk_bilesenleri  = data.get('renk_bilesenleri') or []

    if yontem == 'TASLAK' and not kaynak_formul_id:
        return jsonify({"ok": False, "hata": "TASLAK yönteminde kaynak_formul_id zorunludur."}), 400

    _kul = session.get('kullanici') or {}
    olusturan_id = _kul.get('id') or _kul.get('kullanici_id') or None

    con = _db()
    try:
        # ── NX-ARF kodu üret ──────────────────────────────────
        arge_kodu = _nx_arf_kod_uret(con)

        # ── Ana kayıt ─────────────────────────────────────────
        con.execute("""
            INSERT INTO nexgen_arge_formul
                (arge_kodu, formul_adi, aciklama, yontem,
                 kaynak_formul_id, cari_id, renk_secim,
                 arge_notu, durum, olusturan_id, olusturma_tarihi)
            VALUES (?, ?, ?, ?,
                    ?, ?, ?,
                    ?, 'TASLAK', ?, datetime('now'))
        """, (arge_kodu, formul_adi, aciklama, yontem,
              kaynak_formul_id, cari_id, renk_secim,
              arge_notu, olusturan_id))

        formul_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]

        # ── TASLAK: kaynak üretim formülünün reçetesini kopyala ──
        if yontem == 'TASLAK' and kaynak_formul_id:
            # Kaynak formülün tüm üretim varyantlarındaki kalemleri al
            # (ilk/varsayılan varyant: önce STANDART, yoksa ilk bulunan)
            kaynak_uv = con.execute("""
                SELECT uv.id FROM nexgen_uretim_varyant uv
                JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
                WHERE rv.formul_id = ? AND uv.aktif = 1
                ORDER BY CASE uv.boyut
                    WHEN 'STANDART' THEN 1
                    WHEN 'LARGE'    THEN 2
                    WHEN 'SMALL'    THEN 3
                    ELSE 4 END
                LIMIT 1
            """, (kaynak_formul_id,)).fetchone()

            if kaynak_uv:
                kaynaklar = con.execute("""
                    SELECT rk.stok_kart_id, rk.sira, rk.miktar_kg, rk.aciklama,
                           sk.ad, sk.kategori, sk.yeni_tanim,
                           COALESCE(sk.renk_bileseni_mi, 0) AS renk_bileseni_mi
                    FROM nexgen_recete_kalem rk
                    JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
                    WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
                    ORDER BY rk.sira
                """, (kaynak_uv['id'],)).fetchall()

                for sira_no, k in enumerate(kaynaklar, start=1):
                    con.execute("""
                        INSERT INTO nexgen_arge_formul_kalem
                            (arge_formul_id, stok_kart_id, sira,
                             miktar_kg, renk_bileseni_mi, aciklama)
                        VALUES (?, ?, ?, ?, ?, ?)
                    """, (formul_id, k['stok_kart_id'], sira_no,
                          k['miktar_kg'], k['renk_bileseni_mi'],
                          k['aciklama']))

        # ── Payload'dan gelen hammaddeler ────────────────────────
        # (SIFIRDAN'da tümü, TASLAK'ta var olanın üzerine eklenir/güncellenir)
        # Önce mevcut formül kalem ID'lerini al (taslakta gelmiş olabilir)
        mevcut_stok_ids = {
            r['stok_kart_id'] for r in con.execute(
                "SELECT stok_kart_id FROM nexgen_arge_formul_kalem WHERE arge_formul_id=? AND aktif=1",
                (formul_id,)
            ).fetchall()
        }

        # Son sıra no
        son_sira_row = con.execute(
            "SELECT COALESCE(MAX(sira),0) FROM nexgen_arge_formul_kalem WHERE arge_formul_id=?",
            (formul_id,)
        ).fetchone()
        son_sira = son_sira_row[0] if son_sira_row else 0

        for hm in hammaddeler:
            stok_id = hm.get('stok_kart_id')
            if not stok_id:
                continue
            try:
                miktar_kg = float(hm.get('kg_str') or 0)
            except (ValueError, TypeError):
                miktar_kg = 0.0

            if stok_id in mevcut_stok_ids:
                # Taslak kopyasında zaten var — miktarı güncelle
                con.execute(
                    "UPDATE nexgen_arge_formul_kalem "
                    "SET miktar_kg=? "
                    "WHERE arge_formul_id=? AND stok_kart_id=? AND aktif=1",
                    (miktar_kg, formul_id, stok_id))
            else:
                son_sira += 1
                con.execute("""
                    INSERT INTO nexgen_arge_formul_kalem
                        (arge_formul_id, stok_kart_id, sira, miktar_kg,
                         renk_bileseni_mi, aktif)
                    VALUES (?, ?, ?, ?, 0, 1)
                """, (formul_id, stok_id, son_sira, miktar_kg))
                mevcut_stok_ids.add(stok_id)

        # ── Renk bileşenleri ─────────────────────────────────────
        for rb in renk_bilesenleri:
            stok_id = rb.get('stok_kart_id')
            if not stok_id:
                continue
            try:
                gram    = float(rb.get('gram_str') or 0)
                kg_val  = round(gram / 1000, 9)
            except (ValueError, TypeError):
                gram, kg_val = 0.0, 0.0

            son_sira += 1
            con.execute("""
                INSERT OR IGNORE INTO nexgen_arge_formul_kalem
                    (arge_formul_id, stok_kart_id, sira, miktar_kg,
                     renk_bileseni_mi, miktar_gr, aktif)
                VALUES (?, ?, ?, ?, 1, ?, 1)
            """, (formul_id, stok_id, son_sira, kg_val, gram))

        con.commit()

        # Kaydın olusturma_tarihi'ni al
        tarih_row = con.execute(
            "SELECT olusturma_tarihi FROM nexgen_arge_formul WHERE id=?",
            (formul_id,)
        ).fetchone()
        olusturma_tarihi = tarih_row['olusturma_tarihi'] if tarih_row else None

        return jsonify({
            "ok"                : True,
            "arge_kodu"         : arge_kodu,
            "formul_id"         : formul_id,
            "formul_adi"        : formul_adi,
            "olusturma_tarihi"  : olusturma_tarihi,
            "durum"             : "TASLAK",
        })

    except Exception as e:
        con.rollback()
        print(f"[nexgen] api_tablet_yeni_formul_kaydet hata: {e}")
        return jsonify({"ok": False, "hata": f"Sunucu hatası: {str(e)}"}), 500
    finally:
        con.close()


@nexgen_bp.route('/tablet/arge/barkod-yazdir')
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def tablet_arge_barkod_yazdir():
    """MODÜL-01 — Barkod Yazdır.
    AR-GE test kaydının barkodunu yazdırma sayfası.
    ?test_id=<int> ile çağrılır.
    """
    test_id = request.args.get('test_id', type=int)
    if not test_id:
        return "test_id parametresi gerekli.", 400

    con = _db()
    try:
        test = con.execute("""
            SELECT
                at.id, at.test_no, at.lot_no, at.test_batch_kg,
                at.numune_orani, at.yeni_renk_adi, at.makina,
                at.notlar, at.talep_referansi, at.olusturma_tarihi,
                at.durum,
                uv.boyut,
                rv.ad  AS rv_ad,
                f.kod  AS formul_kod,
                f.ad   AS formul_ad,
                c.unvan AS cari_ad,
                rf.rf_kod, rf.ad AS rf_ad
            FROM nexgen_arge_test at
            JOIN nexgen_uretim_varyant uv ON uv.id = at.kaynak_uretim_varyant_id
            JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f          ON f.id  = rv.formul_id
            LEFT JOIN nexgen_cari c       ON c.id  = at.cari_id
            LEFT JOIN nexgen_rf_renk rf   ON rf.id = at.rf_renk_id
            WHERE at.id = ?
        """, (test_id,)).fetchone()

        if not test:
            return f"Test ID={test_id} bulunamadı.", 404

        # Code39 benzeri SVG barkod oluştur (basit dikey çizgi temsili)
        barkod_svg = _barkod_svg_olustur(test['test_no'])

        return render_template(
            'nexgen/modul01_barkod.html',
            active='nexgen',
            test=dict(test),
            barkod_svg=barkod_svg,
        )
    finally:
        con.close()


def _barkod_svg_olustur(metin):
    """Verilen metinden basit görsel barkod SVG üretir.
    Gerçek Code39 encoder olmadan deterministik çizgi genişliği kullanır.
    Sonuç baskıda tanımlanabilir değil, görsel temsil amaçlıdır.
    Gerçek barkod okutma için ZPL/PDF entegrasyonu gerekir.
    """
    import hashlib
    W, H = 300, 60
    ince, kalin = 2, 5
    bosluk = 2

    # Metni hash'e çevirip deterministik çizgi deseni üret
    h = hashlib.md5(metin.encode()).hexdigest()
    bars = []
    x = 10
    for i, ch in enumerate(h[:40]):
        val = int(ch, 16)
        genislik = kalin if val > 7 else ince
        if x + genislik > W - 10:
            break
        bars.append((x, genislik))
        x += genislik + bosluk

    rects = ''.join(
        f'<rect x="{bx}" y="4" width="{bw}" height="{H - 8}" fill="#0B2545"/>'
        for bx, bw in bars
    )
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" '
        f'viewBox="0 0 {W} {H}">{rects}</svg>'
    )


@nexgen_bp.route('/api/tablet/arge/recete-onizle', methods=['GET'])
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def api_tablet_recete_onizle():
    """MODÜL-01 Reçete Önizleme API.

    Giriş: uv_id, rf_id (0=yok), oran (numune yüzdesi, ör: 10.0 = %10)
    Hesap: numune_kg = master_kg × (oran / 100)
    RF boya da aynı oranla ölçeklenir.
    debug=1 eklenirse ham audit bilgisi döner.
    DB yazmaz.
    """
    if not yetki_var('nexgen.tablet.view', 'can_view'):
        return jsonify({'ok': False, 'hata': 'Yetki yok'}), 403

    uv_id    = request.args.get('uv_id', type=int)
    rf_id    = request.args.get('rf_id', type=int, default=0)
    oran_str = request.args.get('oran',  type=str, default='10')
    debug    = request.args.get('debug', type=int, default=0)

    try:
        oran = float(oran_str)   # yüzde değeri, örn: 10.0 = %10
    except (TypeError, ValueError):
        return jsonify({'ok': False, 'hata': 'Geçersiz oran değeri'}), 400

    if oran <= 0 or oran > 100:
        return jsonify({'ok': False, 'hata': 'oran 0-100 arasında olmalı'}), 400

    if not uv_id:
        return jsonify({'ok': False, 'hata': 'uv_id zorunlu'}), 400

    con = _db()
    try:
        # Üretim varyantı doğrula
        uv = con.execute("""
            SELECT uv.id, uv.boyut,
                   rv.id AS rv_id, rv.ad AS rv_ad,
                   f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f ON f.id = rv.formul_id
            WHERE uv.id = ? AND uv.aktif = 1
        """, (uv_id,)).fetchone()
        if not uv:
            return jsonify({'ok': False, 'hata': f'uv_id={uv_id} bulunamadı veya pasif'}), 404

        # Master reçete kalemleri — TÜMÜ (BOYA dahil, sadece audit için)
        kalemler = con.execute("""
            SELECT rk.miktar_kg, rk.sira, sk.id AS sk_id, sk.kod, sk.ad, sk.kategori
            FROM nexgen_recete_kalem rk
            JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
            ORDER BY rk.sira, rk.id
        """, (uv_id,)).fetchall()
        if not kalemler:
            return jsonify({'ok': False, 'hata': f'uv_id={uv_id} için reçete kalemi yok'}), 404

        # Master KG = tüm kalemlerin toplamı (BOYA dahil)
        master_kg = round(sum(float(k['miktar_kg']) for k in kalemler), 4)
        if master_kg <= 0:
            return jsonify({'ok': False, 'hata': 'Master reçete KG = 0'}), 400

        # NexGen hesap kuralı:
        #   Giriş: oran (%) — operatör tarafından seçilir
        #   Hesap: numune_kg = master_kg × (oran / 100)
        numune_orani       = oran / 100.0          # ondalık çarpan, ör: 0.10
        numune_kg          = round(master_kg * numune_orani, 4)
        numune_orani_yuzde = oran                  # ekranda gösterilecek % değeri

        # Taban hammaddeler (BOYA kategorisi hariç)
        taban = []
        taban_audit = []
        for k in kalemler:
            kategori = (k['kategori'] or '').upper()
            ham_kg   = float(k['miktar_kg'])
            olcek_kg = ham_kg * numune_orani
            olcek_kg_yuvarlak = round(olcek_kg, 4)

            taban_audit.append({
                'ad': k['ad'] or '', 'kod': k['kod'] or '',
                'kategori': kategori,
                'master_kg': ham_kg,
                'olcek_kg': olcek_kg,
                'olcek_kg_yuvarlak': olcek_kg_yuvarlak,
                'atildi': kategori == 'BOYA' or olcek_kg_yuvarlak <= 0,
            })

            if kategori == 'BOYA':
                continue
            if olcek_kg_yuvarlak <= 0:
                continue
            taban.append({'ad': k['ad'] or '', 'kod': k['kod'] or '', 'kg': olcek_kg_yuvarlak})

        # RF Boya kalemleri
        # nexgen_rf_kalem.miktar_kg → RF'nin master reçete bazında miktarı (kg)
        # Aynı numune_orani ile ölçeklenir.
        boya = []
        boya_audit = []
        rf_debug_info = {'rf_id': rf_id, 'row_count': 0, 'pigment_ad_col_exists': None}

        if rf_id and rf_id > 0:
            # Önce sütun varlığını kontrol et
            try:
                pragma = con.execute("PRAGMA table_info(nexgen_rf_kalem)").fetchall()
                rf_cols = [p['name'] for p in pragma]
                rf_debug_info['columns'] = rf_cols
                has_pigment_ad = 'pigment_ad' in rf_cols
                rf_debug_info['pigment_ad_col_exists'] = has_pigment_ad
            except Exception as e:
                rf_debug_info['pragma_error'] = str(e)
                has_pigment_ad = False

            rf_rows = con.execute("""
                SELECT rk.id, rk.miktar_kg, rk.sira,
                       rk.stok_kart_id,
                       sk.kod AS stok_kod, sk.ad AS stok_ad
                FROM nexgen_rf_kalem rk
                LEFT JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
                WHERE rk.rf_renk_id = ? AND rk.aktif = 1
                ORDER BY rk.sira, rk.id
            """, (rf_id,)).fetchall()
            rf_debug_info['row_count'] = len(rf_rows)

            # pigment_ad varsa ayrıca çek
            pigment_map = {}
            if has_pigment_ad:
                try:
                    pa_rows = con.execute(
                        "SELECT id, pigment_ad FROM nexgen_rf_kalem WHERE rf_renk_id=? AND aktif=1",
                        (rf_id,)
                    ).fetchall()
                    pigment_map = {row['id']: (row['pigment_ad'] or '') for row in pa_rows}
                except Exception as e:
                    rf_debug_info['pigment_ad_error'] = str(e)

            for r in rf_rows:
                ham_kg   = float(r['miktar_kg'])
                olcek_kg = ham_kg * numune_orani
                # RF/pigment kalemleri için round(6) — çok küçük değerleri sıfıra düşürme
                olcek_kg_yuvarlak = round(olcek_kg, 6)

                p_ad = pigment_map.get(r['id'], '')
                ad   = r['stok_ad'] or p_ad or f'(rf_kalem id={r["id"]})'

                boya_audit.append({
                    'id': r['id'],
                    'stok_kart_id': r['stok_kart_id'],
                    'stok_kod': r['stok_kod'] or '',
                    'ad': ad,
                    'master_kg': ham_kg,
                    'olcek_kg': olcek_kg,
                    'olcek_kg_yuvarlak': olcek_kg_yuvarlak,
                    'atildi': olcek_kg_yuvarlak <= 0,
                })

                if olcek_kg_yuvarlak <= 0:
                    continue
                boya.append({'ad': ad, 'kod': r['stok_kod'] or '', 'kg': olcek_kg_yuvarlak})

        # Toplamlar ve yüzdeler
        taban_top = round(sum(t['kg'] for t in taban), 4)
        boya_top  = round(sum(b['kg'] for b in boya),  6)
        genel_top = round(taban_top + boya_top, 4)

        def yuzde(x):
            return round(x / genel_top * 100, 2) if genel_top > 0 else 0.0

        for t in taban:
            t['yuzde'] = yuzde(t['kg'])
        for b in boya:
            b['yuzde'] = yuzde(b['kg'])

        sonuc = {
            'ok':               True,
            'boyut':            uv['boyut'] or '—',
            'rv_ad':            uv['rv_ad'] or '—',
            'formul':           uv['formul_kod'] + ' ' + uv['formul_ad'],
            'master_kg':        master_kg,
            'numune_kg':        numune_kg,       # master × oran
            'numune_orani':     numune_orani_yuzde,   # % değeri (ör: 10.0)
            'taban':            taban,
            'boya':             boya,
            'taban_top':        taban_top,
            'boya_top':         round(boya_top, 4),
            'genel_top':        genel_top,
        }

        if debug:
            sonuc['_audit'] = {
                'uv_id': uv_id, 'rf_id': rf_id,
                'oran_girdi': oran,
                'master_kg': master_kg,
                'numune_kg_hesap': numune_kg,
                'numune_orani_ondalik': numune_orani,
                'taban_audit': taban_audit,
                'boya_audit': boya_audit,
                'rf_debug': rf_debug_info,
            }

        return jsonify(sonuc)

    finally:
        con.close()


@nexgen_bp.route('/api/tablet/uretim-onizleme', methods=['POST'])
@yetki_gerekli('nexgen.tablet.view', 'can_view')
def api_tablet_uretim_onizleme():
    """Planlanan KG için reçete ölçekler, stok yeterliliğini döner.
    Stok hareketi YAZMAZ — sadece hesap ve okuma.

    POST JSON:
        uretim_varyant_id : int
        planlanan_kg      : float
    """
    d = request.get_json(silent=True) or {}
    uv_id     = d.get('uretim_varyant_id')
    planlanan = d.get('planlanan_kg')

    if not uv_id or not planlanan:
        return jsonify({"ok": False, "hata": "uretim_varyant_id ve planlanan_kg zorunlu"}), 400
    try:
        planlanan = float(planlanan)
        if planlanan <= 0:
            return jsonify({"ok": False, "hata": "planlanan_kg sıfırdan büyük olmalı"}), 400
    except Exception:
        return jsonify({"ok": False, "hata": "Geçersiz planlanan_kg"}), 400

    con = _db()
    try:
        uv = con.execute(
            "SELECT uv.id, uv.boyut, uv.recete_durum, uv.ad AS uv_ad,"
            " rv.ad AS renk_ad, f.ad AS formul_ad, f.kod AS formul_kod"
            " FROM nexgen_uretim_varyant uv"
            " JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id"
            " JOIN nexgen_formul f ON f.id=rv.formul_id"
            " WHERE uv.id=? AND uv.aktif=1",
            (uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({"ok": False, "hata": "Üretim varyantı bulunamadı"}), 404
        if uv['recete_durum'] != 'URETIME_ACIK':
            return jsonify({
                "ok": False,
                "hata": f"Sadece URETIME_ACIK reçeteler kullanılabilir. Mevcut: {uv['recete_durum']}"
            }), 400

        # Reçete kalemleri
        kalemler_db = con.execute("""
            SELECT rk.id, rk.stok_kart_id, rk.miktar_kg, rk.sira,
                   sk.ad AS stok_ad, sk.birim, sk.kod AS stok_kod
            FROM nexgen_recete_kalem rk
            JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
            ORDER BY rk.sira
        """, (uv_id,)).fetchall()

        if not kalemler_db:
            return jsonify({"ok": False, "hata": "Bu varyanta ait aktif reçete kalemi bulunamadı"}), 400

        # Batch KG = kalem miktarları toplamı
        batch_kg = round(sum(float(k['miktar_kg']) for k in kalemler_db), 3)
        if batch_kg <= 0:
            return jsonify({"ok": False, "hata": "Reçete batch KG sıfır olamaz"}), 400

        carpan = round(planlanan / batch_kg, 6)

        # Her kalem için ölçekle ve stok kontrol et
        tum_yeterli = True
        kalemler_sonuc = []
        for k in kalemler_db:
            recete_kg  = round(float(k['miktar_kg']), 3)
            gerekli_kg = round(recete_kg * carpan, 3)
            mevcut_kg  = _mevcut_stok(con, k['stok_kart_id'])
            fark_kg    = round(mevcut_kg - gerekli_kg, 3)
            yeterli    = mevcut_kg >= gerekli_kg

            if not yeterli:
                tum_yeterli = False

            kalemler_sonuc.append({
                "stok_kart_id":    k['stok_kart_id'],
                "stok_kod":        k['stok_kod'] or '',
                "hammadde_adi":    k['stok_ad'],
                "birim":           k['birim'] or 'KG',
                "recete_miktar_kg": recete_kg,
                "gerekli_kg":      gerekli_kg,
                "mevcut_stok_kg":  mevcut_kg,
                "fark_kg":         fark_kg,
                "yeterli":         yeterli,
                "durum":           "YETERLİ" if yeterli else "EKSİK",
            })

        return jsonify({
            "ok":          True,
            "uv_id":       uv_id,
            "formul_ad":   uv['formul_ad'],
            "renk_ad":     uv['renk_ad'],
            "boyut":       uv['boyut'],
            "batch_kg":    batch_kg,
            "planlanan_kg": round(planlanan, 3),
            "carpan":      carpan,
            "toplam_kalem": len(kalemler_sonuc),
            "yeterli_mi":  tum_yeterli,
            "kalemler":    kalemler_sonuc,
        })
    except Exception as e:
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()


@nexgen_bp.route('/api/tablet/uretim-kodu-olustur', methods=['POST'])
@yetki_gerekli('nexgen.tablet.uretim', 'can_uretim')
def api_tablet_uretim_kodu():
    """Üretim batch kodu oluşturur. Stok hareketi yapmaz."""
    d = request.get_json(silent=True) or {}
    uv_id      = d.get('uretim_varyant_id')
    planlanan  = d.get('planlanan_kg')
    notlar     = (d.get('notlar') or '').strip() or None

    if not uv_id or not planlanan:
        return jsonify({"ok": False, "hata": "uretim_varyant_id ve planlanan_kg zorunlu"}), 400
    try:
        planlanan = float(planlanan)
        if planlanan <= 0:
            return jsonify({"ok": False, "hata": "Planlanan KG sıfırdan büyük olmalı"}), 400
    except Exception:
        return jsonify({"ok": False, "hata": "Geçersiz planlanan_kg"}), 400

    import math as _math
    con = _db()
    try:
        uv = con.execute(
            "SELECT uv.id, uv.boyut, uv.recete_durum, rv.ad AS renk_ad, f.ad AS formul_ad "
            "FROM nexgen_uretim_varyant uv "
            "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
            "JOIN nexgen_formul f ON f.id=rv.formul_id "
            "WHERE uv.id=? AND uv.aktif=1",
            (uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({"ok": False, "hata": "Üretim varyantı bulunamadı"}), 404
        if uv['recete_durum'] != 'URETIME_ACIK':
            return jsonify({"ok": False, "hata": f"Sadece URETIME_ACIK reçeteler kullanılabilir. Mevcut: {uv['recete_durum']}"}), 400

        batch_kodu = _batch_kodu_uret(con)
        lot_kodu   = _lot_kodu_uret(con)
        uid = _kullanici_id()
        con.execute(
            "INSERT INTO nexgen_uretim_batch(batch_kodu, lot_kodu, uretim_varyant_id, planlanan_kg, durum, olusturan_id, notlar) "
            "VALUES(?,?,?,?,'HAZIR',?,?)",
            (batch_kodu, lot_kodu, uv_id, round(planlanan, 3), uid, notlar)
        )

        # Alt emirleri otomatik oluştur (wizard'dan açılan batch'ler için)
        alt_emir_sayisi = 0
        if _parca_tablosu_var(con):
            batch_row = con.execute(
                "SELECT id FROM nexgen_uretim_batch WHERE batch_kodu=?",
                (batch_kodu,)
            ).fetchone()
            batch_id = batch_row['id'] if batch_row else None
            rf_renk_id_raw = d.get('rf_renk_id')
            rf_renk_id = None
            if rf_renk_id_raw not in (None, ''):
                try:
                    rf_renk_id = int(rf_renk_id_raw)
                except (TypeError, ValueError):
                    rf_renk_id = None
            batch_meta = _batch_uretim_hesapla(
                con, uv_id, planlanan, rf_renk_id=rf_renk_id,
            )
            formul_batch_kg = batch_meta.get('tam_formul_kg', batch_meta.get('formul_batch_kg', 0.0))
            if batch_id and batch_meta.get('ok') and formul_batch_kg > 0:
                alt_emir_sayisi = batch_meta['batch_sayisi']
                parca_cols = [c['name'] for c in con.execute(
                    "PRAGMA table_info(nexgen_uretim_parca)"
                ).fetchall()]
                has_formul_kg_col = 'formul_batch_kg' in parca_cols
                for no in range(1001, 1001 + alt_emir_sayisi):
                    if has_formul_kg_col:
                        con.execute("""
                            INSERT INTO nexgen_uretim_parca
                                (batch_id, batch_kodu, parca_no,
                                 hedef_kg, formul_batch_kg, uretilen_kg,
                                 durum, operator_id)
                            VALUES (?, ?, ?, ?, ?, 0, 'HAZIR', ?)
                        """, (batch_id, batch_kodu, no,
                              round(formul_batch_kg, 3),
                              round(formul_batch_kg, 3), uid))
                    else:
                        con.execute("""
                            INSERT INTO nexgen_uretim_parca
                                (batch_id, batch_kodu, parca_no,
                                 hedef_kg, uretilen_kg, durum, operator_id)
                            VALUES (?, ?, ?, ?, 0, 'HAZIR', ?)
                        """, (batch_id, batch_kodu, no,
                              round(formul_batch_kg, 3), uid))

        con.commit()
        return jsonify({
            "ok": True,
            "batch_kodu":      batch_kodu,
            "lot_kodu":        lot_kodu,
            "formul_ad":       uv['formul_ad'],
            "renk_ad":         uv['renk_ad'],
            "boyut":           uv['boyut'],
            "planlanan_kg":    round(planlanan, 3),
            "alt_emir_sayisi": alt_emir_sayisi,
        })
    except Exception as e:
        con.rollback()
        return jsonify({"ok": False, "hata": str(e)}), 500
    finally:
        con.close()


