# ─────────────────────────────────────────────────────────────
# NEXGEN FAZ-5D — ÜRETİM PLAN / İŞ KUYRUĞU
# KURAL: Ana Planlama modülüne dokunma. Korgun bağlantısı yok.
#        Stok hareketi yok. Sadece plan CRUD + tablet bağlantısı.
# ─────────────────────────────────────────────────────────────

def _plan_kodu_uret(con):
    """NP-YYYY-NNNNN formatında benzersiz plan kodu üretir."""
    import datetime
    yil = datetime.datetime.now().year
    son = con.execute(
        "SELECT plan_kodu FROM nexgen_uretim_plan "
        "WHERE plan_kodu LIKE ? ORDER BY id DESC LIMIT 1",
        (f"NP-{yil}-%",)
    ).fetchone()
    if son:
        try:
            son_no = int(son['plan_kodu'].split('-')[-1])
        except Exception:
            son_no = 0
    else:
        son_no = 0
    return f"NP-{yil}-{son_no + 1:05d}"


def _nexgen_siparis_no_uret(con):
    """NSP-YYYY-NNNNN formatında benzersiz sipariş no üretir.

    Kullanıcı sipariş no girmezse otomatik çağrılır.
    LARGE+SMALL aynı request'ten geliyorsa JS aynı no'yu tekrar gönderir.
    """
    import datetime
    yil = datetime.datetime.now().year
    prefix = f"NSP-{yil}-%"
    son_no = 0
    for tbl in ('nexgen_planlama_siparis', 'nexgen_uretim_plan'):
        try:
            row = con.execute(
                f"SELECT siparis_no FROM {tbl} "
                "WHERE siparis_no LIKE ? ORDER BY id DESC LIMIT 1",
                (prefix,),
            ).fetchone()
            if row and row['siparis_no']:
                try:
                    n = int(row['siparis_no'].split('-')[-1])
                    son_no = max(son_no, n)
                except Exception:
                    pass
        except Exception:
            pass
    return f"NSP-{yil}-{son_no + 1:05d}"


def _tablet_ana_veri(con):
    """Tablet ana ekran — üretim plan ile aynı aktif plan/batch listesi."""
    from datetime import date as _date
    bugun = _date.today().isoformat()
    _AKTIF_BATCH = ('TASLAK', 'HAZIR', 'DEVAM', 'BEKLEME')
    planlar = [dict(p) for p in _plan_liste_sorgu(con, sadece_aktif=True)]

    devam_eden = []
    plan_isler = []
    seen_batches = set()

    for pl in planlar:
        bk = pl.get('batch_kodu')
        bd = pl.get('batch_durum')
        if bk and bd in _AKTIF_BATCH and bk not in seen_batches:
            seen_batches.add(bk)
            b = con.execute("""
                SELECT nb.batch_kodu, nb.lot_kodu, nb.planlanan_kg, nb.durum,
                       nb.olusturma_tarihi, nb.uretim_varyant_id,
                       uv.ad AS uv_ad, uv.boyut,
                       rv.ad AS renk_ad, f.ad AS formul_ad
                FROM nexgen_uretim_batch nb
                JOIN nexgen_uretim_varyant uv ON uv.id = nb.uretim_varyant_id
                JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
                JOIN nexgen_formul f          ON f.id  = rv.formul_id
                WHERE nb.batch_kodu = ?
            """, (bk,)).fetchone()
            if b:
                row = dict(b)
                row['musteri_adi'] = pl.get('musteri_adi')
                row['siparis_no'] = pl.get('siparis_no') or pl.get('plan_kodu')
                rf = _batch_plan_rf_bilgi(
                    con, batch_kodu=bk,
                    uretim_varyant_id=row.get('uretim_varyant_id') or pl.get('uv_id'),
                )
                if rf:
                    row['rf_kod'] = rf['rf_kod']
                    row['rf_renk_ad'] = rf.get('renk_ad')
                else:
                    row['rf_kod'] = None
                    row['rf_renk_ad'] = None
                devam_eden.append(row)
        elif pl['durum'] == 'PLANLANDI' and (pl.get('plan_tarihi') or '') <= bugun and not bk:
            pi = {
                'plan_id': pl['id'],
                'plan_kodu': pl['plan_kodu'],
                'planlanan_kg': pl['planlanan_kg'],
                'plan_durum': pl['durum'],
                'oncelik_sira': pl.get('oncelik_sira'),
                'notlar': pl.get('notlar'),
                'musteri_adi': pl.get('musteri_adi'),
                'uv_id': pl['uv_id'],
                'boyut': pl['boyut'],
                'renk_ad': pl['renk_ad'],
                'formul_ad': pl['formul_ad'],
            }
            rf = _plan_rf_bilgi(con, rf_renk_id=pl.get('rf_renk_id'), uretim_varyant_id=pl['uv_id'])
            if rf:
                pi['rf_kod'] = rf['rf_kod']
                pi['rf_renk_ad'] = rf.get('renk_ad')
            plan_isler.append(pi)

    plan_isler.sort(key=lambda p: (p.get('oncelik_sira') or 999, p.get('plan_id') or 0))
    devam_eden.sort(key=lambda b: b.get('olusturma_tarihi') or '', reverse=True)
    devam_eden = devam_eden[:20]
    plan_isler = plan_isler[:20]

    if _parca_tablosu_var(con):
        for b in devam_eden:
            _batch_kg_rf_enrich(con, b, liste_modu=True)
    else:
        for b in devam_eden:
            b['toplam_alt_emir'] = None
            b['biten_alt_emir'] = None
            b['uretilen_kg'] = 0.0
            _batch_kg_rf_enrich(con, b, liste_modu=True)

    return devam_eden, plan_isler


def _plan_cari_kolonu_var(con):
    return 'cari_id' in [
        c['name'] for c in con.execute(
            "PRAGMA table_info(nexgen_uretim_plan)"
        ).fetchall()
    ]


def _plan_rf_renk_kolonu_var(con):
    return 'rf_renk_id' in [
        c['name'] for c in con.execute(
            "PRAGMA table_info(nexgen_uretim_plan)"
        ).fetchall()
    ]


def _plan_termin_kolonu_var(con):
    return 'termin_tarihi' in [
        c['name'] for c in con.execute(
            "PRAGMA table_info(nexgen_uretim_plan)"
        ).fetchall()
    ]


def _plan_planlama_siparis_kolonu_var(con):
    return 'planlama_siparis_id' in [
        c['name'] for c in con.execute(
            "PRAGMA table_info(nexgen_uretim_plan)"
        ).fetchall()
    ]


def _mpr_plan_insert(con, meta):
    """Merkezi nexgen_uretim_plan INSERT — çağıranın transaction'ını kullanır.

    meta zorunlu: uretim_varyant_id, planlanan_kg, kaynak
    meta opsiyonel: durum, plan_kodu, plan_tarihi, oncelik_sira, notlar, created_by,
        siparis_bilgisi, siparis_no, musteri_adi, cari_id, planlama_siparis_id,
        rf_renk_id, termin_tarihi, formul_id, rf_rev_no_ekle, kalip_carpani
    """
    from datetime import date as _date

    uv_id = meta['uretim_varyant_id']
    kg = round(float(meta['planlanan_kg']), 3)
    kaynak = meta['kaynak']
    durum = meta.get('durum', 'ON_CALISMA')
    plan_kodu = meta.get('plan_kodu') or _plan_kodu_uret(con)
    plan_tarihi = meta.get('plan_tarihi') or _date.today().isoformat()
    oncelik = int(meta.get('oncelik_sira', 10))
    notlar = meta.get('notlar')
    uid = meta.get('created_by') if meta.get('created_by') is not None else _kullanici_id()

    cols = ['plan_kodu', 'kaynak']
    vals = [plan_kodu, kaynak]

    if meta.get('siparis_bilgisi'):
        cols.extend(['siparis_no', 'musteri_adi'])
        vals.extend([meta.get('siparis_no'), meta.get('musteri_adi')])

    if _plan_cari_kolonu_var(con) and 'cari_id' in meta:
        cols.append('cari_id')
        vals.append(meta.get('cari_id'))

    cols.extend([
        'uretim_varyant_id', 'planlanan_kg', 'oncelik_sira', 'plan_tarihi',
    ])
    vals.extend([uv_id, kg, oncelik, plan_tarihi])

    if _plan_planlama_siparis_kolonu_var(con) and 'planlama_siparis_id' in meta:
        cols.append('planlama_siparis_id')
        vals.append(meta['planlama_siparis_id'])

    if _plan_rf_renk_kolonu_var(con) and 'rf_renk_id' in meta:
        cols.append('rf_renk_id')
        vals.append(meta.get('rf_renk_id'))

    if _plan_termin_kolonu_var(con) and 'termin_tarihi' in meta:
        cols.append('termin_tarihi')
        vals.append(meta.get('termin_tarihi'))

    cols.extend(['durum', 'notlar', 'created_by'])
    vals.extend([durum, notlar, uid])

    if meta.get('rf_rev_no_ekle') and meta.get('rf_renk_id'):
        _rf_plan_revizyon_bilgi_ekle(con, meta['rf_renk_id'], cols, vals)

    if 'kalip_carpani' in meta and _kolon_var_chk(con, 'nexgen_uretim_plan', 'kalip_carpani'):
        if 'kalip_carpani' not in cols:
            cols.append('kalip_carpani')
            vals.append(meta.get('kalip_carpani'))

    formul_id = meta.get('formul_id')
    rf_renk_id = meta.get('rf_renk_id')
    if rf_renk_id and formul_id:
        _uretim_kodu_plan_kolonlari_ekle(con, cols, vals, rf_renk_id, formul_id)

    placeholders = ','.join(['?'] * len(cols))
    con.execute(
        f"INSERT INTO nexgen_uretim_plan ({','.join(cols)}) VALUES ({placeholders})",
        vals,
    )
    plan_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]
    return plan_id, plan_kodu


def _mpr_plan_satir_item(plan_id, plan_kodu, kalem_sira, boyut_satirlari, durum='ON_CALISMA'):
    """Pazarlama mpr-olustur yanıtı için standart plan satırı."""
    return {
        'plan_id': plan_id,
        'plan_kodu': plan_kodu,
        'kalem_sira': kalem_sira,
        'boyutlar': [{'boyut': b, 'kg': k} for b, _, k in boyut_satirlari],
        'durum': durum,
    }


def _pzm_mpr_boyut_hesap_satir(con, uretim_varyant_id, talep_kg, boyut, rf_renk_id=None, rf_rev_no=None):
    """Tek boyut için tam formül / üretim metrikleri."""
    bh = _batch_uretim_hesapla(
        con, uretim_varyant_id, talep_kg, rf_renk_id=rf_renk_id, rf_rev_no=rf_rev_no,
    )
    if not bh.get('ok'):
        return {
            'boyut': boyut,
            'kg': round(float(talep_kg or 0), 3),
            'talep_kg': round(float(talep_kg or 0), 3),
            'uretim_varyant_id': uretim_varyant_id,
            'hesap_hata': bh.get('hata'),
        }
    uret = bh['uretilecek_kg']
    return {
        'boyut': boyut,
        'kg': bh['talep_kg'],
        'talep_kg': bh['talep_kg'],
        'ana_recete_kg': bh['ana_recete_kg'],
        'rf_boya_kg': bh['rf_boya_kg'],
        'tam_formul_kg': bh['tam_formul_kg'],
        'formul_adedi': bh['formul_adedi'],
        'uretilecek_kg': uret,
        'faturalanacak_kg': uret,
        'fazla_kg': bh['fazla_kg'],
        'uretim_varyant_id': uretim_varyant_id,
    }


def _pzm_mpr_plan_satir_zengin(con, plan_id, kalem_sira=1):
    """Pazarlama kartı için zenginleştirilmiş plan satırı (hydrate + mpr-olustur)."""
    plan_cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_uretim_plan)").fetchall()]
    rev_sql = ", rf_rev_no" if "rf_rev_no" in plan_cols else ", NULL AS rf_rev_no"
    plan = con.execute(
        f"SELECT id, plan_kodu, durum, uretim_varyant_id, planlanan_kg, rf_renk_id{rev_sql} "
        "FROM nexgen_uretim_plan WHERE id=?",
        (plan_id,),
    ).fetchone()
    if not plan:
        return None

    rf_renk_id = plan['rf_renk_id']
    rf_rev_no = plan['rf_rev_no']
    boyutlar_out = []
    toplam_talep = 0.0
    toplam_uret = 0.0
    toplam_fazla = 0.0
    toplam_formul_adedi = 0
    ana_kg = None
    rf_kg = None
    tam_kg = None

    parcalar = _plan_boyut_parcalari_list(con, plan_id)
    if parcalar:
        for bp in parcalar:
            satir = _pzm_mpr_boyut_hesap_satir(
                con, bp['uretim_varyant_id'], bp['siparis_kg'], bp['boyut'],
                rf_renk_id=rf_renk_id, rf_rev_no=rf_rev_no,
            )
            boyutlar_out.append(satir)
            toplam_talep += float(satir.get('talep_kg') or 0)
            toplam_uret += float(satir.get('uretilecek_kg') or 0)
            toplam_fazla += float(satir.get('fazla_kg') or 0)
            toplam_formul_adedi += int(satir.get('formul_adedi') or 0)
            if ana_kg is None and satir.get('ana_recete_kg') is not None:
                ana_kg = satir['ana_recete_kg']
                rf_kg = satir.get('rf_boya_kg')
                tam_kg = satir.get('tam_formul_kg')
    elif plan['uretim_varyant_id']:
        talep = float(plan['planlanan_kg'] or 0)
        satir = _pzm_mpr_boyut_hesap_satir(
            con, plan['uretim_varyant_id'], talep, 'STANDART',
            rf_renk_id=rf_renk_id, rf_rev_no=rf_rev_no,
        )
        boyutlar_out.append(satir)
        toplam_talep = float(satir.get('talep_kg') or talep)
        toplam_uret = float(satir.get('uretilecek_kg') or 0)
        toplam_fazla = float(satir.get('fazla_kg') or 0)
        toplam_formul_adedi = int(satir.get('formul_adedi') or 0)
        ana_kg = satir.get('ana_recete_kg')
        rf_kg = satir.get('rf_boya_kg')
        tam_kg = satir.get('tam_formul_kg')

    toplam_uret_r = round(toplam_uret, 3)
    return {
        'plan_id': plan_id,
        'plan_kodu': plan['plan_kodu'],
        'kalem_sira': kalem_sira,
        'durum': plan['durum'],
        'rf_renk_id': rf_renk_id,
        'boyutlar': boyutlar_out,
        'talep_kg': round(toplam_talep, 3),
        'ana_recete_kg': ana_kg,
        'rf_boya_kg': rf_kg,
        'tam_formul_kg': tam_kg,
        'formul_adedi': toplam_formul_adedi,
        'uretilecek_kg': toplam_uret_r,
        'faturalanacak_kg': toplam_uret_r,
        'fazla_kg': round(toplam_fazla, 3),
    }


def _pzm_siparis_mpr_planlar(con, talep_id):
    """Siparişe bağlı mevcut MPR planlarını zengin formatta döner."""
    if not _plan_planlama_siparis_kolonu_var(con):
        return []
    rows = con.execute("""
        SELECT id FROM nexgen_uretim_plan
        WHERE planlama_siparis_id=? AND durum NOT IN ('IPTAL')
        ORDER BY id
    """, (talep_id,)).fetchall()
    planlar = []
    for i, row in enumerate(rows, start=1):
        item = _pzm_mpr_plan_satir_zengin(con, row['id'], i)
        if item:
            planlar.append(item)
    return planlar


def _planlama_siparis_tablosu_var(con):
    return con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' "
        "AND name='nexgen_planlama_siparis'"
    ).fetchone() is not None


def _planlama_siparis_olustur(con, siparis_no, cari_id, cari_unvan,
                                termin_tarihi=None, notlar=None,
                                talep_referansi=None, olusturan_id=None,
                                durum='TALEP'):
    """Yeni planlama sipariş header kaydı oluşturur."""
    cur = con.execute("""
        INSERT INTO nexgen_planlama_siparis
            (siparis_no, cari_id, cari_unvan, termin_tarihi, talep_referansi,
             durum, notlar, olusturan_id)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """, (
        siparis_no, cari_id, cari_unvan, termin_tarihi, talep_referansi,
        durum, notlar, olusturan_id,
    ))
    return cur.lastrowid


def _planlama_siparis_bul_veya_olustur(con, siparis_no, cari_id, cari_unvan,
                                         termin_tarihi=None, notlar=None,
                                         olusturan_id=None):
    """siparis_no ile header bulur; yoksa oluşturur."""
    if not _planlama_siparis_tablosu_var(con):
        return None
    row = con.execute(
        "SELECT id FROM nexgen_planlama_siparis WHERE siparis_no=?",
        (siparis_no,),
    ).fetchone()
    if row:
        return row['id']
    return _planlama_siparis_olustur(
        con, siparis_no, cari_id, cari_unvan,
        termin_tarihi=termin_tarihi, notlar=notlar,
        olusturan_id=olusturan_id,
    )


def _plan_cari_select_sql(con):
    """Plan sorgularında cari gösterim: FK unvan, yoksa musteri_adi."""
    if _plan_cari_kolonu_var(con):
        return (
            "np.cari_id, COALESCE(c.unvan, np.musteri_adi) AS musteri_adi, "
            "np.musteri_adi AS musteri_adi_legacy",
            "LEFT JOIN nexgen_cari c ON c.id = np.cari_id",
        )
    return "NULL AS cari_id, np.musteri_adi, np.musteri_adi AS musteri_adi_legacy", ""


def _plan_liste_sorgu(con, sadece_aktif=False, mpr_on_calisma_only=False):
    """Plan listesini join'li şekilde döner.
    plan_id üzerinden bağlı batch_kodu da getirilir (BASLADI → Devam linki için).
    """
    where_parts = []
    if sadece_aktif:
        where_parts.append("np.durum NOT IN ('BITTI','IPTAL')")
    if mpr_on_calisma_only:
        where_parts.append("np.durum = 'ON_CALISMA'")
    where = ("WHERE " + " AND ".join(where_parts)) if where_parts else ""
    # plan_id kolonu varlığına göre batch JOIN kararı
    _bcols = [c['name'] for c in con.execute(
        "PRAGMA table_info(nexgen_uretim_batch)"
    ).fetchall()]
    batch_join = ""
    batch_select = "NULL AS batch_kodu, NULL AS batch_durum"
    if 'plan_id' in _bcols:
        batch_join = (
            "LEFT JOIN nexgen_uretim_batch nb "
            "ON nb.plan_id = np.id AND nb.durum NOT IN ('BITTI')"
        )
        batch_select = "nb.batch_kodu, nb.durum AS batch_durum"
    cari_select, cari_join = _plan_cari_select_sql(con)
    if _plan_rf_renk_kolonu_var(con):
        mpr_select = (
            "np.rf_renk_id, np.termin_tarihi, "
            "rf.rf_kod AS rf_kod_fk, rf.ad AS rf_ad_fk, "
        )
        mpr_join = "LEFT JOIN nexgen_rf_renk rf ON rf.id = np.rf_renk_id "
    else:
        mpr_select = (
            "NULL AS rf_renk_id, NULL AS termin_tarihi, "
            "NULL AS rf_kod_fk, NULL AS rf_ad_fk, "
        )
        mpr_join = ""
    hdr_select = ""
    hdr_join = ""
    if _plan_planlama_siparis_kolonu_var(con) and _planlama_siparis_tablosu_var(con):
        hdr_select = (
            "np.planlama_siparis_id, "
            "ps.siparis_no AS hdr_siparis_no, ps.cari_unvan AS hdr_cari_unvan, "
            "ps.termin_tarihi AS hdr_termin_tarihi, ps.durum AS hdr_durum, "
            "ps.talep_referansi AS hdr_talep_referansi, "
        )
        hdr_join = (
            "LEFT JOIN nexgen_planlama_siparis ps "
            "ON ps.id = np.planlama_siparis_id "
        )
    else:
        hdr_select = (
            "NULL AS planlama_siparis_id, NULL AS hdr_siparis_no, "
            "NULL AS hdr_cari_unvan, NULL AS hdr_termin_tarihi, "
            "NULL AS hdr_durum, NULL AS hdr_talep_referansi, "
        )
    return con.execute(f"""
        SELECT np.id, np.plan_kodu, np.kaynak, np.siparis_no,
               {cari_select},
               {hdr_select}
               {mpr_select}
               np.planlanan_kg, np.oncelik_sira, np.plan_tarihi,
               np.durum, np.notlar, np.created_at,
               uv.id AS uv_id, uv.boyut,
               rv.ad AS renk_ad,
               f.ad AS formul_ad, f.kod AS formul_kod, f.id AS formul_id,
               ku.KullaniciAdi AS olusturan_ad,
               {batch_select}
        FROM nexgen_uretim_plan np
        {cari_join}
        {hdr_join}
        {mpr_join}
        JOIN nexgen_uretim_varyant uv ON uv.id = np.uretim_varyant_id
        JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
        JOIN nexgen_formul f          ON f.id  = rv.formul_id
        LEFT JOIN sistem_kullanici ku ON ku.Id  = np.created_by
        {batch_join}
        {where}
        ORDER BY np.id DESC
    """).fetchall()


@nexgen_bp.route('/uretim-plan')
@yetki_gerekli('nexgen.plan.view', 'can_view')
def uretim_plan_liste():
    """Üretim plan listesi."""
    con = _db()
    try:
        planlar = [dict(p) for p in _plan_liste_sorgu(con)]

        for pl in planlar:
            rf = _plan_rf_bilgi(
                con,
                rf_renk_id=pl.get('rf_renk_id'),
                uretim_varyant_id=pl['uv_id'],
            )
            if rf:
                pl['rf_kod'] = rf['rf_kod']
                pl['rf_renk_ad'] = rf.get('renk_ad')
                pl['rf_uyari'] = None
            else:
                pl['rf_kod'] = pl.get('rf_kod_fk')
                pl['rf_renk_ad'] = pl.get('rf_ad_fk')
                pl['rf_uyari'] = (
                    'Bu formül/renk için ONAYLI RF eşleşmesi bulunamadı.'
                )
            if pl.get('rf_renk_id') and pl.get('cari_id') and rf and rf.get('cari_id'):
                pl['rf_cari_uyari'] = _rf_cari_uyari(con, rf['cari_id'], pl['cari_id'])
            else:
                pl['rf_cari_uyari'] = None

            sk = _siparis_kontrol_get(con, pl['id'])
            if sk:
                pl['siparis_toplam_kg'] = sk['siparis_toplam_kg']
                pl['uretilen_kg'] = sk['uretilen_kg']
                pl['kalan_kg'] = max(0.0, float(sk['fark_kg']))
                pl['kontrol_durum'] = sk.get('kontrol_durum')
                pl['kontrol_uyari'] = sk.get('uyari')
            else:
                pl['siparis_toplam_kg'] = pl.get('planlanan_kg', 0)
                pl['uretilen_kg'] = 0.0
                pl['kalan_kg'] = pl['siparis_toplam_kg']

        for pl in planlar:
            pl['boyut_parcalari'] = _plan_boyut_parcalari_list(con, pl['id'])

        # Alt emir sayaçlarını planlara ekle (Migration 072+ gerekli)
        if _parca_tablosu_var(con):
            for pl in planlar:
                if not pl.get('batch_kodu') and pl.get('id'):
                    brow = con.execute("""
                        SELECT batch_kodu, durum FROM nexgen_uretim_batch
                        WHERE plan_id=? ORDER BY id DESC LIMIT 1
                    """, (pl['id'],)).fetchone()
                    if brow:
                        pl['batch_kodu'] = brow['batch_kodu']
                        pl['batch_durum'] = brow['durum']
                bk = pl.get('batch_kodu')
                if bk:
                    sayac = con.execute("""
                        SELECT COUNT(*) AS toplam,
                               SUM(CASE WHEN durum='BITTI' THEN 1 ELSE 0 END) AS biten
                        FROM nexgen_uretim_parca WHERE batch_kodu=?
                    """, (bk,)).fetchone()
                    pl['toplam_alt_emir'] = sayac['toplam'] or 0
                    pl['biten_alt_emir']  = sayac['biten']  or 0
                else:
                    pl['toplam_alt_emir'] = 0
                    pl['biten_alt_emir']  = 0
        else:
            for pl in planlar:
                pl['toplam_alt_emir'] = 0
                pl['biten_alt_emir']  = 0

        # Aktif varyantları formül > renk > boyut hiyerarşisinde grupla
        # Yapı: [{formul_id, formul_ad, renkler: [{renk_id, renk_ad,
        #          large_uv_id, small_uv_id}]}]
        varyant_rows = con.execute("""
            SELECT uv.id AS uv_id, uv.boyut, uv.recete_durum,
                   rv.id AS renk_id, rv.ad AS renk_ad,
                   f.id  AS formul_id, f.ad AS formul_ad
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f        ON f.id  = rv.formul_id
            WHERE uv.aktif = 1
              AND uv.recete_durum = 'URETIME_ACIK'
            ORDER BY f.ad, rv.ad, uv.boyut
        """).fetchall()

        # Hiyerarşik dict oluştur
        formul_map = {}
        for r in varyant_rows:
            fid = r['formul_id']
            if fid not in formul_map:
                formul_map[fid] = {'formul_id': fid, 'formul_ad': r['formul_ad'], 'renkler': {}}
            rid = r['renk_id']
            if rid not in formul_map[fid]['renkler']:
                formul_map[fid]['renkler'][rid] = {
                    'renk_id': rid, 'renk_ad': r['renk_ad'],
                    'large_uv_id': None, 'small_uv_id': None, 'standart_uv_id': None,
                }
            if r['boyut'] == 'LARGE':
                formul_map[fid]['renkler'][rid]['large_uv_id'] = r['uv_id']
            elif r['boyut'] == 'SMALL':
                formul_map[fid]['renkler'][rid]['small_uv_id'] = r['uv_id']
            elif r['boyut'] in ('STANDART', 'MEDIUM'):
                formul_map[fid]['renkler'][rid]['standart_uv_id'] = r['uv_id']

        formuller = []
        for f in formul_map.values():
            formuller.append({
                'formul_id': f['formul_id'],
                'formul_ad': f['formul_ad'],
                'renkler': list(f['renkler'].values()),
            })

        # Aktif cariler — dropdown için
        try:
            cari_rows = con.execute(
                "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE aktif=1 ORDER BY cari_kod"
            ).fetchall()
            cariler = [dict(c) for c in cari_rows]
        except Exception:
            cariler = []

    finally:
        con.close()
    return render_template(
        'nexgen/uretim_plan.html',
        active='nexgen',
        planlar=planlar,
        formuller=formuller,
        cariler=cariler,
        can_manage=yetki_var('nexgen.plan.manage', 'can_manage'),
    )


def _formuller_varyant_hiyerarsi(con):
    """Aktif URETIME_ACIK varyantları formül > renk > boyut hiyerarşisinde döner."""
    varyant_rows = con.execute("""
        SELECT uv.id AS uv_id, uv.boyut, uv.recete_durum,
               rv.id AS renk_id, rv.ad AS renk_ad,
               f.id  AS formul_id, f.ad AS formul_ad, f.kod AS formul_kod
        FROM nexgen_uretim_varyant uv
        JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
        JOIN nexgen_formul f        ON f.id  = rv.formul_id
        WHERE uv.aktif = 1
          AND uv.recete_durum = 'URETIME_ACIK'
        ORDER BY f.ad, rv.ad, uv.boyut
    """).fetchall()

    formul_map = {}
    for r in varyant_rows:
        fid = r['formul_id']
        if fid not in formul_map:
            # Display format: "675 - AYM" — kod varsa önüne ekle
            raw_ad  = r['formul_ad'] or ''
            raw_kod = r['formul_kod'] or ''
            display_ad = (f'{raw_kod} - {raw_ad}') if raw_kod else raw_ad
            formul_map[fid] = {
                'formul_id':  fid,
                'formul_ad':  display_ad,
                'formul_kod': raw_kod,
                'renkler': {},
            }
        rid = r['renk_id']
        if rid not in formul_map[fid]['renkler']:
            formul_map[fid]['renkler'][rid] = {
                'renk_id': rid, 'renk_ad': r['renk_ad'],
                'large_uv_id': None, 'small_uv_id': None, 'standart_uv_id': None,
            }
        if r['boyut'] == 'LARGE':
            formul_map[fid]['renkler'][rid]['large_uv_id'] = r['uv_id']
        elif r['boyut'] == 'SMALL':
            formul_map[fid]['renkler'][rid]['small_uv_id'] = r['uv_id']
        elif r['boyut'] in ('STANDART', 'MEDIUM'):
            formul_map[fid]['renkler'][rid]['standart_uv_id'] = r['uv_id']

    return [
        {
            'formul_id':  f['formul_id'],
            'formul_ad':  f['formul_ad'],   # "675 - AYM" formatı
            'formul_kod': f['formul_kod'],
            'renkler': list(f['renkler'].values()),
        }
        for f in formul_map.values()
    ]


def _mpr_dev_test_mode_allowed():
    """MPR workflow test modu — yalnızca MPR_TEST_MODE=true env ile aktif (BR-G-06)."""
    try:
        from flask import current_app
        return bool(current_app.config.get('MPR_TEST_MODE_ALLOWED', False))
    except Exception:
        return False


@nexgen_bp.route('/planlama')
@nexgen_bp.route('/planlama/')
@yetki_gerekli('nexgen.plan.view', 'can_view')
def planlama_merkezi_alias():
    """Eski /nexgen/planlama linkleri — resmi MPR planlama merkezine yönlendirir."""
    from flask import redirect, url_for
    return redirect(url_for('nexgen.mpr_on_calisma_liste'), code=302)


@nexgen_bp.route('/mpr')
@yetki_gerekli('nexgen.plan.view', 'can_view')
def mpr_on_calisma_liste():
    """MPR ön çalışma listesi — siparişsiz MPR satırları."""
    con = _db()
    try:
        planlar = [dict(p) for p in _plan_liste_sorgu(con, mpr_on_calisma_only=True)]

        for pl in planlar:
            rf = _plan_rf_bilgi(
                con,
                rf_renk_id=pl.get('rf_renk_id'),
                uretim_varyant_id=pl['uv_id'],
            )
            if rf:
                pl['rf_kod'] = rf['rf_kod']
                pl['rf_renk_ad'] = rf.get('renk_ad')
            else:
                pl['rf_kod'] = pl.get('rf_kod_fk')
                pl['rf_renk_ad'] = pl.get('rf_ad_fk')
            # Stok hesabı sayfa yükünde yapılmaz (N+1 / FAZ-1 KRİTİK #1).
            # Her kart /api/plan/<id>/stok-durum ile lazy olarak yükler.
            pl['stok_yeterli_mi'] = None
            pl['stok_eksik_sayisi'] = None
            # Display format: "675 - AYM" — kod varsa önüne ekle
            fkod = (pl.get('formul_kod') or '').strip()
            fad  = (pl.get('formul_ad')  or '').strip()
            pl['formul_ad'] = (f'{fkod} - {fad}') if fkod and fkod not in fad else (fad or '—')

        formuller = _formuller_varyant_hiyerarsi(con)
        try:
            cariler = [
                dict(c) for c in con.execute(
                    "SELECT id, cari_kod, unvan FROM nexgen_cari "
                    "WHERE aktif=1 ORDER BY cari_kod"
                ).fetchall()
            ]
        except Exception:
            cariler = []
    finally:
        con.close()

    return render_template(
        'nexgen/mpr_on_calisma.html',
        active='nexgen',
        planlar=planlar,
        formuller=formuller,
        cariler=cariler,
        can_manage=yetki_var('nexgen.plan.manage', 'can_manage'),
        mpr_test_mode_allowed=_mpr_dev_test_mode_allowed(),
    )


@nexgen_bp.route('/malzeme-ihtiyac-merkezi')
@yetki_gerekli('nexgen.plan.view', 'can_view')
def malzeme_ihtiyac_merkezi():
    """Malzeme İhtiyaç Merkezi — çoklu plan hammadde analizi (salt okuma UI)."""
    con = _db()
    try:
        raw = [dict(p) for p in _plan_liste_sorgu(con, sadece_aktif=True)]
        aile_map = {}
        try:
            aile_map = {
                int(r['id']): (r['urun_ailesi'] or '')
                for r in con.execute(
                    "SELECT id, urun_ailesi FROM nexgen_formul"
                ).fetchall()
            }
        except Exception:
            aile_map = {}

        planlar = []
        for pl in raw:
            try:
                kg = float(pl.get('planlanan_kg') or 0)
            except (TypeError, ValueError):
                kg = 0.0
            if kg <= 0:
                continue
            durum = (pl.get('durum') or '').upper()
            if durum in ('IPTAL', 'BITTI'):
                continue

            rf = _plan_rf_bilgi(
                con,
                rf_renk_id=pl.get('rf_renk_id'),
                uretim_varyant_id=pl.get('uv_id'),
            )
            rf_kod = (rf or {}).get('rf_kod') or pl.get('rf_kod_fk') or ''
            rf_ad = (rf or {}).get('renk_ad') or pl.get('rf_ad_fk') or pl.get('renk_ad') or ''

            siparis_id = pl.get('planlama_siparis_id')
            siparis_kodu = (
                pl.get('hdr_siparis_no')
                or pl.get('siparis_no')
                or (f'SIP-{siparis_id}' if siparis_id else None)
            )
            cari = (
                pl.get('hdr_cari_unvan')
                or pl.get('musteri_adi')
                or ''
            )
            termin = pl.get('hdr_termin_tarihi') or pl.get('termin_tarihi') or ''
            formul_id = pl.get('formul_id')
            urun_ailesi = aile_map.get(int(formul_id)) if formul_id else ''

            planlar.append({
                'plan_id': pl['id'],
                'plan_kodu': pl.get('plan_kodu') or '',
                'siparis_id': siparis_id,
                'siparis_kodu': siparis_kodu or '',
                'cari': cari,
                'cari_id': pl.get('cari_id'),
                'termin': termin,
                'plan_durum': pl.get('durum') or '',
                'urun_ailesi': urun_ailesi or '',
                'formul': pl.get('formul_kod') or pl.get('formul_ad') or '',
                'formul_ad': pl.get('formul_ad') or '',
                'renk': ((rf_kod + ' — ' + rf_ad).strip(' —') if (rf_kod or rf_ad) else (pl.get('renk_ad') or '')),
                'boyut': pl.get('boyut') or '',
                'planlanan_kg': round(kg, 3),
            })

        cariler = sorted({
            p['cari'] for p in planlar if (p.get('cari') or '').strip()
        })
        durumlar = sorted({
            p['plan_durum'] for p in planlar if (p.get('plan_durum') or '').strip()
        })
        aileler = sorted({
            p['urun_ailesi'] for p in planlar if (p.get('urun_ailesi') or '').strip()
        })
        formuller = sorted({
            p['formul'] for p in planlar if (p.get('formul') or '').strip()
        })
        renkler = sorted({
            p['renk'] for p in planlar if (p.get('renk') or '').strip()
        })
        boyutlar = sorted({
            p['boyut'] for p in planlar if (p.get('boyut') or '').strip()
        })
    finally:
        con.close()

    return render_template(
        'nexgen/malzeme_ihtiyac_merkezi.html',
        active='nexgen',
        planlar_json=planlar,
        filtre_cariler=cariler,
        filtre_durumlar=durumlar,
        filtre_aileler=aileler,
        filtre_formuller=formuller,
        filtre_renkler=renkler,
        filtre_boyutlar=boyutlar,
        can_manage=yetki_var('nexgen.plan.manage', 'can_manage'),
    )


@nexgen_bp.route('/api/mpr/on-calisma/ekle', methods=['POST'])
@yetki_gerekli('nexgen.plan.manage', 'can_manage')
def api_mpr_on_calisma_ekle():
    """Siparişsiz MPR ön çalışma satırı oluşturur."""
    d = request.get_json(silent=True) or {}
    boyut_kg_raw = d.get('boyut_kg')
    boyut_kg = _boyut_kg_parse(boyut_kg_raw) if boyut_kg_raw else {}
    uv_id = d.get('uretim_varyant_id')
    kg = d.get('planlanan_kg')
    notlar = (d.get('notlar') or d.get('not') or '').strip() or None
    rf_renk_id_raw = d.get('rf_renk_id')
    renk_varyant_id_raw = d.get('renk_varyant_id')

    from datetime import date as _date
    plan_tarihi = _date.today().isoformat()

    con = _db()
    try:
        rf_renk_id = None
        rf = None
        renk_varyant_id = None
        uv = None
        toplam_kg = 0.0
        boyut_satirlari = []

        if boyut_kg:
            if not renk_varyant_id_raw:
                return jsonify({'ok': False, 'hata': 'renk_varyant_id zorunlu (boyut_kg ile)'}), 400
            try:
                renk_varyant_id = int(renk_varyant_id_raw)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'renk_varyant_id geçersiz'}), 400

            rv = con.execute("""
                SELECT rv.id, rv.ad AS renk_ad, f.id AS formul_id, f.ad AS formul_ad
                FROM nexgen_renk_varyant rv
                JOIN nexgen_formul f ON f.id = rv.formul_id
                WHERE rv.id = ?
            """, (renk_varyant_id,)).fetchone()
            if not rv:
                return jsonify({'ok': False, 'hata': 'Renk varyantı bulunamadı'}), 404

            uv_map = _renk_varyant_uv_haritasi(con, renk_varyant_id)
            for boyut, bkg in boyut_kg.items():
                uv_b = uv_map.get(boyut)
                if not uv_b:
                    return jsonify({
                        'ok': False,
                        'hata': f'{boyut} için URETIME_ACIK varyant bulunamadı',
                    }), 400
                boyut_satirlari.append((boyut, uv_b, bkg))

            toplam_kg = round(sum(b[2] for b in boyut_satirlari), 3)
            if toplam_kg <= 0:
                return jsonify({'ok': False, 'hata': 'En az bir boyut kg > 0 olmalı'}), 400

            header_uv_id, header_boyut = _mpr_header_uv_boyut(boyut_kg, uv_map)
            if not header_uv_id:
                return jsonify({'ok': False, 'hata': 'Header varyant seçilemedi'}), 400

            uv = con.execute(
                "SELECT uv.id, uv.boyut, rv.id AS renk_varyant_id, "
                "rv.ad AS renk_ad, f.ad AS formul_ad, f.kod AS formul_kod "
                "FROM nexgen_uretim_varyant uv "
                "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
                "JOIN nexgen_formul f ON f.id=rv.formul_id "
                "WHERE uv.id=? AND uv.aktif=1",
                (header_uv_id,),
            ).fetchone()
            uv_id = header_uv_id
            kg = toplam_kg
        else:
            if not uv_id or not kg:
                return jsonify({'ok': False, 'hata': 'uretim_varyant_id ve planlanan_kg zorunlu'}), 400
            try:
                kg = float(kg)
                if kg <= 0:
                    return jsonify({'ok': False, 'hata': 'KG sıfırdan büyük olmalı'}), 400
            except Exception:
                return jsonify({'ok': False, 'hata': 'Geçersiz planlanan_kg'}), 400

            uv = con.execute(
                "SELECT uv.id, uv.boyut, rv.id AS renk_varyant_id, rv.ad AS renk_ad, "
                "f.id AS formul_id, f.ad AS formul_ad, f.kod AS formul_kod "
                "FROM nexgen_uretim_varyant uv "
                "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
                "JOIN nexgen_formul f ON f.id=rv.formul_id "
                "WHERE uv.id=? AND uv.aktif=1",
                (uv_id,),
            ).fetchone()
            if not uv:
                return jsonify({'ok': False, 'hata': 'Üretim varyantı bulunamadı'}), 404
            renk_varyant_id = uv['renk_varyant_id']
            toplam_kg = round(float(kg), 3)
            boyut_satirlari = [(uv['boyut'], uv_id, toplam_kg)]

        if _plan_rf_renk_kolonu_var(con):
            if not rf_renk_id_raw:
                return jsonify({'ok': False, 'hata': 'rf_renk_id zorunlu'}), 400
            try:
                rf_renk_id = int(rf_renk_id_raw)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'rf_renk_id geçersiz'}), 400
            rf = _rf_renk_formul_dogrula(con, rf_renk_id, renk_varyant_id)
            if not rf:
                frm_chk = con.execute("""
                    SELECT f.kod FROM nexgen_renk_varyant rv
                    JOIN nexgen_formul f ON f.id = rv.formul_id
                    WHERE rv.id = ?
                """, (renk_varyant_id,)).fetchone()
                if frm_chk and cekirdek_formul_mu(frm_chk['kod']):
                    return jsonify({
                        'ok': False,
                        'hata': 'Seçilen formül ve renk için aktif üretim kodu bulunamadı.',
                    }), 409
                return jsonify({
                    'ok': False,
                    'hata': 'Seçilen renk bulunamadı veya onaylı değil.',
                }), 400

        plan_kodu = _plan_kodu_uret(con)
        uid = _kullanici_id()

        formul_id_snap = None
        if uv and 'formul_id' in uv.keys():
            formul_id_snap = uv['formul_id']
        elif renk_varyant_id:
            fr = con.execute(
                "SELECT formul_id FROM nexgen_renk_varyant WHERE id=?",
                (renk_varyant_id,),
            ).fetchone()
            formul_id_snap = fr['formul_id'] if fr else None

        insert_meta = {
            'uretim_varyant_id': uv_id,
            'planlanan_kg': toplam_kg,
            'kaynak': 'MPR_ONCALISMA',
            'plan_kodu': plan_kodu,
            'plan_tarihi': plan_tarihi,
            'oncelik_sira': 10,
            'notlar': notlar,
            'created_by': uid,
            'formul_id': formul_id_snap,
        }
        if _plan_rf_renk_kolonu_var(con):
            insert_meta['rf_renk_id'] = rf_renk_id
            insert_meta['rf_rev_no_ekle'] = bool(rf_renk_id)
        plan_id, plan_kodu = _mpr_plan_insert(con, insert_meta)

        for boyut, uv_b, bkg in boyut_satirlari:
            _plan_boyut_satir_ensure(
                con, plan_id, uv_b, bkg, boyut,
                rf_renk_id=rf_renk_id if _plan_rf_renk_kolonu_var(con) else None,
            )

        con.commit()

        _fkod = (uv['formul_kod'] or '').strip() if uv['formul_kod'] else ''
        _fad  = (uv['formul_ad']  or '').strip()
        _formul_display = (f'{_fkod} - {_fad}') if _fkod and _fkod not in _fad else (_fad or '—')
        resp = {
            'ok': True,
            'plan_id': plan_id,
            'plan_kodu': plan_kodu,
            'formul_ad': _formul_display,
            'formul_kod': _fkod,
            'renk_ad': uv['renk_ad'],
            'boyut': uv['boyut'],
            'planlanan_kg': round(toplam_kg, 3),
            'durum': 'ON_CALISMA',
            'kaynak': 'MPR_ONCALISMA',
            'cok_boyut': len(boyut_satirlari) > 1,
        }
        if boyut_kg:
            resp['boyut_kg'] = boyut_kg
        if renk_varyant_id:
            resp['renk_varyant_id'] = renk_varyant_id
        if rf_renk_id is not None and rf:
            resp['rf_renk_id'] = rf_renk_id
            resp['rf_kod'] = rf['rf_kod']
            resp['rf_renk_ad'] = rf['ad']
        return jsonify(resp)
    except Exception as e:
        con.rollback()
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()


# ═════════════════════════════════════════════════════════════
# PAZARLAMA MERKEZİ V1 — talep taslağı + MPR (üretim emri yok)
# ═════════════════════════════════════════════════════════════

_PZM_JSON_PREFIX = '__PZM_V1__'
_PZM_V2_JSON_PREFIX = '__PZM_V2__'
_PZM_TALEP_LIKE = '__PZM_V%'
_PZM_AILELER = frozenset({'TERLIK', 'TABAN', 'DOKME'})
_PZM_DURUMLAR = frozenset({
    'TASLAK', 'MPR_BEKLIYOR', 'PLANLAMAYA_HAZIR', 'URETIMDE', 'TAMAMLANDI', 'IPTAL',
})


def _pzm_payload_pack(data):
    import json
    return _PZM_JSON_PREFIX + json.dumps(data, ensure_ascii=False, separators=(',', ':'))


def _pzm_payload_unpack(ref):
    if not ref or not str(ref).startswith(_PZM_JSON_PREFIX):
        return None
    import json
    try:
        return json.loads(str(ref)[len(_PZM_JSON_PREFIX):])
    except Exception:
        return None


def _pzm_siparis_no_uret(con):
    import datetime
    yil = datetime.datetime.now().year
    prefix = f'PZM-{yil}-'
    row = con.execute(
        "SELECT siparis_no FROM nexgen_planlama_siparis "
        "WHERE siparis_no LIKE ? ORDER BY id DESC LIMIT 1",
        (prefix + '%',),
    ).fetchone()
    son = 0
    if row and row['siparis_no']:
        try:
            son = int(str(row['siparis_no']).split('-')[-1])
        except Exception:
            son = 0
    return f'PZM-{yil}-{son + 1:04d}'


def _pzm_grup_aile_kod(aile_grup: str) -> str:
    a = (aile_grup or '').upper().replace('İ', 'I').replace('Ö', 'O')
    if a in ('DOKME', 'DÖKME'):
        return 'DOKME'
    if a == 'TABAN':
        return 'TABAN'
    return 'TERLIK'


def _pzm_aile_sql_filtre(urun_ailesi=None) -> tuple[str, list]:
    if urun_ailesi == 'TABAN':
        return " AND f.kod LIKE '2BA-%'", []
    if urun_ailesi == 'DOKME':
        return " AND f.kod LIKE '3BA-%'", []
    if urun_ailesi == 'TERLIK':
        return " AND f.kod LIKE '1BA-%'", []
    if urun_ailesi:
        return " AND UPPER(COALESCE(f.urun_ailesi,'')) = ?", [urun_ailesi.upper()]
    return '', []


def _pzm_formul_kardesleri(con, formul_id):
    """Aynı ad+aile çekirdek formül kardeşlerinin id listesi."""
    ref = con.execute(
        "SELECT ad, urun_ailesi FROM nexgen_formul WHERE id=?", (formul_id,),
    ).fetchone()
    if not ref:
        return []
    rows = con.execute(f"""
        SELECT f.id FROM nexgen_formul f
        WHERE f.aktif = 1
          AND UPPER(TRIM(f.ad)) = UPPER(TRIM(?))
          AND UPPER(COALESCE(f.urun_ailesi,'')) = UPPER(COALESCE(?, ''))
          AND ({cekirdek_kod_sql_filter('f')})
    """, (ref['ad'], ref['urun_ailesi'])).fetchall()
    return [r['id'] for r in rows]


def _pzm_renk_etiketi(rf_kod, ad):
    kod = (rf_kod or '').strip()
    ad = (ad or '').strip()
    onek = renk_sayisal_onek(kod)
    if onek:
        ad_t = ad.upper().replace('İ', 'I')
        ad_clean = ad
        if ad_t.startswith(onek):
            ad_clean = ad[len(onek):].strip().lstrip('.-–— ').strip()
        if ad_clean:
            return f'{onek} — {ad_clean}'
        return onek
    return ad or '—'


def _pzm_formul_boyutlari(con, formul_id):
    """Formül grubunun üretime açık boyut/UV listesi (RF bağımsız)."""
    kardes = _pzm_formul_kardesleri(con, formul_id)
    if not kardes:
        return []
    ph = ','.join(['?'] * len(kardes))
    rows = con.execute(f"""
        SELECT rv.id AS rv_id, uv.id AS uv_id, uv.boyut
        FROM nexgen_formul f
        JOIN nexgen_renk_varyant rv ON rv.formul_id = f.id AND rv.aktif = 1
        JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id
            AND uv.aktif = 1 AND uv.recete_durum = 'URETIME_ACIK'
        JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
        WHERE f.id IN ({ph})
        ORDER BY uv.boyut, uv.id
    """, kardes).fetchall()
    out_map: dict[str, dict] = {}
    for r in rows:
        b = (r['boyut'] or '').upper()
        label = 'MEDIUM' if b in ('STANDART', 'MEDIUM') else b
        if label and label not in out_map:
            out_map[label] = {
                'boyut': label,
                'uv_id': r['uv_id'],
                'rv_id': r['rv_id'],
            }
    sira = {'LARGE': 1, 'SMALL': 2, 'MEDIUM': 3}
    return sorted(out_map.values(), key=lambda x: sira.get(x['boyut'], 99))


def _pzm_renk_kart_listesi(con, cari_id=None):
    """Renk Merkezi aktif çekirdek renk kartları — RF uygunluk şart değil."""
    rows = con.execute("""
        SELECT id, rf_kod, ad, durum, aktif, cari_id, ilk_talep_cari_id, kaynak_arge_test_id
        FROM nexgen_rf_renk
        WHERE aktif = 1 AND durum = 'ONAYLI'
        ORDER BY rf_kod, id
    """).fetchall()
    kartlar = []
    for r in rows:
        d = dict(r)
        if not yeni_secimde_renk_gosterilebilir_mi(d):
            continue
        if not _pzm_rf_cari_uygun(d, cari_id):
            continue
        kartlar.append(d)
    return renk_kart_tekillestir(kartlar)


def _pzm_rf_formul_uygunluk_var(con, rf_renk_id, formul_id) -> bool:
    kardes = _pzm_formul_kardesleri(con, formul_id)
    if not kardes:
        return False
    ph = ','.join(['?'] * len(kardes))
    return bool(con.execute(
        f"""
        SELECT 1 FROM nexgen_rf_formul_uygunluk
        WHERE rf_renk_id = ? AND formul_id IN ({ph}) AND aktif = 1
        LIMIT 1
        """,
        [rf_renk_id, *kardes],
    ).fetchone())


def _pzm_rf_cari_uygun(rf: dict, cari_id: int | None) -> bool:
    if not cari_id:
        return True
    cid = rf.get('cari_id')
    itk = rf.get('ilk_talep_cari_id')
    if not cid and not itk:
        return True
    return cid == cari_id or itk == cari_id


def _pzm_formuller_filtreli(con, urun_ailesi=None):
    """Pazarlama sipariş ekranı — çekirdek FL/FS/FM grupları tek seçim satırı."""
    aile_filtre, params = _pzm_aile_sql_filtre(urun_ailesi)
    varyantlar = [dict(v) for v in con.execute(f"""
        SELECT uv.id, uv.boyut, uv.ad AS uv_ad, uv.recete_durum,
               rv.id AS rv_id, rv.ad AS renk_ad,
               f.id AS formul_id, f.kod AS formul_kod, f.ad AS formul_ad,
               f.urun_ailesi
        FROM nexgen_uretim_varyant uv
        JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id AND rv.aktif = 1
        JOIN nexgen_formul f ON f.id = rv.formul_id AND f.aktif = 1
        JOIN nexgen_recete_kalem rk ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
        WHERE uv.aktif = 1 AND uv.recete_durum = 'URETIME_ACIK'
          AND f.durum IN ('AKTIF', 'URETIME_ACIK')
          AND ({cekirdek_kod_sql_filter('f')})
          {aile_filtre}
        GROUP BY uv.id
        ORDER BY f.kod, rv.ad, uv.boyut
    """, params).fetchall()]

    gruplar = formul_secim_gruplari_hazirla(varyantlar)
    out = []
    for g in gruplar:
        aile_kod = _pzm_grup_aile_kod(g.get('aile') or '')
        if urun_ailesi and aile_kod != urun_ailesi:
            continue
        secenekler = g.get('secenekler') or []
        if not secenekler:
            continue
        fids = [int(s['formul_id']) for s in secenekler if s.get('formul_id')]
        if not fids:
            continue
        out.append({
            'formul_id': min(fids),
            'formul_ad': g.get('baslik') or '',
            'urun_ailesi': aile_kod,
            'grup_key': g.get('grup_key'),
        })
    return out


def _pzm_renk_satir_bul(renk_liste, renk_varyant_id):
    """Grup birleşik listede canonical veya boyut rv_id ile eşleşme."""
    try:
        rid = int(renk_varyant_id)
    except (TypeError, ValueError):
        return None
    for r in renk_liste:
        if int(r.get('renk_id') or 0) == rid:
            return r
        for b in r.get('boyutlar') or []:
            if int(b.get('rv_id') or 0) == rid:
                return r
    return None


def _pzm_renk_boyut_listesi(con, formul_id, cari_id=None, urun_ailesi=None):
    """Renk Merkezi kartları + formül grubu boyutları (RF uygunluk taslak için şart değil)."""
    del urun_ailesi  # gelecekte aile bazlı yasak listesi için
    boyutlar = _pzm_formul_boyutlari(con, formul_id)
    if not boyutlar:
        return []

    kartlar = _pzm_renk_kart_listesi(con, cari_id)
    sonuc = []
    for rf in kartlar:
        rf_id = int(rf['id'])
        uyg_var = _pzm_rf_formul_uygunluk_var(con, rf_id, formul_id)
        sonuc.append({
            'renk_id': rf_id,
            'rf_renk_id': rf_id,
            'renk_ad': _pzm_renk_etiketi(rf.get('rf_kod'), rf.get('ad')),
            'rf_kod': rf.get('rf_kod'),
            'rf_uygunluk_var': uyg_var,
            'mpr_hazir': uyg_var,
            'boyutlar': boyutlar,
        })
    sonuc.sort(key=lambda x: (x.get('rf_kod') or '', x.get('renk_ad') or ''))
    return sonuc


def _pzm_kalem_renk_coz(con, formul_id, renk_varyant_id, cari_id=None, rf_renk_id=None):
    """Taslak kalem: renk kartı (rf_renk_id) + formül boyutları."""
    liste = _pzm_renk_boyut_listesi(con, formul_id, cari_id)
    rid = rf_renk_id if rf_renk_id not in (None, '') else renk_varyant_id
    try:
        rid = int(rid)
    except (TypeError, ValueError):
        return None, renk_varyant_id
    satir = next((r for r in liste if int(r.get('rf_renk_id') or r.get('renk_id') or 0) == rid), None)
    if satir:
        rv_id = None
        for b in satir.get('boyutlar') or []:
            if b.get('rv_id'):
                rv_id = int(b['rv_id'])
                break
        return satir, rv_id or rid
    return None, rid


def _pzm_rf_oner(con, cari_id=None):
    rows = con.execute("""
        SELECT rf.id, rf.rf_kod, rf.ad, rf.cari_id, rf.ilk_talep_cari_id,
               rf.aktif, rf.durum, rf.kaynak_arge_test_id
        FROM nexgen_rf_renk rf
        WHERE rf.aktif = 1 AND rf.durum = 'ONAYLI'
        ORDER BY rf.rf_kod
    """).fetchall()
    liste = [dict(r) for r in rows if yeni_secimde_renk_gosterilebilir_mi(dict(r))]
    if cari_id:
        liste.sort(key=lambda x: (
            0 if (x.get('cari_id') == cari_id or x.get('ilk_talep_cari_id') == cari_id) else 1,
            x.get('rf_kod') or '',
        ))
    return (liste[0]['id'] if liste else None), liste


def _pzm_termin_dogrula(termin):
    from datetime import date
    if not termin:
        return False, 'Teslim tarihi zorunlu.', None
    try:
        t = date.fromisoformat(str(termin)[:10])
    except ValueError:
        return False, 'Geçersiz teslim tarihi.', None
    if t < date.today():
        return False, 'Teslim tarihi geçmiş olamaz.', None
    return True, None, t.isoformat()


def _pzm_boyut_kg_normalize(boyut_miktar_raw):
    boyut_kg = {}
    if not isinstance(boyut_miktar_raw, dict):
        return boyut_kg, 'Boyut miktarı geçersiz.'
    for b, v in boyut_miktar_raw.items():
        key = (b or '').upper()
        if key == 'MEDIUM':
            key = 'STANDART'
        if key not in ('LARGE', 'SMALL', 'STANDART'):
            continue
        try:
            kg = round(float(v), 3)
        except (TypeError, ValueError):
            return boyut_kg, f'{b} miktarı geçersiz.'
        if kg < 0:
            return boyut_kg, 'Miktar negatif olamaz.'
        if kg > 0:
            boyut_kg[key] = kg
    if not boyut_kg or sum(boyut_kg.values()) <= 0:
        return boyut_kg, 'En az bir boyut için pozitif miktar girin.'
    return boyut_kg, None


def _pzm_talep_satir_dict(row, con=None):
    d = dict(row)
    payload = _pzm_payload_unpack(d.get('talep_referansi'))
    d['payload'] = payload
    d['durum_etiket'] = {
        'TASLAK': 'Taslak',
        'MPR_BEKLIYOR': 'MPR Bekliyor',
        'PLANLAMAYA_HAZIR': 'Planlamaya Hazır',
        'URETIMDE': 'Üretimde',
        'TAMAMLANDI': 'Tamamlandı',
        'IPTAL': 'İptal',
    }.get(d.get('durum'), d.get('durum') or '—')
    if con is not None and d.get('id'):
        from modules.nexgen.pzm_siparis_read import (
            pzm_siparis_kalemleri_getir,
            pzm_siparis_ozet,
        )
        kalemler = pzm_siparis_kalemleri_getir(con, d['id'])
        ozet = pzm_siparis_ozet(kalemler)
        d['kalemler'] = kalemler
        d['kalem_sayisi'] = ozet['kalem_sayisi']
        d['toplam_kg'] = ozet['toplam_kg']
        d['terlik_kg'] = ozet.get('terlik_kg', 0)
        d['taban_kg'] = ozet.get('taban_kg', 0)
        d['dokme_kg'] = ozet.get('dokme_kg', 0)
        d['en_yakin_termin'] = ozet.get('en_yakin_termin') or d.get('termin_tarihi')
        sip_durum = (d.get('durum') or '').upper()
        if sip_durum in ('MPR_BEKLIYOR', 'PLANLAMAYA_HAZIR', 'URETIMDE'):
            d['mpr_planlar'] = _pzm_siparis_mpr_planlar(con, d['id'])
        else:
            d['mpr_planlar'] = []
    return d


def _pzm_talep_payload_olustur(con, data):
    """Ortak talep payload doğrulama."""
    try:
        cari_id = int(data.get('cari_id'))
    except (TypeError, ValueError):
        return None, 'Cari seçimi zorunlu.'
    cari = con.execute(
        "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE id=? AND aktif=1",
        (cari_id,),
    ).fetchone()
    if not cari:
        return None, 'Cari bulunamadı.'

    urun_ailesi = (data.get('urun_ailesi') or '').strip().upper()
    if urun_ailesi not in _GECERLI_AILELER:
        return None, 'Ürün ailesi TERLİK veya TABAN olmalı.'

    try:
        formul_id = int(data.get('formul_id'))
        renk_varyant_id = int(data.get('renk_varyant_id'))
    except (TypeError, ValueError):
        return None, 'Ürün ve renk seçimi zorunlu.'

    f = con.execute(
        "SELECT id, ad, kod FROM nexgen_formul WHERE id=? AND aktif=1 "
        "AND durum IN ('AKTIF','URETIME_ACIK')",
        (formul_id,),
    ).fetchone()
    if not f:
        return None, 'Seçilen ürün uygun değil.'

    rv = con.execute(
        "SELECT id, ad, renk FROM nexgen_renk_varyant "
        "WHERE id=? AND formul_id=? AND aktif=1",
        (renk_varyant_id, formul_id),
    ).fetchone()
    if not rv:
        return None, 'Seçilen renk uygun değil.'

    boyut_kg, b_hata = _pzm_boyut_kg_normalize(data.get('boyut_miktar') or {})
    if b_hata:
        return None, b_hata

    ok, t_hata, termin = _pzm_termin_dogrula(data.get('termin_tarihi'))
    if not ok:
        return None, t_hata

    rf_renk_id = data.get('rf_renk_id')
    if rf_renk_id in (None, ''):
        rf_renk_id, _ = _pzm_rf_oner(con, cari_id)
    else:
        try:
            rf_renk_id = int(rf_renk_id)
        except (TypeError, ValueError):
            return None, 'Renk formülü geçersiz.'
    if _plan_rf_renk_kolonu_var(con) and not rf_renk_id:
        return None, 'Bu ürün için onaylı renk formülü bulunamadı.'
    if rf_renk_id:
        rf = _rf_renk_formul_dogrula(con, rf_renk_id, renk_varyant_id)
        if not rf:
            return None, 'Seçilen renk formülü onaylı değil.'

    uv_map = _renk_varyant_uv_haritasi(con, renk_varyant_id)
    for boyut in boyut_kg:
        if not uv_map.get(boyut):
            return None, f'{boyut} boyutu bu renk için üretime açık değil.'

    notlar = (data.get('notlar') or data.get('not') or '').strip() or None
    payload = {
        'v': 1,
        'urun_ailesi': urun_ailesi,
        'formul_id': formul_id,
        'formul_ad': (f['ad'] or f['kod'] or '').strip(),
        'renk_varyant_id': renk_varyant_id,
        'renk_ad': (rv['ad'] or rv['renk'] or '').strip(),
        'rf_renk_id': rf_renk_id,
        'boyut_miktar': boyut_kg,
        'termin_tarihi': termin,
        'notlar': notlar,
    }
    return {
        'cari': dict(cari),
        'payload': payload,
        'boyut_kg': boyut_kg,
        'termin': termin,
        'notlar': notlar,
        'rf_renk_id': rf_renk_id,
        'renk_varyant_id': renk_varyant_id,
    }, None


@nexgen_bp.route('/pazarlama')
@yetki_gerekli('nexgen.plan.view', 'can_view')
def pazarlama_merkezi():
    """Pazarlama personeli talep / MPR V1 ekranı."""
    con = _db()
    try:
        cariler = [
            dict(c) for c in con.execute(
                "SELECT id, cari_kod, unvan FROM nexgen_cari WHERE aktif=1 ORDER BY unvan"
            ).fetchall()
        ]
        talepler = []
        if _planlama_siparis_tablosu_var(con):
            rows = con.execute("""
                SELECT id, siparis_no, cari_id, cari_unvan, termin_tarihi,
                       durum, notlar, talep_referansi, olusturma_tarihi
                FROM nexgen_planlama_siparis
                WHERE talep_referansi LIKE ?
                ORDER BY id DESC LIMIT 30
            """, (_PZM_TALEP_LIKE,)).fetchall()
            talepler = [_pzm_talep_satir_dict(r, con) for r in rows]
    finally:
        con.close()
    return render_template(
        'nexgen/pazarlama_merkezi.html',
        active='nexgen',
        cariler=cariler,
        talepler=talepler,
        can_manage=yetki_var('nexgen.plan.manage', 'can_manage'),
    )


