# ═════════════════════════════════════════════════════════════
# ÜRETİM EMİRLERİ MERKEZİ V1 — plan → batch → tablet
# ═════════════════════════════════════════════════════════════

_UEM_TABLET_MARKER = '__UEM_TABLET__'
_UEM_BEKLET_MARKER = '__UEM_BEKLET__'
_TUA_AKTIF_BATCH_DURUMLAR = ('HAZIR', 'DEVAM', 'BEKLEME')


def _tua_tablet_marker_var(notlar):
    return _UEM_TABLET_MARKER in (notlar or '')


def _tua_tablet_marker_satir(kullanici_id=None, kullanici_ad=None):
    from datetime import datetime as _dt
    uid = kullanici_id or _kullanici_id() or 0
    kad = (kullanici_ad or '').strip() or f'uid:{uid}'
    return f"{_UEM_TABLET_MARKER}|{_dt.now().strftime('%Y-%m-%d %H:%M')}|{kad}"


def _tua_plan_durum_sync(con, plan_id, batch_durum):
    """Tablet batch durumuna göre plan durumunu günceller (tek plan)."""
    if not plan_id:
        return
    if batch_durum == 'DEVAM':
        con.execute(
            "UPDATE nexgen_uretim_plan SET durum='URETIMDE' "
            "WHERE id=? AND durum IN ('PLANLANDI','URETIMDE','BASLADI')",
            (plan_id,),
        )
    elif batch_durum == 'BEKLEME':
        con.execute(
            "UPDATE nexgen_uretim_plan SET durum='URETIMDE' "
            "WHERE id=? AND durum IN ('PLANLANDI','URETIMDE','BASLADI')",
            (plan_id,),
        )
    elif batch_durum == 'BITTI':
        con.execute(
            "UPDATE nexgen_uretim_plan SET durum='BITTI' "
            "WHERE id=? AND durum IN ('BASLADI','URETIMDE')",
            (plan_id,),
        )
        _pzm_siparis_tamamlandi_sync(con, plan_id)


def _tua_batch_bitir_kontrol(con, batch_kodu, mevcut_durum):
    """Bitir öncesi doğrulama — batch seviyesi Başla/Devam zorunlu."""
    if mevcut_durum == 'BEKLEME':
        return False, 'Beklemedeki iş bitirilemez. Önce DEVAM ET ile sürdürün.'
    if mevcut_durum != 'DEVAM':
        return False, 'Önce üretimi başlatın (BAŞLA).'
    return True, None


def _tua_tablet_is_liste_sorgu(con):
    """ÜEM'den tablete gönderilmiş aktif batch listesi."""
    _cols = [c['name'] for c in con.execute(
        "PRAGMA table_info(nexgen_uretim_batch)"
    ).fetchall()]
    if 'plan_id' not in _cols:
        return []
    cari_select, cari_join = _plan_cari_select_sql(con)
    termin_sel = "np.termin_tarihi," if _plan_termin_kolonu_var(con) else "NULL AS termin_tarihi,"
    uk_sel = "np.uretim_kodu," if _kolon_var_chk(con, 'nexgen_uretim_plan', 'uretim_kodu') else "NULL AS uretim_kodu,"
    af_sel = "np.ana_formul_kodu," if _kolon_var_chk(con, 'nexgen_uretim_plan', 'ana_formul_kodu') else "NULL AS ana_formul_kodu,"
    rk_sel = "np.renk_kodu," if _kolon_var_chk(con, 'nexgen_uretim_plan', 'renk_kodu') else "NULL AS renk_kodu,"
    rows = con.execute(f"""
        SELECT nb.id, nb.batch_kodu, nb.planlanan_kg, nb.durum AS batch_durum,
               nb.notlar, nb.olusturma_tarihi,
               np.id AS plan_id, np.plan_kodu, np.siparis_no, np.durum AS plan_durum,
               {termin_sel} np.oncelik_sira, np.plan_tarihi,
               {uk_sel} {af_sel} {rk_sel}
               {cari_select},
               uv.boyut, rv.ad AS renk_ad,
               f.ad AS formul_ad, f.kod AS formul_kod
        FROM nexgen_uretim_batch nb
        JOIN nexgen_uretim_plan np ON np.id = nb.plan_id
        JOIN nexgen_uretim_varyant uv ON uv.id = nb.uretim_varyant_id
        JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
        JOIN nexgen_formul f ON f.id = rv.formul_id
        {cari_join}
        WHERE COALESCE(nb.notlar, '') LIKE ?
          AND nb.durum IN ('HAZIR','DEVAM','BEKLEME')
        ORDER BY np.oncelik_sira ASC, nb.id DESC
        LIMIT 100
    """, (f'%{_UEM_TABLET_MARKER}%',)).fetchall()
    liste = []
    for r in rows:
        d = dict(r)
        fkod = (d.get('formul_kod') or '').strip()
        fad = (d.get('formul_ad') or '').strip()
        d['formul_goster'] = (f'{fkod} - {fad}') if fkod and fkod not in fad else (fad or fkod or '—')
        d['emir_no'] = d.get('plan_kodu') or d.get('siparis_no') or d.get('batch_kodu')
        d['cari_goster'] = d.get('musteri_adi') or '—'
        d['termin_goster'] = d.get('termin_tarihi') or d.get('plan_tarihi') or '—'
        d['oncelik_goster'] = d.get('oncelik_sira') if d.get('oncelik_sira') is not None else 10
        if d.get('uretim_kodu'):
            d['uretim_kodu_goster'] = d['uretim_kodu']
            alt = []
            if d.get('formul_kod'):
                g = cekirdek_formul_gosterim(d['formul_kod'], d.get('formul_ad'))
                if g.get('alt_metin'):
                    alt.append(g['alt_metin'])
            if d.get('renk_kodu') and d.get('renk_ad'):
                alt.append(f"{d['renk_kodu']} {d['renk_ad']}")
            elif d.get('renk_ad'):
                alt.append(d['renk_ad'])
            d['uretim_kodu_alt'] = '\n'.join(alt) if alt else (d.get('renk_ad') or '')
        bd = d.get('batch_durum') or 'HAZIR'
        d['durum_etiket'] = {
            'HAZIR': 'Hazır', 'DEVAM': 'Üretimde', 'BEKLEME': 'Beklemede',
        }.get(bd, bd)
        liste.append(d)
    return liste


def _uem_emir_liste_sorgu(con):
    """Planlamaya hazır / üretimdeki emirleri listeler."""
    where = "np.durum IN ('ON_CALISMA','PLANLANDI','URETIMDE')"
    _bcols = [c['name'] for c in con.execute(
        "PRAGMA table_info(nexgen_uretim_batch)"
    ).fetchall()]
    batch_join = ""
    batch_select = (
        "NULL AS batch_kodu, NULL AS batch_durum, NULL AS batch_id, "
        "NULL AS lot_kodu, 0 AS tablet_gonderildi"
    )
    if 'plan_id' in _bcols:
        batch_join = (
            "LEFT JOIN nexgen_uretim_batch nb "
            "ON nb.plan_id = np.id AND nb.durum NOT IN ('IPTAL','BITTI')"
        )
        batch_select = (
            "nb.batch_kodu, nb.durum AS batch_durum, nb.id AS batch_id, "
            "nb.lot_kodu, "
            "CASE WHEN COALESCE(nb.notlar,'') LIKE '%__UEM_TABLET__%' THEN 1 ELSE 0 END "
            "AS tablet_gonderildi"
        )
    cari_select, cari_join = _plan_cari_select_sql(con)
    hdr_select = ""
    hdr_join = ""
    if _plan_planlama_siparis_kolonu_var(con) and _planlama_siparis_tablosu_var(con):
        hdr_select = (
            "np.planlama_siparis_id, ps.siparis_no AS hdr_siparis_no, "
            "ps.durum AS hdr_durum, "
        )
        hdr_join = (
            "LEFT JOIN nexgen_planlama_siparis ps ON ps.id = np.planlama_siparis_id "
        )
    else:
        hdr_select = "NULL AS planlama_siparis_id, NULL AS hdr_siparis_no, NULL AS hdr_durum, "
    rf_select = ""
    rf_join = ""
    if _plan_rf_renk_kolonu_var(con):
        rf_select = "np.rf_renk_id, np.termin_tarihi, rf.rf_kod, rf.ad AS rf_ad, "
        rf_join = "LEFT JOIN nexgen_rf_renk rf ON rf.id = np.rf_renk_id "
    else:
        rf_select = "NULL AS rf_renk_id, NULL AS termin_tarihi, NULL AS rf_kod, NULL AS rf_ad, "
    rows = con.execute(f"""
        SELECT np.id, np.plan_kodu, np.kaynak, np.siparis_no,
               {cari_select},
               {hdr_select}
               {rf_select}
               np.planlanan_kg, np.oncelik_sira, np.plan_tarihi,
               np.durum, np.notlar, np.created_at,
               uv.id AS uv_id, uv.boyut,
               rv.ad AS renk_ad,
               f.ad AS formul_ad, f.kod AS formul_kod, f.id AS formul_id,
               ku.KullaniciAdi AS olusturan_ad,
               {batch_select}
        FROM nexgen_uretim_plan np
        {cari_join}
        {hdr_join}
        {rf_join}
        JOIN nexgen_uretim_varyant uv ON uv.id = np.uretim_varyant_id
        JOIN nexgen_renk_varyant rv   ON rv.id = uv.renk_varyant_id
        JOIN nexgen_formul f          ON f.id  = rv.formul_id
        LEFT JOIN sistem_kullanici ku ON ku.Id  = np.created_by
        {batch_join}
        WHERE {where}
        ORDER BY np.oncelik_sira ASC, np.id DESC
        LIMIT 80
    """).fetchall()
    return rows


def _uem_emir_dict(con, row):
    d = dict(row)
    fkod = (d.get('formul_kod') or '').strip()
    fad = (d.get('formul_ad') or '').strip()
    d['formul_goster'] = (f'{fkod} - {fad}') if fkod and fkod not in fad else (fad or fkod or '—')
    d['cari_goster'] = d.get('musteri_adi') or d.get('hdr_cari_unvan') or '—'
    d['emir_no'] = d.get('plan_kodu') or f"PLAN-{d.get('id')}"
    d['boyut_parcalari'] = _plan_boyut_parcalari_list(con, d['id'])
    if d['boyut_parcalari']:
        d['boyut_ozet'] = ', '.join(
            f"{b['boyut']} {b['kg']:.3f}kg" for b in d['boyut_parcalari']
        )
    else:
        d['boyut_ozet'] = d.get('boyut') or '—'
    d['bekletildi'] = _UEM_BEKLET_MARKER in (d.get('notlar') or '')
    durum = d.get('durum') or ''
    bk = d.get('batch_kodu')
    bd = d.get('batch_durum')
    if durum == 'URETIMDE' and bk:
        if bd == 'BEKLEME':
            d['durum_etiket'] = 'Bekletildi'
        elif bd == 'DEVAM':
            d['durum_etiket'] = 'Üretimde'
        elif d.get('tablet_gonderildi'):
            d['durum_etiket'] = 'Tablette'
        else:
            d['durum_etiket'] = 'Üretimde'
    elif durum == 'PLANLANDI':
        d['durum_etiket'] = 'Planlandı'
    elif durum == 'ON_CALISMA':
        d['durum_etiket'] = 'MPR Bekliyor' if d.get('planlama_siparis_id') else 'Taslak MPR'
    else:
        d['durum_etiket'] = durum
    d['termin_goster'] = d.get('termin_tarihi') or d.get('plan_tarihi') or '—'
    d['oncelik_goster'] = d.get('oncelik_sira') if d.get('oncelik_sira') is not None else 10
    return d


