@nexgen_bp.route('/api/plan/rf-renk-varyantlari')
@login_gerekli
def api_plan_rf_renk_varyantlari():
    """Seçilen hammadde formülüne ait üretim varyantları (LARGE/SMALL/MEDIUM).

    FAZ-3F-6: Artık nexgen_rf_formul_uygunluk JOIN'i kullanılmıyor.
    formul_id parametresi zorunlu — JS'den mv-formul değeri gönderilir.
    rf_renk_id hâlâ kabul edilir (ileride pigment hesabı için kullanılabilir).
    """
    formul_id_raw = request.args.get('formul_id')
    if not formul_id_raw:
        return jsonify({'ok': False, 'hata': 'formul_id zorunlu'}), 400
    try:
        formul_id = int(formul_id_raw)
    except (TypeError, ValueError):
        return jsonify({'ok': False, 'hata': 'formul_id geçersiz'}), 400

    con = _db()
    try:
        # Önce URETIME_ACIK UV'leri çek
        rows = con.execute("""
            SELECT rv.id AS renk_id, rv.ad AS renk_ad,
                   uv.id AS uv_id, uv.boyut,
                   f.id AS formul_id,
                   1 AS uretime_acik
            FROM nexgen_renk_varyant rv
            JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id
                AND uv.aktif = 1
                AND uv.recete_durum = 'URETIME_ACIK'
            JOIN nexgen_formul f ON f.id = rv.formul_id
            WHERE rv.formul_id = ?
            ORDER BY rv.ad, uv.boyut
        """, (formul_id,)).fetchall()

        # URETIME_ACIK yoksa, aktif UV'ler olmasa da en azından RV var mı bak
        if not rows:
            rows_rv = con.execute("""
                SELECT rv.id AS renk_id, rv.ad AS renk_ad,
                       uv.id AS uv_id, uv.boyut, uv.recete_durum,
                       f.id AS formul_id,
                       0 AS uretime_acik
                FROM nexgen_renk_varyant rv
                LEFT JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id
                    AND uv.aktif = 1
                JOIN nexgen_formul f ON f.id = rv.formul_id
                WHERE rv.formul_id = ?
                ORDER BY rv.ad, uv.boyut
            """, (formul_id,)).fetchall()
            rows = rows_rv

        # renk_id bazında grupla
        renk_map = {}
        for r in rows:
            rid = r['renk_id']
            if rid not in renk_map:
                renk_map[rid] = {
                    'renk_id': rid,
                    'renk_ad': r['renk_ad'],
                    'large_uv_id': None,
                    'small_uv_id': None,
                    'standart_uv_id': None,
                    'uretime_acik': bool(r['uretime_acik']),
                }
            b = (r['boyut'] or '').upper()
            if r['uretime_acik']:
                if b == 'LARGE':
                    renk_map[rid]['large_uv_id'] = r['uv_id']
                elif b == 'SMALL':
                    renk_map[rid]['small_uv_id'] = r['uv_id']
                elif b in ('STANDART', 'MEDIUM'):
                    renk_map[rid]['standart_uv_id'] = r['uv_id']
        return jsonify({'ok': True, 'liste': list(renk_map.values())})
    finally:
        con.close()


@nexgen_bp.route('/api/plan/ekle', methods=['POST'])
@yetki_gerekli('nexgen.plan.manage', 'can_manage')
def api_plan_ekle():
    """Yeni üretim planı oluştur. Stok hareketi yapılmaz."""
    d = request.get_json(silent=True) or {}
    uv_id      = d.get('uretim_varyant_id')
    kg         = d.get('planlanan_kg')
    oncelik    = d.get('oncelik_sira', 10)
    plan_tarihi = (d.get('plan_tarihi') or '').strip()
    notlar     = (d.get('notlar') or '').strip() or None
    siparis_no  = (d.get('siparis_no') or '').strip() or None
    musteri_adi = (d.get('musteri_adi') or '').strip() or None
    cari_id_raw = d.get('cari_id')
    rf_renk_id_raw = d.get('rf_renk_id')
    termin_tarihi = (d.get('termin_tarihi') or '').strip()

    if not uv_id or not kg:
        return jsonify({'ok': False, 'hata': 'uretim_varyant_id ve planlanan_kg zorunlu'}), 400
    try:
        kg = float(kg)
        if kg <= 0:
            return jsonify({'ok': False, 'hata': 'KG sıfırdan büyük olmalı'}), 400
    except Exception:
        return jsonify({'ok': False, 'hata': 'Geçersiz planlanan_kg'}), 400

    if not plan_tarihi:
        from datetime import date as _date
        plan_tarihi = _date.today().isoformat()

    con = _db()
    try:
        uv = con.execute(
            "SELECT uv.id, uv.boyut, rv.ad AS renk_ad, f.ad AS formul_ad, f.id AS formul_id "
            "FROM nexgen_uretim_varyant uv "
            "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
            "JOIN nexgen_formul f ON f.id=rv.formul_id "
            "WHERE uv.id=? AND uv.aktif=1",
            (uv_id,)
        ).fetchone()
        if not uv:
            return jsonify({'ok': False, 'hata': 'Üretim varyantı bulunamadı'}), 404

        cari_id = None
        if cari_id_raw is not None and cari_id_raw != '':
            try:
                cari_id = int(cari_id_raw)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'cari_id geçersiz'}), 400
            cari = con.execute(
                "SELECT id, unvan FROM nexgen_cari WHERE id=? AND aktif=1",
                (cari_id,)
            ).fetchone()
            if not cari:
                return jsonify({'ok': False, 'hata': f'Cari bulunamadı (id={cari_id})'}), 400
            musteri_adi = cari['unvan']
        elif not musteri_adi:
            return jsonify({'ok': False, 'hata': 'Cari seçimi zorunludur.'}), 400

        rf_renk_id = None
        rf_cari_uyari = None
        if _plan_rf_renk_kolonu_var(con):
            if not rf_renk_id_raw:
                return jsonify({'ok': False, 'hata': 'rf_renk_id zorunlu'}), 400
            try:
                rf_renk_id = int(rf_renk_id_raw)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'rf_renk_id geçersiz'}), 400
            # FAZ-3F-6: Formül bağlantısı kontrolü kaldırıldı — RF ONAYLI+aktif ise yeterli
            rf = con.execute("""
                SELECT rf.id, rf.rf_kod, rf.ad, rf.cari_id
                FROM nexgen_rf_renk rf
                WHERE rf.id = ?
                  AND rf.durum = 'ONAYLI' AND rf.aktif = 1
            """, (rf_renk_id,)).fetchone()
            if not rf:
                return jsonify({
                    'ok': False,
                    'hata': 'Seçilen renk bulunamadı veya onaylı değil.',
                }), 400
            frm_row = con.execute(
                "SELECT kod FROM nexgen_formul WHERE id=?", (uv['formul_id'],)
            ).fetchone()
            if frm_row and cekirdek_formul_mu(frm_row['kod']):
                uk_kontrol = _yeni_plan_uretim_kodu_zorunlu_dogrula(
                    con, uv['formul_id'], rf_renk_id,
                )
                if not uk_kontrol.get('ok'):
                    return jsonify({
                        'ok': False,
                        'hata': uk_kontrol.get('hata'),
                    }), uk_kontrol.get('status', 409)
            if cari_id and rf['cari_id']:
                rf_cari_uyari = _rf_cari_uyari(con, rf['cari_id'], cari_id)

        if _plan_termin_kolonu_var(con) and not termin_tarihi:
            return jsonify({'ok': False, 'hata': 'termin_tarihi zorunlu'}), 400

        # Sipariş no boşsa otomatik üret
        if not siparis_no:
            siparis_no = _nexgen_siparis_no_uret(con)

        planlama_siparis_id = None
        if (_plan_planlama_siparis_kolonu_var(con)
                and _planlama_siparis_tablosu_var(con)):
            planlama_siparis_id = _planlama_siparis_bul_veya_olustur(
                con, siparis_no, cari_id, musteri_adi,
                termin_tarihi=termin_tarihi, notlar=notlar,
                olusturan_id=_kullanici_id(),
            )

        plan_kodu = _plan_kodu_uret(con)
        uid = _kullanici_id()

        kalip_carpani_plan = None
        try:
            kc_raw = d.get('kalip_carpani')
            if kc_raw not in (None, ''):
                kalip_carpani_plan = float(kc_raw)
        except (TypeError, ValueError):
            pass

        insert_meta = {
            'uretim_varyant_id': uv_id,
            'planlanan_kg': kg,
            'kaynak': 'MANUEL',
            'plan_kodu': plan_kodu,
            'plan_tarihi': plan_tarihi,
            'oncelik_sira': oncelik,
            'notlar': notlar,
            'created_by': uid,
            'siparis_bilgisi': True,
            'siparis_no': siparis_no,
            'musteri_adi': musteri_adi,
            'formul_id': uv['formul_id'] if uv and 'formul_id' in uv.keys() else None,
            'durum': 'PLANLANDI',
            'rf_rev_no_ekle': True,
        }
        if _plan_cari_kolonu_var(con):
            insert_meta['cari_id'] = cari_id
        if planlama_siparis_id is not None:
            insert_meta['planlama_siparis_id'] = planlama_siparis_id
        if _plan_rf_renk_kolonu_var(con):
            insert_meta['rf_renk_id'] = rf_renk_id
        if _plan_termin_kolonu_var(con):
            insert_meta['termin_tarihi'] = termin_tarihi
        if _kolon_var_chk(con, 'nexgen_uretim_plan', 'kalip_carpani'):
            insert_meta['kalip_carpani'] = kalip_carpani_plan
        plan_id, plan_kodu = _mpr_plan_insert(con, insert_meta)
        con.commit()
        resp = {
            'ok': True,
            'plan_kodu': plan_kodu,
            'siparis_no': siparis_no,
            'formul_ad': uv['formul_ad'],
            'renk_ad': uv['renk_ad'],
            'boyut': uv['boyut'],
            'planlanan_kg': round(kg, 3),
            'musteri_adi': musteri_adi,
        }
        if cari_id is not None:
            resp['cari_id'] = cari_id
        if planlama_siparis_id is not None:
            resp['planlama_siparis_id'] = planlama_siparis_id
        if rf_renk_id is not None:
            resp['rf_renk_id'] = rf_renk_id
            resp['rf_kod'] = rf['rf_kod']
            resp['rf_renk_ad'] = rf['ad']
        if termin_tarihi:
            resp['termin_tarihi'] = termin_tarihi
        if rf_cari_uyari:
            resp['rf_cari_uyari'] = rf_cari_uyari
        return jsonify(resp)
    except Exception as e:
        con.rollback()
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()


@nexgen_bp.route('/api/planlama-siparis/<int:ps_id>/mpr-ekle', methods=['POST'])
@yetki_gerekli('nexgen.plan.manage', 'can_manage')
def api_planlama_siparis_mpr_ekle(ps_id):
    """Mevcut planlama sipariş header'ına yeni MPR satırı ekler."""
    d = request.get_json(silent=True) or {}
    uv_id = d.get('uretim_varyant_id')
    kg = d.get('planlanan_kg')
    oncelik = d.get('oncelik_sira', 10)
    plan_tarihi = (d.get('plan_tarihi') or '').strip()
    notlar = (d.get('notlar') or '').strip() or None
    rf_renk_id_raw = d.get('rf_renk_id')

    if not uv_id or not kg:
        return jsonify({'ok': False, 'hata': 'uretim_varyant_id ve planlanan_kg zorunlu'}), 400
    try:
        kg = float(kg)
        if kg <= 0:
            return jsonify({'ok': False, 'hata': 'KG sıfırdan büyük olmalı'}), 400
    except Exception:
        return jsonify({'ok': False, 'hata': 'Geçersiz planlanan_kg'}), 400

    if not plan_tarihi:
        from datetime import date as _date
        plan_tarihi = _date.today().isoformat()

    con = _db()
    try:
        if not _planlama_siparis_tablosu_var(con):
            return jsonify({'ok': False, 'hata': 'Planlama sipariş tablosu yok'}), 400

        hdr = con.execute(
            "SELECT id, siparis_no, cari_id, cari_unvan, termin_tarihi, durum "
            "FROM nexgen_planlama_siparis WHERE id=?",
            (ps_id,),
        ).fetchone()
        if not hdr:
            return jsonify({'ok': False, 'hata': 'Planlama siparişi bulunamadı'}), 404
        if hdr['durum'] == 'IPTAL':
            return jsonify({'ok': False, 'hata': 'İptal edilmiş siparişe satır eklenemez'}), 400

        uv = con.execute(
            "SELECT uv.id, uv.boyut, rv.ad AS renk_ad, f.ad AS formul_ad, f.id AS formul_id "
            "FROM nexgen_uretim_varyant uv "
            "JOIN nexgen_renk_varyant rv ON rv.id=uv.renk_varyant_id "
            "JOIN nexgen_formul f ON f.id=rv.formul_id "
            "WHERE uv.id=? AND uv.aktif=1",
            (uv_id,),
        ).fetchone()
        if not uv:
            return jsonify({'ok': False, 'hata': 'Üretim varyantı bulunamadı'}), 404

        cari_id = hdr['cari_id']
        musteri_adi = hdr['cari_unvan']
        siparis_no = hdr['siparis_no']
        termin_tarihi = hdr['termin_tarihi']

        rf_renk_id = None
        rf_cari_uyari = None
        rf = None
        if _plan_rf_renk_kolonu_var(con):
            if not rf_renk_id_raw:
                return jsonify({'ok': False, 'hata': 'rf_renk_id zorunlu'}), 400
            try:
                rf_renk_id = int(rf_renk_id_raw)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'rf_renk_id geçersiz'}), 400
            # Çekirdek formül için aktif uygunluk + dolu üretim kodu zorunlu
            rv_row = con.execute(
                "SELECT rv.id FROM nexgen_renk_varyant rv "
                "JOIN nexgen_uretim_varyant uv ON uv.renk_varyant_id = rv.id "
                "WHERE uv.id = ?",
                (uv_id,),
            ).fetchone()
            rf = None
            if rv_row:
                rf = _rf_renk_formul_dogrula(con, rf_renk_id, rv_row['id'])
            if not rf:
                frm_row = con.execute(
                    "SELECT f.kod FROM nexgen_formul f WHERE f.id=?",
                    (uv['formul_id'],),
                ).fetchone()
                if frm_row and cekirdek_formul_mu(frm_row['kod']):
                    return jsonify({
                        'ok': False,
                        'hata': 'Seçilen formül ve renk için aktif üretim kodu bulunamadı.',
                    }), 409
                return jsonify({
                    'ok': False,
                    'hata': 'Seçilen renk bulunamadı veya onaylı değil.',
                }), 400
            if cari_id and rf['cari_id']:
                rf_cari_uyari = _rf_cari_uyari(con, rf['cari_id'], cari_id)

        if _plan_termin_kolonu_var(con) and not termin_tarihi:
            return jsonify({'ok': False, 'hata': 'Header termin tarihi eksik'}), 400

        planlama_siparis_id = hdr['id']
        plan_kodu = _plan_kodu_uret(con)
        uid = _kullanici_id()

        insert_meta = {
            'uretim_varyant_id': uv_id,
            'planlanan_kg': kg,
            'kaynak': 'MANUEL',
            'plan_kodu': plan_kodu,
            'plan_tarihi': plan_tarihi,
            'oncelik_sira': oncelik,
            'notlar': notlar,
            'created_by': uid,
            'siparis_bilgisi': True,
            'siparis_no': siparis_no,
            'musteri_adi': musteri_adi,
            'planlama_siparis_id': planlama_siparis_id,
            'formul_id': uv['formul_id'] if uv and 'formul_id' in uv.keys() else None,
            'durum': 'PLANLANDI',
        }
        if _plan_cari_kolonu_var(con):
            insert_meta['cari_id'] = cari_id
        if _plan_rf_renk_kolonu_var(con):
            insert_meta['rf_renk_id'] = rf_renk_id
        if _plan_termin_kolonu_var(con):
            insert_meta['termin_tarihi'] = termin_tarihi
        plan_id, plan_kodu = _mpr_plan_insert(con, insert_meta)
        con.commit()
        resp = {
            'ok': True,
            'plan_kodu': plan_kodu,
            'siparis_no': siparis_no,
            'planlama_siparis_id': planlama_siparis_id,
            'formul_ad': uv['formul_ad'],
            'renk_ad': uv['renk_ad'],
            'boyut': uv['boyut'],
            'planlanan_kg': round(kg, 3),
            'musteri_adi': musteri_adi,
        }
        if cari_id is not None:
            resp['cari_id'] = cari_id
        if rf_renk_id is not None and rf:
            resp['rf_renk_id'] = rf_renk_id
            resp['rf_kod'] = rf['rf_kod']
            resp['rf_renk_ad'] = rf['ad']
        if termin_tarihi:
            resp['termin_tarihi'] = termin_tarihi
        if rf_cari_uyari:
            resp['rf_cari_uyari'] = rf_cari_uyari
        return jsonify(resp)
    except Exception as e:
        con.rollback()
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()


@nexgen_bp.route('/api/plan/<int:plan_id>/iptal', methods=['POST'])
@yetki_gerekli('nexgen.plan.manage', 'can_manage')
def api_plan_iptal(plan_id):
    """Planı IPTAL durumuna çeker."""
    d = request.get_json(silent=True) or {}
    nedeni = (d.get('nedeni') or d.get('gerekce') or '').strip() or 'Plan iptal'
    con = _db()
    try:
        p = con.execute(
            "SELECT id, durum FROM nexgen_uretim_plan WHERE id=?", (plan_id,)
        ).fetchone()
        if not p:
            return jsonify({'ok': False, 'hata': 'Plan bulunamadı'}), 404
        if p['durum'] == 'BITTI':
            return jsonify({'ok': False, 'hata': 'Tamamlanan plan iptal edilemez'}), 400
        rezerv = _rezerv_aktif_iptal(con, plan_id=plan_id, nedeni=nedeni)
        if not rezerv.get('ok'):
            con.rollback()
            return jsonify({'ok': False, 'hata': rezerv.get('hata')}), 400
        con.execute(
            "UPDATE nexgen_uretim_plan SET durum='IPTAL' WHERE id=?", (plan_id,)
        )
        con.commit()
        return jsonify({'ok': True, 'rezerv': rezerv})
    except Exception as e:
        con.rollback()
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()


