@nexgen_bp.route('/api/batch/<batch_kodu>/durum', methods=['POST'])
@login_gerekli
def api_batch_durum_guncelle(batch_kodu):
    """Batch durumunu güncelle.

    Kabul edilen geçişler:
      HAZIR      → DEVAM      (operatör başlattı)
      DEVAM      → BEKLEME    (beklemede)
      BEKLEME    → DEVAM      (devam ettirdi)
      DEVAM      → BITTI      (üretim bitti)
      HAZIR      → BITTI      (direkt bitti)

    Yetki: nexgen.tablet.uretim VEYA nexgen.plan.manage
    """
    if not (yetki_var('nexgen.tablet.uretim', 'can_uretim') or
            yetki_var('nexgen.plan.manage', 'can_manage')):
        return jsonify({'ok': False, 'hata': 'Yetki yok'}), 403

    d = request.get_json(silent=True) or {}
    yeni_durum = (d.get('durum') or '').strip().upper()
    notlar = (d.get('notlar') or '').strip() or None

    GECERLI_DURUMLAR = {'HAZIR', 'DEVAM', 'BEKLEME', 'BITTI'}
    GECISLER = {
        'HAZIR':   {'DEVAM'},
        'DEVAM':   {'BEKLEME', 'BITTI'},
        'BEKLEME': {'DEVAM'},
        'BITTI':   set(),
    }

    if yeni_durum not in GECERLI_DURUMLAR:
        return jsonify({'ok': False, 'hata': f'Geçersiz durum: {yeni_durum}'}), 400

    con = _db()
    try:
        batch = con.execute(
            "SELECT batch_kodu, durum, plan_id, notlar FROM nexgen_uretim_batch WHERE batch_kodu=?",
            (batch_kodu,)
        ).fetchone()
        if not batch:
            return jsonify({'ok': False, 'hata': 'Batch bulunamadı'}), 404

        mevcut = batch['durum']
        if mevcut == yeni_durum:
            return jsonify({
                'ok': False,
                'hata': f'Batch zaten {mevcut} durumunda.',
            }), 400
        izin = GECISLER.get(mevcut, set())
        if yeni_durum not in izin:
            return jsonify({
                'ok': False,
                'hata': f'{mevcut} → {yeni_durum} geçişi geçersiz'
            }), 400

        if yeni_durum == 'BITTI':
            uygun, b_hata = _tua_batch_bitir_kontrol(con, batch_kodu, mevcut)
            if not uygun:
                return jsonify({'ok': False, 'hata': b_hata}), 400

        mevcut_notlar = batch['notlar'] or ''
        if notlar:
            yeni_notlar = (mevcut_notlar.strip() + '\n' + notlar.strip()).strip()
            con.execute(
                "UPDATE nexgen_uretim_batch SET durum=?, notlar=? WHERE batch_kodu=?",
                (yeni_durum, yeni_notlar, batch_kodu)
            )
        else:
            con.execute(
                "UPDATE nexgen_uretim_batch SET durum=? WHERE batch_kodu=?",
                (yeni_durum, batch_kodu)
            )

        _tua_plan_durum_sync(con, batch['plan_id'], yeni_durum)

        if yeni_durum == 'DEVAM':
            _rf_kullanim_tablet_sync(con, batch_kodu)
        elif yeni_durum == 'BITTI':
            _rf_kullanim_tablet_sync(con, batch_kodu, tamamlandi=True)

        con.commit()
        return jsonify({
            'ok': True,
            'durum': yeni_durum,
            'batch_kodu': batch_kodu,
            'plan_id': batch['plan_id'],
        })
    except Exception as e:
        con.rollback()
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()


def _ana_recete_kg_hesapla(con, uretim_varyant_id):
    """Aktif ana reçete toplamı (BOYA hariç)."""
    row = con.execute("""
        SELECT COALESCE(SUM(rk.miktar_kg), 0) AS toplam
        FROM nexgen_recete_kalem rk
        JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
          AND UPPER(COALESCE(sk.kategori, '')) != 'BOYA'
    """, (uretim_varyant_id,)).fetchone()
    return round(float(row['toplam']), 3) if row else 0.0


def _rf_boya_kg_birim_hesapla(con, rf_renk_id, rf_rev_no=None):
    """Tek tam formül için RF/Boya toplam kg."""
    if rf_renk_id in (None, ''):
        return 0.0
    try:
        rf_id = int(rf_renk_id)
    except (TypeError, ValueError):
        return 0.0

    revizyon_sonuc = _rf_revizyon_pigmentleri_getir(con, rf_id, rf_rev_no)
    if revizyon_sonuc.get('ok') and revizyon_sonuc.get('pigmentler'):
        return round(
            sum(float(p.get('miktar_kg') or 0) for p in revizyon_sonuc['pigmentler']),
            3,
        )

    row = con.execute("""
        SELECT COALESCE(SUM(miktar_kg), 0) AS toplam
        FROM nexgen_rf_kalem
        WHERE rf_renk_id = ? AND aktif = 1
    """, (rf_id,)).fetchone()
    return round(float(row['toplam']), 3) if row else 0.0


def _tam_formul_kg_hesapla(con, uretim_varyant_id, rf_renk_id=None, rf_rev_no=None):
    """Tam formül kg = Ana reçete + RF/Boya (tek batch)."""
    ana = _ana_recete_kg_hesapla(con, uretim_varyant_id)
    boya = _rf_boya_kg_birim_hesapla(con, rf_renk_id, rf_rev_no)
    return round(ana + boya, 3)


def _formul_batch_kg_hesapla(con, uretim_varyant_id, rf_renk_id=None, rf_rev_no=None):
    """Tam formül batch kg — geriye uyumluluk alias."""
    return _tam_formul_kg_hesapla(con, uretim_varyant_id, rf_renk_id, rf_rev_no)


def _batch_uretim_hesapla(con, uretim_varyant_id, siparis_kg, rf_renk_id=None, rf_rev_no=None):
    """Talep KG → tam formül adedi (ceil) ve üretilecek KG.

    tam_formul_kg = ana_recete_kg + rf_boya_kg
    formul_adedi   = ceil(talep_kg / tam_formul_kg)
    uretilecek_kg  = formul_adedi × tam_formul_kg
    fazla_kg       = uretilecek_kg − talep_kg
    """
    import math
    try:
        siparis_kg = float(siparis_kg)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'Geçersiz siparis_kg'}
    if siparis_kg <= 0:
        return {'ok': False, 'hata': 'siparis_kg sıfırdan büyük olmalı'}

    ana_recete_kg = _ana_recete_kg_hesapla(con, uretim_varyant_id)
    if ana_recete_kg <= 0:
        return {
            'ok': False,
            'hata': 'Ana reçete KG bulunamadı (aktif kalem yok).',
            'ana_recete_kg': 0.0,
            'rf_boya_kg': 0.0,
            'tam_formul_kg': 0.0,
            'formul_batch_kg': 0.0,
            'formul_adedi': 0,
            'batch_sayisi': 0,
            'siparis_kg': round(siparis_kg, 3),
            'talep_kg': round(siparis_kg, 3),
            'uretilecek_kg': 0.0,
            'fazla_kg': 0.0,
        }

    rf_boya_kg = _rf_boya_kg_birim_hesapla(con, rf_renk_id, rf_rev_no)
    tam_formul_kg = round(ana_recete_kg + rf_boya_kg, 3)
    if tam_formul_kg <= 0:
        return {
            'ok': False,
            'hata': 'Tam formül KG hesaplanamadı.',
            'ana_recete_kg': ana_recete_kg,
            'rf_boya_kg': rf_boya_kg,
            'tam_formul_kg': 0.0,
            'formul_batch_kg': 0.0,
            'formul_adedi': 0,
            'batch_sayisi': 0,
            'siparis_kg': round(siparis_kg, 3),
            'talep_kg': round(siparis_kg, 3),
            'uretilecek_kg': 0.0,
            'fazla_kg': 0.0,
        }

    formul_adedi = int(math.ceil(siparis_kg / tam_formul_kg))
    uretilecek_kg = round(formul_adedi * tam_formul_kg, 3)
    fazla_kg = round(uretilecek_kg - siparis_kg, 3)
    return {
        'ok': True,
        'ana_recete_kg': ana_recete_kg,
        'rf_boya_kg': rf_boya_kg,
        'tam_formul_kg': tam_formul_kg,
        'formul_batch_kg': tam_formul_kg,
        'formul_adedi': formul_adedi,
        'batch_sayisi': formul_adedi,
        'siparis_kg': round(siparis_kg, 3),
        'talep_kg': round(siparis_kg, 3),
        'uretilecek_kg': uretilecek_kg,
        'fazla_kg': fazla_kg,
    }


_PARCA_BOYUT_UV_MARKER = '__BOYUT_UV__'


def _parca_boyut_uv_notlar(boyut, uretim_varyant_id):
    """Parça notlarında boyut/UV meta (migration gerektirmez)."""
    if not boyut or not uretim_varyant_id:
        return None
    return f"{_PARCA_BOYUT_UV_MARKER}|{(boyut or '').strip().upper()}|{int(uretim_varyant_id)}"


def _parca_boyut_uv_parse(notlar):
    """Parça notlarından boyut + uretim_varyant_id okur."""
    if not notlar or _PARCA_BOYUT_UV_MARKER not in (notlar or ''):
        return None, None
    for line in (notlar or '').split('\n'):
        if not line.startswith(_PARCA_BOYUT_UV_MARKER + '|'):
            continue
        parts = line.split('|')
        if len(parts) >= 3:
            try:
                return parts[1], int(parts[2])
            except (TypeError, ValueError):
                return parts[1], None
    return None, None


def _parca_effective_uv_id(parca_notlar, batch_uv_id):
    """Batch UV yerine parça boyut UV'si (çok boyutlu plan)."""
    _, uv_id = _parca_boyut_uv_parse(parca_notlar)
    return uv_id if uv_id else batch_uv_id


def _mpr_plan_uretim_parcalari_hesapla(con, plan_id, rf_renk_id=None, rf_rev_no=None):
    """Plan → üretim parça satırları (boyut bazlı veya legacy tek varyant)."""
    plan_col_list = [c[1] for c in con.execute(
        "PRAGMA table_info(nexgen_uretim_plan)"
    ).fetchall()]
    rev_sql = ", rf_rev_no" if "rf_rev_no" in plan_col_list else ", NULL AS rf_rev_no"
    plan = con.execute(
        f"SELECT id, uretim_varyant_id, planlanan_kg, rf_renk_id{rev_sql} "
        "FROM nexgen_uretim_plan WHERE id=?",
        (plan_id,),
    ).fetchone()
    if not plan:
        raise ValueError('Plan bulunamadı')
    if rf_renk_id is None:
        rf_renk_id = plan['rf_renk_id']
    if rf_rev_no is None and 'rf_rev_no' in plan.keys():
        rf_rev_no = plan['rf_rev_no']

    boyut_satirlari = _plan_boyut_parcalari_list(con, plan_id)
    kaynak = []

    if not boyut_satirlari:
        uv_id = plan['uretim_varyant_id']
        if not uv_id:
            raise ValueError('Plan varyant bilgisi yok')
        try:
            siparis_kg = float(plan['planlanan_kg'] or 0)
        except (TypeError, ValueError):
            siparis_kg = 0.0
        if siparis_kg <= 0:
            raise ValueError('planlanan_kg sıfırdan büyük olmalı')
        kaynak.append((None, uv_id, siparis_kg))
    else:
        for bp in boyut_satirlari:
            uv_id = bp.get('uretim_varyant_id')
            siparis_kg = float(bp.get('siparis_kg') or 0)
            if not uv_id or siparis_kg <= 0:
                continue
            kaynak.append((bp.get('boyut'), uv_id, siparis_kg))
        if not kaynak:
            raise ValueError('Aktif boyut satırı yok')

    satirlar = []
    for boyut, uv_id, siparis_kg in kaynak:
        batch = _batch_uretim_hesapla(
            con, uv_id, siparis_kg,
            rf_renk_id=rf_renk_id, rf_rev_no=rf_rev_no,
        )
        if not batch.get('ok'):
            raise ValueError(batch.get('hata', 'Batch hesaplanamadı'))
        if batch.get('batch_sayisi', 0) <= 0 or batch.get('formul_batch_kg', 0) <= 0:
            raise ValueError(f'Boyut {boyut or "?"} için formül batch KG hesaplanamadı')
        satirlar.append({
            'boyut': boyut,
            'uretim_varyant_id': uv_id,
            'siparis_kg': round(siparis_kg, 3),
            'formul_batch_kg': round(float(batch['formul_batch_kg']), 3),
            'parca_sayisi': int(batch['batch_sayisi']),
            'uretilecek_kg': round(float(batch['uretilecek_kg']), 3),
        })
    return satirlar


def _pzm_siparis_tamamlandi_sync(con, plan_id):
    """Plan BITTI sonrası — tüm planlar bittiyse siparişi TAMAMLANDI yap."""
    if not plan_id or not _plan_planlama_siparis_kolonu_var(con):
        return {'ok': True, 'atlandi': True}
    if not _planlama_siparis_tablosu_var(con):
        return {'ok': True, 'atlandi': True}
    row = con.execute(
        "SELECT planlama_siparis_id FROM nexgen_uretim_plan WHERE id=?",
        (plan_id,),
    ).fetchone()
    if not row or not row['planlama_siparis_id']:
        return {'ok': True, 'atlandi': True}
    ps_id = row['planlama_siparis_id']
    acik = con.execute("""
        SELECT COUNT(*) AS c FROM nexgen_uretim_plan
        WHERE planlama_siparis_id=? AND durum NOT IN ('BITTI','IPTAL')
    """, (ps_id,)).fetchone()
    if acik and int(acik['c'] or 0) > 0:
        return {'ok': True, 'atlandi': True, 'acik_plan_sayisi': int(acik['c'])}
    con.execute("""
        UPDATE nexgen_planlama_siparis
        SET durum='TAMAMLANDI',
            guncelleme_tarihi=datetime('now','localtime')
        WHERE id=? AND durum NOT IN ('IPTAL','TAMAMLANDI')
    """, (ps_id,))
    return {'ok': True, 'siparis_id': ps_id, 'durum': 'TAMAMLANDI'}


def _plan_boyut_tablosu_var(con):
    return con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_uretim_plan_boyut'"
    ).fetchone() is not None


def _plan_boyut_parcalari_list(con, plan_id):
    """Planın aktif boyut kırılımlarını UI listesi için döner."""
    if not _plan_boyut_tablosu_var(con):
        return []
    rows = con.execute("""
        SELECT boyut, siparis_kg, uretim_varyant_id
        FROM nexgen_uretim_plan_boyut
        WHERE plan_id=? AND aktif=1 AND siparis_kg > 0
        ORDER BY sira, id
    """, (plan_id,)).fetchall()
    return [
        {
            'boyut': r['boyut'],
            'siparis_kg': float(r['siparis_kg']),
            'kg': float(r['siparis_kg']),
            'uretim_varyant_id': r['uretim_varyant_id'],
        }
        for r in rows
    ]


def _plan_boyut_sira(boyut):
    b = (boyut or '').upper()
    if b == 'LARGE':
        return 1
    if b == 'SMALL':
        return 2
    if b == 'STANDART':
        return 3
    return 9


def _plan_boyut_satir_ensure(con, plan_id, uretim_varyant_id, planlanan_kg, boyut,
                             rf_renk_id=None, rf_rev_no=None):
    """FAZ-BOYUT-1: Plan için boyut satırı yoksa ekler (idempotent, aynı transaction)."""
    if not _plan_boyut_tablosu_var(con):
        return False
    mevcut = con.execute(
        "SELECT id FROM nexgen_uretim_plan_boyut "
        "WHERE plan_id=? AND uretim_varyant_id=?",
        (plan_id, uretim_varyant_id),
    ).fetchone()
    if mevcut:
        return False

    boyut_norm = (boyut or 'STANDART').upper()
    if boyut_norm == 'MEDIUM':
        boyut_norm = 'STANDART'

    siparis_kg = round(float(planlanan_kg or 0), 3)
    bh = _batch_uretim_hesapla(
        con, uretim_varyant_id, siparis_kg, rf_renk_id=rf_renk_id, rf_rev_no=rf_rev_no,
    )
    if bh.get('ok'):
        fb = bh['tam_formul_kg']
        batch_sayisi = bh['batch_sayisi']
        uretilecek_kg = bh['uretilecek_kg']
        fazla_kg = bh['fazla_kg']
    else:
        fb = _tam_formul_kg_hesapla(con, uretim_varyant_id, rf_renk_id, rf_rev_no)
        batch_sayisi = 0
        uretilecek_kg = 0.0
        fazla_kg = 0.0

    now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    con.execute("""
        INSERT INTO nexgen_uretim_plan_boyut (
            plan_id, uretim_varyant_id, boyut, siparis_kg,
            formul_batch_kg, batch_sayisi, uretilecek_kg, fazla_kg,
            sira, aktif, olusturma_tarihi, guncelleme_tarihi
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
    """, (
        plan_id, uretim_varyant_id, boyut_norm, siparis_kg,
        fb, batch_sayisi, uretilecek_kg, fazla_kg,
        _plan_boyut_sira(boyut_norm), now, now,
    ))
    return True


def _boyut_kg_parse(raw):
    """boyut_kg dict → {LARGE|SMALL|STANDART: kg} (kg>0)."""
    if not raw or not isinstance(raw, dict):
        return {}
    key_map = {
        'LARGE': 'LARGE', 'L': 'LARGE',
        'SMALL': 'SMALL', 'S': 'SMALL',
        'STANDART': 'STANDART', 'MEDIUM': 'STANDART', 'M': 'STANDART',
    }
    out = {}
    for k, v in raw.items():
        bk = key_map.get((str(k or '')).upper())
        if not bk:
            continue
        try:
            fv = round(float(v or 0), 3)
        except (TypeError, ValueError):
            continue
        if fv > 0:
            out[bk] = round(out.get(bk, 0.0) + fv, 3)
    return out


def _renk_varyant_uv_haritasi(con, renk_varyant_id):
    """renk_varyant_id → boyut → uretim_varyant_id."""
    rows = con.execute("""
        SELECT id, boyut FROM nexgen_uretim_varyant
        WHERE renk_varyant_id=? AND aktif=1 AND recete_durum='URETIME_ACIK'
    """, (renk_varyant_id,)).fetchall()
    out = {}
    for r in rows:
        b = (r['boyut'] or '').upper()
        if b == 'MEDIUM':
            b = 'STANDART'
        out[b] = r['id']
    return out


def _mpr_header_uv_boyut(boyut_kg_map, uv_map):
    """Header legacy uv_id: öncelik LARGE → SMALL → STANDART."""
    for b in ('LARGE', 'SMALL', 'STANDART'):
        if boyut_kg_map.get(b, 0) > 0 and uv_map.get(b):
            return uv_map[b], b
    return None, None


def _rf_renk_formul_dogrula(con, rf_renk_id, renk_varyant_id):
    """RF'nin seçili formüle aktif uygunluk + dolu üretim kodu ile bağlı olduğunu doğrular."""
    rv = con.execute("""
        SELECT rv.id, rv.formul_id, f.kod AS formul_kod
        FROM nexgen_renk_varyant rv
        JOIN nexgen_formul f ON f.id = rv.formul_id
        WHERE rv.id = ?
    """, (renk_varyant_id,)).fetchone()
    if not rv:
        return None

    rf = con.execute("""
        SELECT rf.id, rf.rf_kod, rf.ad, rf.cari_id, rf.aktif, rf.durum,
               rf.kaynak_arge_test_id
        FROM nexgen_rf_renk rf
        WHERE rf.id = ?
          AND rf.durum = 'ONAYLI' AND rf.aktif = 1
    """, (rf_renk_id,)).fetchone()
    if not rf or not yeni_secimde_renk_gosterilebilir_mi(dict(rf)):
        return None

    if cekirdek_formul_mu(rv['formul_kod']):
        uygun = con.execute("""
            SELECT id FROM nexgen_rf_formul_uygunluk
            WHERE rf_renk_id=? AND formul_id=? AND aktif=1
        """, (rf_renk_id, rv['formul_id'])).fetchone()
        if not uygun:
            return None
        if not _uretim_kodu_db_dolu_mi(con, rf_renk_id, rv['formul_id']):
            return None
    return rf


# ─────────────────────────────────────────────────────────────
# FAZ-BOYA-RECETESI-02C: Revizyon Pigment Okuma
# ─────────────────────────────────────────────────────────────

def _rf_revizyon_pigmentleri_getir(con, rf_renk_id, rf_rev_no):
    """Belirtilen revizyon numarasinin dogrulanmis pigment listesini doner.

    Donus:
      {
        'ok': True/False,
        'pigmentler': [...],           # dogrulanmis pigment satirlari
        'kaynak': 'REVIZYON_SNAPSHOT' | 'LEGACY_CANLI',
        'legacy_fallback': True/False,
        'rev_no': kullanilan_rev_no,
        'uyari': None | 'aciklama',    # bilgi amacli
        'hata': None | 'aciklama',     # hata oldugunda
      }

    Revizyon bulunamazsa sessizce aktif revizyona gecmez — hata uretir.
    rf_rev_no=None ise kontrollü legacy fallback yapar (geri uyumluluk).
    """
    if not _rf_revizyon_tablosu_var(con):
        return {
            'ok': True, 'pigmentler': [], 'kaynak': 'LEGACY_CANLI',
            'legacy_fallback': True, 'rev_no': None,
            'uyari': 'nexgen_rf_revizyon tablosu yok (Migration 098 calistirilmamis).',
        }

    try:
        rf_renk_id = int(rf_renk_id)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'rf_renk_id gecersiz.', 'kaynak': None}

    # ── Legacy fallback: rf_rev_no belirtilmemis ─────────────────────
    if rf_rev_no is None:
        aktif_rev = con.execute(
            "SELECT aktif_rev_no FROM nexgen_rf_renk WHERE id=? AND aktif=1",
            (rf_renk_id,)
        ).fetchone()
        aktif_no = aktif_rev['aktif_rev_no'] if aktif_rev else 0
        return {
            'ok': True, 'pigmentler': [], 'kaynak': 'LEGACY_CANLI',
            'legacy_fallback': True, 'rev_no': None,
            'uyari': (
                f"Bu kayit icin rf_rev_no belirlenmemis. "
                f"Aktif revizyon: REV-{aktif_no}. "
                f"Hesaplama aktif nexgen_rf_kalem listesinden yapiliyor (eski plan uyumlulugu)."
            ),
        }

    # ── Revizyonu bul ────────────────────────────────────────────────
    try:
        rf_rev_no = int(rf_rev_no)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'rf_rev_no gecersiz.', 'kaynak': None}

    rev = con.execute("""
        SELECT id, rf_renk_id, rev_no, durum, kilitli_mi, aktif, pigmentler_json
        FROM nexgen_rf_revizyon
        WHERE rf_renk_id = ? AND rev_no = ? AND aktif = 1
    """, (rf_renk_id, rf_rev_no)).fetchone()

    if not rev:
        return {
            'ok': False,
            'hata': f"Boya Recetesi REV-{rf_rev_no} bulunamadi veya pasif.",
            'kaynak': None,
        }

    if rev['durum'] != 'ONAYLANDI':
        return {
            'ok': False,
            'hata': (
                f"Boya Recetesi REV-{rf_rev_no} durumu '{rev['durum']}' — "
                f"Sadece ONAYLANDI revizyon MRP'de kullanilabilir."
            ),
            'kaynak': None,
        }

    if not rev['kilitli_mi']:
        return {
            'ok': False,
            'hata': f"Boya Recetesi REV-{rf_rev_no} kilitli degil — MRP'de kullanilamaz.",
            'kaynak': None,
        }

    # ── JSON parse ve dogrulama ──────────────────────────────────────
    try:
        raw_pigmentler = json.loads(rev['pigmentler_json'] or '[]')
    except (ValueError, TypeError):
        return {
            'ok': False,
            'hata': f"Boya Recetesi REV-{rf_rev_no} pigment kaydi dogrulanamadi (bozuk JSON).",
            'kaynak': None,
        }

    if not raw_pigmentler:
        return {
            'ok': False,
            'hata': f"Boya Recetesi REV-{rf_rev_no} pigment listesi bos.",
            'kaynak': None,
        }

    # Her pigmenti dogrula
    gorulmus_stok_idler = set()
    dogrulanmis = []
    for p in raw_pigmentler:
        sid = p.get('stok_kart_id')
        if not sid:
            return {
                'ok': False,
                'hata': f"Boya Recetesi REV-{rf_rev_no} pigment kaydi dogrulanamadi (stok_kart_id eksik).",
                'kaynak': None,
            }
        try:
            sid = int(sid)
            miktar = float(p.get('miktar_kg', 0))
        except (TypeError, ValueError):
            return {
                'ok': False,
                'hata': f"Boya Recetesi REV-{rf_rev_no} pigment kaydi dogrulanamadi (gecersiz deger).",
                'kaynak': None,
            }
        if miktar <= 0:
            return {
                'ok': False,
                'hata': f"Boya Recetesi REV-{rf_rev_no} sifir miktarli pigment iceriyor.",
                'kaynak': None,
            }
        if sid in gorulmus_stok_idler:
            return {
                'ok': False,
                'hata': f"Boya Recetesi REV-{rf_rev_no} duplicate pigment iceriyor (stok_kart_id={sid}).",
                'kaynak': None,
            }
        gorulmus_stok_idler.add(sid)

        stok = con.execute(
            "SELECT id, kod, ad FROM nexgen_stok_kart WHERE id=? AND aktif=1",
            (sid,)
        ).fetchone()
        dogrulanmis.append({
            'stok_kart_id':   sid,
            'stok_kart_var':  stok is not None,
            'stok_kod':       stok['kod'] if stok else '',
            'stok_ad':        stok['ad'] if stok else (p.get('pigment_ad') or ''),
            'pigment_ad':     p.get('pigment_ad') or (stok['ad'] if stok else ''),
            'miktar_kg':      miktar,
            'sira':           p.get('sira', 1),
        })

    # Aktif revizyon ile karsilastirma uyarisi
    uyari = None
    if _rf_aktif_rev_no_var(con):
        rf_row = con.execute(
            "SELECT aktif_rev_no FROM nexgen_rf_renk WHERE id=?", (rf_renk_id,)
        ).fetchone()
        aktif_no = rf_row['aktif_rev_no'] if rf_row else 0
        if aktif_no and aktif_no != rf_rev_no:
            uyari = (
                f"Bu plan REV-{rf_rev_no} ile olusturuldu. "
                f"Guncel Boya Recetesi REV-{aktif_no}'dir. "
                f"Hesaplama REV-{rf_rev_no} uzerinden yapilmaktadir."
            )

    return {
        'ok': True,
        'pigmentler': dogrulanmis,
        'kaynak': 'REVIZYON_SNAPSHOT',
        'legacy_fallback': False,
        'rev_no': rf_rev_no,
        'uyari': uyari,
        'hata': None,
    }


def _mpr_stok_ihtiyac_hesapla(con, uretim_varyant_id, rf_renk_id, planlanan_kg,
                              exclude_batch_kodu=None, rf_rev_no=None):
    """MPR stok ihtiyacı önizleme — taban hammadde (BOYA hariç) + RF boya.

    Batch sayısı tam formül kg (ana reçete + RF/Boya) ile hesaplanır.
    Stok kalemlerinde taban reçetedeki BOYA dahil edilmez; RF varsa boya ihtiyacı RF'den gelir
    (çift boya sayımı önlenir).

    Stok hareketi YAZMAZ.
    Yeterlilik: kullanilabilir_kg (fiziksel − aktif rezerv − yumuşak talep).
    exclude_batch_kodu: kendi batch rezerv/talep hariç (üretim tüketimi).
    """
    try:
        planlanan_kg = float(planlanan_kg)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'Geçersiz planlanan_kg'}
    if planlanan_kg <= 0:
        return {'ok': False, 'hata': 'planlanan_kg sıfırdan büyük olmalı'}

    batch = _batch_uretim_hesapla(
        con, uretim_varyant_id, planlanan_kg, rf_renk_id=rf_renk_id, rf_rev_no=rf_rev_no,
    )
    if not batch.get('ok'):
        return {
            'ok': False,
            'hata': batch.get('hata', 'Batch hesaplanamadı'),
            'taban_batch_kg': batch.get('tam_formul_kg', batch.get('formul_batch_kg', 0.0)),
        }

    tam_formul_kg = batch['tam_formul_kg']
    ana_recete_kg = batch['ana_recete_kg']
    rf_boya_kg = batch['rf_boya_kg']
    taban_batch_kg = tam_formul_kg
    siparis_kg = batch['siparis_kg']
    uretilecek_kg = batch['uretilecek_kg']
    batch_sayisi = batch['batch_sayisi']
    fazla_kg = batch['fazla_kg']
    carpan = float(batch_sayisi)
    satirlar = []

    # FAZ-3I-1: UV detay debug bilgisi
    uv_meta = con.execute("""
        SELECT uv.id, uv.boyut, uv.recete_durum, uv.renk_varyant_id,
               rv.ad AS rv_ad, f.kod AS formul_kod
        FROM nexgen_uretim_varyant uv
        JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
        JOIN nexgen_formul f        ON f.id  = rv.formul_id
        WHERE uv.id = ?
    """, (uretim_varyant_id,)).fetchone()

    taban_rows = con.execute("""
        SELECT rk.stok_kart_id, rk.miktar_kg,
               sk.kod AS stok_kod, sk.ad AS stok_ad
        FROM nexgen_recete_kalem rk
        JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
          AND UPPER(COALESCE(sk.kategori, '')) != 'BOYA'
        ORDER BY rk.sira, rk.id
    """, (uretim_varyant_id,)).fetchall()

    for row in taban_rows:
        gerekli = round(float(row['miktar_kg']) * carpan, 3)
        if gerekli <= 0:
            continue
        satirlar.append({
            'kaynak': 'TABAN',
            'stok_kart_id': row['stok_kart_id'],
            'stok_kod': row['stok_kod'] or '',
            'stok_ad': row['stok_ad'] or '',
            'gerekli_kg': gerekli,
        })

    rf_id = None
    if rf_renk_id not in (None, ''):
        try:
            rf_id = int(rf_renk_id)
        except (TypeError, ValueError):
            pass

    rf_debug_kalemler = []  # FAZ-3I-1: tüm RF kalemleri (sıfır dahil)
    rf_rev_kaynak = None
    rf_rev_no_kullanilan = None
    rf_rev_uyari = None

    if rf_id:
        # FAZ-BOYA-RECETESI-02C: Revizyon snapshot kullan (rf_rev_no verilmisse)
        revizyon_sonuc = _rf_revizyon_pigmentleri_getir(con, rf_id, rf_rev_no)
        rf_rev_kaynak = revizyon_sonuc.get('kaynak')
        rf_rev_no_kullanilan = revizyon_sonuc.get('rev_no')
        rf_rev_uyari = revizyon_sonuc.get('uyari')

        if revizyon_sonuc.get('kaynak') == 'REVIZYON_SNAPSHOT' and revizyon_sonuc.get('ok'):
            # Snapshot'tan pigment listesi
            for p in revizyon_sonuc['pigmentler']:
                gerekli = round(float(p['miktar_kg']) * carpan, 6)
                stok_kart_id = p['stok_kart_id']
                ad = p['stok_ad'] or p['pigment_ad'] or ''
                rf_debug_kalemler.append({
                    'stok_kod': p['stok_kod'] or '',
                    'stok_ad': ad,
                    'miktar_kg_birim': float(p['miktar_kg']),
                    'gerekli_kg': gerekli,
                    'sifir': gerekli <= 0,
                    'kaynak': 'REVIZYON_SNAPSHOT',
                })
                if gerekli <= 0:
                    continue
                satirlar.append({
                    'kaynak': 'RF',
                    'stok_kart_id': stok_kart_id,
                    'stok_kod': p['stok_kod'] or '',
                    'stok_ad': ad,
                    'pigment_ad': p['pigment_ad'] or ad,
                    'stok_eslesmis': stok_kart_id is not None and p['stok_kart_var'],
                    'gerekli_kg': gerekli,
                })
        elif revizyon_sonuc.get('kaynak') == 'LEGACY_CANLI':
            # rf_rev_no=None — eski plan uyumlulugu, aktif nexgen_rf_kalem kullan
            rf_rows = con.execute("""
                SELECT rk.stok_kart_id, rk.miktar_kg,
                       rk.pigment_ad,
                       sk.kod AS stok_kod, sk.ad AS stok_ad
                FROM nexgen_rf_kalem rk
                LEFT JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
                WHERE rk.rf_renk_id = ? AND rk.aktif = 1
                ORDER BY rk.sira, rk.id
            """, (rf_id,)).fetchall()
            for row in rf_rows:
                # FAZ-3I-5B: round(6) — küçük pigment miktarları sıfıra yuvarlanmasın
                gerekli = round(float(row['miktar_kg']) * carpan, 6)
                stok_kart_id = row['stok_kart_id']
                pigment_ad = None
                try:
                    pigment_ad = row['pigment_ad']
                except (IndexError, KeyError):
                    pass
                ad = row['stok_ad'] or pigment_ad or ''
                rf_debug_kalemler.append({
                    'stok_kod': row['stok_kod'] or '',
                    'stok_ad': ad,
                    'miktar_kg_birim': float(row['miktar_kg']),
                    'gerekli_kg': gerekli,
                    'sifir': gerekli <= 0,
                    'kaynak': 'LEGACY_CANLI',
                })
                if gerekli <= 0:
                    continue
                satirlar.append({
                    'kaynak': 'RF',
                    'stok_kart_id': stok_kart_id,
                    'stok_kod': row['stok_kod'] or '',
                    'stok_ad': ad,
                    'pigment_ad': pigment_ad or ad,
                    'stok_eslesmis': stok_kart_id is not None,
                    'gerekli_kg': gerekli,
                })
        # revizyon_sonuc['ok']=False durumunda: pigment satirlari eklenmez,
        # debug_info'ya hata yazilir; MRP taban hesabi bozulmaz.

    # Stok talep toplamı — NULL stok_kart_id olanlar atlanır (stok kontrolü yapılamaz)
    talep = {}
    for s in satirlar:
        sid = s['stok_kart_id']
        if sid is None:
            continue
        talep[sid] = round(talep.get(sid, 0.0) + s['gerekli_kg'], 3)

    stok_cache = {}
    for sid in talep:
        fiziksel = _mevcut_stok(con, sid)
        rezerve = _aktif_rezerv_toplam(con, sid, exclude_batch_kodu)
        yumusak = _yumusak_talep_toplam(con, sid, exclude_batch_kodu)
        kullanilabilir = round(fiziksel - rezerve - yumusak, 3)
        # FAZ-MRP-01: Açık SA arz bilgisini de çek (üretime başlama kontrolünü bozmaz)
        acik_sa = _acik_satin_alma_arzi(con, sid)
        stok_cache[sid] = {
            'fiziksel_kg': fiziksel,
            'rezerve_kg': rezerve,
            'yumusak_talep_kg': yumusak,
            'kullanilabilir_kg': kullanilabilir,
            'yolda_kg': acik_sa['yolda_kg'],
            'acik_sa_siparisler': acik_sa['siparisler'],
        }

    eksik_stok_ids = {
        sid for sid, gerekli in talep.items()
        if stok_cache[sid]['kullanilabilir_kg'] < gerekli - 0.0005
    }

    kalemler = []
    for s in satirlar:
        sid = s['stok_kart_id']
        stok_eslesmis = s.get('stok_eslesmis', True)
        if sid is None or not stok_eslesmis:
            # NULL stok kartı — stok kontrolü yapılamaz, uyarı olarak eklenir
            kalemler.append({
                'kaynak': s['kaynak'],
                'stok_kart_id': None,
                'stok_kod': '',
                'stok_ad': s.get('pigment_ad') or s.get('stok_ad') or '?',
                'pigment_ad': s.get('pigment_ad') or s.get('stok_ad') or '?',
                'stok_eslesmis': False,
                'gerekli_kg': s['gerekli_kg'],
                'fiziksel_kg': 0.0,
                'rezerve_kg': 0.0,
                'yumusak_talep_kg': 0.0,
                'kullanilabilir_kg': 0.0,
                'mevcut_kg': 0.0,
                'fark_kg': -s['gerekli_kg'],
                'yeterli': False,
                'yolda_kg': 0.0,
                'fiziksel_eksik_kg': s['gerekli_kg'],
                'net_eksik_kg': s['gerekli_kg'],
                'malzeme_durumu': 'EKSİK',
                'tahmini_hazir': None,
                'termin_riski': False,
                'acik_sa_siparisler': [],
            })
            eksik_stok_ids.add(None)
            continue
        toplam_gerekli = talep[sid]
        sc = stok_cache[sid]
        fiziksel_eksik = round(max(toplam_gerekli - sc['kullanilabilir_kg'], 0.0), 3)
        yolda_kg = sc['yolda_kg']
        net_eksik = round(max(fiziksel_eksik - yolda_kg, 0.0), 3)
        # FAZ-MRP-01: tahmini hazır tarih
        th = _tahmini_hazir_tarih(
            toplam_gerekli, sc['kullanilabilir_kg'], {'siparisler': sc['acik_sa_siparisler']}
        )
        durum = _mpr_malzeme_durumu(
            toplam_gerekli, sc['kullanilabilir_kg'], yolda_kg,
            fiziksel_eksik, net_eksik
        )
        kalemler.append({
            'kaynak': s['kaynak'],
            'stok_kart_id': sid,
            'stok_kod': s['stok_kod'],
            'stok_ad': s['stok_ad'],
            'pigment_ad': s.get('pigment_ad') or s['stok_ad'],
            'stok_eslesmis': True,
            'gerekli_kg': s['gerekli_kg'],
            'fiziksel_kg': sc['fiziksel_kg'],
            'rezerve_kg': sc['rezerve_kg'],
            'yumusak_talep_kg': sc['yumusak_talep_kg'],
            'kullanilabilir_kg': sc['kullanilabilir_kg'],
            'mevcut_kg': sc['fiziksel_kg'],
            'fark_kg': round(sc['kullanilabilir_kg'] - toplam_gerekli, 3),
            'yeterli': sid not in eksik_stok_ids,
            # FAZ-MRP-01 ek alanlar (PDF A2, A3, A5)
            'yolda_kg': yolda_kg,
            'fiziksel_eksik_kg': fiziksel_eksik,
            'net_eksik_kg': net_eksik,
            'malzeme_durumu': durum,
            'tahmini_hazir': th['tarih'],
            'termin_riski': th['termin_riski'],
            'tahmini_aciklama': th['aciklama'],
            'acik_sa_siparisler': sc['acik_sa_siparisler'],
        })

    # FAZ-3I-1/2: debug_info — UV kimliği, batch detayı, RF kalem özeti
    _boyut_val = uv_meta['boyut'] if uv_meta else None
    debug_info = {
        'uv_id':         uretim_varyant_id,
        'rv_id':         uv_meta['renk_varyant_id'] if uv_meta else None,
        'rv_ad':         uv_meta['rv_ad']            if uv_meta else None,
        'formul_kod':    uv_meta['formul_kod']       if uv_meta else None,
        'boyut':         _boyut_val,
        'recete_durum':  uv_meta['recete_durum']     if uv_meta else None,
        'batch_kg':      tam_formul_kg,
        'tam_formul_kg': tam_formul_kg,
        'ana_recete_kg': ana_recete_kg,
        'rf_boya_kg':    rf_boya_kg,
        'batch_sayisi':  batch_sayisi,
        'siparis_kg':    siparis_kg,
        'uretilecek_kg': uretilecek_kg,
        'carpan':        carpan,
        'kalem_say':     len(taban_rows),
        'rf_id':         rf_id,
        'rf_renk_id':    rf_id,
        'rf_rev_no':          rf_rev_no_kullanilan,
        'rf_rev_kaynak':      rf_rev_kaynak,
        'rf_rev_uyari':       rf_rev_uyari,
        'rf_kalem_say':  len(rf_debug_kalemler),
        'rf_sifir_say':  sum(1 for k in rf_debug_kalemler if k['sifir']),
        'rf_kalemler':   rf_debug_kalemler,
        # FAZ-3I-2: tekli UV için de boyutlar array — JS tek kod yolu
        'boyutlar': [{
            'boyut':        _boyut_val,
            'uv_id':        uretim_varyant_id,
            'rv_id':        uv_meta['renk_varyant_id'] if uv_meta else None,
            'formul_kod':   uv_meta['formul_kod']       if uv_meta else None,
            'recete_durum': uv_meta['recete_durum']     if uv_meta else None,
            'batch_kg':     tam_formul_kg,
            'tam_formul_kg': tam_formul_kg,
            'ana_recete_kg': ana_recete_kg,
            'rf_boya_kg':    rf_boya_kg,
            'siparis_kg':   siparis_kg,
            'batch_sayisi': batch_sayisi,
            'uretilecek_kg': uretilecek_kg,
            'carpan':       carpan,
            'kalem_say':    len(taban_rows),
        }],
    }

    return {
        'ok': True,
        'yeterli_mi': len(eksik_stok_ids) == 0,
        'eksik_sayisi': len(eksik_stok_ids),
        'taban_batch_kg': taban_batch_kg,
        'formul_batch_kg': tam_formul_kg,
        'tam_formul_kg': tam_formul_kg,
        'ana_recete_kg': ana_recete_kg,
        'rf_boya_kg': rf_boya_kg,
        'formul_adedi': batch_sayisi,
        'batch_sayisi': batch_sayisi,
        'talep_kg': siparis_kg,
        'siparis_kg': siparis_kg,
        'uretilecek_kg': uretilecek_kg,
        'fazla_kg': fazla_kg,
        'planlanan_kg': siparis_kg,
        'kalemler': kalemler,
        'debug_info': debug_info,
        # FAZ-BOYA-RECETESI-02C: revizyon meta
        'rf_renk_id':       rf_id,
        'rf_rev_no':        rf_rev_no_kullanilan,
        'rf_rev_kaynak':    rf_rev_kaynak,
        'rf_rev_uyari':     rf_rev_uyari,
    }


def _mpr_stok_ihtiyac_birlestir(con, plan_id, exclude_batch_kodu=None):
    """Çok boyutlu MPR stok ihtiyacı — boyut satırlarını ayrı hesaplayıp birleştirir.

    Düzeltme (KRİTİK #3 / FAZ-1):
    Tüm boyutlar için önce talep toplamı ve stok kart listesi çıkarılır,
    ardından stok bakiyeleri TEK SEFERDE sorgulanır. Her boyut için ayrı
    stok sorgusu yapılmaz — tutarsızlık ve N×M sorgu sorunu giderildi.

    Boyut satırı yoksa header üzerinden tek varyantlı eski akışa düşer.
    """
    # FAZ-BOYA-RECETESI-02C: plan kolonlarini dinamik oku
    plan_col_list = [c[1] for c in con.execute("PRAGMA table_info(nexgen_uretim_plan)").fetchall()]
    _rev_no_col = "rf_rev_no" if "rf_rev_no" in plan_col_list else "NULL"
    plan = con.execute(
        f"SELECT id, uretim_varyant_id, planlanan_kg, rf_renk_id, {_rev_no_col} AS rf_rev_no "
        "FROM nexgen_uretim_plan WHERE id=?",
        (plan_id,),
    ).fetchone()
    if not plan:
        return {'ok': False, 'hata': 'Plan bulunamadı'}

    rf_renk_id = plan['rf_renk_id']
    plan_rf_rev_no = plan['rf_rev_no']  # FAZ-02C: revizyon sabitleme
    boyut_satirlari = []
    if _plan_boyut_tablosu_var(con):
        boyut_satirlari = con.execute("""
            SELECT uretim_varyant_id, boyut, siparis_kg
            FROM nexgen_uretim_plan_boyut
            WHERE plan_id=? AND aktif=1 AND siparis_kg > 0
            ORDER BY sira, id
        """, (plan_id,)).fetchall()

    if not boyut_satirlari:
        if not plan['uretim_varyant_id']:
            return {'ok': False, 'hata': 'Plan varyant bilgisi yok'}
        try:
            planlanan_kg = float(plan['planlanan_kg'] or 0)
        except (TypeError, ValueError):
            planlanan_kg = 0.0
        if planlanan_kg <= 0:
            return {'ok': False, 'hata': 'planlanan_kg sıfırdan büyük olmalı'}
        sonuc = _mpr_stok_ihtiyac_hesapla(
            con, plan['uretim_varyant_id'], rf_renk_id, planlanan_kg,
            exclude_batch_kodu=exclude_batch_kodu,
            rf_rev_no=plan_rf_rev_no,   # FAZ-02C: revizyon snapshot
        )
        if not sonuc.get('ok'):
            return sonuc
        sonuc['plan_id'] = plan_id
        sonuc['boyut_ozetleri'] = []
        sonuc['toplam_siparis_kg'] = sonuc.get('siparis_kg', 0)
        sonuc['toplam_uretilecek_kg'] = sonuc.get('uretilecek_kg', 0)
        sonuc['toplam_fazla_kg'] = sonuc.get('fazla_kg', 0)
        sonuc['toplam_hammadde_kg'] = round(
            sum(float(k.get('gerekli_kg') or 0) for k in sonuc.get('kalemler', [])), 3
        )
        sonuc['batch_toplam'] = sonuc.get('batch_sayisi', 0)
        sonuc['cok_boyut'] = False
        return sonuc

    # ── Adım 1: Her boyut için reçete + batch hesabını yap; stok sorgusu YOK ──
    boyut_ozetleri = []
    merged_talep = {}   # stok_kart_id → toplam gerekli_kg
    stok_kart_meta = {} # stok_kart_id → {stok_kod, stok_ad, kaynak}
    toplam_siparis = 0.0
    toplam_uretilecek = 0.0
    toplam_fazla = 0.0
    batch_toplam = 0

    for row in boyut_satirlari:
        uv_id = row['uretim_varyant_id']
        try:
            siparis_kg = float(row['siparis_kg'])
        except (TypeError, ValueError):
            continue
        if siparis_kg <= 0:
            continue

        batch = _batch_uretim_hesapla(
            con, uv_id, siparis_kg, rf_renk_id=rf_renk_id, rf_rev_no=plan_rf_rev_no,
        )
        if not batch.get('ok'):
            return {'ok': False, 'hata': batch.get('hata', 'Batch hesaplanamadı')}

        carpan = float(batch['batch_sayisi'])

        # FAZ-3I-1: UV kimlik bilgilerini boyut özetine ekle
        uv_meta_b = con.execute("""
            SELECT uv.id, uv.boyut AS uv_boyut, uv.recete_durum, uv.renk_varyant_id,
                   rv.ad AS rv_ad, f.kod AS formul_kod,
                   COUNT(rk.id) AS kalem_say
            FROM nexgen_uretim_varyant uv
            JOIN nexgen_renk_varyant rv ON rv.id = uv.renk_varyant_id
            JOIN nexgen_formul f        ON f.id  = rv.formul_id
            LEFT JOIN nexgen_recete_kalem rk
                   ON rk.uretim_varyant_id = uv.id AND rk.aktif = 1
                  AND UPPER(COALESCE((SELECT kategori FROM nexgen_stok_kart WHERE id=rk.stok_kart_id),'')) != 'BOYA'
            WHERE uv.id = ?
            GROUP BY uv.id
        """, (uv_id,)).fetchone()
        boyut_ozetleri.append({
            'boyut': row['boyut'],
            'siparis_kg': batch['siparis_kg'],
            'talep_kg': batch['talep_kg'],
            'ana_recete_kg': batch['ana_recete_kg'],
            'rf_boya_kg': batch['rf_boya_kg'],
            'tam_formul_kg': batch['tam_formul_kg'],
            'formul_batch_kg': batch['tam_formul_kg'],
            'formul_adedi': batch['formul_adedi'],
            'batch_sayisi': batch['batch_sayisi'],
            'uretilecek_kg': batch['uretilecek_kg'],
            'fazla_kg': batch['fazla_kg'],
            'uv_id': uv_id,
            'rv_id': uv_meta_b['renk_varyant_id'] if uv_meta_b else None,
            'rv_ad': uv_meta_b['rv_ad']            if uv_meta_b else None,
            'formul_kod': uv_meta_b['formul_kod']  if uv_meta_b else None,
            'recete_durum': uv_meta_b['recete_durum'] if uv_meta_b else None,
            'kalem_say': uv_meta_b['kalem_say']    if uv_meta_b else 0,
            'carpan': carpan,
        })
        toplam_siparis += float(batch['siparis_kg'])
        toplam_uretilecek += float(batch['uretilecek_kg'])
        toplam_fazla += float(batch['fazla_kg'])
        batch_toplam += int(batch['batch_sayisi'])

        # Taban reçete (BOYA hariç)
        taban_rows = con.execute("""
            SELECT rk.stok_kart_id, rk.miktar_kg,
                   sk.kod AS stok_kod, sk.ad AS stok_ad
            FROM nexgen_recete_kalem rk
            JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
            WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
              AND UPPER(COALESCE(sk.kategori, '')) != 'BOYA'
            ORDER BY rk.sira, rk.id
        """, (uv_id,)).fetchall()
        for r in taban_rows:
            gerekli = round(float(r['miktar_kg']) * carpan, 3)
            if gerekli <= 0:
                continue
            sid = r['stok_kart_id']
            merged_talep[sid] = round(merged_talep.get(sid, 0.0) + gerekli, 3)
            if sid not in stok_kart_meta:
                stok_kart_meta[sid] = {
                    'stok_kod': r['stok_kod'] or '',
                    'stok_ad': r['stok_ad'] or '',
                    'kaynak': 'TABAN',
                }

        # RF boya kalemleri — FAZ-BOYA-RECETESI-02C: revizyon snapshot
        rf_id = None
        if rf_renk_id not in (None, ''):
            try:
                rf_id = int(rf_renk_id)
            except (TypeError, ValueError):
                pass
        if rf_id:
            rev_sonuc = _rf_revizyon_pigmentleri_getir(con, rf_id, plan_rf_rev_no)
            if rev_sonuc.get('kaynak') == 'REVIZYON_SNAPSHOT' and rev_sonuc.get('ok'):
                rf_pigmentler_iter = [
                    {
                        'stok_kart_id': p['stok_kart_id'],
                        'miktar_kg': p['miktar_kg'],
                        'pigment_ad': p['pigment_ad'],
                        'stok_kod': p['stok_kod'],
                        'stok_ad': p['stok_ad'],
                        'stok_eslesmis': p['stok_kart_var'],
                    }
                    for p in rev_sonuc['pigmentler']
                ]
            else:
                # Legacy fallback: aktif nexgen_rf_kalem
                _rf_rows = con.execute("""
                    SELECT rk.stok_kart_id, rk.miktar_kg,
                           rk.pigment_ad,
                           sk.kod AS stok_kod, sk.ad AS stok_ad
                    FROM nexgen_rf_kalem rk
                    LEFT JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
                    WHERE rk.rf_renk_id = ? AND rk.aktif = 1
                    ORDER BY rk.sira, rk.id
                """, (rf_id,)).fetchall()
                rf_pigmentler_iter = [
                    {
                        'stok_kart_id': r['stok_kart_id'],
                        'miktar_kg': r['miktar_kg'],
                        'pigment_ad': r['pigment_ad'] if 'pigment_ad' in r.keys() else None,
                        'stok_kod': r['stok_kod'],
                        'stok_ad': r['stok_ad'],
                        'stok_eslesmis': r['stok_kart_id'] is not None,
                    }
                    for r in _rf_rows
                ]

            for r in rf_pigmentler_iter:
                # FAZ-3I-5B: round(6) — küçük pigment miktarları sıfıra yuvarlanmasın
                gerekli = round(float(r['miktar_kg']) * carpan, 6)
                if gerekli <= 0:
                    continue
                sid = r['stok_kart_id']
                pigment_ad = r.get('pigment_ad')
                ad = r['stok_ad'] or pigment_ad or ''
                if sid is None:
                    # NULL stok kartı — stok_kart_meta'ya özel anahtar ile ekle
                    null_key = 'RF_NULL_' + ad
                    stok_kart_meta[null_key] = {
                        'stok_kod': '',
                        'stok_ad': ad,
                        'pigment_ad': pigment_ad or ad,
                        'stok_eslesmis': False,
                        'kaynak': 'RF',
                    }
                    # talep'e eklenmez — stok kontrolü yapılamaz
                    continue
                merged_talep[sid] = round(merged_talep.get(sid, 0.0) + gerekli, 6)
                if sid not in stok_kart_meta:
                    stok_kart_meta[sid] = {
                        'stok_kod': r['stok_kod'] or '',
                        'stok_ad': ad,
                        'pigment_ad': pigment_ad or ad,
                        'stok_eslesmis': True,
                        'kaynak': 'RF',
                    }

    if not merged_talep:
        return {'ok': False, 'hata': 'Reçete kalemi bulunamadı'}

    # ── Adım 2: Tüm stok kartları için bakiye TEK SEFERDE sorgulanır ──
    stok_bakiye = {}
    for sid in merged_talep:
        fiziksel = _mevcut_stok(con, sid)
        rezerve = _aktif_rezerv_toplam(con, sid, exclude_batch_kodu)
        yumusak = _yumusak_talep_toplam(con, sid, exclude_batch_kodu)
        # FAZ-MRP-01: Açık SA arz bilgisi
        acik_sa = _acik_satin_alma_arzi(con, sid)
        stok_bakiye[sid] = {
            'fiziksel_kg': fiziksel,
            'rezerve_kg': rezerve,
            'yumusak_talep_kg': yumusak,
            'kullanilabilir_kg': round(fiziksel - rezerve - yumusak, 3),
            'yolda_kg': acik_sa['yolda_kg'],
            'acik_sa_siparisler': acik_sa['siparisler'],
        }

    # ── Adım 3: Yeterlilik hesabı ──
    eksik_stok_ids = set()
    kalemler = []
    for sid, gerekli in merged_talep.items():
        meta = stok_kart_meta[sid]
        bak = stok_bakiye[sid]
        kullanilabilir = bak['kullanilabilir_kg']
        fark = round(kullanilabilir - gerekli, 3)
        if fark < -0.0005:
            eksik_stok_ids.add(sid)
        fiziksel_eksik = round(max(gerekli - kullanilabilir, 0.0), 3)
        yolda_kg = bak['yolda_kg']
        net_eksik = round(max(fiziksel_eksik - yolda_kg, 0.0), 3)
        th = _tahmini_hazir_tarih(
            gerekli, kullanilabilir, {'siparisler': bak['acik_sa_siparisler']}
        )
        durum = _mpr_malzeme_durumu(gerekli, kullanilabilir, yolda_kg, fiziksel_eksik, net_eksik)
        kalemler.append({
            'kaynak': meta['kaynak'],
            'stok_kart_id': sid,
            'stok_kod': meta['stok_kod'],
            'stok_ad': meta['stok_ad'],
            'pigment_ad': meta.get('pigment_ad') or meta['stok_ad'],
            'stok_eslesmis': meta.get('stok_eslesmis', True),
            'gerekli_kg': gerekli,
            'fiziksel_kg': bak['fiziksel_kg'],
            'rezerve_kg': bak['rezerve_kg'],
            'yumusak_talep_kg': bak['yumusak_talep_kg'],
            'kullanilabilir_kg': kullanilabilir,
            'mevcut_kg': bak['fiziksel_kg'],
            'fark_kg': fark,
            'yeterli': sid not in eksik_stok_ids,
            # FAZ-MRP-01 ek alanlar
            'yolda_kg': yolda_kg,
            'fiziksel_eksik_kg': fiziksel_eksik,
            'net_eksik_kg': net_eksik,
            'malzeme_durumu': durum,
            'tahmini_hazir': th['tarih'],
            'termin_riski': th['termin_riski'],
            'tahmini_aciklama': th['aciklama'],
            'acik_sa_siparisler': bak['acik_sa_siparisler'],
        })

    # NULL stok_kart_id'li RF kalemleri (eşleşmemiş pigmentler) ekle
    for null_key, meta in stok_kart_meta.items():
        if not isinstance(null_key, str) or not null_key.startswith('RF_NULL_'):
            continue
        eksik_stok_ids.add(null_key)
        kalemler.append({
            'kaynak': 'RF',
            'stok_kart_id': None,
            'stok_kod': '',
            'stok_ad': meta['stok_ad'],
            'pigment_ad': meta.get('pigment_ad') or meta['stok_ad'],
            'stok_eslesmis': False,
            'gerekli_kg': 0.0,
            'fiziksel_kg': 0.0,
            'rezerve_kg': 0.0,
            'yumusak_talep_kg': 0.0,
            'kullanilabilir_kg': 0.0,
            'mevcut_kg': 0.0,
            'fark_kg': 0.0,
            'yeterli': False,
            'yolda_kg': 0.0,
            'fiziksel_eksik_kg': 0.0,
            'net_eksik_kg': 0.0,
            'malzeme_durumu': 'EKSİK',
            'tahmini_hazir': None,
            'termin_riski': False,
            'tahmini_aciklama': 'EKSİK',
            'acik_sa_siparisler': [],
        })

    kalemler.sort(key=lambda x: (x.get('kaynak') or '', x.get('stok_kod') or '', x.get('stok_kart_id') or 0))
    toplam_siparis = round(toplam_siparis, 3)
    toplam_uretilecek = round(toplam_uretilecek, 3)
    toplam_fazla = round(toplam_fazla, 3)
    toplam_hammadde = round(sum(merged_talep.values()), 3)

    # FAZ-3I-1: debug_info — çok boyutlu özet
    debug_info = {
        'cok_boyut': len(boyut_ozetleri) > 1,
        'toplam_boyut': len(boyut_ozetleri),
        'rf_renk_id': rf_renk_id,
        'boyutlar': [
            {
                'boyut':          oz['boyut'],
                'uv_id':          oz['uv_id'],
                'rv_id':          oz['rv_id'],
                'rv_ad':          oz['rv_ad'],
                'formul_kod':     oz['formul_kod'],
                'recete_durum':   oz['recete_durum'],
                'batch_kg':       oz['formul_batch_kg'],
                'siparis_kg':     oz['siparis_kg'],
                'batch_sayisi':   oz['batch_sayisi'],
                'carpan':         oz['carpan'],
                'kalem_say':      oz['kalem_say'],
            }
            for oz in boyut_ozetleri
        ],
    }

    return {
        'ok': True,
        'plan_id': plan_id,
        'toplam_siparis_kg': toplam_siparis,
        'toplam_uretilecek_kg': toplam_uretilecek,
        'toplam_fazla_kg': toplam_fazla,
        'toplam_hammadde_kg': toplam_hammadde,
        'batch_toplam': batch_toplam,
        'boyut_ozetleri': boyut_ozetleri,
        'kalemler': kalemler,
        'yeterli_mi': len(eksik_stok_ids) == 0,
        'eksik_sayisi': len(eksik_stok_ids),
        'siparis_kg': toplam_siparis,
        'uretilecek_kg': toplam_uretilecek,
        'fazla_kg': toplam_fazla,
        'batch_sayisi': batch_toplam,
        'planlanan_kg': toplam_siparis,
        'cok_boyut': len(boyut_ozetleri) > 1,
        'debug_info': debug_info,
    }


def _mi_merkez_kaynak_turu(kaynak_or_set):
    """MPR kaynak kodunu merkezi ekran kaynak_turu değerine çevirir."""
    if isinstance(kaynak_or_set, str):
        srcs = {kaynak_or_set} if kaynak_or_set else set()
    else:
        srcs = set(kaynak_or_set or [])
    mapped = set()
    for s in srcs:
        if s == 'TABAN':
            mapped.add('ANA_RECETE')
        elif s == 'RF':
            mapped.add('BOYA_RECETESI')
        elif s in ('ANA_RECETE', 'BOYA_RECETESI', 'HER_IKISI'):
            mapped.add(s)
    if 'ANA_RECETE' in mapped and 'BOYA_RECETESI' in mapped:
        return 'HER_IKISI'
    if 'BOYA_RECETESI' in mapped:
        return 'BOYA_RECETESI'
    if 'ANA_RECETE' in mapped:
        return 'ANA_RECETE'
    return 'ANA_RECETE'


def _mi_merkez_plan_oku(con, plan_id):
    """Malzeme İhtiyaç Merkezi — plan meta (dinamik kolon)."""
    plan_cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_uretim_plan)").fetchall()]
    rev_sql = ", rf_rev_no" if "rf_rev_no" in plan_cols else ", NULL AS rf_rev_no"
    sip_sql = ", siparis_no" if "siparis_no" in plan_cols else ", NULL AS siparis_no"
    must_sql = ", musteri_adi" if "musteri_adi" in plan_cols else ", NULL AS musteri_adi"
    sip_id_sql = ", planlama_siparis_id AS siparis_id" if "planlama_siparis_id" in plan_cols else ", NULL AS siparis_id"
    cari_sql = ", cari_id" if "cari_id" in plan_cols else ", NULL AS cari_id"
    return con.execute(
        f"SELECT id, plan_kodu, durum, uretim_varyant_id, planlanan_kg, "
        f"rf_renk_id{rev_sql}{sip_sql}{must_sql}{sip_id_sql}{cari_sql} "
        "FROM nexgen_uretim_plan WHERE id=?",
        (plan_id,),
    ).fetchone()


def _mpr_plan_detay_trace_uret(con, plan_id, exclude_batch_kodu=None):
    """Tek plan için boyut/UV kırılımlı hammadde trace — stok düşümü yapmaz."""
    plan = _mi_merkez_plan_oku(con, plan_id)
    if not plan:
        return {'ok': False, 'hata': 'Plan bulunamadı'}

    rf_renk_id = plan['rf_renk_id']
    plan_rf_rev_no = plan['rf_rev_no']
    satirlar = []

    def _trace_satir_ekle(kalem, uretim_meta):
        sid = kalem.get('stok_kart_id')
        batch_sayisi = int(uretim_meta.get('batch_sayisi') or uretim_meta.get('formul_adedi') or 0)
        gerekli = float(kalem.get('gerekli_kg') or 0)
        bir_formulde_kg = round(gerekli / batch_sayisi, 6) if batch_sayisi > 0 else 0.0
        kaynak_raw = kalem.get('kaynak')
        satirlar.append({
            'plan_id': plan_id,
            'plan_kodu': plan['plan_kodu'],
            'siparis_id': plan['siparis_id'],
            'siparis_no': plan['siparis_no'],
            'cari_id': plan['cari_id'],
            'musteri_adi': plan['musteri_adi'],
            'boyut': uretim_meta.get('boyut'),
            'uretim_varyant_id': uretim_meta.get('uretim_varyant_id'),
            'formul_kod': uretim_meta.get('formul_kod'),
            'rv_id': uretim_meta.get('rv_id'),
            'rv_ad': uretim_meta.get('rv_ad'),
            'siparis_kg': uretim_meta.get('siparis_kg'),
            'uretilecek_kg': uretim_meta.get('uretilecek_kg'),
            'formul_adedi': uretim_meta.get('formul_adedi'),
            'batch_sayisi': batch_sayisi,
            'kaynak': kaynak_raw,
            'kaynak_turu': _mi_merkez_kaynak_turu(kaynak_raw),
            'stok_kart_id': sid,
            'stok_kod': kalem.get('stok_kod') or '',
            'stok_ad': kalem.get('stok_ad') or '',
            'pigment_ad': kalem.get('pigment_ad') or kalem.get('stok_ad') or '',
            'stok_eslesmis': kalem.get('stok_eslesmis', sid is not None),
            'bir_formulde_kg': bir_formulde_kg,
            'gerekli_kg': gerekli,
        })

    boyut_parcalari = _plan_boyut_parcalari_list(con, plan_id)
    if boyut_parcalari:
        for bp in boyut_parcalari:
            uv_id = bp.get('uretim_varyant_id')
            if not uv_id:
                return {'ok': False, 'hata': 'Boyut satırında üretim varyantı yok', 'boyut': bp.get('boyut')}
            hesap = _mpr_stok_ihtiyac_hesapla(
                con, uv_id, rf_renk_id, bp['siparis_kg'],
                exclude_batch_kodu=exclude_batch_kodu,
                rf_rev_no=plan_rf_rev_no,
            )
            if not hesap.get('ok'):
                return {
                    'ok': False,
                    'hata': hesap.get('hata', 'Hesaplanamadı'),
                    'boyut': bp.get('boyut'),
                }
            dbg = hesap.get('debug_info') or {}
            uretim_meta = {
                'boyut': bp.get('boyut') or dbg.get('boyut'),
                'uretim_varyant_id': uv_id,
                'formul_kod': dbg.get('formul_kod'),
                'rv_id': dbg.get('rv_id'),
                'rv_ad': dbg.get('rv_ad'),
                'siparis_kg': hesap.get('siparis_kg'),
                'uretilecek_kg': hesap.get('uretilecek_kg'),
                'formul_adedi': hesap.get('formul_adedi'),
                'batch_sayisi': hesap.get('batch_sayisi'),
            }
            for k in hesap.get('kalemler', []):
                _trace_satir_ekle(k, uretim_meta)
    else:
        if not plan['uretim_varyant_id']:
            return {'ok': False, 'hata': 'Plan varyant bilgisi yok'}
        try:
            planlanan_kg = float(plan['planlanan_kg'] or 0)
        except (TypeError, ValueError):
            planlanan_kg = 0.0
        if planlanan_kg <= 0:
            return {'ok': False, 'hata': 'planlanan_kg sıfırdan büyük olmalı'}
        hesap = _mpr_stok_ihtiyac_hesapla(
            con, plan['uretim_varyant_id'], rf_renk_id, planlanan_kg,
            exclude_batch_kodu=exclude_batch_kodu,
            rf_rev_no=plan_rf_rev_no,
        )
        if not hesap.get('ok'):
            return {'ok': False, 'hata': hesap.get('hata', 'Hesaplanamadı')}
        dbg = hesap.get('debug_info') or {}
        uretim_meta = {
            'boyut': dbg.get('boyut'),
            'uretim_varyant_id': plan['uretim_varyant_id'],
            'formul_kod': dbg.get('formul_kod'),
            'rv_id': dbg.get('rv_id'),
            'rv_ad': dbg.get('rv_ad'),
            'siparis_kg': hesap.get('siparis_kg'),
            'uretilecek_kg': hesap.get('uretilecek_kg'),
            'formul_adedi': hesap.get('formul_adedi'),
            'batch_sayisi': hesap.get('batch_sayisi'),
        }
        for k in hesap.get('kalemler', []):
            _trace_satir_ekle(k, uretim_meta)

    if not satirlar:
        return {'ok': False, 'hata': 'Reçete kalemi bulunamadı'}

    return {'ok': True, 'satirlar': satirlar}


def _mpr_stok_ihtiyac_coklu_plan(con, plan_ids, exclude_batch_kodu=None):
    """FAZ-MI-MERKEZ-BE-1 — Çoklu plan malzeme ihtiyacı wrapper.

    Mevcut _mpr_stok_ihtiyac_birlestir / _mpr_stok_ihtiyac_hesapla motorunu yeniden kullanır.
    Detay katmanı: plan × boyut × hammadde trace (stok düşümü yok).
    Toplu katman: stok_kart_id bazında birleşik talep + stok tek seferde uygulanır.
    """
    if plan_ids is None:
        return {'ok': False, 'hata': 'plan_ids zorunlu'}
    if not isinstance(plan_ids, (list, tuple)):
        return {'ok': False, 'hata': 'plan_ids liste olmalı'}

    uniq_ids = []
    seen = set()
    for raw in plan_ids:
        try:
            pid = int(raw)
        except (TypeError, ValueError):
            return {'ok': False, 'hata': f'Geçersiz plan_id: {raw!r}'}
        if pid <= 0:
            return {'ok': False, 'hata': f'Geçersiz plan_id: {pid}'}
        if pid not in seen:
            seen.add(pid)
            uniq_ids.append(pid)

    if not uniq_ids:
        return {'ok': False, 'hata': 'En az bir plan_id gerekli'}

    plan_ozetleri = []
    hesaplanamayan_planlar = []
    detay = []
    merged_talep = {}
    stok_kart_meta = {}
    stok_trace = {}
    eslesmemis_rf = []

    toplam_siparis_kg = 0.0
    toplam_uretilecek_kg = 0.0
    toplam_fazla_kg = 0.0
    batch_toplam = 0

    def _stok_trace_ensure(sid):
        if sid not in stok_trace:
            stok_trace[sid] = {
                'kaynak_raw': set(),
                'plan_ids': set(),
                'siparis_ids': set(),
                'cari_ids': set(),
                'formul_kods': set(),
            }
        return stok_trace[sid]

    def _stok_trace_kaydet(sid, plan_id, plan_row, trace_row):
        tr = _stok_trace_ensure(sid)
        tr['plan_ids'].add(plan_id)
        if trace_row.get('kaynak'):
            tr['kaynak_raw'].add(trace_row['kaynak'])
        sip_id = plan_row['siparis_id']
        if sip_id not in (None, ''):
            try:
                tr['siparis_ids'].add(int(sip_id))
            except (TypeError, ValueError):
                pass
        cari_id = plan_row['cari_id']
        if cari_id not in (None, ''):
            try:
                tr['cari_ids'].add(int(cari_id))
            except (TypeError, ValueError):
                pass
        fk = trace_row.get('formul_kod')
        if fk:
            tr['formul_kods'].add(fk)

    for plan_id in uniq_ids:
        plan_row = _mi_merkez_plan_oku(con, plan_id)
        if not plan_row:
            hesaplanamayan_planlar.append({
                'plan_id': plan_id,
                'hata': 'Plan bulunamadı',
            })
            continue

        plan_sonuc = _mpr_stok_ihtiyac_birlestir(
            con, plan_id, exclude_batch_kodu=exclude_batch_kodu,
        )
        if not plan_sonuc.get('ok'):
            hesaplanamayan_planlar.append({
                'plan_id': plan_id,
                'plan_kodu': plan_row['plan_kodu'],
                'hata': plan_sonuc.get('hata', 'Hesaplanamadı'),
            })
            continue

        trace_sonuc = _mpr_plan_detay_trace_uret(
            con, plan_id, exclude_batch_kodu=exclude_batch_kodu,
        )
        if not trace_sonuc.get('ok'):
            hesaplanamayan_planlar.append({
                'plan_id': plan_id,
                'plan_kodu': plan_row['plan_kodu'],
                'hata': trace_sonuc.get('hata', 'Detay trace üretilemedi'),
            })
            continue

        plan_ozetleri.append({
            'plan_id': plan_id,
            'plan_kodu': plan_row['plan_kodu'],
            'siparis_id': plan_row['siparis_id'],
            'siparis_no': plan_row['siparis_no'],
            'cari_id': plan_row['cari_id'],
            'musteri_adi': plan_row['musteri_adi'],
            'durum': plan_row['durum'],
            'rf_renk_id': plan_row['rf_renk_id'],
            'toplam_siparis_kg': plan_sonuc.get('toplam_siparis_kg', plan_sonuc.get('siparis_kg', 0)),
            'toplam_uretilecek_kg': plan_sonuc.get('toplam_uretilecek_kg', plan_sonuc.get('uretilecek_kg', 0)),
            'toplam_faturalanacak_kg': plan_sonuc.get(
                'toplam_uretilecek_kg', plan_sonuc.get('uretilecek_kg', 0),
            ),
            'toplam_fazla_kg': plan_sonuc.get('toplam_fazla_kg', plan_sonuc.get('fazla_kg', 0)),
            'toplam_hammadde_kg': plan_sonuc.get('toplam_hammadde_kg', 0),
            'batch_toplam': plan_sonuc.get('batch_toplam', plan_sonuc.get('batch_sayisi', 0)),
            'yeterli_mi': plan_sonuc.get('yeterli_mi'),
            'eksik_sayisi': plan_sonuc.get('eksik_sayisi', 0),
            'cok_boyut': plan_sonuc.get('cok_boyut', False),
        })

        toplam_siparis_kg += float(plan_sonuc.get('toplam_siparis_kg') or plan_sonuc.get('siparis_kg') or 0)
        toplam_uretilecek_kg += float(plan_sonuc.get('toplam_uretilecek_kg') or plan_sonuc.get('uretilecek_kg') or 0)
        toplam_fazla_kg += float(plan_sonuc.get('toplam_fazla_kg') or plan_sonuc.get('fazla_kg') or 0)
        batch_toplam += int(plan_sonuc.get('batch_toplam') or plan_sonuc.get('batch_sayisi') or 0)

        for t in trace_sonuc['satirlar']:
            sid = t.get('stok_kart_id')
            gerekli = float(t.get('gerekli_kg') or 0)
            if sid is None or not t.get('stok_eslesmis', sid is not None):
                eslesmemis_rf.append({
                    'plan_id': plan_id,
                    'plan_kodu': t.get('plan_kodu'),
                    'boyut': t.get('boyut'),
                    'formul_kod': t.get('formul_kod'),
                    'rv_ad': t.get('rv_ad'),
                    'pigment_ad': t.get('pigment_ad') or t.get('stok_ad'),
                    'gerekli_kg': gerekli,
                })
                detay.append({**t, 'net_eksik_kg': None, 'net_eksik_toplanabilir': False})
                continue
            if gerekli <= 0:
                continue
            merged_talep[sid] = round(merged_talep.get(sid, 0.0) + gerekli, 6)
            _stok_trace_kaydet(sid, plan_id, plan_row, t)
            if sid not in stok_kart_meta:
                stok_kart_meta[sid] = {
                    'stok_kod': t.get('stok_kod') or '',
                    'stok_ad': t.get('stok_ad') or '',
                    'pigment_ad': t.get('pigment_ad') or t.get('stok_ad') or '',
                    'kaynak': t.get('kaynak') or '',
                    'stok_eslesmis': True,
                }
            detay.append({**t, 'net_eksik_kg': None, 'net_eksik_toplanabilir': False})

    if not merged_talep and not eslesmemis_rf:
        hata = 'Hiçbir planda hammadde ihtiyacı hesaplanamadı'
        if hesaplanamayan_planlar and not plan_ozetleri:
            hata = hesaplanamayan_planlar[0].get('hata') or hata
        return {
            'ok': False,
            'hata': hata,
            'plan_ids': uniq_ids,
            'hesaplanamayan_planlar': hesaplanamayan_planlar,
        }

    stok_bakiye = {}
    for sid in merged_talep:
        fiziksel = _mevcut_stok(con, sid)
        rezerve = _aktif_rezerv_toplam(con, sid, exclude_batch_kodu)
        yumusak = _yumusak_talep_toplam(con, sid, exclude_batch_kodu)
        acik_sa = _acik_satin_alma_arzi(con, sid)
        stok_bakiye[sid] = {
            'fiziksel_kg': fiziksel,
            'rezerve_kg': rezerve,
            'yumusak_talep_kg': yumusak,
            'kullanilabilir_kg': round(fiziksel - rezerve - yumusak, 3),
            'yolda_kg': acik_sa['yolda_kg'],
            'acik_sa_siparisler': acik_sa['siparisler'],
        }

    birim_map = {}
    if merged_talep:
        sid_list = list(merged_talep.keys())
        placeholders = ','.join(['?'] * len(sid_list))
        birim_map = {
            r['id']: r['birim'] or 'KG'
            for r in con.execute(
                f"SELECT id, birim FROM nexgen_stok_kart WHERE id IN ({placeholders})",
                sid_list,
            ).fetchall()
        }

    eksik_stok_ids = set()
    toplu = []
    for sid, gerekli in merged_talep.items():
        meta = stok_kart_meta[sid]
        bak = stok_bakiye[sid]
        kullanilabilir = bak['kullanilabilir_kg']
        fark = round(kullanilabilir - gerekli, 3)
        if fark < -0.0005:
            eksik_stok_ids.add(sid)
        fiziksel_eksik = round(max(gerekli - kullanilabilir, 0.0), 3)
        yolda_kg = bak['yolda_kg']
        net_eksik = round(max(fiziksel_eksik - yolda_kg, 0.0), 3)
        th = _tahmini_hazir_tarih(
            gerekli, kullanilabilir, {'siparisler': bak['acik_sa_siparisler']},
        )
        durum = _mpr_malzeme_durumu(
            gerekli, kullanilabilir, yolda_kg, fiziksel_eksik, net_eksik,
        )
        tr = stok_trace.get(sid, {})
        kaynak_turu = _mi_merkez_kaynak_turu(tr.get('kaynak_raw') or meta.get('kaynak'))
        toplu.append({
            'kaynak': meta['kaynak'],
            'kaynak_turu': kaynak_turu,
            'stok_kart_id': sid,
            'stok_kod': meta['stok_kod'],
            'stok_ad': meta['stok_ad'],
            'pigment_ad': meta.get('pigment_ad') or meta['stok_ad'],
            'stok_eslesmis': True,
            'birim': birim_map.get(sid, 'KG'),
            'gerekli_kg': gerekli,
            'toplam_gerekli_kg': gerekli,
            'fiziksel_kg': bak['fiziksel_kg'],
            'rezerve_kg': bak['rezerve_kg'],
            'yumusak_talep_kg': bak['yumusak_talep_kg'],
            'kullanilabilir_kg': kullanilabilir,
            'mevcut_kg': bak['fiziksel_kg'],
            'fark_kg': fark,
            'yeterli': sid not in eksik_stok_ids,
            'yolda_kg': yolda_kg,
            'fiziksel_eksik_kg': fiziksel_eksik,
            'net_eksik_kg': net_eksik,
            'net_eksik_toplanabilir': True,
            'malzeme_durumu': durum,
            'durum': durum,
            'plan_sayisi': len(tr.get('plan_ids') or []),
            'siparis_sayisi': len(tr.get('siparis_ids') or []),
            'cari_sayisi': len(tr.get('cari_ids') or []),
            'formul_sayisi': len(tr.get('formul_kods') or []),
            'tahmini_hazir': th['tarih'],
            'termin_riski': th['termin_riski'],
            'tahmini_aciklama': th['aciklama'],
            'acik_sa_siparisler': bak['acik_sa_siparisler'],
        })

    for d in detay:
        sid = d.get('stok_kart_id')
        if sid in stok_bakiye:
            bak = stok_bakiye[sid]
            d['fiziksel_kg'] = bak['fiziksel_kg']
            d['rezerve_kg'] = bak['rezerve_kg']
            d['yumusak_talep_kg'] = bak['yumusak_talep_kg']
            d['kullanilabilir_kg'] = bak['kullanilabilir_kg']
            d['yolda_kg'] = bak['yolda_kg']
            d['birim'] = birim_map.get(sid, 'KG')

    toplu.sort(key=lambda x: (x.get('kaynak') or '', x.get('stok_kod') or '', x.get('stok_kart_id') or 0))
    detay.sort(key=lambda x: (
        x.get('plan_id') or 0,
        x.get('formul_kod') or '',
        x.get('boyut') or '',
        x.get('stok_kod') or '',
        x.get('stok_kart_id') or 0,
    ))

    toplam_hammadde_kg = round(sum(merged_talep.values()), 3)
    toplam_net_eksik_kg = round(sum(float(k.get('net_eksik_kg') or 0) for k in toplu), 3)
    yeterli_kalem_sayisi = sum(1 for k in toplu if k.get('yeterli'))
    yeterli_mi = len(eksik_stok_ids) == 0 and len(eslesmemis_rf) == 0

    basarili_siparis_ids = set()
    basarili_cari_ids = set()
    for p in plan_ozetleri:
        sip_id = p.get('siparis_id')
        if sip_id not in (None, ''):
            try:
                basarili_siparis_ids.add(int(sip_id))
            except (TypeError, ValueError):
                pass
        cari_id = p.get('cari_id')
        if cari_id not in (None, ''):
            try:
                basarili_cari_ids.add(int(cari_id))
            except (TypeError, ValueError):
                pass

    toplam_faturalanacak_kg = round(toplam_uretilecek_kg, 3)

    ozet = {
        'plan_sayisi': len(uniq_ids),
        'basarili_plan_sayisi': len(plan_ozetleri),
        'hesaplanamayan_plan_sayisi': len(hesaplanamayan_planlar),
        'siparis_sayisi': len(basarili_siparis_ids),
        'cari_sayisi': len(basarili_cari_ids),
        'detay_satir_sayisi': len(detay),
        'toplu_satir_sayisi': len(toplu),
        'toplam_siparis_kg': round(toplam_siparis_kg, 3),
        'toplam_talep_kg': round(toplam_siparis_kg, 3),
        'toplam_uretilecek_kg': round(toplam_uretilecek_kg, 3),
        'toplam_faturalanacak_kg': toplam_faturalanacak_kg,
        'toplam_fazla_kg': round(toplam_fazla_kg, 3),
        'toplam_hammadde_kg': toplam_hammadde_kg,
        'batch_toplam': batch_toplam,
        'toplam_net_eksik_kg': toplam_net_eksik_kg,
        'eksik_stok_sayisi': len(eksik_stok_ids),
        'eksik_kalem_sayisi': len(eksik_stok_ids),
        'yeterli_kalem_sayisi': yeterli_kalem_sayisi,
        'eslesmemis_rf_sayisi': len(eslesmemis_rf),
        'yeterli_mi': yeterli_mi,
    }

    return {
        'ok': True,
        'plan_ids': uniq_ids,
        'ozet': ozet,
        'plan_ozetleri': plan_ozetleri,
        'hesaplanamayan_planlar': hesaplanamayan_planlar,
        'detay': detay,
        'toplu': toplu,
        'eslesmemis_rf': eslesmemis_rf,
        'kalemler': toplu,
        'yeterli_mi': yeterli_mi,
        'eksik_sayisi': len(eksik_stok_ids) + len(eslesmemis_rf),
    }


def _formul_kalemleri_birimli(con, mpr_kalemler, kaynak):
    """_mpr_stok_ihtiyac_hesapla kalemlerini API görünüm formatına çevirir."""
    sid_list = [k['stok_kart_id'] for k in mpr_kalemler if k.get('kaynak') == kaynak]
    if not sid_list:
        return []
    placeholders = ','.join(['?'] * len(sid_list))
    birim_map = {
        r['id']: {'birim': r['birim'] or 'KG', 'kategori': (r['kategori'] or '').upper()}
        for r in con.execute(
            f"SELECT id, birim, kategori FROM nexgen_stok_kart WHERE id IN ({placeholders})",
            sid_list,
        ).fetchall()
    }
    out = []
    for k in mpr_kalemler:
        if k.get('kaynak') != kaynak:
            continue
        meta = birim_map.get(k['stok_kart_id'], {'birim': 'KG', 'kategori': ''})
        out.append({
            'ad': k.get('stok_ad') or '',
            'kod': k.get('stok_kod') or '',
            'miktar_kg': k.get('gerekli_kg', 0),
            'birim': meta['birim'] or 'KG',
            'kategori': meta['kategori'],
        })
    return out


def _formul_bolum_toplamlar(taban, rf):
    """Formül bölümü alt toplamları (kg cinsinden)."""
    taban_kg = round(sum(float(k.get('miktar_kg') or 0) for k in taban), 3)
    rf_kg = round(sum(float(k.get('miktar_kg') or 0) for k in rf), 3)
    return {
        'taban_kg': taban_kg,
        'rf_kg': rf_kg,
        'genel_kg': round(taban_kg + rf_kg, 3),
    }


def _formul_bolum_yap(con, ihtiyac, kg):
    """Tek formül bölümü: taban + RF kalemleri ve toplamlar."""
    taban = _formul_kalemleri_birimli(con, ihtiyac.get('kalemler', []), 'TABAN')
    rf = _formul_kalemleri_birimli(con, ihtiyac.get('kalemler', []), 'RF')
    return {
        'kg': round(float(kg), 3),
        'taban': taban,
        'rf': rf,
        'toplamlar': _formul_bolum_toplamlar(taban, rf),
        'taban_batch_kg': ihtiyac.get('taban_batch_kg'),
    }


def _depo_hazirlik_tablosu_var(con):
    return con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_depo_hazirlik'"
    ).fetchone() is not None


def _depo_hazirlik_no_uret(con):
    """DH-YYYY-NNNNN formatında benzersiz hazırlık numarası."""
    import datetime
    yil = datetime.datetime.now().year
    son = con.execute(
        "SELECT hazirlik_no FROM nexgen_depo_hazirlik "
        "WHERE hazirlik_no LIKE ? ORDER BY id DESC LIMIT 1",
        (f"DH-{yil}-%",),
    ).fetchone()
    if son:
        try:
            son_no = int(son['hazirlik_no'].split('-')[-1])
        except Exception:
            son_no = 0
    else:
        son_no = 0
    return f"DH-{yil}-{son_no + 1:05d}"


def _depo_hazirlik_olustur(con, batch_kodu, plan_id, uretim_varyant_id,
                            planlanan_kg, rf_renk_id=None, cari_id=None,
                            planlama_siparis_id=None, olusturan_id=None):
    """FAZ-5B: batch oluşunca depo hazırlık snapshot (FAZ-4E toplam hesap). Stok yazmaz."""
    if not _depo_hazirlik_tablosu_var(con):
        return None

    mevcut = con.execute(
        "SELECT id FROM nexgen_depo_hazirlik "
        "WHERE batch_kodu=? AND durum NOT IN ('IPTAL')",
        (batch_kodu,),
    ).fetchone()
    if mevcut:
        return mevcut['id']

    ihtiyac = None
    if plan_id:
        ihtiyac = _mpr_stok_ihtiyac_birlestir(con, plan_id)
    if not ihtiyac or not ihtiyac.get('ok'):
        toplam_kg = round(float(planlanan_kg), 3)
        ihtiyac = _mpr_stok_ihtiyac_hesapla(
            con, uretim_varyant_id, rf_renk_id, toplam_kg,
        )
    if not ihtiyac.get('ok'):
        return None

    hazirlik_no = _depo_hazirlik_no_uret(con)
    uid = olusturan_id if olusturan_id is not None else _kullanici_id()
    con.execute("""
        INSERT INTO nexgen_depo_hazirlik
          (hazirlik_no, batch_kodu, plan_id, planlama_siparis_id, cari_id,
           durum, olusturan_id)
        VALUES (?, ?, ?, ?, ?, 'BEKLIYOR', ?)
    """, (hazirlik_no, batch_kodu, plan_id, planlama_siparis_id,
          cari_id, uid))
    hid = con.execute("SELECT last_insert_rowid()").fetchone()[0]

    for k in ihtiyac.get('kalemler', []):
        gerekli = round(float(k.get('gerekli_kg') or 0), 3)
        if gerekli <= 0:
            continue
        con.execute("""
            INSERT INTO nexgen_depo_hazirlik_kalem
              (hazirlik_id, stok_kart_id, kaynak, gerekli_kg, hazirlanan_kg)
            VALUES (?, ?, ?, ?, 0)
        """, (hid, k['stok_kart_id'], k.get('kaynak') or 'TABAN', gerekli))

    return hid


def _depo_hazirlik_kalemleri(con, hazirlik_id):
    rows = con.execute("""
        SELECT k.id, k.stok_kart_id, k.kaynak, k.gerekli_kg, k.hazirlanan_kg,
               sk.kod AS stok_kod, sk.ad AS stok_ad, sk.birim, sk.kategori
        FROM nexgen_depo_hazirlik_kalem k
        JOIN nexgen_stok_kart sk ON sk.id = k.stok_kart_id
        WHERE k.hazirlik_id=?
        ORDER BY k.kaynak, sk.kod
    """, (hazirlik_id,)).fetchall()
    return [dict(r) for r in rows]


def _depo_hazirlik_batch_durum(con, batch_kodu):
    if not _depo_hazirlik_tablosu_var(con):
        return None
    row = con.execute("""
        SELECT id, hazirlik_no, durum, hazir_tarihi
        FROM nexgen_depo_hazirlik
        WHERE batch_kodu=? AND durum NOT IN ('IPTAL')
        ORDER BY id DESC LIMIT 1
    """, (batch_kodu,)).fetchone()
    return dict(row) if row else None


def _batch_depo_hazir_zorunlu(con, batch_kodu):
    """Parça bitirmeden önce batch için depo hazırlığının HAZIR olmasını zorunlu kılar."""
    if not _depo_hazirlik_tablosu_var(con):
        return {'ok': True, 'atlandi': True}
    dh = _depo_hazirlik_batch_durum(con, batch_kodu)
    if not dh:
        return {
            'ok': False,
            'hata': 'Bu batch için depo hazırlık kaydı yok. Önce üretime gönderin.',
        }
    if dh.get('durum') != 'HAZIR':
        return {
            'ok': False,
            'hata': (
                f'Depo hazırlığı tamamlanmadı (durum: {dh.get("durum")}). '
                'Parça bitirmeden önce depoda HAZIR işaretleyin.'
            ),
            'depo_durum': dh.get('durum'),
        }
    return {'ok': True, 'depo_durum': 'HAZIR'}


def _depo_hazirlik_mi_uyari(con, plan_id, kalemler):
    """Hazırlık snapshot'ını güncel MI ile karşılaştır — otomatik değiştirme yok."""
    if not plan_id:
        return None
    mi = _mpr_stok_ihtiyac_birlestir(con, plan_id)
    if not mi.get('ok'):
        return None
    mi_map = {}
    for k in mi.get('kalemler', []):
        sid = k.get('stok_kart_id')
        if sid:
            mi_map[int(sid)] = round(float(k.get('gerekli_kg') or 0), 3)
    snap_map = {}
    for k in kalemler:
        sid = k.get('stok_kart_id')
        if sid:
            snap_map[int(sid)] = round(float(k.get('gerekli_kg') or 0), 3)
    farklar = []
    for sid in sorted(set(mi_map) | set(snap_map)):
        mi_kg = mi_map.get(sid, 0)
        snap_kg = snap_map.get(sid, 0)
        if abs(mi_kg - snap_kg) > 0.05:
            farklar.append({
                'stok_kart_id': sid,
                'snapshot_kg': snap_kg,
                'guncel_kg': mi_kg,
            })
    if not farklar:
        return None
    return {
        'uyari': (
            'Hazırlık snapshot\'ı güncel Malzeme İhtiyacı ile uyuşmuyor. '
            'Yeniden kontrol edin.'
        ),
        'fark_sayisi': len(farklar),
        'farklar': farklar[:10],
    }


def _stok_rezerv_tablosu_var(con):
    return con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_stok_rezerv'"
    ).fetchone() is not None


def _aktif_rezerv_toplam(con, stok_kart_id, exclude_batch_kodu=None):
    """AKTIF rezerv kalan_kg toplamı. exclude_batch_kodu: kendi batch hariç."""
    if not _stok_rezerv_tablosu_var(con):
        return 0.0
    params = [stok_kart_id]
    batch_filtre = ""
    if exclude_batch_kodu:
        batch_filtre = " AND batch_kodu != ?"
        params.append(exclude_batch_kodu)
    row = con.execute(f"""
        SELECT COALESCE(SUM(kalan_kg), 0) AS toplam
        FROM nexgen_stok_rezerv
        WHERE stok_kart_id = ? AND durum = 'AKTIF'{batch_filtre}
    """, params).fetchone()
    return round(float(row['toplam'] or 0), 3) if row else 0.0


def _yumusak_talep_toplam(con, stok_kart_id, exclude_batch_kodu=None):
    """BEKLIYOR/HAZIRLANIYOR depo hazırlık kalemlerinin gerekli_kg toplamı."""
    if not _depo_hazirlik_tablosu_var(con):
        return 0.0
    params = [stok_kart_id]
    batch_filtre = ""
    if exclude_batch_kodu:
        batch_filtre = " AND h.batch_kodu != ?"
        params.append(exclude_batch_kodu)
    row = con.execute(f"""
        SELECT COALESCE(SUM(k.gerekli_kg), 0) AS toplam
        FROM nexgen_depo_hazirlik_kalem k
        JOIN nexgen_depo_hazirlik h ON h.id = k.hazirlik_id
        WHERE k.stok_kart_id = ?
          AND h.durum IN ('BEKLIYOR', 'HAZIRLANIYOR'){batch_filtre}
    """, params).fetchone()
    return round(float(row['toplam'] or 0), 3) if row else 0.0


def _kullanilabilir_stok(con, stok_kart_id, exclude_batch_kodu=None):
    """Fiziksel − aktif rezerv − yumuşak talep (kendi batch hariç tutulabilir)."""
    fiziksel = _mevcut_stok(con, stok_kart_id)
    rezerv = _aktif_rezerv_toplam(con, stok_kart_id, exclude_batch_kodu)
    yumusak = _yumusak_talep_toplam(con, stok_kart_id, exclude_batch_kodu)
    return round(fiziksel - rezerv - yumusak, 3)


def _acik_satin_alma_arzi(con, stok_kart_id):
    """FAZ-MRP-01 — PDF Kararı A2: Açık satın alma siparişlerinin arz hesabı.

    Yalnızca ONAYLANDI + BEKLIYOR veya KISMI_TESLIM durumundaki siparişler dahil.
    TAMAMLANDI ve IPTAL siparişler ARZ'a dahil edilmez.

    Kalan açık miktar = siparis_miktari_kg - SUM(nexgen_mal_kabul.miktar_kg)

    Dönen yapı:
        yolda_kg          : Tüm açık SA'ların kalan toplam miktarı
        siparisler        : Liste — her sipariş için ayrı satır
            siparis_id
            siparis_no
            tedarikci_ad
            siparis_miktari_kg
            gelen_kg         (mal kabul toplam)
            kalan_kg         (yolda olan)
            beklenen_teslim  (str veya None)
            durum

    PDF kuralı: "Yoldaki malzeme üretime hazır stok sayılmamalı."
    Bu nedenle bu fonksiyon sadece planlama/görüntüleme için kullanılır;
    üretime başlama kontrolü _kullanilabilir_stok() üzerinden yapılmaya devam eder.
    """
    # Tablo yoksa sıfır arz döndür (eski sistemler veya test ortamı)
    tablo_var = con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_satin_siparis'"
    ).fetchone()
    if not tablo_var:
        return {'yolda_kg': 0.0, 'siparisler': []}

    rows = con.execute("""
        SELECT ss.id         AS siparis_id,
               ss.siparis_no,
               ss.siparis_miktari_kg,
               ss.beklenen_teslim,
               ss.durum,
               t.ad          AS tedarikci_ad,
               COALESCE(
                   (SELECT SUM(mk.miktar_kg)
                    FROM nexgen_mal_kabul mk
                    WHERE mk.satin_siparis_id = ss.id), 0
               ) AS gelen_kg
        FROM nexgen_satin_siparis ss
        JOIN nexgen_tedarikci t ON t.id = ss.tedarikci_id
        WHERE ss.stok_kart_id = ?
          AND ss.durum IN ('BEKLIYOR', 'KISMI_TESLIM')
          AND ss.onay_durumu = 'ONAYLANDI'
        ORDER BY ss.beklenen_teslim ASC NULLS LAST, ss.id DESC
    """, (stok_kart_id,)).fetchall()

    siparisler = []
    toplam_yolda = 0.0
    for r in rows:
        sip_kg  = float(r['siparis_miktari_kg'] or 0)
        gel_kg  = float(r['gelen_kg'] or 0)
        kal_kg  = round(max(sip_kg - gel_kg, 0.0), 3)
        if kal_kg <= 0:
            # Fiilen tamamlanmış ama durum güncellenmemiş — dahil etme
            continue
        siparisler.append({
            'siparis_id':        r['siparis_id'],
            'siparis_no':        r['siparis_no'],
            'tedarikci_ad':      r['tedarikci_ad'],
            'siparis_miktari_kg': sip_kg,
            'gelen_kg':          round(gel_kg, 3),
            'kalan_kg':          kal_kg,
            'beklenen_teslim':   r['beklenen_teslim'],
            'durum':             r['durum'],
        })
        toplam_yolda = round(toplam_yolda + kal_kg, 3)

    return {
        'yolda_kg':   toplam_yolda,
        'siparisler': siparisler,
    }


def _mpr_malzeme_durumu(gerekli_kg, kullanilabilir_kg, yolda_kg,
                         fiziksel_eksik_kg, net_eksik_kg):
    """FAZ-MRP-01 — PDF Kararı: Malzeme durum etiketi.

    Öncelik sırası (üstten alta):
        HAZIR            → kullanılabilir fiziksel stok ihtiyacı tam karşılıyor
        DEPO HAZIRLIKTA  → yumuşak talep var ama henüz gerçekleşmemiş
        YOLDA            → fiziksel eksik var ama açık SA tamamen karşılıyor
        KISMEN YOLDA     → fiziksel eksik var, açık SA kısmen karşılıyor
        SATIN ALMA GEREKLİ → hem fiziksel hem SA yetmiyor (net_eksik > 0)
        EKSİK            → hiç stok/yolda yok (fallback)
    """
    if net_eksik_kg <= 0.001 and fiziksel_eksik_kg <= 0.001:
        return 'HAZIR'
    if net_eksik_kg <= 0.001 and fiziksel_eksik_kg > 0.001:
        if yolda_kg >= fiziksel_eksik_kg - 0.001:
            return 'YOLDA'
        return 'KISMEN YOLDA'
    # net_eksik > 0 → satın alma gerekli
    if yolda_kg > 0.001:
        return 'KISMEN YOLDA'
    return 'SATIN ALMA GEREKLİ'


def _tahmini_hazir_tarih(gerekli_kg, kullanilabilir_kg, acik_sa_arzi, uretim_termini=None):
    """FAZ-MRP-01 — PDF Kararı A3: Tahmini hazır olma tarihi.

    Kural (PDF Sayfa 6-7):
      1. Fiziksel stok yeterliyse → bugün (HAZIR)
      2. Tüm eksik açık SA'lardan karşılanıyorsa → eksik miktarı dolduran
         son SA'nın beklenen_teslim tarihi
      3. Açık SA yetmiyorsa → None (SATIN ALMA GEREKLİ)
      4. Tahmini tarih uretim_termini'ni geçiyorsa → termin_riski=True

    Döner: {'tarih': str|None, 'termin_riski': bool, 'aciklama': str}
    """
    import datetime

    fiziksel_eksik = round(gerekli_kg - kullanilabilir_kg, 3)
    if fiziksel_eksik <= 0.001:
        return {
            'tarih':         None,
            'termin_riski':  False,
            'aciklama':      'HAZIR',
        }

    kalan_eksik = fiziksel_eksik
    son_tarih = None

    for sip in acik_sa_arzi.get('siparisler', []):
        if kalan_eksik <= 0.001:
            break
        karsilanan = min(sip['kalan_kg'], kalan_eksik)
        kalan_eksik = round(kalan_eksik - karsilanan, 3)
        t = sip.get('beklenen_teslim')
        if t:
            # En geç teslim tarihini al
            if son_tarih is None or t > son_tarih:
                son_tarih = t

    if kalan_eksik > 0.001:
        # Açık SA yetmiyor
        return {
            'tarih':         None,
            'termin_riski':  True,
            'aciklama':      'SATIN ALMA GEREKLİ',
        }

    if son_tarih is None:
        # SA var ama tarih belirtilmemiş
        return {
            'tarih':         None,
            'termin_riski':  False,
            'aciklama':      'YOLDA (tarih belirsiz)',
        }

    # Termin riski kontrolü
    termin_riski = False
    if uretim_termini:
        try:
            if son_tarih > uretim_termini:
                termin_riski = True
        except Exception:
            pass

    return {
        'tarih':         son_tarih,
        'termin_riski':  termin_riski,
        'aciklama':      'YOLDA' if not termin_riski else 'TERMİN RİSKİ',
    }


def _rezerv_no_uret(con):
    """RZ-YYYY-NNNNN formatında benzersiz rezerv numarası."""
    import datetime
    yil = datetime.datetime.now().year
    son = con.execute(
        "SELECT rezerv_no FROM nexgen_stok_rezerv "
        "WHERE rezerv_no LIKE ? ORDER BY id DESC LIMIT 1",
        (f"RZ-{yil}-%",),
    ).fetchone()
    if son:
        try:
            son_no = int(son['rezerv_no'].split('-')[-1])
        except Exception:
            son_no = 0
    else:
        son_no = 0
    return f"RZ-{yil}-{son_no + 1:05d}"


def _depo_hazirlik_rezerv_olustur(con, hazirlik_id, olusturan_id=None):
    """FAZ-5C-2: Depo HAZIR anında AKTIF rezerv oluştur. Stok hareketi yazmaz."""
    if not _stok_rezerv_tablosu_var(con):
        return {'ok': True, 'atlandi': True, 'rezerv_sayisi': 0}

    mevcut = con.execute(
        "SELECT id FROM nexgen_stok_rezerv "
        "WHERE hazirlik_id=? AND durum='AKTIF' LIMIT 1",
        (hazirlik_id,),
    ).fetchone()
    if mevcut:
        cnt = con.execute(
            "SELECT COUNT(*) FROM nexgen_stok_rezerv "
            "WHERE hazirlik_id=? AND durum='AKTIF'",
            (hazirlik_id,),
        ).fetchone()[0]
        return {'ok': True, 'atlandi': True, 'rezerv_sayisi': cnt}

    hdr = con.execute("""
        SELECT id, batch_kodu, plan_id, planlama_siparis_id, cari_id
        FROM nexgen_depo_hazirlik WHERE id=?
    """, (hazirlik_id,)).fetchone()
    if not hdr:
        return {'ok': False, 'hata': 'Hazırlık bulunamadı'}

    kalemler = con.execute("""
        SELECT k.id, k.stok_kart_id, k.kaynak, k.gerekli_kg, k.hazirlanan_kg,
               sk.kod AS stok_kod, sk.ad AS stok_ad
        FROM nexgen_depo_hazirlik_kalem k
        JOIN nexgen_stok_kart sk ON sk.id = k.stok_kart_id
        WHERE k.hazirlik_id=?
    """, (hazirlik_id,)).fetchall()
    if not kalemler:
        return {'ok': False, 'hata': 'Hazırlık kalemi yok'}

    batch_kodu = hdr['batch_kodu']
    talep = {}
    meta = {}
    for k in kalemler:
        hk = float(k['hazirlanan_kg'] or 0)
        gk = float(k['gerekli_kg'] or 0)
        miktar = round(hk if hk > 0 else gk, 3)
        if miktar <= 0:
            continue
        sid = k['stok_kart_id']
        talep[sid] = round(talep.get(sid, 0) + miktar, 3)
        meta[sid] = {'stok_kod': k['stok_kod'], 'stok_ad': k['stok_ad']}

    eksik_kalemler = []
    for sid, miktar in talep.items():
        kul = _kullanilabilir_stok(con, sid, exclude_batch_kodu=batch_kodu)
        if kul < miktar - 0.0005:
            eksik_kalemler.append({
                'stok_kart_id': sid,
                'stok_kod': meta[sid]['stok_kod'],
                'stok_ad': meta[sid]['stok_ad'],
                'gerekli_kg': miktar,
                'kullanilabilir_kg': kul,
                'fark_kg': round(kul - miktar, 3),
            })

    if eksik_kalemler:
        return {
            'ok': False,
            'hata': 'Rezerv için stok yetersiz',
            'eksik_sayisi': len(eksik_kalemler),
            'eksik_kalemler': eksik_kalemler,
        }

    uid = olusturan_id if olusturan_id is not None else _kullanici_id()
    rezerv_sayisi = 0
    for k in kalemler:
        hk = float(k['hazirlanan_kg'] or 0)
        gk = float(k['gerekli_kg'] or 0)
        miktar = round(hk if hk > 0 else gk, 3)
        if miktar <= 0:
            continue
        rezerv_no = _rezerv_no_uret(con)
        con.execute("""
            INSERT INTO nexgen_stok_rezerv
              (rezerv_no, stok_kart_id, kaynak_tip, kaynak_id, hazirlik_id,
               batch_kodu, plan_id, planlama_siparis_id, cari_id,
               miktar_kg, kalan_kg, durum, olusturan_id)
            VALUES (?, ?, 'DEPO_HAZIRLIK', ?, ?, ?, ?, ?, ?, ?, ?, 'AKTIF', ?)
        """, (
            rezerv_no, k['stok_kart_id'], hazirlik_id, hazirlik_id,
            batch_kodu, hdr['plan_id'], hdr['planlama_siparis_id'],
            hdr['cari_id'], miktar, miktar, uid,
        ))
        rezerv_sayisi += 1

    return {'ok': True, 'atlandi': False, 'rezerv_sayisi': rezerv_sayisi}


def _refresh_depo_snapshot(con, batch_kodu):
    """Batch depo/rezerv snapshot'ını canlı MPR motor çıktısı ile günceller.

    Depo kalemlerini silmez; gerekli_kg (HAZIR ise hazirlanan_kg) günceller.
    AKTIF rezerv miktar_kg/kalan_kg değerlerini senkronize eder. Stok hareketi yazmaz.
    """
    if not _depo_hazirlik_tablosu_var(con):
        return {'ok': False, 'hata': 'Depo hazırlık tablosu yok'}

    batch = con.execute("""
        SELECT nb.batch_kodu, nb.planlanan_kg, nb.plan_id, nb.uretim_varyant_id
        FROM nexgen_uretim_batch nb
        WHERE nb.batch_kodu = ? AND nb.durum NOT IN ('IPTAL')
    """, (batch_kodu,)).fetchone()
    if not batch:
        return {'ok': False, 'hata': f'Batch bulunamadı: {batch_kodu}'}

    depo = _depo_hazirlik_batch_durum(con, batch_kodu)
    if not depo:
        return {'ok': False, 'hata': f'Depo hazırlık bulunamadı: {batch_kodu}'}

    hazirlik_id = depo['id']
    siparis_kg = round(float(batch['planlanan_kg']), 3)
    uv_id = batch['uretim_varyant_id']
    plan_id = batch['plan_id']

    rf_renk_id = None
    if plan_id:
        prow = con.execute(
            "SELECT rf_renk_id FROM nexgen_uretim_plan WHERE id = ?", (plan_id,),
        ).fetchone()
        if prow:
            rf_renk_id = prow['rf_renk_id']

    once_snap = _nexgen_batch_snapshot(con, batch_kodu)
    once_depo = once_snap['depo_toplam_kg'] if once_snap else 0.0
    once_rezerv = once_snap['rezerv_kg'] if once_snap else 0.0
    once_canli = once_snap['canli_ihtiyac_toplam_kg'] if once_snap else 0.0

    ihtiyac = _mpr_stok_ihtiyac_hesapla(con, uv_id, rf_renk_id, siparis_kg)
    if not ihtiyac.get('ok'):
        return {'ok': False, 'hata': ihtiyac.get('hata', 'MPR hesaplanamadı')}

    mpr_map = {}
    for k in ihtiyac.get('kalemler', []):
        key = (k['stok_kart_id'], k.get('kaynak') or 'TABAN')
        mpr_map[key] = round(float(k.get('gerekli_kg') or 0), 3)

    depo_kalemler = _depo_hazirlik_kalemleri(con, hazirlik_id)
    depo_durum = depo.get('durum')
    guncellenen_depo = 0
    eslesmeyen = []

    for k in depo_kalemler:
        key = (k['stok_kart_id'], k.get('kaynak') or 'TABAN')
        yeni = mpr_map.get(key)
        if yeni is None:
            eslesmeyen.append({'stok_kod': k.get('stok_kod'), 'kaynak': key[1]})
            continue
        eski_gk = round(float(k.get('gerekli_kg') or 0), 3)
        eski_hk = round(float(k.get('hazirlanan_kg') or 0), 3)
        degisti = abs(eski_gk - yeni) > 0.0005
        if depo_durum == 'HAZIR' and eski_hk > 0:
            degisti = degisti or abs(eski_hk - yeni) > 0.0005
        if not degisti:
            continue
        if depo_durum == 'HAZIR' and eski_hk > 0:
            con.execute(
                "UPDATE nexgen_depo_hazirlik_kalem SET gerekli_kg=?, hazirlanan_kg=? WHERE id=?",
                (yeni, yeni, k['id']),
            )
        else:
            con.execute(
                "UPDATE nexgen_depo_hazirlik_kalem SET gerekli_kg=? WHERE id=?",
                (yeni, k['id']),
            )
        guncellenen_depo += 1

    guncellenen_rezerv = 0
    if _stok_rezerv_tablosu_var(con):
        depo_kalemler = _depo_hazirlik_kalemleri(con, hazirlik_id)
        for k in depo_kalemler:
            hk = float(k.get('hazirlanan_kg') or 0)
            gk = float(k.get('gerekli_kg') or 0)
            miktar = round(hk if hk > 0 else gk, 3)
            if miktar <= 0:
                continue
            rez_rows = con.execute("""
                SELECT id, miktar_kg, kalan_kg
                FROM nexgen_stok_rezerv
                WHERE hazirlik_id = ? AND stok_kart_id = ? AND durum = 'AKTIF'
            """, (hazirlik_id, k['stok_kart_id'])).fetchall()
            for r in rez_rows:
                eski_miktar = float(r['miktar_kg'] or 0)
                eski_kalan = float(r['kalan_kg'] or 0)
                tuketilen = round(max(0.0, eski_miktar - eski_kalan), 3)
                yeni_kalan = round(max(0.0, miktar - tuketilen), 3)
                if abs(eski_miktar - miktar) > 0.0005 or abs(eski_kalan - yeni_kalan) > 0.0005:
                    con.execute(
                        "UPDATE nexgen_stok_rezerv SET miktar_kg=?, kalan_kg=? WHERE id=?",
                        (miktar, yeni_kalan, r['id']),
                    )
                    guncellenen_rezerv += 1

    son_snap = _nexgen_batch_snapshot(con, batch_kodu)
    return {
        'ok': True,
        'batch_kodu': batch_kodu,
        'hazirlik_id': hazirlik_id,
        'guncellenen_depo_kalem': guncellenen_depo,
        'guncellenen_rezerv': guncellenen_rezerv,
        'eslesmeyen_kalem': eslesmeyen,
        'once': {
            'depo_toplam_kg': once_depo,
            'rezerv_kg': once_rezerv,
            'canli_ihtiyac_toplam_kg': once_canli,
            'stale_depo_var_mi': once_snap.get('stale_depo_var_mi') if once_snap else None,
        },
        'sonra': {
            'depo_toplam_kg': son_snap['depo_toplam_kg'] if son_snap else 0.0,
            'rezerv_kg': son_snap['rezerv_kg'] if son_snap else 0.0,
            'canli_ihtiyac_toplam_kg': son_snap['canli_ihtiyac_toplam_kg'] if son_snap else 0.0,
            'stale_depo_var_mi': son_snap.get('stale_depo_var_mi') if son_snap else None,
            'uretilecek_kg': son_snap.get('uretilecek_kg') if son_snap else 0.0,
        },
        'ihtiyac': {
            'uretilecek_kg': ihtiyac.get('uretilecek_kg'),
            'batch_sayisi': ihtiyac.get('batch_sayisi'),
            'formul_batch_kg': ihtiyac.get('formul_batch_kg'),
        },
    }


def _batch_formul_parca_sec(con, batch_kodu, parca_id=None):
    """Formül önizleme için varsayılan parça: DEVAM → HAZIR → ilk kayıt."""
    if parca_id:
        row = con.execute(
            "SELECT id, parca_no, hedef_kg, durum FROM nexgen_uretim_parca "
            "WHERE id=? AND batch_kodu=?",
            (parca_id, batch_kodu),
        ).fetchone()
        return dict(row) if row else None

    for durum in ('DEVAM', 'HAZIR', 'BEKLEME'):
        row = con.execute(
            "SELECT id, parca_no, hedef_kg, durum FROM nexgen_uretim_parca "
            "WHERE batch_kodu=? AND durum=? ORDER BY parca_no LIMIT 1",
            (batch_kodu, durum),
        ).fetchone()
        if row:
            return dict(row)

    row = con.execute(
        "SELECT id, parca_no, hedef_kg, durum FROM nexgen_uretim_parca "
        "WHERE batch_kodu=? ORDER BY parca_no LIMIT 1",
        (batch_kodu,),
    ).fetchone()
    return dict(row) if row else None


def _arge_formul_taban_onizle(con, uretim_varyant_id, test_kg):
    """ARGE tablet önizleme — test-olustur ile aynı ölçek, TABAN (BOYA hariç)."""
    try:
        test_kg = float(test_kg)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'Geçersiz test_kg'}
    if test_kg <= 0:
        return {'ok': False, 'hata': 'test_kg sıfırdan büyük olmalı'}

    kalemler = con.execute("""
        SELECT rk.stok_kart_id, rk.miktar_kg, rk.sira,
               sk.kod AS stok_kod, sk.ad AS stok_ad, sk.birim, sk.kategori
        FROM nexgen_recete_kalem rk
        JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.uretim_varyant_id = ? AND rk.aktif = 1
        ORDER BY rk.sira, rk.id
    """, (uretim_varyant_id,)).fetchall()
    if not kalemler:
        return {'ok': False, 'hata': 'Reçete kalemi bulunamadı'}

    kaynak_batch_kg = round(sum(float(k['miktar_kg']) for k in kalemler), 3)
    if kaynak_batch_kg <= 0:
        return {'ok': False, 'hata': 'Kaynak batch KG sıfır'}

    carpan = test_kg / kaynak_batch_kg
    taban = []
    for k in kalemler:
        if (k['kategori'] or '').upper() == 'BOYA':
            continue
        miktar = round(float(k['miktar_kg']) * carpan, 4)
        if miktar <= 0:
            continue
        taban.append({
            'ad': k['stok_ad'] or '',
            'kod': k['stok_kod'] or '',
            'miktar_kg': miktar,
            'birim': k['birim'] or 'KG',
        })

    return {
        'ok': True,
        'test_kg': round(test_kg, 3),
        'kaynak_batch_kg': kaynak_batch_kg,
        'carpan': round(carpan, 6),
        'taban': taban,
    }


def _rezerv_tuket_talep_hesapla(con, parca_row, tuketim_kg, tuketim_kalemleri=None):
    """Parça tüketim talebini stok_kart_id bazında döner (FAZ-4B ile aynı MPR)."""
    if tuketim_kalemleri is not None:
        if isinstance(tuketim_kalemleri, dict):
            return {'ok': True, 'talep': dict(tuketim_kalemleri)}
        talep = {}
        for k in tuketim_kalemleri:
            sid = k['stok_kart_id']
            talep[sid] = round(talep.get(sid, 0.0) + float(k['gerekli_kg']), 3)
        return {'ok': True, 'talep': talep}

    uv_id = _parca_effective_uv_id(
        parca_row.get('parca_notlar'), parca_row['uretim_varyant_id'],
    )
    rf_renk_id = parca_row['rf_renk_id']
    if not rf_renk_id:
        rf_bilgi = _batch_plan_rf_bilgi(
            con,
            batch_kodu=parca_row['batch_kodu'],
            plan_id=parca_row.get('parca_plan_id') or parca_row.get('batch_plan_id'),
            uretim_varyant_id=uv_id,
        )
        if rf_bilgi:
            rf_renk_id = rf_bilgi.get('rf_renk_id')

    ihtiyac = _mpr_stok_ihtiyac_hesapla(
        con, uv_id, rf_renk_id, tuketim_kg,
        exclude_batch_kodu=parca_row['batch_kodu'],
    )
    if not ihtiyac.get('ok'):
        return {'ok': False, 'hata': ihtiyac.get('hata', 'Stok hesaplanamadı')}
    talep = {}
    for k in ihtiyac.get('kalemler', []):
        sid = k['stok_kart_id']
        talep[sid] = round(talep.get(sid, 0.0) + float(k['gerekli_kg']), 3)
    return {'ok': True, 'talep': talep}


def _batch_aktif_rezerv_var(con, batch_kodu):
    if not _stok_rezerv_tablosu_var(con):
        return False
    return con.execute(
        "SELECT 1 FROM nexgen_stok_rezerv "
        "WHERE batch_kodu=? AND durum='AKTIF' LIMIT 1",
        (batch_kodu,),
    ).fetchone() is not None


def _rezerv_tuket(con, parca_id, tuketim_kalemleri=None, uretilen_kg=None, kontrol_only=False):
    """FAZ-5C-4: Alt emir bitince batch AKTIF rezerv kalan_kg düşür.

    Legacy: batch için AKTIF rezerv yoksa sessizce atlanır.
    Idempotent: aktif stok tüketimi varsa tekrar düşmez.
    kontrol_only: yalnızca yeterlilik kontrolü (yazma yok).
    """
    if not _stok_rezerv_tablosu_var(con):
        return {'ok': True, 'atlandi': True, 'legacy': True, 'guncellenen': 0}

    parca_durum = con.execute(
        "SELECT durum FROM nexgen_uretim_parca WHERE id=?", (parca_id,),
    ).fetchone()
    if (not kontrol_only and parca_durum and parca_durum['durum'] == 'BITTI'
            and _parca_stok_net_tuketim(con, parca_id) < -0.0005):
        return {'ok': True, 'atlandi': True, 'guncellenen': 0}

    row = con.execute("""
        SELECT p.id, p.parca_no, p.hedef_kg, p.uretilen_kg, p.batch_kodu,
               p.plan_id AS parca_plan_id, p.notlar AS parca_notlar,
               b.uretim_varyant_id, b.plan_id AS batch_plan_id,
               pl.rf_renk_id
        FROM nexgen_uretim_parca p
        JOIN nexgen_uretim_batch b ON b.batch_kodu = p.batch_kodu
        LEFT JOIN nexgen_uretim_plan pl
               ON pl.id = COALESCE(p.plan_id, b.plan_id)
        WHERE p.id = ?
    """, (parca_id,)).fetchone()
    if not row:
        return {'ok': False, 'hata': 'Parça bulunamadı'}

    parca_row = dict(row)
    parca_row['uretim_varyant_id'] = _parca_effective_uv_id(
        parca_row.get('parca_notlar'), parca_row['uretim_varyant_id'],
    )
    batch_kodu = parca_row['batch_kodu']
    if not _batch_aktif_rezerv_var(con, batch_kodu):
        return {'ok': True, 'atlandi': True, 'legacy': True, 'guncellenen': 0}

    if uretilen_kg is None:
        uretilen_kg = parca_row['uretilen_kg'] if parca_row['uretilen_kg'] else parca_row['hedef_kg']
    try:
        tuketim_kg = round(float(uretilen_kg), 3)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'Geçersiz uretilen_kg'}
    if tuketim_kg <= 0:
        return {'ok': False, 'hata': 'uretilen_kg sıfırdan büyük olmalı'}

    talep_res = _rezerv_tuket_talep_hesapla(
        con, parca_row, tuketim_kg, tuketim_kalemleri=tuketim_kalemleri,
    )
    if not talep_res.get('ok'):
        return talep_res
    talep = talep_res['talep']

    eksik = []
    for sid, miktar in talep.items():
        if miktar <= 0:
            continue
        rez_row = con.execute("""
            SELECT COALESCE(SUM(kalan_kg), 0) AS toplam
            FROM nexgen_stok_rezerv
            WHERE batch_kodu=? AND stok_kart_id=? AND durum='AKTIF'
        """, (batch_kodu, sid)).fetchone()
        kul = round(float(rez_row['toplam'] or 0), 3) if rez_row else 0.0
        if kul < miktar - 0.0005:
            eksik.append({'stok_kart_id': sid, 'gerekli_kg': miktar, 'kalan_kg': kul})

    if eksik:
        return {
            'ok': False,
            'hata': 'Rezerv yetersiz',
            'eksik_sayisi': len(eksik),
            'eksik_kalemler': eksik,
        }

    if kontrol_only:
        return {'ok': True, 'atlandi': False, 'kontrol': True, 'guncellenen': 0}

    guncellenen = 0
    for sid, miktar in talep.items():
        if miktar <= 0:
            continue
        kalan_tuket = miktar
        satirlar = con.execute("""
            SELECT id, kalan_kg FROM nexgen_stok_rezerv
            WHERE batch_kodu=? AND stok_kart_id=? AND durum='AKTIF'
            ORDER BY id
        """, (batch_kodu, sid)).fetchall()
        for sat in satirlar:
            if kalan_tuket <= 0.0005:
                break
            kk = round(float(sat['kalan_kg'] or 0), 3)
            dus = round(min(kk, kalan_tuket), 3)
            if dus <= 0:
                continue
            yeni = round(kk - dus, 3)
            kalan_tuket = round(kalan_tuket - dus, 3)
            if yeni <= 0.001:
                con.execute("""
                    UPDATE nexgen_stok_rezerv
                    SET kalan_kg=0, durum='TUKETILDI',
                        kapanis_tarihi=datetime('now','localtime')
                    WHERE id=?
                """, (sat['id'],))
            else:
                con.execute(
                    "UPDATE nexgen_stok_rezerv SET kalan_kg=? WHERE id=?",
                    (yeni, sat['id']),
                )
            guncellenen += 1

    return {'ok': True, 'atlandi': False, 'guncellenen': guncellenen, 'batch_kodu': batch_kodu}


def _rezerv_iade(con, parca_id):
    """FAZ-5C-4: Geri alma sonrası batch rezerv kalan_kg geri yükle."""
    if not _stok_rezerv_tablosu_var(con):
        return {'ok': True, 'atlandi': True, 'legacy': True, 'guncellenen': 0}

    row = con.execute("""
        SELECT p.id, p.durum, p.hedef_kg, p.uretilen_kg, p.batch_kodu,
               p.plan_id AS parca_plan_id,
               b.uretim_varyant_id, b.plan_id AS batch_plan_id,
               pl.rf_renk_id
        FROM nexgen_uretim_parca p
        JOIN nexgen_uretim_batch b ON b.batch_kodu = p.batch_kodu
        LEFT JOIN nexgen_uretim_plan pl
               ON pl.id = COALESCE(p.plan_id, b.plan_id)
        WHERE p.id = ?
    """, (parca_id,)).fetchone()
    if not row:
        return {'ok': False, 'hata': 'Parça bulunamadı'}
    if row['durum'] != 'BITTI':
        return {'ok': True, 'atlandi': True, 'guncellenen': 0}

    parca_row = dict(row)
    batch_kodu = parca_row['batch_kodu']
    rezerv_var = con.execute(
        "SELECT 1 FROM nexgen_stok_rezerv WHERE batch_kodu=? LIMIT 1",
        (batch_kodu,),
    ).fetchone()
    if not rezerv_var:
        return {'ok': True, 'atlandi': True, 'legacy': True, 'guncellenen': 0}

    tuketim_kg = parca_row['uretilen_kg'] if parca_row['uretilen_kg'] else parca_row['hedef_kg']
    try:
        tuketim_kg = round(float(tuketim_kg), 3)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'Geçersiz tüketim KG'}

    talep_res = _rezerv_tuket_talep_hesapla(con, parca_row, tuketim_kg)
    if not talep_res.get('ok'):
        return talep_res
    talep = talep_res['talep']

    guncellenen = 0
    for sid, miktar in talep.items():
        if miktar <= 0:
            continue
        kalan_iade = miktar
        satirlar = con.execute("""
            SELECT id, kalan_kg, miktar_kg, durum FROM nexgen_stok_rezerv
            WHERE batch_kodu=? AND stok_kart_id=?
              AND durum IN ('AKTIF', 'TUKETILDI')
            ORDER BY id DESC
        """, (batch_kodu, sid)).fetchall()
        for sat in satirlar:
            if kalan_iade <= 0.0005:
                break
            kk = round(float(sat['kalan_kg'] or 0), 3)
            mk = round(float(sat['miktar_kg'] or 0), 3)
            bosluk = round(mk - kk, 3)
            if bosluk <= 0.0005:
                continue
            ekle = round(min(bosluk, kalan_iade), 3)
            yeni = round(min(kk + ekle, mk), 3)
            kalan_iade = round(kalan_iade - ekle, 3)
            con.execute("""
                UPDATE nexgen_stok_rezerv
                SET kalan_kg=?, durum='AKTIF', kapanis_tarihi=NULL
                WHERE id=?
            """, (yeni, sat['id']))
            guncellenen += 1

    return {'ok': True, 'atlandi': False, 'guncellenen': guncellenen, 'batch_kodu': batch_kodu}


def _rezerv_tablo_kolonlari(con):
    if not _stok_rezerv_tablosu_var(con):
        return set()
    return {r[1] for r in con.execute("PRAGMA table_info(nexgen_stok_rezerv)").fetchall()}


def _rezerv_aktif_iptal(con, batch_kodu=None, plan_id=None, hazirlik_id=None, nedeni=None):
    """FAZ-5C-5: AKTIF rezervleri IPTAL yap. kalan_kg korunur, TUKETILDI dokunulmaz."""
    if not _stok_rezerv_tablosu_var(con):
        return {'ok': True, 'atlandi': True, 'legacy': True, 'guncellenen': 0}

    filtre = ["durum='AKTIF'"]
    params = []
    if batch_kodu:
        filtre.append("batch_kodu=?")
        params.append(batch_kodu)
    if plan_id is not None:
        filtre.append("plan_id=?")
        params.append(plan_id)
    if hazirlik_id is not None:
        filtre.append("hazirlik_id=?")
        params.append(hazirlik_id)
    if len(filtre) == 1:
        return {'ok': False, 'hata': 'Rezerv iptal filtresi gerekli'}

    satirlar = con.execute(
        f"SELECT id, notlar FROM nexgen_stok_rezerv WHERE {' AND '.join(filtre)}",
        params,
    ).fetchall()
    if not satirlar:
        return {'ok': True, 'atlandi': True, 'guncellenen': 0}

    cols = _rezerv_tablo_kolonlari(con)
    nedeni_trim = (nedeni or '').strip() or None
    guncellenen = 0
    for sat in satirlar:
        set_parts = ["durum='IPTAL'"]
        upd_params = []
        if 'iptal_tarihi' in cols:
            set_parts.append("iptal_tarihi=datetime('now','localtime')")
        else:
            set_parts.append("kapanis_tarihi=datetime('now','localtime')")
        if 'iptal_nedeni' in cols:
            set_parts.append("iptal_nedeni=?")
            upd_params.append(nedeni_trim or '')
        elif nedeni_trim:
            mevcut = (sat['notlar'] or '').strip()
            yeni_not = (
                f"{mevcut} | İPTAL: {nedeni_trim}".strip(' |')
                if mevcut else f"İPTAL: {nedeni_trim}"
            )
            set_parts.append("notlar=?")
            upd_params.append(yeni_not)
        upd_params.append(sat['id'])
        con.execute(
            f"UPDATE nexgen_stok_rezerv SET {', '.join(set_parts)} WHERE id=?",
            upd_params,
        )
        guncellenen += 1

    return {'ok': True, 'atlandi': False, 'guncellenen': guncellenen}


def _parca_stok_net_tuketim(con, parca_id):
    """Parça için net stok tüketimi (negatif = aktif tüketim var)."""
    row = con.execute("""
        SELECT COALESCE(SUM(miktar_kg), 0) AS net
        FROM nexgen_stok_hareket
        WHERE referans_id = ?
          AND (
            (referans_tip = 'URETIM_PARCA' AND hareket_tipi = 'URETIM_TUKETIM')
            OR (referans_tip = 'URETIM_PARCA_IPTAL' AND hareket_tipi = 'URETIM_TUKETIM_IPTAL')
          )
    """, (parca_id,)).fetchone()
    return round(float(row['net'] or 0), 3) if row else 0.0


def _parca_stok_tuket(con, parca_id, uretilen_kg=None, olusturan_id=None):
    """Alt emir bitince hammadde tüketimini nexgen_stok_hareket'e yazar.

    Idempotent: net tüketim (URETIM_PARCA − URETIM_PARCA_IPTAL) aktifse tekrar yazmaz.
    Stok yetersizse hareket yazmaz, ok=False döner.
    """
    if _parca_stok_net_tuketim(con, parca_id) < -0.0005:
        return {'ok': True, 'atlandi': True, 'hareket_sayisi': 0}

    row = con.execute("""
        SELECT p.id, p.parca_no, p.hedef_kg, p.formul_batch_kg, p.batch_kodu,
               p.plan_id AS parca_plan_id, p.notlar AS parca_notlar,
               b.lot_kodu, b.uretim_varyant_id, b.plan_id AS batch_plan_id,
               pl.rf_renk_id, pl.cari_id, pl.planlama_siparis_id
        FROM nexgen_uretim_parca p
        JOIN nexgen_uretim_batch b ON b.batch_kodu = p.batch_kodu
        LEFT JOIN nexgen_uretim_plan pl
               ON pl.id = COALESCE(p.plan_id, b.plan_id)
        WHERE p.id = ?
    """, (parca_id,)).fetchone()
    if not row:
        return {'ok': False, 'hata': 'Parça bulunamadı'}

    if uretilen_kg is None:
        uretilen_kg = row['hedef_kg']
    try:
        tuketim_kg = round(float(uretilen_kg), 3)
    except (TypeError, ValueError):
        return {'ok': False, 'hata': 'Geçersiz uretilen_kg'}
    if tuketim_kg <= 0:
        return {'ok': False, 'hata': 'uretilen_kg sıfırdan büyük olmalı'}

    uv_id = _parca_effective_uv_id(row['parca_notlar'], row['uretim_varyant_id'])
    rf_renk_id = row['rf_renk_id']
    if not rf_renk_id:
        rf_bilgi = _batch_plan_rf_bilgi(
            con,
            batch_kodu=row['batch_kodu'],
            plan_id=row['parca_plan_id'] or row['batch_plan_id'],
            uretim_varyant_id=uv_id,
        )
        if rf_bilgi:
            rf_renk_id = rf_bilgi.get('rf_renk_id')

    ihtiyac = _mpr_stok_ihtiyac_hesapla(
        con, uv_id, rf_renk_id, tuketim_kg,
        exclude_batch_kodu=row['batch_kodu'],
    )
    if not ihtiyac.get('ok'):
        return {'ok': False, 'hata': ihtiyac.get('hata', 'Stok hesaplanamadı')}
    if not ihtiyac.get('yeterli_mi'):
        eksik = [k for k in ihtiyac.get('kalemler', []) if not k.get('yeterli')]
        return {
            'ok': False,
            'hata': 'Stok yetersiz',
            'eksik_sayisi': ihtiyac.get('eksik_sayisi', len(eksik)),
            'eksik_kalemler': eksik,
            'kalemler': ihtiyac.get('kalemler', []),
        }

    talep = {}
    for k in ihtiyac.get('kalemler', []):
        sid = k['stok_kart_id']
        talep[sid] = round(talep.get(sid, 0.0) + float(k['gerekli_kg']), 3)

    batch_kodu = row['batch_kodu']
    lot_kodu = row['lot_kodu'] or '—'
    parca_no = row['parca_no']
    aciklama = f"Batch {batch_kodu} / LOT {lot_kodu} / Alt emir {parca_no}"
    uid = olusturan_id if olusturan_id is not None else _kullanici_id()

    hareket_sayisi = 0
    for sid, miktar in talep.items():
        if miktar <= 0:
            continue
        negatif = round(-miktar, 3)
        _stok_hareket_yaz(
            con, sid, 'URETIM_TUKETIM', negatif,
            aciklama=aciklama,
            referans_tip='URETIM_PARCA',
            referans_id=parca_id,
            olusturan_id=uid,
        )
        hareket_sayisi += 1

    return {
        'ok': True,
        'atlandi': False,
        'hareket_sayisi': hareket_sayisi,
        'tuketim_kg': tuketim_kg,
        'batch_kodu': batch_kodu,
        'lot_kodu': lot_kodu,
        'parca_no': parca_no,
    }


def _parca_stok_iade(con, parca_id, gerekce, olusturan_id=None):
    """BITTI alt emir stok tüketimini ters kayıtla iade eder (silme yok)."""
    parca = con.execute("""
        SELECT id, durum, batch_kodu, parca_no, baslama_zamani
        FROM nexgen_uretim_parca WHERE id=?
    """, (parca_id,)).fetchone()
    if not parca:
        return {'ok': False, 'hata': 'Parça bulunamadı'}
    if parca['durum'] != 'BITTI':
        return {'ok': False, 'hata': f'Parça BITTI değil (durum: {parca["durum"]})'}

    iptal_var = con.execute(
        "SELECT id FROM nexgen_stok_hareket "
        "WHERE referans_tip='URETIM_PARCA_IPTAL' AND referans_id=? LIMIT 1",
        (parca_id,),
    ).fetchone()
    if iptal_var:
        return {'ok': True, 'atlandi': True, 'hareket_sayisi': 0}

    originals = con.execute("""
        SELECT stok_kart_id, miktar_kg
        FROM nexgen_stok_hareket
        WHERE referans_tip='URETIM_PARCA' AND referans_id=?
          AND hareket_tipi='URETIM_TUKETIM' AND miktar_kg < 0
    """, (parca_id,)).fetchall()
    if not originals:
        return {'ok': False, 'hata': 'Geri alınacak stok tüketimi bulunamadı'}

    gerekce_trim = (gerekce or '').strip()
    aciklama = f"Geri alma — Alt emir {parca['parca_no']}: {gerekce_trim}"
    uid = olusturan_id if olusturan_id is not None else _kullanici_id()
    hareket_sayisi = 0
    for orig in originals:
        pozitif = round(abs(float(orig['miktar_kg'])), 3)
        if pozitif <= 0:
            continue
        sid = orig['stok_kart_id']
        _stok_hareket_yaz(
            con, sid, 'URETIM_TUKETIM_IPTAL', pozitif,
            aciklama=aciklama,
            referans_tip='URETIM_PARCA_IPTAL',
            referans_id=parca_id,
            olusturan_id=uid,
        )
        hareket_sayisi += 1

    return {
        'ok': True,
        'atlandi': False,
        'hareket_sayisi': hareket_sayisi,
        'parca_no': parca['parca_no'],
    }


def _parca_geri_al_uygula(con, parca_id, batch_kodu, gerekce):
    """FAZ-4D: stok iade + parça durum geri sarma + RF/batch/plan senkron."""
    stok = _parca_stok_iade(con, parca_id, gerekce)
    if not stok.get('ok'):
        return stok

    rezerv = _rezerv_iade(con, parca_id)
    if not rezerv.get('ok'):
        return rezerv

    parca = con.execute(
        "SELECT id, baslama_zamani, batch_kodu, plan_id FROM nexgen_uretim_parca WHERE id=?",
        (parca_id,),
    ).fetchone()
    if not parca:
        return {'ok': False, 'hata': 'Parça bulunamadı'}

    yeni_durum = 'DEVAM' if parca['baslama_zamani'] else 'HAZIR'
    con.execute("""
        UPDATE nexgen_uretim_parca
        SET durum=?, uretilen_kg=0, bitis_zamani=NULL,
            updated_at=datetime('now','localtime')
        WHERE id=?
    """, (yeni_durum, parca_id))

    _rf_kullanim_tablet_sync(con, batch_kodu, uretim_emir_id=parca_id)

    batch = con.execute(
        "SELECT durum, plan_id FROM nexgen_uretim_batch WHERE batch_kodu=?",
        (batch_kodu,),
    ).fetchone()
    batch_yeni_durum = None
    if batch and batch['durum'] == 'BITTI':
        acik = con.execute("""
            SELECT COUNT(*) AS c FROM nexgen_uretim_parca
            WHERE batch_kodu=? AND durum NOT IN ('BITTI')
        """, (batch_kodu,)).fetchone()
        if acik and acik['c'] > 0:
            con.execute(
                "UPDATE nexgen_uretim_batch SET durum='DEVAM' WHERE batch_kodu=?",
                (batch_kodu,),
            )
            batch_yeni_durum = 'DEVAM'

    plan_id = parca['plan_id'] or (batch['plan_id'] if batch else None)
    plan_yeni_durum = None
    if plan_id:
        plan = con.execute(
            "SELECT durum FROM nexgen_uretim_plan WHERE id=?", (plan_id,)
        ).fetchone()
        if plan and plan['durum'] == 'BITTI':
            con.execute(
                "UPDATE nexgen_uretim_plan SET durum='BASLADI' WHERE id=?",
                (plan_id,),
            )
            plan_yeni_durum = 'BASLADI'

    return {
        'ok': True,
        'parca_id': parca_id,
        'yeni_durum': yeni_durum,
        'stok_iade': stok,
        'rezerv_iade': rezerv,
        'batch_yeni_durum': batch_yeni_durum,
        'plan_yeni_durum': plan_yeni_durum,
    }


def _parca_bitir_uygula(con, parca_id, hedef_kg, notlar=None):
    """FAZ-4B/5C-4: stok tüketimi + rezerv kapatma + parça BITTI (tek transaction içi)."""
    row = con.execute(
        "SELECT batch_kodu, durum FROM nexgen_uretim_parca WHERE id=?",
        (parca_id,),
    ).fetchone()
    if not row:
        return {'ok': False, 'hata': 'Alt emir bulunamadı'}
    if row['durum'] == 'BITTI':
        return {'ok': True, 'atlandi': True, 'uretilen_kg': round(float(hedef_kg), 3)}
    if row['durum'] not in ('DEVAM', 'HAZIR'):
        return {'ok': False, 'hata': f'{row["durum"]} durumundaki alt emir bitirilemez'}

    depo_chk = _batch_depo_hazir_zorunlu(con, row['batch_kodu'])
    if not depo_chk.get('ok'):
        return depo_chk

    uretilen_kg = round(float(hedef_kg), 3)
    rezerv_kontrol = _rezerv_tuket(
        con, parca_id, uretilen_kg=uretilen_kg, kontrol_only=True,
    )
    if not rezerv_kontrol.get('ok'):
        return rezerv_kontrol

    stok = _parca_stok_tuket(con, parca_id, uretilen_kg=uretilen_kg)
    if not stok.get('ok'):
        return stok

    rezerv = _rezerv_tuket(con, parca_id, uretilen_kg=uretilen_kg)
    if not rezerv.get('ok'):
        return rezerv

    update_fields = [
        "durum='BITTI'",
        "uretilen_kg=?",
        "bitis_zamani=datetime('now','localtime')",
        "updated_at=datetime('now','localtime')",
    ]
    params = [uretilen_kg]
    if notlar:
        update_fields.append("notlar=?")
        params.append(notlar)
    params.append(parca_id)
    con.execute(
        f"UPDATE nexgen_uretim_parca SET {', '.join(update_fields)} "
        f"WHERE id=? AND durum IN ('DEVAM','HAZIR')",
        params,
    )
    if con.total_changes == 0:
        return {'ok': False, 'hata': 'Alt emir zaten bitirilmiş veya durum uygun değil'}
    return {
        'ok': True,
        'uretilen_kg': uretilen_kg,
        'stok_atlandi': stok.get('atlandi'),
        'rezerv_atlandi': rezerv.get('atlandi'),
        'hareket_sayisi': stok.get('hareket_sayisi', 0),
        'rezerv_guncellenen': rezerv.get('guncellenen', 0),
    }


def _parca_stok_yetersiz_response(stok):
    """Bitirme endpoint'leri için ortak 400 gövdesi."""
    eksik = stok.get('eksik_kalemler', [])
    return jsonify({
        'ok': False,
        'hata': stok.get('hata', 'Stok yetersiz'),
        'eksik_sayisi': stok.get('eksik_sayisi', len(eksik)),
        'eksik_kalemler': eksik,
        'kalemler': stok.get('kalemler', []),
    }), 400


@nexgen_bp.route('/api/plan/stok-onizle', methods=['POST'])
@login_gerekli
def api_plan_stok_onizle():
    """MPR stok ihtiyacı önizleme — salt okuma, hareket yazmaz."""
    if not (yetki_var('nexgen.plan.manage', 'can_manage') or
            yetki_var('nexgen.plan.view', 'can_view')):
        return jsonify({'ok': False, 'hata': 'Yetki yok'}), 403

    d = request.get_json(silent=True) or {}
    plan_id = d.get('plan_id')
    uv_id = d.get('uretim_varyant_id')
    rf_renk_id = d.get('rf_renk_id')
    planlanan_kg = d.get('planlanan_kg')

    con = _db()
    try:
        if plan_id:
            try:
                plan_id = int(plan_id)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'plan_id geçersiz'}), 400
            sonuc = _mpr_stok_ihtiyac_birlestir(con, plan_id)
            if not sonuc.get('ok'):
                return jsonify(sonuc), 400
            return jsonify(sonuc)

        if not uv_id:
            return jsonify({'ok': False, 'hata': 'uretim_varyant_id zorunlu'}), 400

        uv = con.execute(
            "SELECT id FROM nexgen_uretim_varyant WHERE id=? AND aktif=1",
            (uv_id,),
        ).fetchone()
        if not uv:
            return jsonify({'ok': False, 'hata': 'Üretim varyantı bulunamadı'}), 404

        sonuc = _mpr_stok_ihtiyac_hesapla(con, uv_id, rf_renk_id, planlanan_kg)
        if not sonuc.get('ok'):
            return jsonify(sonuc), 400
        return jsonify(sonuc)
    finally:
        con.close()


@nexgen_bp.route('/api/mi-merkez/analiz', methods=['POST'])
@login_gerekli
def api_mi_merkez_analiz():
    """Malzeme İhtiyaç Merkezi — çoklu plan malzeme analizi (salt okuma, DB yazmaz)."""
    if not (yetki_var('nexgen.plan.manage', 'can_manage') or
            yetki_var('nexgen.plan.view', 'can_view')):
        return jsonify({'ok': False, 'hata': 'Yetki yok'}), 403

    d = request.get_json(silent=True) or {}
    plan_ids = d.get('plan_ids')
    if plan_ids is None:
        return jsonify({'ok': False, 'hata': 'plan_ids zorunlu'}), 400
    if not isinstance(plan_ids, list):
        return jsonify({'ok': False, 'hata': 'plan_ids liste olmalı'}), 400
    if len(plan_ids) > 200:
        return jsonify({
            'ok': False,
            'hata': 'En fazla 200 plan aynı anda analiz edilebilir.',
        }), 400
    for raw in plan_ids:
        if isinstance(raw, bool) or not isinstance(raw, int):
            return jsonify({'ok': False, 'hata': f'Geçersiz plan_id: {raw!r}'}), 400

    exclude_batch_kodu = d.get('exclude_batch_kodu')
    if exclude_batch_kodu is not None and not isinstance(exclude_batch_kodu, str):
        exclude_batch_kodu = str(exclude_batch_kodu)

    con = _db()
    try:
        sonuc = _mpr_stok_ihtiyac_coklu_plan(
            con, plan_ids, exclude_batch_kodu=exclude_batch_kodu,
        )
        if not sonuc.get('ok'):
            return jsonify(sonuc), 400
        return jsonify(sonuc)
    except Exception:
        return jsonify({'ok': False, 'hata': 'Analiz hesaplanamadı'}), 500
    finally:
        con.close()


@nexgen_bp.route('/api/plan/<int:plan_id>/stok-durum')
@login_gerekli
def api_plan_stok_durum(plan_id):
    """Hafif stok durum sorgusu — liste rozeti için (FAZ-1 KRİTİK #1).

    FAZ-MRP-03: Depo hazırlık durumu ve açık SA özeti de eklendi (bilgi amaçlı).
    Hard block değişmedi — sadece bilgi alanları eklendi.
    """
    if not (yetki_var('nexgen.plan.manage', 'can_manage') or
            yetki_var('nexgen.plan.view', 'can_view')):
        return jsonify({'ok': False, 'hata': 'Yetki yok'}), 403
    con = _db()
    try:
        sonuc = _mpr_stok_ihtiyac_birlestir(con, plan_id)
        if not sonuc.get('ok'):
            return jsonify({'ok': False, 'hata': sonuc.get('hata')}), 400

        # Toplam yolda_kg hesabı (tüm kalemler üzerinden)
        toplam_yolda_kg = round(
            sum(float(k.get('yolda_kg') or 0) for k in sonuc.get('kalemler', [])), 3
        )
        toplam_net_eksik_kg = round(
            sum(float(k.get('net_eksik_kg') or 0) for k in sonuc.get('kalemler', [])), 3
        )

        # Depo hazırlık durumu (varsa)
        depo_hazirlik = None
        if _depo_hazirlik_tablosu_var(con):
            dh = con.execute("""
                SELECT id, hazirlik_no, durum, hazir_tarihi
                FROM nexgen_depo_hazirlik
                WHERE plan_id=? AND durum NOT IN ('IPTAL')
                ORDER BY id DESC LIMIT 1
            """, (plan_id,)).fetchone()
            if dh:
                depo_hazirlik = {
                    'id': dh['id'],
                    'hazirlik_no': dh['hazirlik_no'],
                    'durum': dh['durum'],
                    'hazir_tarihi': dh['hazir_tarihi'],
                }

        resp = {
            'ok': True,
            'plan_id': plan_id,
            'yeterli_mi': sonuc.get('yeterli_mi'),
            'eksik_sayisi': sonuc.get('eksik_sayisi', 0),
            # FAZ-MRP-03 bilgi alanları
            'toplam_yolda_kg': toplam_yolda_kg,
            'toplam_net_eksik_kg': toplam_net_eksik_kg,
            'depo_hazirlik': depo_hazirlik,
        }
        return jsonify(resp)
    finally:
        con.close()


@nexgen_bp.route('/api/batch/<batch_kodu>/formul-icerik')
@login_gerekli
def api_batch_formul_icerik(batch_kodu):
    """Alt emir formül hazırlık listesi — salt okuma, FAZ-4B tüketim ile aynı hesap."""
    if not yetki_var('nexgen.tablet.view', 'can_view'):
        return jsonify({'ok': False, 'hata': 'Yetki yok'}), 403

    parca_id = request.args.get('parca_id', type=int)

    con = _db()
    try:
        batch = con.execute("""
            SELECT nb.batch_kodu, nb.lot_kodu, nb.uretim_varyant_id, nb.plan_id,
                   nb.planlanan_kg,
                   COALESCE(c.unvan, np.musteri_adi) AS cari_ad,
                   np.siparis_no, np.rf_renk_id AS plan_rf_renk_id
            FROM nexgen_uretim_batch nb
            LEFT JOIN nexgen_uretim_plan np ON np.id = nb.plan_id
            LEFT JOIN nexgen_cari c ON c.id = np.cari_id
            WHERE nb.batch_kodu = ?
        """, (batch_kodu,)).fetchone()
        if not batch:
            return jsonify({'ok': False, 'hata': 'Batch bulunamadı'}), 404

        if not _parca_tablosu_var(con):
            return jsonify({'ok': False, 'hata': 'Migration 072 çalıştırılmadı'}), 500

        parca = _batch_formul_parca_sec(con, batch_kodu, parca_id=parca_id)
        if not parca:
            return jsonify({'ok': False, 'hata': 'Alt emir bulunamadı'}), 404

        parca_kg = round(float(parca['hedef_kg']), 3)
        rf_bilgi = _batch_plan_rf_bilgi(
            con,
            batch_kodu=batch_kodu,
            plan_id=batch['plan_id'],
            uretim_varyant_id=batch['uretim_varyant_id'],
        )
        rf_renk_id = rf_bilgi.get('rf_renk_id') if rf_bilgi else batch['plan_rf_renk_id']

        batch_meta = _batch_uretim_hesapla(
            con, batch['uretim_varyant_id'], float(batch['planlanan_kg']),
            rf_renk_id=rf_renk_id,
        )
        toplam_kg = batch_meta.get('uretilecek_kg') if batch_meta.get('ok') else float(batch['planlanan_kg'] or 0)
        if toplam_kg <= 0:
            row_sum = con.execute("""
                SELECT COALESCE(SUM(hedef_kg), 0) AS s
                FROM nexgen_uretim_parca WHERE batch_kodu=?
            """, (batch_kodu,)).fetchone()
            toplam_kg = float(row_sum['s'] or 0) if row_sum else parca_kg
        toplam_kg = round(toplam_kg, 3)

        ihtiyac_parca = _mpr_stok_ihtiyac_hesapla(
            con, batch['uretim_varyant_id'], rf_renk_id, parca_kg,
        )
        if not ihtiyac_parca.get('ok'):
            return jsonify({'ok': False, 'hata': ihtiyac_parca.get('hata', 'Hesaplanamadı')}), 400

        ihtiyac_toplam = _mpr_stok_ihtiyac_hesapla(
            con, batch['uretim_varyant_id'], rf_renk_id, float(batch['planlanan_kg']),
        )
        if not ihtiyac_toplam.get('ok'):
            return jsonify({'ok': False, 'hata': ihtiyac_toplam.get('hata', 'Toplam hesaplanamadı')}), 400

        parca_blok = _formul_bolum_yap(con, ihtiyac_parca, parca_kg)
        toplam_blok = _formul_bolum_yap(con, ihtiyac_toplam, toplam_kg)

        return jsonify({
            'ok': True,
            'batch_kodu': batch_kodu,
            'lot_kodu': batch['lot_kodu'],
            'cari_ad': batch['cari_ad'],
            'siparis_no': batch['siparis_no'],
            'rf_kod': rf_bilgi.get('rf_kod') if rf_bilgi else None,
            'rf_renk_ad': rf_bilgi.get('renk_ad') if rf_bilgi else None,
            'rf_renk_id': rf_renk_id,
            'rf_var': bool(rf_renk_id),
            'parca_id': parca['id'],
            'parca_no': parca['parca_no'],
            'parca_durum': parca['durum'],
            'siparis_kg': batch_meta.get('siparis_kg', float(batch['planlanan_kg'] or 0)),
            'formul_batch_kg': batch_meta.get('formul_batch_kg'),
            'batch_sayisi': batch_meta.get('batch_sayisi'),
            'uretilecek_kg': toplam_kg,
            'fazla_kg': batch_meta.get('fazla_kg', 0),
            'toplam_kg': toplam_kg,
            'parca': parca_blok,
            'toplam': toplam_blok,
            'batch_uretim': batch_meta,
            # FAZ-4C geriye uyumluluk
            'kg': parca_kg,
            'taban_batch_kg': ihtiyac_parca.get('taban_batch_kg'),
            'taban': parca_blok['taban'],
            'rf': parca_blok['rf'],
        })
    finally:
        con.close()


@nexgen_bp.route('/api/tablet/arge/formul-onizle')
@login_gerekli
def api_tablet_arge_formul_onizle():
    """ARGE numune taban hammadde önizleme — test-olustur ölçeği, DB yazmaz."""
