# ─────────────────────────────────────────────────────────────
# ENDPOINT: Migration 098 çalıştır (sadece admin, idempotent)
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/admin/migration-098-calistir', methods=['POST'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_migration_098_calistir():
    """Migration 098'i idempotent olarak çalıştırır.
    Admin yetkisi gerektirir. Birden fazla çalıştırmak güvenlidir.
    """
    try:
        import importlib.util
        mig_path = os.path.join(os.path.dirname(__file__), '..', '..', 'migrations', '098_nexgen_rf_revizyon.py')
        mig_path = os.path.abspath(mig_path)
        if not os.path.exists(mig_path):
            return jsonify({'ok': False, 'hata': f'Migration dosyasi bulunamadi: {mig_path}'}), 404
        spec = importlib.util.spec_from_file_location("migration_098", mig_path)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        mod.run()
        return jsonify({'ok': True, 'mesaj': 'Migration 098 basariyla calistirildi.'})
    except Exception as e:
        return jsonify({'ok': False, 'hata': str(e)}), 500


_RF_REVIZYON_NEDENLER = {
    'KALIP_CARPANI': 'Kalip Carpani',
    'ANA_FORMUL':    'Ana Formul',
    'TITAN':         'Titan',
    'PIGMENT':       'Pigment',
    'HAMMADDE':      'Hammadde',
    'MUSTERI_TALEBI': 'Musteri Talebi',
    'DIGER':         'Diger',
    'ILKREVIZYON':   'Ilk Revizyon',
}


def _rf_revizyon_tablosu_var(con):
    r = con.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='nexgen_rf_revizyon'"
    ).fetchone()
    return r is not None


def _rf_revizyon_kolon_var(con, kolon):
    cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_rf_revizyon)").fetchall()]
    return kolon in cols


def _rf_aktif_rev_no_var(con):
    return _kolon_var_chk(con, 'nexgen_rf_renk', 'aktif_rev_no')


def _kolon_var_chk(con, tablo, kolon):
    cols = [c[1] for c in con.execute(f"PRAGMA table_info({tablo})").fetchall()]
    return kolon in cols


def _uretim_kodu_kolon_var(con, tablo='nexgen_rf_formul_uygunluk'):
    return _kolon_var_chk(con, tablo, 'uretim_kodu')


def _uretim_kodu_girdi_dogrula(rf_row, formul_kod: str) -> dict:
    """Çekirdek formül + aktif onaylı renk doğrulaması."""
    rf = dict(rf_row) if rf_row else {}
    fk = (formul_kod or '').strip().upper()
    if not cekirdek_formul_mu(fk):
        return {'ok': False, 'hata': f'Legacy/test formül ile üretim kodu oluşturulamaz: {fk}'}
    if not yeni_secimde_renk_gosterilebilir_mi(rf):
        rk = rf.get('rf_kod') or ''
        if rf.get('aktif') == 0:
            return {'ok': False, 'hata': 'Pasif renk için üretim kodu oluşturulamaz.'}
        return {'ok': False, 'hata': f'Geçersiz veya onaysız renk: {rk}'}
    renk_kodu = renk_sayisal_onek(rf.get('rf_kod'))
    if not renk_kodu:
        return {'ok': False, 'hata': 'Sayısal çekirdek renk kodu bulunamadı.'}
    uretim_kodu = uretim_kodu_uret(fk, renk_kodu)
    if not uretim_kodu_format_gecerli_mi(uretim_kodu):
        return {'ok': False, 'hata': f'Üretim kodu formatı geçersiz: {uretim_kodu}'}
    return {
        'ok': True,
        'ana_formul_kodu': fk,
        'renk_kodu': renk_kodu,
        'uretim_kodu': uretim_kodu,
    }


def _uretim_kodu_cakisma_kontrol(con, uretim_kodu, rf_renk_id, formul_id) -> dict:
    """Aynı kod farklı identity'de varsa BLOCKER."""
    if not _uretim_kodu_kolon_var(con):
        return {'ok': True}
    row = con.execute("""
        SELECT id, rf_renk_id, formul_id, uretim_kodu
        FROM nexgen_rf_formul_uygunluk
        WHERE uretim_kodu=? AND aktif=1
          AND NOT (rf_renk_id=? AND formul_id=?)
        LIMIT 1
    """, (uretim_kodu, rf_renk_id, formul_id)).fetchone()
    if row:
        return {
            'ok': False,
            'blocker': True,
            'hata': (
                f'Üretim kodu {uretim_kodu} başka bir formül-renk kombinasyonunda kayıtlı '
                f'(uygunluk_id={row["id"]}).'
            ),
        }
    return {'ok': True}


def _uretim_kodu_mevcut_bul(con, rf_renk_id, formul_id) -> dict | None:
    """Aktif uygunluk kaydından mevcut üretim kodunu döner."""
    cols = [c[1] for c in con.execute("PRAGMA table_info(nexgen_rf_formul_uygunluk)").fetchall()]
    sel_uk = 'uretim_kodu' if 'uretim_kodu' in cols else "NULL AS uretim_kodu"
    sel_af = 'ana_formul_kodu' if 'ana_formul_kodu' in cols else "NULL AS ana_formul_kodu"
    sel_rk = 'renk_kodu' if 'renk_kodu' in cols else "NULL AS renk_kodu"
    row = con.execute(f"""
        SELECT id AS uygunluk_id, {sel_uk}, {sel_af}, {sel_rk}
        FROM nexgen_rf_formul_uygunluk
        WHERE rf_renk_id=? AND formul_id=? AND aktif=1
        LIMIT 1
    """, (rf_renk_id, formul_id)).fetchone()
    if not row:
        return None
    d = dict(row)
    if d.get('uretim_kodu'):
        return d
    rf = con.execute("SELECT rf_kod FROM nexgen_rf_renk WHERE id=?", (rf_renk_id,)).fetchone()
    frm = con.execute("SELECT kod FROM nexgen_formul WHERE id=?", (formul_id,)).fetchone()
    if rf and frm:
        hesap = _uretim_kodu_girdi_dogrula({'rf_kod': rf['rf_kod'], 'aktif': 1, 'durum': 'ONAYLI'}, frm['kod'])
        if hesap.get('ok'):
            d.update({
                'uretim_kodu': hesap['uretim_kodu'],
                'ana_formul_kodu': hesap['ana_formul_kodu'],
                'renk_kodu': hesap['renk_kodu'],
            })
    return d if d.get('uretim_kodu') else None


def _uretim_kodu_db_dolu_mi(con, rf_renk_id, formul_id) -> dict | None:
    """Yalnız DB kolonundaki dolu üretim kodunu döner (hesaplama yok)."""
    if not _uretim_kodu_kolon_var(con):
        return None
    row = con.execute("""
        SELECT id AS uygunluk_id, uretim_kodu, ana_formul_kodu, renk_kodu
        FROM nexgen_rf_formul_uygunluk
        WHERE rf_renk_id=? AND formul_id=? AND aktif=1
          AND uretim_kodu IS NOT NULL AND TRIM(uretim_kodu) != ''
          AND ana_formul_kodu IS NOT NULL AND TRIM(ana_formul_kodu) != ''
          AND renk_kodu IS NOT NULL AND TRIM(renk_kodu) != ''
        LIMIT 1
    """, (rf_renk_id, formul_id)).fetchone()
    return dict(row) if row else None


def _yeni_plan_uretim_kodu_zorunlu_dogrula(con, formul_id, rf_renk_id) -> dict:
    """Yeni çekirdek plan/MPR için DB'de dolu üretim kodu zorunluluğu."""
    frm = con.execute("SELECT kod FROM nexgen_formul WHERE id=?", (formul_id,)).fetchone()
    if not frm or not cekirdek_formul_mu(frm['kod']):
        return {'ok': True, 'legacy': True}
    uygun = con.execute("""
        SELECT id FROM nexgen_rf_formul_uygunluk
        WHERE rf_renk_id=? AND formul_id=? AND aktif=1
    """, (rf_renk_id, formul_id)).fetchone()
    if not uygun:
        return {
            'ok': False,
            'hata': 'Seçilen formül ve renk için aktif üretim kodu bulunamadı.',
            'status': 409,
        }
    uk = _uretim_kodu_db_dolu_mi(con, rf_renk_id, formul_id)
    if not uk or not uretim_kodu_format_gecerli_mi(uk.get('uretim_kodu')):
        return {
            'ok': False,
            'hata': 'Seçilen formül ve renk için aktif üretim kodu bulunamadı.',
            'status': 409,
        }
    return {'ok': True, **uk}


def _cekirdek_formul_rf_secenekleri(con, formul_id, *, uretim_kodu_zorunlu=True) -> list[dict]:
    """Seçili çekirdek formüle bağlı aktif uygunluk → onaylı çekirdek renk listesi."""
    frm = con.execute(
        "SELECT id, kod FROM nexgen_formul WHERE id=?", (formul_id,)
    ).fetchone()
    if not frm or not cekirdek_formul_mu(frm['kod']):
        return []

    rows = con.execute("""
        SELECT u.id AS uygunluk_id, u.formul_id, u.rf_renk_id,
               u.uretim_kodu, u.ana_formul_kodu, u.renk_kodu,
               rf.rf_kod, rf.ad AS renk_adi, rf.durum, rf.aktif,
               rf.aktif_rev_no, rf.kaynak_arge_test_id, rf.cari_id,
               (SELECT COALESCE(SUM(k.miktar_kg), 0) FROM nexgen_rf_kalem k
                WHERE k.rf_renk_id = rf.id AND k.aktif = 1) AS toplam_kg
        FROM nexgen_rf_formul_uygunluk u
        JOIN nexgen_rf_renk rf ON rf.id = u.rf_renk_id
        WHERE u.formul_id = ? AND u.aktif = 1
          AND rf.aktif = 1 AND rf.durum = 'ONAYLI'
          AND rf.rf_kod NOT LIKE 'RF-%' AND rf.rf_kod NOT LIKE 'NX-%'
          AND rf.kaynak_arge_test_id IS NULL
        ORDER BY rf.rf_kod
    """, (formul_id,)).fetchall()

    liste: list[dict] = []
    for r in rows:
        rf_dict = {
            'rf_kod': r['rf_kod'],
            'aktif': r['aktif'],
            'durum': r['durum'],
            'kaynak_arge_test_id': r['kaynak_arge_test_id'],
        }
        if not yeni_secimde_renk_gosterilebilir_mi(rf_dict):
            continue
        uk = (r['uretim_kodu'] or '').strip()
        af = (r['ana_formul_kodu'] or '').strip()
        rk = (r['renk_kodu'] or '').strip()
        if uretim_kodu_zorunlu:
            if not uk or not af or not rk:
                continue
            if not uretim_kodu_format_gecerli_mi(uk):
                continue
        rev_no = r['aktif_rev_no']
        rev_id = None
        if rev_no and _rf_revizyon_tablosu_var(con):
            rev_row = con.execute(
                "SELECT id FROM nexgen_rf_revizyon WHERE rf_renk_id=? AND rev_no=? AND aktif=1",
                (r['rf_renk_id'], rev_no),
            ).fetchone()
            if rev_row:
                rev_id = rev_row['id']
        toplam_kg = float(r['toplam_kg'] or 0)
        renk_kodu = rk or renk_sayisal_onek(r['rf_kod'])
        liste.append({
            'uygunluk_id': r['uygunluk_id'],
            'formul_id': r['formul_id'],
            'uretim_varyant_id': None,
            'rf_renk_id': r['rf_renk_id'],
            'id': r['rf_renk_id'],
            'rf_kod': r['rf_kod'],
            'ad': r['renk_adi'],
            'renk_adi': r['renk_adi'],
            'renk_kodu': renk_kodu,
            'ana_formul_kodu': af or frm['kod'],
            'uretim_kodu': uk or None,
            'rf_rev_no': rev_no,
            'rf_revizyon_id': rev_id,
            'toplam_kg': round(toplam_kg, 6),
            'toplam_gr': _miktar_kg_to_gr(toplam_kg),
            'cari_id': r['cari_id'],
        })
    return liste


def _uretim_kodu_uygunluk_kaydet(con, uygunluk_id, uk: dict) -> None:
    """Migration 104 kolonları varsa uygunluk kaydına yazar."""
    if not _uretim_kodu_kolon_var(con):
        return
    con.execute("""
        UPDATE nexgen_rf_formul_uygunluk
        SET uretim_kodu=?, ana_formul_kodu=?, renk_kodu=?
        WHERE id=?
    """, (uk['uretim_kodu'], uk['ana_formul_kodu'], uk['renk_kodu'], uygunluk_id))


def _uretim_kodu_bagla_islem(con, rf_row, formul_id, formul_kod) -> dict:
    """Tek formül+RF için üretim kodu üret veya idempotent döndür."""
    rf_id = rf_row['id']
    mevcut = _uretim_kodu_mevcut_bul(con, rf_id, formul_id)
    if mevcut:
        return {
            'ok': True,
            'idempotent': True,
            'uygunluk_id': mevcut['uygunluk_id'],
            'uretim_kodu': mevcut['uretim_kodu'],
            'ana_formul_kodu': mevcut.get('ana_formul_kodu'),
            'renk_kodu': mevcut.get('renk_kodu'),
        }
    dogrula = _uretim_kodu_girdi_dogrula(rf_row, formul_kod)
    if not dogrula.get('ok'):
        return dogrula
    cakisma = _uretim_kodu_cakisma_kontrol(
        con, dogrula['uretim_kodu'], rf_id, formul_id,
    )
    if not cakisma.get('ok'):
        return cakisma
    return {
        'ok': True,
        'idempotent': False,
        **dogrula,
    }


def _uretim_kodu_plan_snapshot_bul(con, rf_renk_id, formul_id) -> dict | None:
    """Plan/batch snapshot için mevcut üretim kodunu bulur."""
    return _uretim_kodu_mevcut_bul(con, rf_renk_id, formul_id)


def _uretim_kodu_plan_kolonlari_ekle(con, cols, vals, rf_renk_id, formul_id):
    """Plan INSERT listesine snapshot kolonları ekler (kolon varsa)."""
    if not rf_renk_id or not formul_id:
        return
    uk = _uretim_kodu_plan_snapshot_bul(con, rf_renk_id, formul_id)
    if not uk:
        return
    if _kolon_var_chk(con, 'nexgen_uretim_plan', 'uretim_kodu'):
        cols.append('uretim_kodu')
        vals.append(uk['uretim_kodu'])
    if _kolon_var_chk(con, 'nexgen_uretim_plan', 'ana_formul_kodu'):
        cols.append('ana_formul_kodu')
        vals.append(uk.get('ana_formul_kodu'))
    if _kolon_var_chk(con, 'nexgen_uretim_plan', 'renk_kodu'):
        cols.append('renk_kodu')
        vals.append(uk.get('renk_kodu'))


def _rf_pigmentler_json_olustur(con, rf_renk_id, boya_kalemler_raw=None, carpan=1.0):
    """
    Mevcut nexgen_rf_kalem'den ya da verilen ham kalem listesinden
    pigmentler_json uretir.
    boya_kalemler_raw: nexgen_arge_test_kalem Row listesi (carpan uygulanacak)
    carpan: test -> RF donusumu icin carpan (varsayilan 1.0)
    """
    if boya_kalemler_raw is not None:
        pigmentler = []
        for k in boya_kalemler_raw:
            miktar_kg = round(float(k['test_miktar_kg']) * carpan, 4)
            if miktar_kg <= 0:
                continue
            stok = con.execute(
                "SELECT id, ad FROM nexgen_stok_kart WHERE id=? AND aktif=1",
                (k['stok_kart_id'],)
            ).fetchone()
            pigmentler.append({
                'stok_kart_id': k['stok_kart_id'],
                'pigment_ad':   stok['ad'] if stok else '',
                'miktar_kg':    miktar_kg,
                'sira':         k['sira'],
            })
        return json.dumps(pigmentler, ensure_ascii=False)

    # Mevcut aktif kalemlerden olustur
    kalemler = con.execute("""
        SELECT rk.stok_kart_id, COALESCE(rk.pigment_ad, sk.ad) AS pigment_ad,
               rk.miktar_kg, rk.sira
        FROM nexgen_rf_kalem rk
        JOIN nexgen_stok_kart sk ON sk.id = rk.stok_kart_id
        WHERE rk.rf_renk_id = ? AND rk.aktif = 1
        ORDER BY rk.sira
    """, (rf_renk_id,)).fetchall()
    pigmentler = [
        {
            'stok_kart_id': k['stok_kart_id'],
            'pigment_ad':   k['pigment_ad'],
            'miktar_kg':    k['miktar_kg'],
            'sira':         k['sira'],
        }
        for k in kalemler
    ]
    return json.dumps(pigmentler, ensure_ascii=False)


def _rf_revizyon_ilk_olustur(con, rf_renk_id, boya_kalemler_raw, carpan,
                              olusturan_id=None, onaylayan_id=None, onay_tarihi=None):
    """
    Yeni olusturulan RF icin REV-1 olusturur.
    Idempotent: mevcut REV-1 varsa dokunmaz.
    commit yapmaz — cagiran fonksiyon commit eder.
    """
    if not _rf_revizyon_tablosu_var(con):
        return

    mevcut = con.execute(
        "SELECT id FROM nexgen_rf_revizyon WHERE rf_renk_id=? AND rev_no=1",
        (rf_renk_id,)
    ).fetchone()
    if mevcut:
        return

    pigmentler_json = _rf_pigmentler_json_olustur(
        con, rf_renk_id, boya_kalemler_raw=boya_kalemler_raw, carpan=carpan
    )

    con.execute("""
        INSERT INTO nexgen_rf_revizyon
            (rf_renk_id, rev_no, durum, pigmentler_json, neden, aciklama,
             olusturan_id, olusturma_tarihi, onaylayan_id, onay_tarihi, kilitli_mi, aktif)
        VALUES (?, 1, 'ONAYLANDI', ?, 'ILKREVIZYON', 'AR-GE aktariminda otomatik REV-1',
                ?, datetime('now'), ?, ?, 1, 1)
    """, (rf_renk_id, pigmentler_json, olusturan_id, onaylayan_id, onay_tarihi))

    if _rf_aktif_rev_no_var(con):
        con.execute(
            "UPDATE nexgen_rf_renk SET aktif_rev_no=1 WHERE id=? AND aktif_rev_no=0",
            (rf_renk_id,)
        )


def _rf_revizyon_mevcut_max_rev_no(con, rf_renk_id):
    row = con.execute(
        "SELECT COALESCE(MAX(rev_no), 0) AS mx FROM nexgen_rf_revizyon WHERE rf_renk_id=?",
        (rf_renk_id,)
    ).fetchone()
    return row['mx'] if row else 0


def _rf_revizyon_pigment_dogrula(pigmentler):
    """pigmentler_json listesini dogrular; hata varsa string doner, yoksa None."""
    if not pigmentler:
        return "En az bir pigment olmalidir."
    stok_idler = [p.get('stok_kart_id') for p in pigmentler]
    if len(stok_idler) != len(set(stok_idler)):
        return "Duplicate pigment vardir."
    for p in pigmentler:
        if not p.get('stok_kart_id'):
            return "stok_kart_id eksik."
        try:
            if float(p.get('miktar_kg', 0)) <= 0:
                return "Miktar sifirdan buyuk olmalidir."
        except (TypeError, ValueError):
            return "Gecersiz miktar_kg."
    toplam = sum(float(p.get('miktar_kg', 0)) for p in pigmentler)
    if toplam <= 0:
        return "Toplam pigment miktari sifirdan buyuk olmalidir."
    return None


# ─────────────────────────────────────────────────────────────
# ENDPOINT: Revizyon ac
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/boya-recetesi/<int:rf_renk_id>/revizyon-ac', methods=['POST'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_rf_revizyon_ac(rf_renk_id):
    """Mevcut boya reçetesine yeni TASLAK revizyon acar.

    POST JSON:
        neden        : str  (opsiyonel; _RF_REVIZYON_NEDENLER listesinden)
        aciklama     : str  (opsiyonel)
        formul_id    : int  (opsiyonel)
        kalip_carpani: float (opsiyonel)
    """
    if not _rf_revizyon_tablosu_var(_db()):
        return jsonify({'ok': False, 'hata': 'Migration 098 calistirilmamis.'}), 503

    data = request.get_json(silent=True) or {}
    neden = (data.get('neden') or '').strip().upper() or None
    aciklama = (data.get('aciklama') or '').strip() or None
    formul_id_raw = data.get('formul_id')
    kalip_carpani_raw = data.get('kalip_carpani')

    con = _db()
    try:
        rf = con.execute(
            "SELECT id, rf_kod, ad, aktif_rev_no FROM nexgen_rf_renk WHERE id=? AND aktif=1",
            (rf_renk_id,)
        ).fetchone()
        if not rf:
            return jsonify({'ok': False, 'hata': 'Boya recetesi bulunamadi.'}), 404

        # Acik TASLAK var mi?
        acik_taslak = con.execute(
            "SELECT id, rev_no FROM nexgen_rf_revizyon "
            "WHERE rf_renk_id=? AND durum='TASLAK' AND aktif=1",
            (rf_renk_id,)
        ).fetchone()
        if acik_taslak:
            return jsonify({
                'ok': False,
                'hata': f"Zaten acik bir TASLAK revizyon var (REV-{acik_taslak['rev_no']}). "
                        "Once mevcut TASLAK'i onaylayin veya pasife alin.",
            }), 409

        # formul_id dogrula
        formul_id = None
        if formul_id_raw not in (None, ''):
            try:
                formul_id = int(formul_id_raw)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'formul_id gecersiz.'}), 400
            if not con.execute(
                "SELECT id FROM nexgen_formul WHERE id=? AND aktif=1", (formul_id,)
            ).fetchone():
                return jsonify({'ok': False, 'hata': f'Formul bulunamadi (id={formul_id}).'}), 400

        # kalip_carpani
        kalip_carpani = None
        if kalip_carpani_raw not in (None, ''):
            try:
                kalip_carpani = float(kalip_carpani_raw)
            except (TypeError, ValueError):
                return jsonify({'ok': False, 'hata': 'kalip_carpani gecersiz.'}), 400

        # Mevcut aktif revizyonun pigment snapshot'ini baslangic kopyas olarak al
        yeni_rev_no = _rf_revizyon_mevcut_max_rev_no(con, rf_renk_id) + 1
        pigmentler_json = _rf_pigmentler_json_olustur(con, rf_renk_id)

        uid = _kullanici_id()
        con.execute("""
            INSERT INTO nexgen_rf_revizyon
                (rf_renk_id, rev_no, durum, pigmentler_json, neden, aciklama,
                 formul_id, kalip_carpani, olusturan_id, olusturma_tarihi, kilitli_mi, aktif)
            VALUES (?, ?, 'TASLAK', ?, ?, ?, ?, ?, ?, datetime('now'), 0, 1)
        """, (rf_renk_id, yeni_rev_no, pigmentler_json, neden, aciklama,
              formul_id, kalip_carpani, uid))
        revizyon_id = con.execute("SELECT last_insert_rowid()").fetchone()[0]
        con.commit()
    except Exception as e:
        con.rollback()
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()

    return jsonify({
        'ok': True,
        'revizyon_id': revizyon_id,
        'rev_no': yeni_rev_no,
        'rf_renk_id': rf_renk_id,
        'durum': 'TASLAK',
        'mesaj': f'REV-{yeni_rev_no} TASLAK olarak acildi.',
    })


# ─────────────────────────────────────────────────────────────
# ENDPOINT: TASLAK revizyon pigment ekle
# ─────────────────────────────────────────────────────────────
@nexgen_bp.route('/api/boya-recetesi/revizyon/<int:revizyon_id>/pigment-ekle', methods=['POST'])
@yetki_gerekli('nexgen.recete.manage', 'can_manage')
def api_rf_revizyon_pigment_ekle(revizyon_id):
    """TASLAK revizyona yeni pigment ekler.

    POST JSON:
        stok_kart_id : int   (zorunlu)
        miktar_kg    : float (zorunlu, > 0)
        sira         : int   (opsiyonel)
    """
    data = request.get_json(silent=True) or {}
    stok_kart_id = data.get('stok_kart_id')
    miktar_kg_raw = data.get('miktar_kg')

    if not stok_kart_id or miktar_kg_raw is None:
        return jsonify({'ok': False, 'hata': 'stok_kart_id ve miktar_kg zorunludur.'}), 400
    try:
        stok_kart_id = int(stok_kart_id)
        miktar_kg = float(miktar_kg_raw)
    except (TypeError, ValueError):
        return jsonify({'ok': False, 'hata': 'Gecersiz parametre.'}), 400
    if miktar_kg <= 0:
        return jsonify({'ok': False, 'hata': 'miktar_kg sifirdan buyuk olmalidir.'}), 400

    con = _db()
    try:
        rev = con.execute(
            "SELECT id, rf_renk_id, durum, kilitli_mi, pigmentler_json "
            "FROM nexgen_rf_revizyon WHERE id=? AND aktif=1",
            (revizyon_id,)
        ).fetchone()
        if not rev:
            return jsonify({'ok': False, 'hata': 'Revizyon bulunamadi.'}), 404
        if rev['durum'] != 'TASLAK' or rev['kilitli_mi']:
            return jsonify({'ok': False, 'hata': 'Yalnizca kilitlenmemis TASLAK revizyon duzenlenebilir.'}), 403

        stok = con.execute(
            "SELECT id, ad FROM nexgen_stok_kart WHERE id=? AND aktif=1",
            (stok_kart_id,)
        ).fetchone()
        if not stok:
            return jsonify({'ok': False, 'hata': f'Stok karti bulunamadi veya pasif (id={stok_kart_id}).'}), 400

        try:
            pigmentler = json.loads(rev['pigmentler_json'] or '[]')
        except (ValueError, TypeError):
            pigmentler = []

        # Duplicate kontrol
        if any(p.get('stok_kart_id') == stok_kart_id for p in pigmentler):
            return jsonify({'ok': False, 'hata': 'Bu pigment zaten revizyonda var.'}), 409

        sira = data.get('sira') or (max((p.get('sira', 0) for p in pigmentler), default=0) + 1)
        pigmentler.append({
            'stok_kart_id': stok_kart_id,
            'pigment_ad':   stok['ad'],
            'miktar_kg':    round(miktar_kg, 4),
            'sira':         int(sira),
        })

        con.execute(
            "UPDATE nexgen_rf_revizyon SET pigmentler_json=? WHERE id=?",
            (json.dumps(pigmentler, ensure_ascii=False), revizyon_id)
        )
        con.commit()
    except Exception as e:
        con.rollback()
        return jsonify({'ok': False, 'hata': str(e)}), 500
    finally:
        con.close()

    return jsonify({'ok': True, 'revizyon_id': revizyon_id, 'pigment_sayisi': len(pigmentler)})


